package com.dongqh.cartservice;

import com.dongqh.cartservice.domain.dto.CartFormDTO;
import com.dongqh.cartservice.domain.vo.CartVO;
import com.dongqh.cartservice.service.ICartService;
import com.dongqh.hmapi.client.ItemClient;
import com.dongqh.hmapi.dto.ItemDTO;
import com.hmall.common.utils.UserContext;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.anyCollection;
import static org.mockito.Mockito.when;

@SpringBootTest(properties = {
        "spring.cloud.nacos.config.enabled=false",
        "spring.cloud.nacos.discovery.enabled=false",
        "spring.cloud.nacos.discovery.register-enabled=false",
        "seata.enabled=false",
        "spring.datasource.url=jdbc:h2:mem:cart_test;MODE=MySQL;DB_CLOSE_DELAY=-1",
        "spring.datasource.driver-class-name=org.h2.Driver",
        "spring.datasource.username=sa",
        "spring.datasource.password=",
        "spring.sql.init.mode=always",
        "spring.rabbitmq.listener.simple.auto-startup=false"
})
class CartServiceApplicationTests {

    @Autowired
    private ICartService cartService;

    @Autowired
    private JdbcTemplate jdbc;

    @MockitoBean
    private ItemClient itemClient;

    @AfterEach
    void clearUserContext() {
        UserContext.removeUser();
    }

    @Test
    void contextLoads() {
    }

    @Test
    @Transactional
    void queryMyCartsUsesTheItemServiceSnapshot() {
        UserContext.setUser(7L);
        CartFormDTO form = new CartFormDTO();
        form.setItemId(1001L);
        form.setName("临时商品");
        form.setPrice(2999);
        form.setImage("item.png");

        ItemDTO item = new ItemDTO();
        item.setId(1001L);
        item.setPrice(2999);
        item.setStatus(1);
        item.setStock(10);
        when(itemClient.queryItemByIds(anyCollection())).thenReturn(List.of(item));

        cartService.addItem2Cart(form);
        List<CartVO> carts = cartService.queryMyCarts();

        assertEquals(1, carts.size());
        assertEquals(2999, carts.get(0).getNewPrice());
        assertEquals(1, carts.get(0).getStatus());
        assertEquals(10, carts.get(0).getStock());
    }

    @Test
    @Transactional
    void missingUserContextDoesNotFallBackToUserOne() {
        UserContext.setUser(1L);
        CartFormDTO form = new CartFormDTO();
        form.setItemId(1002L);
        form.setName("用户一商品");
        form.setPrice(1999);
        form.setImage("item-1.png");
        cartService.addItem2Cart(form);

        UserContext.removeUser();

        assertEquals(0, cartService.queryMyCarts().size());
    }

    @Test
    @Transactional
    void asynchronousCleanupPreservesItemsUpdatedAfterCheckout() {
        var checkoutAt = java.time.LocalDateTime.of(2026, 9, 17, 12, 0);
        jdbc.update("INSERT INTO cart(user_id,item_id,num,name,price,update_time) VALUES (7,1001,1,'old',100,?)",
                checkoutAt.minusSeconds(1));
        jdbc.update("INSERT INTO cart(user_id,item_id,num,name,price,update_time) VALUES (7,1002,1,'readded',100,?)",
                checkoutAt.plusSeconds(1));
        jdbc.update("INSERT INTO cart(user_id,item_id,num,name,price,update_time) VALUES (8,1001,1,'other-user',100,?)",
                checkoutAt.minusSeconds(1));

        cartService.removeOrderedItems(7L, List.of(1001L, 1002L), checkoutAt);

        assertEquals(0, jdbc.queryForObject(
                "SELECT COUNT(*) FROM cart WHERE user_id=7 AND item_id=1001", Integer.class));
        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM cart WHERE user_id=7 AND item_id=1002", Integer.class));
        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM cart WHERE user_id=8 AND item_id=1001", Integer.class));
    }

}

package com.dongqh.cartservice.listener;

import com.dongqh.cartservice.service.ICartService;
import com.dongqh.hmapi.dto.OrderCreatedMessage;
import org.junit.jupiter.api.Test;
import org.springframework.amqp.rabbit.annotation.RabbitListener;

import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.assertj.core.api.Assertions.assertThat;

class OrderCreatedListenerTest {

    @Test
    void removesOnlyTheOrderingUsersCheckoutSnapshot() {
        ICartService carts = mock(ICartService.class);
        OrderCreatedListener listener = new OrderCreatedListener(carts);
        LocalDateTime occurredAt = LocalDateTime.of(2026, 9, 17, 12, 0);
        OrderCreatedMessage message = new OrderCreatedMessage(
                UUID.randomUUID(), 101L, 7L, List.of(11L, 12L), occurredAt);

        listener.onOrderCreated(message);

        verify(carts).removeOrderedItems(7L, List.of(11L, 12L), occurredAt);
    }

    @Test
    void declaresDurableQueueBindingAndDeadLetterExchange() throws Exception {
        RabbitListener listener = OrderCreatedListener.class
                .getMethod("onOrderCreated", OrderCreatedMessage.class)
                .getAnnotation(RabbitListener.class);

        assertThat(listener.bindings()).hasSize(1);
        var binding = listener.bindings()[0];
        assertThat(binding.value().name()).isEqualTo("cart.trade.order-created.queue");
        assertThat(binding.value().durable()).isEqualTo("true");
        assertThat(binding.exchange().name()).isEqualTo("trade.events.topic");
        assertThat(binding.key()).containsExactly("trade.order.created");
        assertThat(binding.value().arguments()).anySatisfy(argument -> {
            assertThat(argument.name()).isEqualTo("x-dead-letter-exchange");
            assertThat(argument.value()).isEqualTo("trade.events.dlx");
        });
    }
}

package com.dongqh.couponservice.config;

import com.dongqh.couponservice.messaging.CouponMessagingTopology;
import org.springframework.amqp.core.BindingBuilder;
import org.springframework.amqp.core.Declarables;
import org.springframework.amqp.core.DirectExchange;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.core.QueueBuilder;
import org.springframework.amqp.support.converter.JacksonJsonMessageConverter;
import org.springframework.amqp.support.converter.MessageConverter;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration(proxyBeanMethods = false)
@ConditionalOnProperty(prefix = "luckyhub.messaging", name = "enabled", havingValue = "true")
public class CouponMessagingConfiguration {

    @Bean
    public MessageConverter couponRabbitMessageConverter() {
        return new JacksonJsonMessageConverter();
    }

    @Bean
    public Declarables couponPaySuccessDeclarables() {
        DirectExchange exchange = new DirectExchange(CouponMessagingTopology.EXCHANGE, true, false);
        DirectExchange deadLetterExchange = new DirectExchange(
                CouponMessagingTopology.DEAD_LETTER_EXCHANGE, true, false);
        Queue queue = QueueBuilder.durable(CouponMessagingTopology.QUEUE)
                .deadLetterExchange(CouponMessagingTopology.DEAD_LETTER_EXCHANGE)
                .deadLetterRoutingKey(CouponMessagingTopology.ROUTING_KEY)
                .build();
        Queue deadLetterQueue = QueueBuilder.durable(CouponMessagingTopology.DEAD_LETTER_QUEUE).build();

        return new Declarables(
                exchange,
                deadLetterExchange,
                queue,
                deadLetterQueue,
                BindingBuilder.bind(queue).to(exchange).with(CouponMessagingTopology.ROUTING_KEY),
                BindingBuilder.bind(deadLetterQueue).to(deadLetterExchange)
                        .with(CouponMessagingTopology.ROUTING_KEY));
    }
}

