package com.dongqh.luckyhub.coupon.integration;

import com.dongqh.hmapi.client.ItemClient;
import com.dongqh.hmapi.client.MembershipClient;
import com.dongqh.hmapi.client.UserClient;
import com.dongqh.hmapi.dto.ItemDTO;
import com.dongqh.hmapi.dto.MembershipBenefitDTO;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * The coupon service's small set of remote calls.
 *
 * Keeping these calls in one concrete class makes the business service easy to
 * read: coupon rules stay in coupon services, remote DTO conversion stays here.
 */
@Component
public class CouponIntegrationService {
    private static final int MIN_DISCOUNT_BASIS_POINTS = 1;
    private static final int MAX_DISCOUNT_BASIS_POINTS = 10_000;

    private final ItemClient items;
    private final MembershipClient memberships;
    private final UserClient users;

    public CouponIntegrationService(ItemClient items, MembershipClient memberships, UserClient users) {
        this.items = items;
        this.memberships = memberships;
        this.users = users;
    }

    public boolean isEnabledUser(long userId) {
        return Boolean.TRUE.equals(users.isEnabled(userId));
    }

    public ItemSnapshot getItem(long itemId) {
        List<ItemDTO> response = items.queryItemByIds(List.of(itemId));
        if (response == null) {
            return null;
        }
        List<ItemDTO> matches = response.stream()
                .filter(Objects::nonNull)
                .filter(item -> Long.valueOf(itemId).equals(item.getId()))
                .limit(2)
                .toList();
        if (matches.size() != 1) {
            return null;
        }
        ItemDTO item = matches.get(0);
        return new ItemSnapshot(item.getId(), item.getName(), item.getPrice(), item.getStock(),
                item.getCategory(), item.getBrand(), item.getStatus());
    }

    public Optional<MembershipBenefit> activeMembershipBenefit(long userId) {
        MembershipBenefitDTO response = memberships.activeBenefit(userId);
        if (response == null) {
            throw new IllegalStateException("Membership service returned no benefit response");
        }
        if (!response.active()) {
            return Optional.empty();
        }
        Integer discountBasisPoints = response.discountBasisPoints();
        if (discountBasisPoints == null
                || discountBasisPoints < MIN_DISCOUNT_BASIS_POINTS
                || discountBasisPoints > MAX_DISCOUNT_BASIS_POINTS) {
            throw new IllegalStateException("Membership service returned an invalid active discount");
        }
        return Optional.of(new MembershipBenefit(discountBasisPoints));
    }

    public record ItemSnapshot(Long id, String name, Integer price, Integer stock,
                               String category, String brand, Integer status) {
        public boolean availableForReward() {
            return id != null && Integer.valueOf(1).equals(status) && stock != null && stock > 0;
        }
    }

    public record MembershipBenefit(Integer discountBasisPoints) {
    }
}

package com.dongqh.luckyhub.mapper.coupon;
import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.dongqh.luckyhub.domain.po.coupon.UserCoupon; import org.apache.ibatis.annotations.*;
import java.time.LocalDateTime;
public interface UserCouponMapper extends BaseMapper<UserCoupon> {
 @Insert("""
         INSERT IGNORE INTO user_coupon
             (coupon_no, template_id, user_id, status, valid_from, valid_until)
         SELECT CONCAT(template_code, '-', #{userId}), id, #{userId}, 'AVAILABLE', valid_from, valid_until
           FROM coupon_template
          WHERE template_code LIKE 'HMALL-CHECKOUT-%'
            AND status = 1
            AND valid_from <= CURRENT_TIMESTAMP(3)
            AND valid_until > CURRENT_TIMESTAMP(3)
         """)
 int issueHmallCheckoutCoupons(@Param("userId") long userId);

 @Insert("""
         INSERT IGNORE INTO coupon_issue_record
             (business_no, template_id, user_id, user_coupon_id)
         SELECT CONCAT('HMALL-AUTO-', coupon.coupon_no), coupon.template_id, coupon.user_id, coupon.id
           FROM user_coupon coupon
           JOIN coupon_template template ON template.id = coupon.template_id
          WHERE coupon.user_id = #{userId}
            AND template.template_code LIKE 'HMALL-CHECKOUT-%'
         """)
 int recordHmallCheckoutCouponIssues(@Param("userId") long userId);

 @Update("UPDATE user_coupon SET status='LOCKED',locked_order_no=#{orderNo},version=version+1 WHERE id=#{id} AND user_id=#{userId} AND status='AVAILABLE' AND valid_from<=CURRENT_TIMESTAMP(3) AND valid_until>CURRENT_TIMESTAMP(3)") int lock(@Param("id") long id,@Param("userId") long userId,@Param("orderNo") String orderNo);
 @Update("UPDATE user_coupon SET status='USED',used_order_no=#{orderNo},version=version+1 WHERE id=#{id} AND status='LOCKED' AND locked_order_no=#{orderNo}") int use(@Param("id") long id,@Param("orderNo") String orderNo);
 @Update("UPDATE user_coupon SET status='AVAILABLE',locked_order_no=NULL,version=version+1 WHERE id=#{id} AND status='LOCKED' AND locked_order_no=#{orderNo}") int release(@Param("id") long id,@Param("orderNo") String orderNo);
 @Update("UPDATE user_coupon SET status='EXPIRED',version=version+1 WHERE status='AVAILABLE' AND valid_until<=CURRENT_TIMESTAMP(3)") int expireAvailable();
 @Update("UPDATE user_coupon SET status='AVAILABLE',locked_order_no=NULL,version=version+1 WHERE status='LOCKED' AND updated_at<=#{cutoff}") int releaseExpiredLocks(@Param("cutoff") LocalDateTime cutoff);
}

