import com.dongqh.fulfillmentservice.service.shipping.ShippingTrackingQueryService;
import com.hmall.common.domain.R;
import com.hmall.common.utils.UserContext;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

import java.util.List;

import static org.springframework.http.HttpStatus.UNAUTHORIZED;

@RestController
@RequestMapping("/api/shipping/orders")
public class ShippingQueryController {
    private final ShippingTrackingQueryService tracking;

    public ShippingQueryController(ShippingTrackingQueryService tracking) {
        this.tracking = tracking;
    }

    @GetMapping("/{shippingNo}")
    public R<ShippingTrackingView> get(@PathVariable("shippingNo") String shippingNo) {
        return R.ok(tracking.getForUser(requireUserId(), shippingNo));
    }

    @GetMapping("/{shippingNo}/tracking")
    public R<List<ShippingTrackingView.TrackingEvent>> events(
            @PathVariable("shippingNo") String shippingNo) {
        return R.ok(tracking.getForUser(requireUserId(), shippingNo).tracking());
    }

    @ExceptionHandler(ShippingDomainException.class)
    public ResponseEntity<R<Void>> handleShippingError(ShippingDomainException exception) {
        ShippingErrorCode error = exception.errorCode();
        HttpStatus status = error == ShippingErrorCode.SHIPPING_NOT_FOUND
                ? HttpStatus.NOT_FOUND : error == ShippingErrorCode.SHIPPING_REQUEST_INVALID
                ? HttpStatus.BAD_REQUEST : HttpStatus.CONFLICT;
        int code = switch (error) {
            case SHIPPING_NOT_FOUND -> 55005;
            case SHIPPING_IDEMPOTENCY_CONFLICT -> 55006;
            case SHIPPING_STATE_CONFLICT -> 55007;
            default -> 55012;
        };
        String message = switch (error) {
            case SHIPPING_NOT_FOUND -> "发货单不存在";
            case SHIPPING_IDEMPOTENCY_CONFLICT -> "发货请求幂等参数冲突";
            case SHIPPING_STATE_CONFLICT -> "发货单状态冲突";
            default -> "物流请求参数不合法";
        };
        return ResponseEntity.status(status).body(R.error(code, message));
    }

    private long requireUserId() {
        Long userId = UserContext.getUser();
        if (userId == null || userId <= 0) {
            throw new ResponseStatusException(UNAUTHORIZED);
        }
        return userId;
    }
}

package com.dongqh.fulfillmentservice.domain;

import com.dongqh.fulfillmentservice.enums.FailureCategory;
import com.dongqh.fulfillmentservice.enums.FulfillmentStatus;

import java.time.LocalDateTime;

public record FulfillmentTransition(
        FulfillmentStatus status,
        LocalDateTime nextAttemptAt,
        LocalDateTime completedAt,
        FailureCategory failureCategory
) {
}

package com.dongqh.fulfillmentservice.domain;

import com.dongqh.fulfillmentservice.enums.AttemptOperation;
import com.dongqh.fulfillmentservice.enums.FailureCategory;
import com.dongqh.fulfillmentservice.enums.FulfillmentStatus;
import com.dongqh.fulfillmentservice.enums.GatewayOutcome;

import java.time.Duration;
import java.time.LocalDateTime;

public class FulfillmentTransitionPolicy {

    public FulfillmentTransition resolve(
            GatewayOutcome outcome,
            AttemptOperation operation,
            int executionAttempts,
            int maxAttempts,
            LocalDateTime now,
            Duration baseDelay,
            Duration maxDelay
    ) {
        FailureCategory failureCategory = category(outcome);
        return switch (outcome) {
            case SUCCEEDED -> new FulfillmentTransition(FulfillmentStatus.SUCCEEDED, null, now, null);
            case UNKNOWN -> new FulfillmentTransition(
                    FulfillmentStatus.RECONCILING, now, null, FailureCategory.UNKNOWN);
            case RETRYABLE_FAILURE -> executionAttempts >= maxAttempts
                    ? new FulfillmentTransition(
                            FulfillmentStatus.QUARANTINED, null, null, failureCategory)
                    : new FulfillmentTransition(
                            FulfillmentStatus.RETRY_WAITING,
                            now.plus(backoff(executionAttempts, baseDelay, maxDelay)),
                            null,
                            failureCategory);
            case PERMANENT_FAILURE -> new FulfillmentTransition(
                    FulfillmentStatus.QUARANTINED, null, null, failureCategory);
            case NOT_FOUND -> operation == AttemptOperation.QUERY
                    ? new FulfillmentTransition(FulfillmentStatus.PENDING, now, null, null)
                    : new FulfillmentTransition(
                            FulfillmentStatus.RETRY_WAITING,
                            now.plus(backoff(executionAttempts, baseDelay, maxDelay)),
                            null,
                            null);
        };
    }

    private Duration backoff(int attempts, Duration baseDelay, Duration maxDelay) {
        long multiplier = 1L << Math.min(30, Math.max(0, attempts - 1));
        Duration calculated;
        try {
            calculated = baseDelay.multipliedBy(multiplier);
        } catch (ArithmeticException exception) {
            calculated = maxDelay;
        }
        return calculated.compareTo(maxDelay) > 0 ? maxDelay : calculated;
    }

    private FailureCategory category(GatewayOutcome outcome) {
        return switch (outcome) {
            case RETRYABLE_FAILURE -> FailureCategory.RETRYABLE;
            case PERMANENT_FAILURE -> FailureCategory.PERMANENT;
            case UNKNOWN -> FailureCategory.UNKNOWN;
            default -> null;
        };
    }
}

