package com.dongqh.fulfillmentservice.domain.model;

import com.dongqh.fulfillmentservice.enums.FulfillmentType;

public record CreateFulfillmentTaskCommand(
        String fulfillmentNo,
        String sourceType,
        String sourceId,
        FulfillmentType fulfillmentType,
        Long targetUserId,
        FulfillmentPayload payload,
        Integer maxAttempts
) {

    public CreateFulfillmentTaskCommand {
        fulfillmentNo = required(fulfillmentNo, "fulfillmentNo");
        sourceType = required(sourceType, "sourceType");
        sourceId = required(sourceId, "sourceId");
        if (fulfillmentType == null || payload == null || payload.fulfillmentType() != fulfillmentType) {
            throw new IllegalArgumentException("履约类型与payload不匹配");
        }
        if (targetUserId == null || targetUserId <= 0) {
            throw new IllegalArgumentException("targetUserId必须大于0");
        }
        maxAttempts = maxAttempts == null ? 5 : maxAttempts;
        if (maxAttempts < 1 || maxAttempts > 100) {
            throw new IllegalArgumentException("maxAttempts必须为1到100");
        }
    }

    private static String required(String value, String name) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(name + "不能为空");
        }
        return value.trim();
    }
}

package com.dongqh.fulfillmentservice.domain.model;

import com.dongqh.fulfillmentservice.enums.AttemptOperation;
import com.dongqh.fulfillmentservice.enums.FulfillmentType;

import java.time.LocalDateTime;
import java.util.Objects;

public record FulfillmentClaim(
        long taskId,
        String fulfillmentNo,
        FulfillmentType fulfillmentType,
        long targetUserId,
        String requestPayload,
        AttemptOperation operation,
        String leaseToken,
        LocalDateTime claimedAt,
        LocalDateTime leaseUntil
) {

    public FulfillmentClaim {
        if (taskId <= 0 || targetUserId <= 0) {
            throw new IllegalArgumentException("履约任务与用户 ID 必须为正数");
        }
        fulfillmentNo = required(fulfillmentNo, "fulfillmentNo");
        requestPayload = required(requestPayload, "requestPayload");
        leaseToken = required(leaseToken, "leaseToken");
        Objects.requireNonNull(fulfillmentType, "fulfillmentType must not be null");
        Objects.requireNonNull(operation, "operation must not be null");
        Objects.requireNonNull(claimedAt, "claimedAt must not be null");
        Objects.requireNonNull(leaseUntil, "leaseUntil must not be null");
        if (!leaseUntil.isAfter(claimedAt)) {
            throw new IllegalArgumentException("leaseUntil 必须晚于 claimedAt");
        }
    }

    private static String required(String value, String name) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(name + " 不能为空");
        }
        return value.trim();
    }
}

package com.dongqh.fulfillmentservice.domain.model;

import com.dongqh.fulfillmentservice.enums.GatewayOutcome;

import java.util.Objects;

public record FulfillmentGatewayResult(
        GatewayOutcome outcome,
        String externalReference,
        String errorCode,
        String safeMessage
) {

    public FulfillmentGatewayResult {
        Objects.requireNonNull(outcome, "outcome must not be null");
        externalReference = optional(externalReference);
        errorCode = bounded(errorCode, 64);
        safeMessage = bounded(safeMessage, 500);
        if (outcome == GatewayOutcome.SUCCEEDED && externalReference == null) {
            throw new IllegalArgumentException("成功结果必须包含externalReference");
        }
    }

    public static FulfillmentGatewayResult succeeded(String reference) {
        return new FulfillmentGatewayResult(GatewayOutcome.SUCCEEDED, reference, null, null);
    }

    public static FulfillmentGatewayResult retryable(String code, String message) {
        return new FulfillmentGatewayResult(GatewayOutcome.RETRYABLE_FAILURE, null, code, message);
    }

    public static FulfillmentGatewayResult permanent(String code, String message) {
        return new FulfillmentGatewayResult(GatewayOutcome.PERMANENT_FAILURE, null, code, message);
    }

    public static FulfillmentGatewayResult unknown(String code, String message) {
        return new FulfillmentGatewayResult(GatewayOutcome.UNKNOWN, null, code, message);
    }

    public static FulfillmentGatewayResult notFound() {
        return new FulfillmentGatewayResult(GatewayOutcome.NOT_FOUND, null, null, null);
    }

    private static String optional(String value) {
        return value == null || value.isBlank() ? null : value.trim();
    }

    private static String bounded(String value, int maxLength) {
        String normalized = optional(value);
        return normalized == null ? null : normalized.substring(0, Math.min(maxLength, normalized.length()));
    }
}

