package com.dongqh.fulfillmentservice.integration.crypto.shipping;

public interface AddressCipher {
    String encrypt(String plaintext);

    String decrypt(String envelope);
}

package com.dongqh.fulfillmentservice.integration.crypto.shipping;

import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.Objects;

public final class AesGcmAddressCipher implements AddressCipher {

    private static final int NONCE_BYTES = 12;
    private static final int TAG_BITS = 128;
    private final String keyVersion;
    private final byte[] key;
    private final SecureRandom random;

    public AesGcmAddressCipher(String keyVersion, String base64Key) {
        this(keyVersion, base64Key, new SecureRandom());
    }

    AesGcmAddressCipher(String keyVersion, String base64Key, SecureRandom random) {
        if (keyVersion == null || !keyVersion.matches("[A-Za-z0-9_-]{1,16}")) {
            throw new IllegalArgumentException("地址加密密钥版本不合法");
        }
        if (base64Key == null || base64Key.isBlank()) {
            throw new IllegalArgumentException("必须配置地址加密密钥");
        }
        try {
            this.key = Base64.getDecoder().decode(base64Key);
        } catch (IllegalArgumentException exception) {
            throw new IllegalArgumentException("地址加密密钥必须是Base64编码", exception);
        }
        if (this.key.length != 32) {
            throw new IllegalArgumentException("地址加密密钥必须解码为32字节");
        }
        this.keyVersion = keyVersion;
        this.random = Objects.requireNonNull(random);
    }

    @Override
    public String encrypt(String plaintext) {
        if (plaintext == null || plaintext.isBlank()) {
            throw new IllegalArgumentException("地址明文不能为空");
        }
        byte[] nonce = new byte[NONCE_BYTES];
        random.nextBytes(nonce);
        byte[] ciphertext = crypt(Cipher.ENCRYPT_MODE, nonce, plaintext.getBytes(StandardCharsets.UTF_8));
        return keyVersion + "." + Base64.getUrlEncoder().withoutPadding().encodeToString(nonce)
                + "." + Base64.getUrlEncoder().withoutPadding().encodeToString(ciphertext);
    }

    @Override
    public String decrypt(String envelope) {
        if (envelope == null) {
            throw new IllegalArgumentException("地址密文不能为空");
        }
        String[] parts = envelope.split("\\.", -1);
        if (parts.length != 3 || !keyVersion.equals(parts[0])) {
            throw new IllegalArgumentException("地址密文版本不受支持");
        }
        try {
            byte[] nonce = Base64.getUrlDecoder().decode(parts[1]);
            byte[] ciphertext = Base64.getUrlDecoder().decode(parts[2]);
            if (nonce.length != NONCE_BYTES || ciphertext.length < TAG_BITS / 8) {
                throw new IllegalArgumentException("地址密文格式不合法");
            }
            return new String(crypt(Cipher.DECRYPT_MODE, nonce, ciphertext), StandardCharsets.UTF_8);
        } catch (IllegalArgumentException exception) {
            throw exception;
        }
    }

    private byte[] crypt(int mode, byte[] nonce, byte[] input) {
        try {
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            cipher.init(mode, new SecretKeySpec(key, "AES"), new GCMParameterSpec(TAG_BITS, nonce));
            cipher.updateAAD(keyVersion.getBytes(StandardCharsets.UTF_8));
            return cipher.doFinal(input);
        } catch (GeneralSecurityException exception) {
            throw new IllegalArgumentException("地址加密/解密失败", exception);
        }
    }

    @Override
    public String toString() {
        return "AesGcmAddressCipher[keyVersion=" + keyVersion + ", key=[REDACTED]]";
    }
}

package com.dongqh.fulfillmentservice.integration.crypto.shipping;

import com.dongqh.fulfillmentservice.config.shipping.LogisticsCallbackProperties;
import com.dongqh.fulfillmentservice.domain.model.shipping.LogisticsCallbackCommand;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.time.format.DateTimeFormatter;
import java.util.Base64;

@Component
public final class LogisticsCallbackSigner {
    private static final String ALGORITHM = "HmacSHA256";
    private static final DateTimeFormatter EVENT_TIME_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME;
    private final byte[] secret;

    @Autowired
    public LogisticsCallbackSigner(LogisticsCallbackProperties properties) {
        this(properties.secret());
    }

    public LogisticsCallbackSigner(String secret) {
        if (secret == null || secret.getBytes(StandardCharsets.UTF_8).length < 32) {
            throw new IllegalArgumentException("fulfillment shipping callback secret must contain at least 32 UTF-8 bytes");
        }
        this.secret = secret.getBytes(StandardCharsets.UTF_8).clone();
    }

    public String canonical(LogisticsCallbackCommand command) {
        return command.callbackId() + '\n'
                + command.nonce() + '\n'
                + command.timestampEpochSecond() + '\n'
                + command.waybillNo() + '\n'
                + command.eventType().name() + '\n'
                + EVENT_TIME_FORMAT.format(command.eventTime());
    }

    public String sign(LogisticsCallbackCommand command) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(mac(canonical(command)));
    }

    public boolean verify(LogisticsCallbackCommand command) {
        byte[] supplied;
        try {
            supplied = Base64.getUrlDecoder().decode(command.signature());
        } catch (IllegalArgumentException exception) {
            return false;
        }
        return supplied.length == 32 && MessageDigest.isEqual(mac(canonical(command)), supplied);
    }

    private byte[] mac(String canonical) {
        try {
            Mac mac = Mac.getInstance(ALGORITHM);
            mac.init(new SecretKeySpec(secret, ALGORITHM));
            return mac.doFinal(canonical.getBytes(StandardCharsets.UTF_8));
        } catch (GeneralSecurityException exception) {
            throw new IllegalStateException("HMAC-SHA256不可用", exception);
        }
    }
}

package com.dongqh.fulfillmentservice.integration;

import com.dongqh.fulfillmentservice.domain.model.FulfillmentGatewayResult;
import feign.FeignException;

final class FulfillmentFeignFailure {
    private FulfillmentFeignFailure() {
    }

    static FulfillmentGatewayResult map(RuntimeException failure) {
        if (!(failure instanceof FeignException feign)) {
            return FulfillmentGatewayResult.unknown("PROVIDER_UNAVAILABLE", "下游服务结果未知");
        }
        int status = feign.status();
        if (status == 409 || status == 408 || status == 425 || status == 429) {
            return FulfillmentGatewayResult.retryable("PROVIDER_RETRYABLE", "下游服务暂不可处理");
        }
        if (status >= 400 && status < 500) {
            return FulfillmentGatewayResult.permanent("PROVIDER_REJECTED", "下游服务拒绝履约请求");
        }
        return FulfillmentGatewayResult.unknown("PROVIDER_UNAVAILABLE", "下游服务结果未知");
    }
}

