        this.cipher = cipher;
    }

    public LogisticsFulfillmentRequest assemble(FulfillmentClaim claim, LogisticsFulfillmentPayload payload) {
        if (claim == null || payload == null || claim.fulfillmentType() != FulfillmentType.LOGISTICS) {
            throw invalidRequest();
        }
        ShippingOrder order = orders.findById(payload.shippingOrderId()).orElse(null);
        if (order == null
                || !Objects.equals(order.fulfillmentNo(), claim.fulfillmentNo())
                || !Objects.equals(order.targetUserId(), claim.targetUserId())
                || !Objects.equals(order.skuCode(), payload.skuCode())
                || !Objects.equals(order.quantity(), payload.quantity())) {
            throw invalidRequest();
        }

        ShippingAddressSnapshot snapshot = snapshots.require(order.addressSnapshotId());
        if (!Objects.equals(snapshot.userId(), order.targetUserId())
                || snapshot.sourceType() != order.sourceType()
                || !Objects.equals(snapshot.sourceId(), order.sourceId())
                || !Objects.equals(snapshot.receiverMasked(), payload.receiverMasked())
                || !Objects.equals(snapshot.phoneMasked(), payload.phoneMasked())) {
            throw invalidRequest();
        }

        // The fulfillment payload intentionally carries only a generic region mask; the order view retains
        // the snapshot's province mask. Do not copy the province mask into the external request envelope.
        return new LogisticsFulfillmentRequest(
                claim.fulfillmentNo(),
                claim.targetUserId(),
                order.id(),
                payload.skuCode(),
                payload.quantity(),
                cipher.decrypt(snapshot.receiverCiphertext()),
                cipher.decrypt(snapshot.phoneCiphertext()),
                cipher.decrypt(snapshot.provinceCiphertext()),
                cipher.decrypt(snapshot.cityCiphertext()),
                cipher.decrypt(snapshot.districtCiphertext()),
                cipher.decrypt(snapshot.detailCiphertext()),
                payload.receiverMasked(),
                payload.phoneMasked(),
                payload.regionMasked());
    }

    private ShippingDomainException invalidRequest() {
        return new ShippingDomainException(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
    }
}

package com.dongqh.fulfillmentservice.integration.shipping;

import com.dongqh.fulfillmentservice.domain.model.shipping.ShippingAddressDetails;

import com.dongqh.hmapi.dto.AddressDTO;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpHeaders;
import org.springframework.stereotype.Component;
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.RestClient;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

import java.util.Optional;

@Component
public class UserServiceShippingAddressProvider {

    private final RestClient client;

    public UserServiceShippingAddressProvider(
            RestClient.Builder builder,
            @Value("${luckyhub.fulfillment.user-service.base-url:http://localhost:8083}") String baseUrl
    ) {
        String normalizedBaseUrl = baseUrl != null && baseUrl.endsWith("/")
                ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
        this.client = builder.baseUrl(normalizedBaseUrl).build();
    }

    public Optional<ShippingAddressDetails> findAddressForUser(long userId, long addressId) {
        String authorization = currentAuthorization();
        if (authorization == null || authorization.isBlank()) {
            throw new IllegalStateException("地址查询缺少调用方认证信息");
        }
        AddressDTO address;
        try {
            address = client.get().uri("/addresses/{addressId}", addressId)
                    .header(HttpHeaders.AUTHORIZATION, authorization)
                    .retrieve().body(AddressDTO.class);
        } catch (HttpClientErrorException.NotFound | HttpClientErrorException.BadRequest exception) {
            return Optional.empty();
        }
        if (address == null || address.getId() == null || address.getUserId() == null
                || address.getId() != addressId || address.getUserId() != userId) {
            return Optional.empty();
        }
        return Optional.of(new ShippingAddressDetails(address.getId(), address.getUserId(), address.getProvince(),
                address.getCity(), address.getTown(), address.getMobile(), address.getStreet(), address.getContact()));
    }

    private static String currentAuthorization() {
        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
            return null;
        }
        HttpServletRequest request = attributes.getRequest();
        return request.getHeader(HttpHeaders.AUTHORIZATION);
    }
}

package com.dongqh.fulfillmentservice.integration;

import com.dongqh.fulfillmentservice.domain.model.FulfillmentGatewayResult;
import com.dongqh.fulfillmentservice.service.port.LogisticsFulfillmentGateway;
import com.dongqh.fulfillmentservice.domain.model.shipping.LogisticsFulfillmentRequest;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

@Component
public class SimulatedLogisticsFulfillmentGateway implements LogisticsFulfillmentGateway {
    private final JdbcTemplate jdbc;
    private final ObjectMapper json;

    public SimulatedLogisticsFulfillmentGateway(JdbcTemplate jdbc, ObjectMapper json) {
        this.jdbc = jdbc;
        this.json = json;
    }

    @Override
    @Transactional
    public FulfillmentGatewayResult execute(LogisticsFulfillmentRequest request) {
        if (request == null || request.fulfillmentNo() == null || request.fulfillmentNo().isBlank()) {
            return FulfillmentGatewayResult.permanent("INVALID_REQUEST", "物流请求无效");
        }
        String payload = serialize(new SafeLogisticsRequest(request.fulfillmentNo(), request.targetUserId(),
                request.shippingOrderId(), request.skuCode(), request.quantity(), request.receiverMasked(),
                request.phoneMasked(), request.regionMasked()));
        String fingerprint = digest(payload);
        FulfillmentGatewayResult existing = find(request.fulfillmentNo(), fingerprint);
        if (existing != null) {
            return existing;
        }
        String reference = "SIM-L-" + digest(request.fulfillmentNo()).substring(0, 24);
        try {
            jdbc.update("""
                    INSERT INTO sim_logistics_record
                        (fulfillment_no, request_fingerprint, request_payload, external_reference, status)
                    VALUES (?, ?, ?, ?, 'SUCCEEDED')
                    """, request.fulfillmentNo(), fingerprint, payload, reference);
            return FulfillmentGatewayResult.succeeded(reference);
        } catch (DuplicateKeyException race) {
            FulfillmentGatewayResult winner = find(request.fulfillmentNo(), fingerprint);
            return winner == null ? FulfillmentGatewayResult.unknown("SIM_RESULT_UNKNOWN", "模拟物流结果待查询") : winner;
        }
    }

    @Override
    @Transactional(readOnly = true)
    public FulfillmentGatewayResult query(String fulfillmentNo) {
        if (fulfillmentNo == null || fulfillmentNo.isBlank()) {
            return FulfillmentGatewayResult.permanent("INVALID_REQUEST", "物流请求无效");
        }
        return jdbc.query("SELECT external_reference FROM sim_logistics_record WHERE fulfillment_no = ?",
                rs -> rs.next() ? FulfillmentGatewayResult.succeeded(rs.getString(1))
                        : FulfillmentGatewayResult.notFound(), fulfillmentNo.trim());
    }

    private FulfillmentGatewayResult find(String fulfillmentNo, String fingerprint) {
        return jdbc.query("SELECT request_fingerprint, external_reference FROM sim_logistics_record WHERE fulfillment_no = ?",
                rs -> {
                    if (!rs.next()) {
                        return null;
                    }
                    return fingerprint.equals(rs.getString("request_fingerprint"))
                            ? FulfillmentGatewayResult.succeeded(rs.getString("external_reference"))
                            : FulfillmentGatewayResult.permanent("SIM_IDEMPOTENCY_CONFLICT", "物流幂等请求参数不一致");
                }, fulfillmentNo);
    }

    private String serialize(SafeLogisticsRequest request) {
        try {
            return json.writeValueAsString(request);
        } catch (JacksonException exception) {
            throw new IllegalStateException("模拟物流请求序列化失败", exception);
        }
    }

    private String digest(String value) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("SHA-256不可用", exception);
        }
    }

    private record SafeLogisticsRequest(String fulfillmentNo, Long targetUserId, long shippingOrderId,
                                        String skuCode, int quantity, String receiverMasked,
                                        String phoneMasked, String regionMasked) {
    }
}

