package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.config.shipping.LogisticsCallbackProperties;
import com.dongqh.fulfillmentservice.integration.crypto.shipping.LogisticsCallbackSigner;
import com.dongqh.fulfillmentservice.domain.shipping.LogisticsCallbackErrorCode;
import com.dongqh.fulfillmentservice.domain.shipping.LogisticsCallbackException;
import com.dongqh.fulfillmentservice.domain.model.shipping.LogisticsCallbackCommand;
import org.springframework.stereotype.Service;

import java.time.Clock;
import java.time.Instant;
import java.util.regex.Pattern;

@Service
public class LogisticsCallbackService {
    private static final Pattern SIGNED_IDENTIFIER = Pattern.compile("[A-Za-z0-9][A-Za-z0-9._:-]{0,99}");

    private final LogisticsCallbackSigner signer;
    private final LogisticsCallbackProperties properties;
    private final TransactionalLogisticsCallbackProcessor processor;
    private final Clock clock;

    public LogisticsCallbackService(
            LogisticsCallbackSigner signer,
            LogisticsCallbackProperties properties,
            TransactionalLogisticsCallbackProcessor processor,
            Clock fulfillmentClock
    ) {
        this.signer = signer;
        this.properties = properties;
        this.processor = processor;
        this.clock = fulfillmentClock;
    }

    public void handle(LogisticsCallbackCommand command) {
        validate(command);
        if (!withinWindow(command.timestampEpochSecond()) || !signer.verify(command)) {
            throw new LogisticsCallbackException(LogisticsCallbackErrorCode.CALLBACK_SIGNATURE_INVALID);
        }
        LogisticsCallbackErrorCode failure = processor.process(command);
        if (failure != null) {
            throw new LogisticsCallbackException(failure);
        }
    }

    private boolean withinWindow(long timestamp) {
        long now = Instant.now(clock).getEpochSecond();
        long window = properties.window().getSeconds();
        return timestamp >= now - window && timestamp <= now + window;
    }

    private void validate(LogisticsCallbackCommand command) {
        if (command == null
                || invalidSignedIdentifier(command.callbackId())
                || invalidSignedIdentifier(command.nonce())
                || invalidSignedIdentifier(command.waybillNo())
                || command.eventType() == null
                || command.eventTime() == null
                || invalidOptional(command.locationSummary(), 200)
                || invalidOptional(command.description(), 500)
                || invalid(command.signature(), 100)) {
            throw new LogisticsCallbackException(LogisticsCallbackErrorCode.SHIPPING_REQUEST_INVALID);
        }
    }

    private boolean invalid(String value, int max) {
        return value == null || value.isBlank() || value.length() > max;
    }

    private boolean invalidSignedIdentifier(String value) {
        return value == null || !SIGNED_IDENTIFIER.matcher(value).matches();
    }

    private boolean invalidOptional(String value, int max) {
        return value != null && value.length() > max;
    }
}

package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.integration.crypto.shipping.AddressCipher;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingDomainException;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingErrorCode;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingSourceType;
import com.dongqh.fulfillmentservice.integration.shipping.UserServiceShippingAddressProvider;
import com.dongqh.fulfillmentservice.domain.model.shipping.ShippingAddressDetails;
import com.dongqh.fulfillmentservice.persistence.shipping.DuplicateShippingAddressSnapshotException;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingAddressSnapshot;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingAddressSnapshotRepository;

import org.springframework.stereotype.Service;

import java.util.Objects;
import java.util.Collection;
import java.util.List;
import java.util.UUID;

@Service
public class ShippingAddressSnapshotService {

    private final ShippingAddressSnapshotRepository repository;
    private final UserServiceShippingAddressProvider addresses;
    private final AddressCipher cipher;

    public ShippingAddressSnapshotService(
            ShippingAddressSnapshotRepository repository,
            UserServiceShippingAddressProvider addresses,
            AddressCipher cipher
    ) {
        this.repository = repository;
        this.addresses = addresses;
        this.cipher = cipher;
    }

    public ShippingAddressSnapshot create(long userId, long addressId, ShippingSourceType sourceType, String sourceId) {
        if (userId <= 0 || addressId <= 0 || sourceType == null || sourceId == null
                || sourceId.isBlank() || sourceId.trim().length() > 100) {
            throw error(ShippingErrorCode.ADDRESS_INVALID);
        }
        ShippingAddressDetails address = addresses.findAddressForUser(userId, addressId)
                .filter(candidate -> Objects.equals(candidate.id(), addressId)
                        && Objects.equals(candidate.userId(), userId))
                .orElseThrow(() -> error(ShippingErrorCode.ADDRESS_NOT_FOUND));
        ShippingAddressSnapshot candidate = copy(userId, addressId, sourceType, sourceId.trim(), address);

        return repository.findBySource(sourceType, candidate.sourceId())
                .map(existing -> requireEqual(existing, candidate))
                .orElseGet(() -> insertOrRequireWinner(candidate));
    }

    public ShippingAddressSnapshot require(long snapshotId) {
        if (snapshotId <= 0) {
            throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
        }
        return repository.findById(snapshotId).orElseThrow(() -> error(ShippingErrorCode.SHIPPING_NOT_FOUND));
    }

    public List<ShippingAddressSnapshot> requireByIds(Collection<Long> snapshotIds) {
        if (snapshotIds == null || snapshotIds.isEmpty()) {
            return List.of();
        }
        List<Long> normalized = snapshotIds.stream().distinct().toList();
        if (normalized.size() > 100 || normalized.stream().anyMatch(id -> id == null || id <= 0)) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        return repository.findByIds(normalized);
    }

    private ShippingAddressSnapshot insertOrRequireWinner(ShippingAddressSnapshot candidate) {
        try {
            return repository.insert(candidate);
        } catch (DuplicateShippingAddressSnapshotException race) {
            return repository.findBySource(candidate.sourceType(), candidate.sourceId())
                    .map(existing -> requireEqual(existing, candidate))
                    .orElseThrow(() -> race);
        }
    }

    private ShippingAddressSnapshot copy(
            long userId,
            long addressId,
            ShippingSourceType sourceType,
            String sourceId,
            ShippingAddressDetails address
    ) {
        String receiver = required(address.contact());
        String phone = required(address.mobile());
        String province = required(address.province());
        String city = required(address.city());
        String district = required(address.town());
        String detail = required(address.street());
        if (!phone.matches("\\d{11}")) {
            throw error(ShippingErrorCode.ADDRESS_INVALID);
        }
        return new ShippingAddressSnapshot(null, "ADDRESS-" + UUID.randomUUID(), userId, addressId,
                sourceType, sourceId, cipher.encrypt(receiver), cipher.encrypt(phone), cipher.encrypt(province),
                cipher.encrypt(city), cipher.encrypt(district), cipher.encrypt(detail), maskReceiver(receiver),
                maskPhone(phone), province + "***", null);
    }

    private String required(String value) {
        if (value == null || value.isBlank()) {
            throw error(ShippingErrorCode.ADDRESS_INVALID);
        }
        return value.trim();
    }

    private String maskReceiver(String receiver) {
        int codePoints = receiver.codePointCount(0, receiver.length());
        if (codePoints <= 1) {
            return "*";
        }
        int firstEnd = receiver.offsetByCodePoints(0, 1);
        return receiver.substring(0, firstEnd) + "*";
    }

    private String maskPhone(String phone) {
        return phone.substring(0, 3) + "****" + phone.substring(phone.length() - 4);
    }

    private ShippingAddressSnapshot requireEqual(
            ShippingAddressSnapshot existing,
            ShippingAddressSnapshot candidate
    ) {
        boolean same = Objects.equals(existing.userId(), candidate.userId())
                && Objects.equals(existing.addressId(), candidate.addressId())
                && existing.sourceType() == candidate.sourceType()
                && Objects.equals(existing.sourceId(), candidate.sourceId())
                && samePlaintext(existing.receiverCiphertext(), candidate.receiverCiphertext())
                && samePlaintext(existing.phoneCiphertext(), candidate.phoneCiphertext())
                && samePlaintext(existing.provinceCiphertext(), candidate.provinceCiphertext())
                && samePlaintext(existing.cityCiphertext(), candidate.cityCiphertext())
                && samePlaintext(existing.districtCiphertext(), candidate.districtCiphertext())
                && samePlaintext(existing.detailCiphertext(), candidate.detailCiphertext())
                && Objects.equals(existing.receiverMasked(), candidate.receiverMasked())
                && Objects.equals(existing.phoneMasked(), candidate.phoneMasked())
                && Objects.equals(existing.regionMasked(), candidate.regionMasked());
        if (!same) {
            throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
        return existing;
    }

    private boolean samePlaintext(String left, String right) {
        return Objects.equals(cipher.decrypt(left), cipher.decrypt(right));
    }

    private ShippingDomainException error(ShippingErrorCode errorCode) {
        return new ShippingDomainException(errorCode);
    }
}

package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.enums.FulfillmentStatus;
import com.dongqh.fulfillmentservice.domain.model.FulfillmentPage;
import com.dongqh.fulfillmentservice.domain.model.FulfillmentTaskView;
import com.dongqh.fulfillmentservice.service.FulfillmentTaskOperationService;
import com.dongqh.fulfillmentservice.service.FulfillmentTaskReadService;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingDomainException;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingErrorCode;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingStatus;
import com.dongqh.fulfillmentservice.domain.model.shipping.ShippingOrderAdminQuery;
import com.dongqh.fulfillmentservice.domain.model.shipping.ShippingOrderView;
import com.dongqh.fulfillmentservice.domain.model.shipping.ShippingTrackingView;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrder;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Service
public class ShippingAdminService {
    private static final Pattern UNSAFE_NOTE = Pattern.compile("(?i)(?:"
            + "[\\p{Cc}\\p{Cf}\\{\\}\\[\\]]"
            + "|[\\w.+-]+@[\\w.-]+\\.[A-Za-z]{2,}"
            + "|(?<!\\d)1[3-9]\\d{9}(?!\\d)"
            + "|(?<!\\d)(?:\\d{17}[0-9Xx]|\\d{15})(?!\\d)"
            + "|(?<!\\d)0\\d{2,3}[- ]?\\d{7,8}(?!\\d)"
            + "|\\b(?:exception|payload|ciphertext|secret|authorization|provider\\s+response)\\b"
            + "|异常堆栈|原始响应|供应商响应|密文|明文|密钥|秘密|授权头|签名"
            + "|收件人|姓名|联系人|手机号|手机号码|电话号码|电话|座机|身份证|证件号|住址|详细地址"
            + "|(?:省|自治区|特别行政区).{0,30}(?:市|州).{0,30}(?:区|县).{0,50}(?:路|街|道|巷|弄|号|栋|单元|室)"
            + ")");
    private static final Pattern SAFE_NOTE = Pattern.compile("^(?:(?:"
            + "人工核验通过|已核对安全数据|已核对商品资料|确认可重试|可以重新发货"
            + "|用户申请终止|停止处理|重复任务|无需继续履约|隔离任务已核验|系统已恢复"
            + "|运维确认|安全原因|工单\\s*[：:#-]?\\s*[A-Za-z0-9_-]{1,32}"
            + ")[\\s，。；、,;]*)+$");

    private final ShippingOrderRepository orders;
    private final ShippingOrderService shipping;
    private final ShippingTrackingQueryService tracking;
    private final FulfillmentTaskReadService tasks;
    private final FulfillmentTaskOperationService taskOperations;
    private final ShippingOrderFulfillmentProjector projector;

    public ShippingAdminService(ShippingOrderRepository orders, ShippingOrderService shipping,
                                ShippingTrackingQueryService tracking, FulfillmentTaskReadService tasks,
                                FulfillmentTaskOperationService taskOperations,
                                ShippingOrderFulfillmentProjector projector) {
        this.orders = orders;
        this.shipping = shipping;
        this.tracking = tracking;
        this.tasks = tasks;
        this.taskOperations = taskOperations;
        this.projector = projector;
    }

    @Transactional(readOnly = true)
    public FulfillmentPage<ShippingOrderView> page(ShippingOrderAdminQuery query) {
        if (query == null) throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        long offset;
        try { offset = Math.multiplyExact(query.getPage() - 1, query.getSize()); }
        catch (ArithmeticException exception) { throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID); }
        List<Long> ids = orders.findAdminPage(query.getStatus(), query.getSourceType(), query.getSourceId(),
                query.getTargetUserId(), query.getWaybillNo(), query.getSize(), offset);
        long total = orders.countAdmin(query.getStatus(), query.getSourceType(), query.getSourceId(),
                query.getTargetUserId(), query.getWaybillNo());
        Map<Long, ShippingOrderView> views = shipping.getByIds(ids).stream()
                .collect(Collectors.toMap(ShippingOrderView::id, value -> value));
        List<ShippingOrderView> ordered = ids.stream().map(views::get).filter(Objects::nonNull).toList();
        long pages = total == 0 ? 0 : ((total - 1) / query.getSize()) + 1;
        return new FulfillmentPage<>(ordered, total, query.getPage(), query.getSize(), pages);
    }

    @Transactional(readOnly = true)
    public ShippingOrderView get(String shippingNo) {
        ShippingOrder order = require(shippingNo);
        return shipping.getForUser(order.targetUserId(), order.shippingNo());
    }

    @Transactional(readOnly = true)
    public ShippingTrackingView tracking(String shippingNo) {
        ShippingOrder order = require(shippingNo);
        return tracking.getForUser(order.targetUserId(), order.shippingNo());
    }

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView retry(String shippingNo, long operatorId, String note) {
        ShippingOrder order = lock(shippingNo);
        if (order.status() != ShippingStatus.FAILED || order.fulfillmentNo() == null) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        FulfillmentTaskView task = tasks.get(order.fulfillmentNo());
        if (task.status() != FulfillmentStatus.QUARANTINED) throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        taskOperations.retryQuarantined(order.fulfillmentNo(), operator(operatorId), safeNote(note));
        projector.projectFulfillmentState(order.fulfillmentNo());
        return get(order.shippingNo());
    }

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView terminate(String shippingNo, long operatorId, String note) {
        ShippingOrder order = lock(shippingNo);
        if (order.fulfillmentNo() == null || order.status() == ShippingStatus.SHIPPED
                || order.status() == ShippingStatus.IN_TRANSIT || order.status() == ShippingStatus.DELIVERED
                || order.status() == ShippingStatus.TERMINATED) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        FulfillmentTaskView task = tasks.get(order.fulfillmentNo());
        if (task.status() == FulfillmentStatus.PROCESSING || task.status() == FulfillmentStatus.SUCCEEDED
                || task.status() == FulfillmentStatus.TERMINATED) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        taskOperations.terminate(order.fulfillmentNo(), operator(operatorId), safeNote(note));
        projector.projectFulfillmentState(order.fulfillmentNo());
        return get(order.shippingNo());
    }

    private ShippingOrder require(String shippingNo) {
        String no = requiredNo(shippingNo);
        return orders.findByShippingNo(no).orElseThrow(() -> error(ShippingErrorCode.SHIPPING_NOT_FOUND));
    }

    private ShippingOrder lock(String shippingNo) {
        String no = requiredNo(shippingNo);
        return orders.lockByShippingNo(no).orElseThrow(() -> error(ShippingErrorCode.SHIPPING_NOT_FOUND));
    }

    private String requiredNo(String value) {
        if (value == null || value.isBlank() || value.trim().length() > 64) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        return value.trim();
    }

    private long operator(long value) {
        if (value <= 0) throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        return value;
    }

    private String safeNote(String value) {
        if (value == null || value.isBlank()) return null;
        String note = value.trim();
        if (UNSAFE_NOTE.matcher(note).find() || !SAFE_NOTE.matcher(note).matches()) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        return note.substring(0, Math.min(note.length(), 500));
    }

    private ShippingDomainException error(ShippingErrorCode code) { return new ShippingDomainException(code); }
}

package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.enums.FulfillmentStatus;
import com.dongqh.fulfillmentservice.enums.FulfillmentType;
import com.dongqh.fulfillmentservice.domain.model.FulfillmentTaskView;
import com.dongqh.fulfillmentservice.service.FulfillmentTaskReadService;
import com.dongqh.fulfillmentservice.service.port.FulfillmentStatusChangedOutbox;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingSourceType;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingStatus;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrder;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrderRepository;
import com.dongqh.hmapi.dto.FulfillmentStatusChangedEventV1;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

@Service
public class ShippingOrderFulfillmentProjector {

    private final ShippingOrderRepository orders;
    private final FulfillmentTaskReadService tasks;
    private final FulfillmentStatusChangedOutbox statusOutbox;
    private final Clock clock;

    public ShippingOrderFulfillmentProjector(
            ShippingOrderRepository orders,
            FulfillmentTaskReadService tasks,
            FulfillmentStatusChangedOutbox statusOutbox,
            Clock fulfillmentClock
    ) {
        this.orders = orders;
        this.tasks = tasks;
        this.statusOutbox = statusOutbox;
        this.clock = fulfillmentClock;
    }

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public void projectFulfillmentState(String fulfillmentNo) {
        String normalizedNo = required(fulfillmentNo);
        ShippingOrder order = orders.findByFulfillmentNo(normalizedNo).orElse(null);
        if (order == null || order.status() == ShippingStatus.DELIVERED
                || order.status() == ShippingStatus.TERMINATED) {
            return;
        }

        FulfillmentTaskView task = tasks.get(normalizedNo);
        requireMatchingTask(order, task, normalizedNo);
        LocalDateTime now = LocalDateTime.now(clock).truncatedTo(ChronoUnit.MILLIS);
        ShippingOrder projected = project(order, task, now);
        if (projected == null || !orders.updateProjection(order, projected)) {
            return;
        }

        if (order.sourceType() == ShippingSourceType.LOTTERY_BENEFIT) {
            statusOutbox.append(new FulfillmentStatusChangedEventV1(
                    UUID.randomUUID().toString(), normalizedNo, order.shippingNo(), order.sourceType().name(),
                    order.sourceId(), projected.status().name(), now));
        }
    }

    private ShippingOrder project(ShippingOrder order, FulfillmentTaskView task, LocalDateTime now) {
        ShippingStatus status = order.status();
        String carrierCode = order.carrierCode();
        String carrierName = order.carrierName();
        String waybillNo = order.waybillNo();
        String errorCode = order.lastErrorCode();
        String errorMessage = order.lastErrorMessage();
        LocalDateTime shippedAt = order.shippedAt();
        LocalDateTime failedAt = order.failedAt();
        LocalDateTime terminatedAt = order.terminatedAt();

        if (task.status() == FulfillmentStatus.SUCCEEDED) {
            if (status == ShippingStatus.SHIPPED || status == ShippingStatus.IN_TRANSIT
                    || status == ShippingStatus.DELIVERED) {
                return null;
            }
            carrierCode = "SIMULATOR";
            carrierName = "模拟物流";
            waybillNo = bounded(task.externalReference(), 100);
            status = ShippingStatus.SHIPPED;
            shippedAt = shippedAt == null ? now : shippedAt;
            errorCode = null;
            errorMessage = null;
            failedAt = null;
        } else if (task.status() == FulfillmentStatus.QUARANTINED) {
            if (status != ShippingStatus.FULFILLING) {
                return null;
            }
            status = ShippingStatus.FAILED;
            errorCode = defaulted(task.lastErrorCode(), "FULFILLMENT_QUARANTINED", 64);
            errorMessage = defaulted(task.lastErrorMessage(), "物流履约已安全隔离", 500);
            failedAt = now;
        } else if (task.status() == FulfillmentStatus.TERMINATED) {
            if (status == ShippingStatus.SHIPPED || status == ShippingStatus.IN_TRANSIT
                    || status == ShippingStatus.DELIVERED) {
                return null;
            }
            status = ShippingStatus.TERMINATED;
            errorCode = defaulted(task.lastErrorCode(), "FULFILLMENT_TERMINATED", 64);
            errorMessage = defaulted(task.lastErrorMessage(), "物流履约已安全终止", 500);
            terminatedAt = now;
        } else if (status == ShippingStatus.FAILED) {
            status = ShippingStatus.FULFILLING;
            errorCode = null;
            errorMessage = null;
            failedAt = null;
        } else {
            return null;
        }

        return new ShippingOrder(order.id(), order.shippingNo(), order.sourceType(), order.sourceId(),
                order.targetUserId(), order.addressSnapshotId(), order.hmallItemId(), order.skuCode(),
                order.productName(), order.imageUrl(), order.quantity(), order.fulfillmentNo(), order.claimRequestId(),
                carrierCode, carrierName, waybillNo, status, errorCode, errorMessage, shippedAt, order.deliveredAt(),
                failedAt, terminatedAt, order.version(), order.createdAt(), order.updatedAt());
    }

    private void requireMatchingTask(ShippingOrder order, FulfillmentTaskView task, String fulfillmentNo) {
        if (task.fulfillmentType() != FulfillmentType.LOGISTICS
                || !Objects.equals(task.fulfillmentNo(), fulfillmentNo)
                || !Objects.equals(task.sourceType(), order.sourceType().name())
                || !Objects.equals(task.sourceId(), order.sourceId())
                || !Objects.equals(task.targetUserId(), order.targetUserId())) {
            throw new IllegalStateException("履约任务与发货单身份不匹配");
        }
    }

    private String required(String value) {
        if (value == null || value.isBlank() || value.trim().length() > 100) {
            throw new IllegalArgumentException("fulfillmentNo参数无效");
        }
        return value.trim();
    }

    private String bounded(String value, int max) {
        if (value == null || value.isBlank()) {
            return null;
        }
        String normalized = value.trim();
        return normalized.substring(0, Math.min(max, normalized.length()));
    }

    private String defaulted(String value, String fallback, int max) {
        String normalized = bounded(value, max);
        return normalized == null ? fallback : normalized;
    }
}

package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.enums.shipping.ShippingStatus;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrder;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ShippingOrderProjectionWorker {

    private final ShippingOrderRepository orders;
    private final ShippingOrderFulfillmentProjector projector;

    public ShippingOrderProjectionWorker(
            ShippingOrderRepository orders,
            ShippingOrderFulfillmentProjector projector
    ) {
        this.orders = orders;
        this.projector = projector;
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW, isolation = Isolation.READ_COMMITTED)
    public boolean projectOne(long shippingOrderId) {
        ShippingOrder order = orders.lockById(shippingOrderId).orElse(null);
        if (order == null || order.status() == ShippingStatus.DELIVERED
                || order.status() == ShippingStatus.TERMINATED || order.fulfillmentNo() == null) {
            return false;
        }
        projector.projectFulfillmentState(order.fulfillmentNo());
        return true;
    }
}

package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.enums.FulfillmentType;
import com.dongqh.fulfillmentservice.domain.model.CreateFulfillmentTaskCommand;
import com.dongqh.fulfillmentservice.domain.model.LogisticsFulfillmentPayload;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingDomainException;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingErrorCode;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingSourceType;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingStatus;
import com.dongqh.fulfillmentservice.domain.model.shipping.CreateShippingOrderCommand;
import com.dongqh.fulfillmentservice.domain.model.shipping.CreateShippingOrderFromAddressCommand;
import com.dongqh.fulfillmentservice.domain.model.shipping.ShippingOrderView;
import com.dongqh.fulfillmentservice.persistence.shipping.DuplicateShippingOrderException;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingAddressSnapshot;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrder;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrderRepository;
import com.dongqh.fulfillmentservice.service.FulfillmentTaskCreationService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.util.Objects;
import java.util.Collection;
import java.util.List;
import java.util.UUID;

@Service
public class ShippingOrderService {

    private static final int MAX_ATTEMPTS = 5;
    private final ShippingOrderRepository orders;
    private final ShippingAddressSnapshotService snapshots;
    private final FulfillmentTaskCreationService tasks;

    public ShippingOrderService(
            ShippingOrderRepository orders,
            ShippingAddressSnapshotService snapshots,
            FulfillmentTaskCreationService tasks
    ) {
        this.orders = orders;
        this.snapshots = snapshots;
        this.tasks = tasks;
    }

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView create(CreateShippingOrderCommand command) {
        ShippingAddressSnapshot snapshot = snapshots.require(command.addressSnapshotId());
        validateSnapshot(command, snapshot);
        var existing = orders.findBySource(command.sourceType(), command.sourceId());
        if (existing.isPresent()) {
            return view(requireEqual(existing.get(), command), snapshot);
        }

        ShippingOrder order;
        try {
            order = orders.insert(candidate(command));
        } catch (DuplicateShippingOrderException race) {
            ShippingOrder winner = findWinner(command);
            if (winner == null) {
                throw race;
            }
            return view(requireEqual(winner, command), snapshots.require(winner.addressSnapshotId()));
        }

        String fulfillmentNo = "LOGISTICS-" + order.id();
        if (!orders.markFulfilling(order.id(), fulfillmentNo)) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        tasks.create(new CreateFulfillmentTaskCommand(fulfillmentNo, command.sourceType().name(), command.sourceId(),
                FulfillmentType.LOGISTICS, command.targetUserId(),
                new LogisticsFulfillmentPayload(order.id(), command.skuCode(), command.quantity(),
                        snapshot.receiverMasked(), snapshot.phoneMasked(),
                        LogisticsFulfillmentPayload.REDACTED_REGION),
                MAX_ATTEMPTS));

        ShippingOrder persisted = orders.findById(order.id()).orElseThrow(() -> error(ShippingErrorCode.SHIPPING_NOT_FOUND));
        return view(persisted, snapshot);
    }

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView createFromAddress(CreateShippingOrderFromAddressCommand command) {
        if (command == null || command.sourceType() == null || command.targetUserId() <= 0
                || command.addressId() <= 0 || command.sourceId() == null
                || command.sourceId().isBlank() || command.sourceId().trim().length() > 100) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        String sourceId = command.sourceId().trim();
        ShippingOrder existing = orders.findBySource(command.sourceType(), sourceId).orElse(null);
        if (existing != null) {
            ShippingAddressSnapshot originalSnapshot = snapshots.require(existing.addressSnapshotId());
            CreateShippingOrderCommand retry = new CreateShippingOrderCommand(command.sourceType(), sourceId,
                    command.targetUserId(), existing.addressSnapshotId(), command.hmallItemId(), command.skuCode(),
                    command.productName(), command.imageUrl(), command.quantity(), command.claimRequestId());
            if (!Objects.equals(originalSnapshot.addressId(), command.addressId())
                    || !Objects.equals(originalSnapshot.userId(), command.targetUserId())) {
                throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
            }
            return view(requireEqual(existing, retry), originalSnapshot);
        }

        ShippingAddressSnapshot snapshot = snapshots.create(command.targetUserId(), command.addressId(),
                command.sourceType(), sourceId);
        return create(new CreateShippingOrderCommand(command.sourceType(), sourceId,
                command.targetUserId(), snapshot.id(), command.hmallItemId(), command.skuCode(),
                command.productName(), command.imageUrl(), command.quantity(), command.claimRequestId()));
    }

    @Transactional(readOnly = true)
    public List<ShippingOrderView> getByIds(Collection<Long> ids) {
        if (ids == null || ids.isEmpty()) {
            return List.of();
        }
        List<Long> normalized = ids.stream().distinct().toList();
        if (normalized.size() > 100 || normalized.stream().anyMatch(id -> id == null || id <= 0)) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        List<ShippingOrder> found = orders.findByIds(normalized);
        var snapshotsById = snapshots.requireByIds(found.stream()
                        .map(ShippingOrder::addressSnapshotId).distinct().toList())
                .stream().collect(java.util.stream.Collectors.toMap(
                        ShippingAddressSnapshot::id, snapshot -> snapshot));
        return found.stream().map(order -> {
            ShippingAddressSnapshot snapshot = snapshotsById.get(order.addressSnapshotId());
            if (snapshot == null) {
                throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
            }
            return view(order, snapshot);
        }).toList();
    }

    @Transactional(readOnly = true)
    public ShippingOrderView getForUser(long userId, String shippingNo) {
        String requiredNo = shippingNo == null ? "" : shippingNo.trim();
        if (userId <= 0 || requiredNo.isEmpty() || requiredNo.length() > 64) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        ShippingOrder order = orders.findByShippingNo(requiredNo).orElse(null);
        if (order == null || !Objects.equals(order.targetUserId(), userId)) {
            throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
        }
        ShippingAddressSnapshot snapshot = snapshots.require(order.addressSnapshotId());
        if (!Objects.equals(snapshot.userId(), userId)) {
            throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
        }
        return view(order, snapshot);
    }

    private ShippingOrder candidate(CreateShippingOrderCommand command) {
        return new ShippingOrder(null, "SHIPPING-" + UUID.randomUUID(), command.sourceType(), command.sourceId(),
                command.targetUserId(), command.addressSnapshotId(), command.hmallItemId(), command.skuCode(),
                command.productName(), command.imageUrl(), command.quantity(), null, command.claimRequestId(),
                null, null, null, ShippingStatus.READY, null, null, null, null, null, null, 0, null, null);
    }

    private ShippingOrder findWinner(CreateShippingOrderCommand command) {
        ShippingOrder winner = orders.findBySource(command.sourceType(), command.sourceId()).orElse(null);
        if (winner == null && command.claimRequestId() != null) {
            winner = orders.findByClaimRequestId(command.claimRequestId()).orElse(null);
        }
        return winner;
    }

    private void validateSnapshot(CreateShippingOrderCommand command, ShippingAddressSnapshot snapshot) {
        if (!Objects.equals(snapshot.userId(), command.targetUserId())
                || snapshot.sourceType() != command.sourceType()
                || !Objects.equals(snapshot.sourceId(), command.sourceId())) {
            throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
    }

    private ShippingOrder requireEqual(ShippingOrder order, CreateShippingOrderCommand command) {
        if (order.sourceType() != command.sourceType()
                || !Objects.equals(order.sourceId(), command.sourceId())
                || !Objects.equals(order.targetUserId(), command.targetUserId())
                || !Objects.equals(order.addressSnapshotId(), command.addressSnapshotId())
                || !Objects.equals(order.hmallItemId(), command.hmallItemId())
                || !Objects.equals(order.skuCode(), command.skuCode())
                || !Objects.equals(order.productName(), command.productName())
                || !Objects.equals(order.imageUrl(), command.imageUrl())
                || !Objects.equals(order.quantity(), command.quantity())
                || !Objects.equals(order.claimRequestId(), command.claimRequestId())) {
            throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
        return order;
    }

    private ShippingOrderView view(ShippingOrder order, ShippingAddressSnapshot snapshot) {
        return new ShippingOrderView(order.id(), order.shippingNo(), order.sourceType(), order.sourceId(),
                order.targetUserId(), order.addressSnapshotId(), snapshot.snapshotNo(), order.hmallItemId(),
                order.skuCode(),
                order.productName(), order.imageUrl(), order.quantity(), order.fulfillmentNo(), order.carrierCode(),
                order.carrierName(), order.waybillNo(), order.status(), order.lastErrorCode(), order.lastErrorMessage(),
                order.shippedAt(), order.deliveredAt(), order.failedAt(), order.terminatedAt(), order.createdAt(),
                order.updatedAt(), snapshot.receiverMasked(), snapshot.phoneMasked(), snapshot.regionMasked());
    }

    private ShippingDomainException error(ShippingErrorCode code) {
        return new ShippingDomainException(code);
    }
}

package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.persistence.shipping.ShippingOrderRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;

@Service
public class ShippingProjectionBatchService {

    private static final Logger log = LoggerFactory.getLogger(ShippingProjectionBatchService.class);
    private static final int MAX_SCAN = 100;
    private static final int FORCED_FAIRNESS_SCAN_INTERVAL = 10;

    private final ShippingOrderRepository orders;
    private final ShippingOrderProjectionWorker worker;
    private long cursorId;
    private long fairnessCursorId;
    private long fairnessHighWaterMarkId;
    private int batchesSinceFairnessScan;

    public ShippingProjectionBatchService(ShippingOrderRepository orders, ShippingOrderProjectionWorker worker) {
        this.orders = orders;
        this.worker = worker;
    }

    public synchronized int projectPending() {
        List<Long> candidates;
        if (++batchesSinceFairnessScan >= FORCED_FAIRNESS_SCAN_INTERVAL) {
            batchesSinceFairnessScan = 0;
            candidates = scanFairnessPage();
        } else {
            CandidateScan scan = scanFrom(cursorId);
            cursorId = scan.nextCursorId();
            candidates = scan.candidateIds();
        }

        int projected = 0;
        for (Long id : candidates) {
            try {
                if (worker.projectOne(id)) {
                    projected++;
                }
            } catch (RuntimeException ignored) {
                log.warn("单条物流状态投影失败 shippingOrderId={}", id);
            }
        }
        return projected;
    }

    private List<Long> scanFairnessPage() {
        if (fairnessHighWaterMarkId == 0) {
            fairnessHighWaterMarkId = orders.selectProjectionCandidateHighWaterMark();
            fairnessCursorId = 0;
        }
        if (fairnessHighWaterMarkId == 0) {
            return List.of();
        }

        List<Long> candidates = orders.selectProjectionCandidateIdsBetween(
                fairnessCursorId, fairnessHighWaterMarkId, MAX_SCAN);
        if (candidates.size() < MAX_SCAN
                || candidates.get(candidates.size() - 1) >= fairnessHighWaterMarkId) {
            fairnessHighWaterMarkId = 0;
            fairnessCursorId = 0;
        } else {
            fairnessCursorId = candidates.get(candidates.size() - 1);
        }
        return candidates;
    }

    private CandidateScan scanFrom(long cursor) {
        List<Long> afterCursor = orders.selectProjectionCandidateIdsAfter(cursor, MAX_SCAN);
        List<Long> candidates = new ArrayList<>(afterCursor);
        if (candidates.size() < MAX_SCAN && cursor > 0) {
            candidates.addAll(orders.selectProjectionCandidateIdsBefore(cursor, MAX_SCAN - candidates.size()));
        }
        long nextCursor = !afterCursor.isEmpty()
                ? afterCursor.get(afterCursor.size() - 1)
                : !candidates.isEmpty() ? candidates.get(candidates.size() - 1) : 0;
        return new CandidateScan(List.copyOf(candidates), nextCursor);
    }

    private record CandidateScan(List<Long> candidateIds, long nextCursorId) {
    }
}

package com.dongqh.fulfillmentservice.service.shipping;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class ShippingProjectionScheduler {

    private static final Logger log = LoggerFactory.getLogger(ShippingProjectionScheduler.class);
    private final ShippingProjectionBatchService service;

    public ShippingProjectionScheduler(ShippingProjectionBatchService service) {
        this.service = service;
    }

    @Scheduled(fixedDelayString = "${luckyhub.fulfillment.projection-interval:5s}",
            initialDelayString = "${luckyhub.fulfillment.projection-initial-delay:60s}")
    public void project() {
        int count = service.projectPending();
        if (count > 0) {
            log.info("物流状态投影完成 count={}", count);
        }
    }
}

