package com.dongqh.fulfillmentservice.service.shipping;

import com.dongqh.fulfillmentservice.domain.shipping.LogisticsCallbackErrorCode;
import com.dongqh.fulfillmentservice.domain.shipping.LogisticsCallbackException;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingSourceType;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingStatus;
import com.dongqh.fulfillmentservice.enums.shipping.TrackingEventType;
import com.dongqh.fulfillmentservice.domain.model.shipping.LogisticsCallbackCommand;
import com.dongqh.fulfillmentservice.persistence.shipping.LogisticsCallbackRepository;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingCallbackOrder;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingCallbackReceipt;
import com.dongqh.fulfillmentservice.persistence.shipping.ShippingTrackingEvent;
import com.dongqh.hmapi.dto.FulfillmentStatusChangedEventV1;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.time.format.DateTimeFormatter;
import java.util.HexFormat;
import java.util.Objects;
import java.util.UUID;

@Service
public class TransactionalLogisticsCallbackProcessor {
    private static final DateTimeFormatter EVENT_TIME_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME;

    private final LogisticsCallbackRepository repository;
    private final Clock clock;

    public TransactionalLogisticsCallbackProcessor(LogisticsCallbackRepository repository, Clock fulfillmentClock) {
        this.repository = repository;
        this.clock = fulfillmentClock;
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public LogisticsCallbackErrorCode process(LogisticsCallbackCommand command) {
        LocalDateTime receivedAt = LocalDateTime.now(clock).truncatedTo(ChronoUnit.MILLIS);
        String nonceDigest = digest(command.nonce());
        String signatureDigest = digest(command.signature());
        ShippingCallbackReceipt receipt = new ShippingCallbackReceipt(
                command.callbackId(), nonceDigest, signatureDigest, command.waybillNo(), command.eventType(),
                databaseTime(command.eventTime()), "RECEIVED", null, receivedAt);
        try {
            repository.insertReceipt(receipt);
        } catch (DuplicateKeyException duplicate) {
            ShippingCallbackReceipt existing = repository.selectReceipt(command.callbackId());
            if (existing != null && sameReceipt(existing, command, nonceDigest, signatureDigest)) {
                return "REJECTED".equals(existing.status())
                        ? LogisticsCallbackErrorCode.fromCode(existing.errorCode()) : null;
            }
            return LogisticsCallbackErrorCode.CALLBACK_REPLAYED;
        }

        ShippingCallbackOrder order = repository.lockOrderByWaybillNo(command.waybillNo());
        if (order == null) {
            reject(receipt.callbackId(), LogisticsCallbackErrorCode.SHIPPING_NOT_FOUND, receivedAt);
            return LogisticsCallbackErrorCode.SHIPPING_NOT_FOUND;
        }
        if (!callbackAllowed(order.status())) {
            reject(receipt.callbackId(), LogisticsCallbackErrorCode.SHIPPING_STATE_CONFLICT, receivedAt);
            return LogisticsCallbackErrorCode.SHIPPING_STATE_CONFLICT;
        }

        insertEvent(order, command, receivedAt);
        advance(order, command.eventType(), receivedAt);
        repository.markReceiptProcessed(receipt.callbackId(), receivedAt);
        return null;
    }

    private void insertEvent(
            ShippingCallbackOrder order, LogisticsCallbackCommand command, LocalDateTime receivedAt
    ) {
        ShippingTrackingEvent event = new ShippingTrackingEvent(
                order.id(), providerEventId(command), command.waybillNo(), command.eventType(),
                normalizeOptional(command.locationSummary()), normalizeOptional(command.description()),
                databaseTime(command.eventTime()), receivedAt);
        try {
            repository.insertTrackingEvent(event);
        } catch (DuplicateKeyException ignored) {
            // A provider event has a deterministic identity, so repeated delivery remains idempotent.
        }
    }

    private void advance(ShippingCallbackOrder order, TrackingEventType eventType, LocalDateTime now) {
        ShippingStatus target = targetStatus(eventType);
        if (rank(target) <= rank(order.status())) {
            return;
        }
        LocalDateTime deliveredAt = target == ShippingStatus.DELIVERED ? now : order.deliveredAt();
        if (!repository.advanceOrderStatus(order, target, deliveredAt)) {
            throw new LogisticsCallbackException(LogisticsCallbackErrorCode.SHIPPING_STATE_CONFLICT);
        }
        if (order.sourceType() == ShippingSourceType.LOTTERY_BENEFIT) {
            repository.appendStatusChanged(new FulfillmentStatusChangedEventV1(
                    UUID.randomUUID().toString(), order.fulfillmentNo(), order.shippingNo(),
                    order.sourceType().name(), order.sourceId(), target.name(), now));
        }
    }

    private void reject(String callbackId, LogisticsCallbackErrorCode code, LocalDateTime processedAt) {
        repository.markReceiptRejected(callbackId, Integer.toString(code.code()), code.message(), processedAt);
    }

    private boolean sameReceipt(
            ShippingCallbackReceipt existing, LogisticsCallbackCommand command,
            String nonceDigest, String signatureDigest
    ) {
        return Objects.equals(existing.nonceDigest(), nonceDigest)
                && Objects.equals(existing.signatureDigest(), signatureDigest)
                && Objects.equals(existing.waybillNo(), command.waybillNo())
                && existing.eventType() == command.eventType()
                && Objects.equals(existing.eventTime(), databaseTime(command.eventTime()));
    }

    private boolean callbackAllowed(ShippingStatus status) {
        return status == ShippingStatus.SHIPPED
                || status == ShippingStatus.IN_TRANSIT
                || status == ShippingStatus.DELIVERED;
    }

    private ShippingStatus targetStatus(TrackingEventType type) {
        return switch (type) {
            case PICKED_UP -> ShippingStatus.SHIPPED;
            case IN_TRANSIT, OUT_FOR_DELIVERY -> ShippingStatus.IN_TRANSIT;
            case DELIVERED -> ShippingStatus.DELIVERED;
        };
    }

    private int rank(ShippingStatus status) {
        return switch (status) {
            case READY -> 0;
            case FULFILLING -> 1;
            case SHIPPED -> 2;
            case IN_TRANSIT -> 3;
            case DELIVERED -> 4;
            case FAILED, TERMINATED -> -1;
        };
    }

    private String providerEventId(LogisticsCallbackCommand command) {
        LocalDateTime persistedEventTime = databaseTime(command.eventTime());
        return digest(command.waybillNo() + '\n' + command.eventType().name() + '\n'
                + EVENT_TIME_FORMAT.format(persistedEventTime));
    }

    private LocalDateTime databaseTime(LocalDateTime value) {
        return value.truncatedTo(ChronoUnit.MILLIS);
    }

    private String normalizeOptional(String value) {
        if (value == null || value.isBlank()) return null;
        return value.trim();
    }

    private String digest(String value) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("SHA-256不可用", exception);
        }
    }
}

package com.dongqh.fulfillmentservice.worker;

import com.dongqh.fulfillmentservice.service.FulfillmentTaskStateService;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@ConditionalOnProperty(prefix = "luckyhub.messaging", name = "enabled", havingValue = "true", matchIfMissing = true)
public class FulfillmentScheduler {

    private final FulfillmentTaskStateService state;
    private final FulfillmentWorker worker;
    private final int recoveryBatchSize;

    public FulfillmentScheduler(
            FulfillmentTaskStateService state,
            FulfillmentWorker worker,
            @Value("${luckyhub.fulfillment.recovery-batch-size:100}") int recoveryBatchSize
    ) {
        if (recoveryBatchSize < 1 || recoveryBatchSize > 1000) {
            throw new IllegalArgumentException("recoveryBatchSize必须为1到1000");
        }
        this.state = state;
        this.worker = worker;
        this.recoveryBatchSize = recoveryBatchSize;
    }

    @Scheduled(
            fixedDelayString = "${luckyhub.fulfillment.poll-interval:5s}",
            initialDelayString = "${luckyhub.fulfillment.initial-delay:60s}"
    )
    public void poll() {
        state.recoverExpiredLeases(recoveryBatchSize);
        worker.runBatch();
        worker.runCompensationBatch();
    }
}

package com.dongqh.fulfillmentservice.worker;

import com.dongqh.fulfillmentservice.enums.AttemptOperation;
import com.dongqh.fulfillmentservice.enums.FulfillmentType;
import com.dongqh.fulfillmentservice.domain.model.CouponFulfillmentPayload;
import com.dongqh.fulfillmentservice.domain.model.FulfillmentClaim;
import com.dongqh.fulfillmentservice.domain.model.FulfillmentGatewayResult;
import com.dongqh.fulfillmentservice.domain.model.LogisticsFulfillmentPayload;
import com.dongqh.fulfillmentservice.domain.model.MembershipFulfillmentPayload;
import com.dongqh.fulfillmentservice.domain.model.PointsFulfillmentPayload;
import com.dongqh.fulfillmentservice.service.FulfillmentTaskStateService;
import com.dongqh.fulfillmentservice.service.port.CouponFulfillmentGateway;
import com.dongqh.fulfillmentservice.service.port.LogisticsFulfillmentGateway;
import com.dongqh.fulfillmentservice.service.port.MembershipFulfillmentGateway;
import com.dongqh.fulfillmentservice.service.port.PointsFulfillmentGateway;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingDomainException;
import com.dongqh.fulfillmentservice.domain.shipping.ShippingErrorCode;
import com.dongqh.fulfillmentservice.integration.shipping.LogisticsRequestAssembler;
import com.dongqh.fulfillmentservice.domain.model.shipping.LogisticsFulfillmentRequest;
import com.dongqh.fulfillmentservice.service.shipping.ShippingOrderFulfillmentProjector;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.time.Duration;
import java.util.Optional;

@Component
@ConditionalOnProperty(prefix = "luckyhub.messaging", name = "enabled", havingValue = "true", matchIfMissing = true)
public class FulfillmentWorker {

    private final FulfillmentTaskStateService state;
    private final CouponFulfillmentGateway coupons;
    private final PointsFulfillmentGateway points;
    private final MembershipFulfillmentGateway memberships;
    private final LogisticsFulfillmentGateway logistics;
    private final LogisticsRequestAssembler logisticsAssembler;
    private final ShippingOrderFulfillmentProjector shippingProjector;
    private final ObjectMapper json;
    private final int batchSize;
    private final Duration leaseDuration;
    private final Duration compensationGrace;

    public FulfillmentWorker(
            FulfillmentTaskStateService state,
            CouponFulfillmentGateway coupons,
            PointsFulfillmentGateway points,
            MembershipFulfillmentGateway memberships,
            LogisticsFulfillmentGateway logistics,
            LogisticsRequestAssembler logisticsAssembler,
            ShippingOrderFulfillmentProjector shippingProjector,
            ObjectMapper json,
            @Value("${luckyhub.fulfillment.batch-size:100}") int batchSize,
            @Value("${luckyhub.fulfillment.lease-duration:30s}") Duration leaseDuration,
            @Value("${luckyhub.fulfillment.compensation-grace:30s}") Duration compensationGrace
    ) {
        if (batchSize < 1 || batchSize > 1000) {
            throw new IllegalArgumentException("batchSize必须为1到1000");
        }
        requirePositive(leaseDuration, "leaseDuration");
        requirePositive(compensationGrace, "compensationGrace");
        this.state = state;
        this.coupons = coupons;
        this.points = points;
        this.memberships = memberships;
        this.logistics = logistics;
        this.logisticsAssembler = logisticsAssembler;
        this.shippingProjector = shippingProjector;
        this.json = json;
        this.batchSize = batchSize;
        this.leaseDuration = leaseDuration;
        this.compensationGrace = compensationGrace;
    }

    public int runBatch() {
        var claims = state.claimDue(batchSize, leaseDuration);
        execute(claims);
        return claims.size();
    }

    public boolean runOne(String fulfillmentNo) {
        Optional<FulfillmentClaim> claim = state.claimReady(fulfillmentNo, leaseDuration);
        claim.ifPresent(this::execute);
        return claim.isPresent();
    }

    public int runCompensationBatch() {
        var claims = state.claimCompensationDue(batchSize, leaseDuration, compensationGrace);
        execute(claims);
        return claims.size();
    }

    private void execute(Iterable<FulfillmentClaim> claims) {
        for (FulfillmentClaim claim : claims) {
            execute(claim);
        }
    }

    private void execute(FulfillmentClaim claim) {
        long startedAt = System.nanoTime();
        FulfillmentGatewayResult result;
        try {
            result = route(claim);
        } catch (ShippingDomainException exception) {
            result = classifyShippingException(exception);
        } catch (RuntimeException exception) {
            result = FulfillmentGatewayResult.retryable("GATEWAY_EXCEPTION", "Gateway调用异常");
        }
        long durationMs = Math.max(0, (System.nanoTime() - startedAt) / 1_000_000);
        state.recordResult(claim, result, durationMs);
        if (claim.fulfillmentType() == FulfillmentType.LOGISTICS) {
            shippingProjector.projectFulfillmentState(claim.fulfillmentNo());
        }
    }

    private FulfillmentGatewayResult route(FulfillmentClaim claim) {
        if (claim.operation() == AttemptOperation.QUERY) {
            return switch (claim.fulfillmentType()) {
                case COUPON -> coupons.query(claim.fulfillmentNo());
                case POINTS -> points.query(claim.fulfillmentNo());
                case MEMBERSHIP -> memberships.query(claim.fulfillmentNo());
                case LOGISTICS -> logistics.query(claim.fulfillmentNo());
            };
        }
        try {
            return switch (claim.fulfillmentType()) {
                case COUPON -> coupons.execute(claim.fulfillmentNo(), claim.targetUserId(),
                        json.readValue(claim.requestPayload(), CouponFulfillmentPayload.class));
                case POINTS -> points.execute(claim.fulfillmentNo(), claim.targetUserId(),
                        json.readValue(claim.requestPayload(), PointsFulfillmentPayload.class));
                case MEMBERSHIP -> memberships.execute(claim.fulfillmentNo(), claim.targetUserId(),
                        json.readValue(claim.requestPayload(), MembershipFulfillmentPayload.class));
                case LOGISTICS -> logistics.execute(logisticsAssembler.assemble(claim,
                        json.readValue(claim.requestPayload(), LogisticsFulfillmentPayload.class)));
            };
        } catch (JacksonException exception) {
            return FulfillmentGatewayResult.permanent("INVALID_SNAPSHOT", "履约快照无法解析");
        }
    }

    private FulfillmentGatewayResult classifyShippingException(ShippingDomainException exception) {
        if (exception.errorCode() == ShippingErrorCode.SHIPPING_REQUEST_INVALID
                || exception.errorCode() == ShippingErrorCode.SHIPPING_NOT_FOUND) {
            return FulfillmentGatewayResult.permanent("INVALID_SNAPSHOT", "物流履约快照无法匹配");
        }
        return FulfillmentGatewayResult.retryable("GATEWAY_EXCEPTION", "Gateway调用异常");
    }

    private void requirePositive(Duration value, String name) {
        if (value == null || value.isZero() || value.isNegative()) {
            throw new IllegalArgumentException(name + "必须为正数");
        }
    }
}

