package com.dongqh.fulfillmentservice.service;

import com.dongqh.fulfillmentservice.messaging.FulfillmentTaskReadyEvent;
import com.dongqh.fulfillmentservice.persistence.FulfillmentOutboxCandidate;
import com.dongqh.fulfillmentservice.persistence.FulfillmentOutboxRepository;
import com.dongqh.hmapi.dto.FulfillmentStatusChangedEventV1;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingSourceType;
import com.dongqh.fulfillmentservice.enums.shipping.ShippingStatus;
import com.dongqh.fulfillmentservice.service.port.FulfillmentTaskReadyPublisher;
import com.dongqh.fulfillmentservice.service.port.FulfillmentStatusChangedPublisher;
import org.junit.jupiter.api.Test;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;

import static org.assertj.core.api.Assertions.assertThat;

class FulfillmentOutboxRelayServiceTests {

    private static final Clock CLOCK = Clock.fixed(Instant.parse("2026-09-27T04:00:00Z"), ZoneOffset.UTC);

    @Test
    void claimsCandidatesPublishesAndMarksOnlyConfirmedRowsSent() {
        FakeRepository repository = new FakeRepository(List.of(
                candidate(1, 0), candidate(2, 1), candidate(3, 0)));
        repository.claimableIds.addAll(List.of(1L, 3L));
        RecordingPublisher publisher = new RecordingPublisher();
        RecordingStatusPublisher statusPublisher = new RecordingStatusPublisher();
        FulfillmentOutboxRelayService service = service(repository, publisher, statusPublisher);

        int relayed = service.relayBatch();

        assertThat(relayed).isEqualTo(2);
        assertThat(publisher.events).extracting(FulfillmentTaskReadyEvent::fulfillmentNo)
                .containsExactly("TASK-1", "TASK-3");
        assertThat(repository.sentIds).containsExactly(1L, 3L);
        assertThat(repository.claims).hasSize(3);
        assertThat(repository.claims.get(0).claimUntil())
                .isEqualTo(LocalDateTime.of(2026, 9, 27, 4, 0).plusSeconds(30));
        assertThat(statusPublisher.events).isEmpty();
    }

    @Test
    void statusChangedOutboxPayloadUsesItsOwnPublisherAndIsNotDecodedAsTaskReady() {
        FakeRepository repository = new FakeRepository(List.of(
                candidate(6, FulfillmentStatusChangedPublisher.EVENT_TYPE, 0)));
        repository.claimableIds.add(6L);
        RecordingPublisher taskPublisher = new RecordingPublisher();
        RecordingStatusPublisher statusPublisher = new RecordingStatusPublisher();

        int relayed = service(repository, taskPublisher, statusPublisher).relayBatch();

        assertThat(relayed).isOne();
        assertThat(taskPublisher.events).isEmpty();
        assertThat(statusPublisher.events).singleElement().satisfies(event -> {
            assertThat(event.eventId()).isEqualTo("EVENT-6");
            assertThat(event.sourceType()).isEqualTo(ShippingSourceType.LOTTERY_BENEFIT.name());
            assertThat(event.sourceId()).isEqualTo("BENEFIT-6");
            assertThat(event.status()).isEqualTo(ShippingStatus.DELIVERED.name());
        });
        assertThat(repository.sentIds).containsExactly(6L);
    }

    @Test
    void eachOutboxRowGetsALeaseStartingAtItsActualClaimTime() {
        MutableClock clock = new MutableClock(CLOCK.instant());
        FakeRepository repository = new FakeRepository(List.of(candidate(1, 0), candidate(2, 0)));
        repository.claimableIds.addAll(List.of(1L, 2L));
        RecordingPublisher publisher = new RecordingPublisher();
        publisher.beforeNextPublish = () -> clock.advance(Duration.ofMinutes(2));

        service(repository, publisher, new RecordingStatusPublisher(), clock).relayBatch();

        assertThat(repository.claims).hasSize(2);
        assertThat(repository.claims.get(0).now()).isEqualTo(LocalDateTime.of(2026, 9, 27, 4, 0));
        assertThat(repository.claims.get(1).now()).isEqualTo(LocalDateTime.of(2026, 9, 27, 4, 2));
        assertThat(repository.claims.get(1).claimUntil())
                .isEqualTo(LocalDateTime.of(2026, 9, 27, 4, 2).plusSeconds(30));
    }

    @Test
    void failedPublishBackoffStartsAfterThePublishFailure() {
        MutableClock clock = new MutableClock(CLOCK.instant());
        FakeRepository repository = new FakeRepository(List.of(candidate(4, 2)));
        repository.claimableIds.add(4L);
        RecordingPublisher publisher = new RecordingPublisher();
        publisher.beforeNextPublish = () -> clock.advance(Duration.ofSeconds(10));
        publisher.failure = new IllegalStateException("temporary publish failure");

        service(repository, publisher, new RecordingStatusPublisher(), clock).relayBatch();

        assertThat(repository.failures).singleElement().satisfies(failure ->
                assertThat(failure.retryAt()).isEqualTo(LocalDateTime.of(2026, 9, 27, 4, 0).plusSeconds(18)));
    }

    @Test
    void failedPublishUsesLegacyExponentialRetryDelayAndTruncatesError() {
        FakeRepository repository = new FakeRepository(List.of(candidate(4, 2)));
        repository.claimableIds.add(4L);
        RecordingPublisher publisher = new RecordingPublisher();
        publisher.failure = new IllegalStateException("x".repeat(700));

        int relayed = service(repository, publisher, new RecordingStatusPublisher()).relayBatch();

        assertThat(relayed).isZero();
        assertThat(repository.failures).hasSize(1);
        assertThat(repository.failures.get(0).error()).hasSize(500);
        assertThat(repository.failures.get(0).retryAt())
                .isEqualTo(LocalDateTime.of(2026, 9, 27, 4, 0).plusSeconds(8));
    }

    @Test
    void malformedOutboxPayloadIsRetriedInsteadOfMarkedSent() {
        FakeRepository repository = new FakeRepository(List.of(
                new FulfillmentOutboxCandidate(5, "FULFILLMENT_TASK_READY", "{not-json", 0)));
        repository.claimableIds.add(5L);

        int relayed = service(repository, new RecordingPublisher(), new RecordingStatusPublisher()).relayBatch();

        assertThat(relayed).isZero();
        assertThat(repository.sentIds).isEmpty();
        assertThat(repository.failures).hasSize(1);
        assertThat(repository.failures.get(0).error()).isNotBlank();
    }

    private FulfillmentOutboxRelayService service(
            FakeRepository repository, RecordingPublisher publisher, RecordingStatusPublisher statusPublisher
    ) {
        return service(repository, publisher, statusPublisher, CLOCK);
    }

    private FulfillmentOutboxRelayService service(
            FakeRepository repository, RecordingPublisher publisher,
            RecordingStatusPublisher statusPublisher, Clock clock
    ) {
        return new FulfillmentOutboxRelayService(
                repository, publisher, statusPublisher, new tools.jackson.databind.ObjectMapper(),
                25, Duration.ofSeconds(30), clock);
    }

    private static FulfillmentOutboxCandidate candidate(long id, int retryCount) {
        return candidate(id, "FULFILLMENT_TASK_READY", retryCount);
    }

    private static FulfillmentOutboxCandidate candidate(long id, String eventType, int retryCount) {
        String payload = FulfillmentStatusChangedPublisher.EVENT_TYPE.equals(eventType)
                ? "{\"eventId\":\"EVENT-" + id + "\",\"fulfillmentNo\":\"TASK-" + id
                + "\",\"shippingNo\":\"SHIP-" + id + "\",\"sourceType\":\"LOTTERY_BENEFIT\","
                + "\"sourceId\":\"BENEFIT-" + id + "\",\"status\":\"DELIVERED\","
                + "\"occurredAt\":\"2026-09-27T04:00:00\"}"
                : "{\"eventId\":\"EVENT-" + id + "\",\"fulfillmentNo\":\"TASK-" + id
                + "\",\"occurredAt\":\"2026-09-27T04:00:00\"}";
        return new FulfillmentOutboxCandidate(id, eventType, payload, retryCount);
    }

    private static final class FakeRepository implements FulfillmentOutboxRepository {
        private final List<FulfillmentOutboxCandidate> candidates;
        private final List<Long> claimableIds = new ArrayList<>();
        private final List<Claim> claims = new ArrayList<>();
        private final List<Long> sentIds = new ArrayList<>();
        private final List<Failure> failures = new ArrayList<>();

        private FakeRepository(List<FulfillmentOutboxCandidate> candidates) {
            this.candidates = candidates;
        }

        @Override
        public List<FulfillmentOutboxCandidate> findRelayCandidates(LocalDateTime now, int limit) {
            return candidates.stream().limit(limit).toList();
        }

        @Override
        public boolean claimForRelay(long id, String claimToken, LocalDateTime now, LocalDateTime claimUntil) {
            claims.add(new Claim(id, claimToken, now, claimUntil));
            return claimableIds.contains(id);
        }

        @Override
        public int markSent(long id, String claimToken, LocalDateTime sentAt) {
            sentIds.add(id);
            return 1;
        }

        @Override
        public int markFailed(long id, String claimToken, String error, LocalDateTime retryAt) {
            failures.add(new Failure(id, claimToken, error, retryAt));
            return 1;
        }
    }

    private static final class RecordingPublisher implements FulfillmentTaskReadyPublisher {
        private final List<FulfillmentTaskReadyEvent> events = new ArrayList<>();
        private RuntimeException failure;
        private Runnable beforeNextPublish;

        @Override
        public void publish(FulfillmentTaskReadyEvent event) {
            if (beforeNextPublish != null) {
                Runnable action = beforeNextPublish;
                beforeNextPublish = null;
                action.run();
            }
            if (failure != null) {
                throw failure;
            }
            events.add(event);
        }
    }

    private static final class RecordingStatusPublisher implements FulfillmentStatusChangedPublisher {
        private final List<FulfillmentStatusChangedEventV1> events = new ArrayList<>();

        @Override
        public void publish(FulfillmentStatusChangedEventV1 event) {
            events.add(event);
        }
    }

    private record Claim(long id, String claimToken, LocalDateTime now, LocalDateTime claimUntil) {
    }

    private record Failure(long id, String claimToken, String error, LocalDateTime retryAt) {
    }

    private static final class MutableClock extends Clock {
        private final AtomicReference<Instant> instant;

        private MutableClock(Instant initial) {
            instant = new AtomicReference<>(initial);
        }

        @Override
        public ZoneId getZone() {
            return ZoneOffset.UTC;
        }

        @Override
        public Clock withZone(ZoneId zone) {
            if (ZoneOffset.UTC.equals(zone)) {
                return this;
            }
            return Clock.fixed(instant.get(), zone);
        }

        @Override
        public Instant instant() {
            return instant.get();
        }

        private void advance(Duration duration) {
            instant.updateAndGet(current -> current.plus(duration));
        }
    }
}

package com.dongqh.fulfillmentservice.service;

import com.dongqh.fulfillmentservice.enums.FulfillmentStatus;
import com.dongqh.fulfillmentservice.enums.FulfillmentType;
import com.dongqh.fulfillmentservice.domain.model.CouponFulfillmentPayload;
import com.dongqh.fulfillmentservice.domain.model.CreateFulfillmentTaskCommand;
import com.dongqh.fulfillmentservice.domain.model.FulfillmentTaskRecord;
import com.dongqh.fulfillmentservice.persistence.DuplicateFulfillmentTaskException;
import com.dongqh.fulfillmentservice.persistence.FulfillmentTaskRepository;
import com.dongqh.fulfillmentservice.service.port.FulfillmentTaskReadyOutbox;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.ObjectMapper;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class FulfillmentTaskCreationServiceTests {

    private final InMemoryRepository repository = new InMemoryRepository();
    private final RecordingOutbox outbox = new RecordingOutbox();
    private final FulfillmentTaskCreationService service = new FulfillmentTaskCreationService(
            repository,
            outbox,
            new ObjectMapper(),
            Clock.fixed(Instant.parse("2026-09-27T04:00:00Z"), ZoneOffset.UTC)
    );

    @Test
    void createsPendingTaskAndAppendsOneReadyEvent() {
        FulfillmentTaskRecord task = service.create(command("TASK-1", "SUMMER"));

        assertThat(task.fulfillmentNo()).isEqualTo("TASK-1");
        assertThat(task.status()).isEqualTo(FulfillmentStatus.PENDING);
        assertThat(task.attemptCount()).isZero();
        assertThat(task.maxAttempts()).isEqualTo(5);
        assertThat(task.nextAttemptAt()).isEqualTo(LocalDateTime.of(2026, 9, 27, 4, 0));
        assertThat(task.requestPayload()).contains("SUMMER");
        assertThat(task.requestFingerprint()).matches("[0-9a-f]{64}");
        assertThat(outbox.fulfillmentNumbers).containsExactly("TASK-1");
    }

    @Test
    void identicalCommandReplayReturnsExistingTaskWithoutDuplicatingEvent() {
        FulfillmentTaskRecord first = service.create(command("TASK-2", "SUMMER"));

        FulfillmentTaskRecord replay = service.create(command("TASK-2", "SUMMER"));

        assertThat(replay.id()).isEqualTo(first.id());
        assertThat(replay.requestFingerprint()).isEqualTo(first.requestFingerprint());
        assertThat(outbox.fulfillmentNumbers).containsExactly("TASK-2");
    }

    @Test
    void conflictingCommandReplayIsRejectedWithoutAppendingEvent() {
        service.create(command("TASK-3", "SUMMER"));

        assertThatThrownBy(() -> service.create(command("TASK-3", "WINTER")))
                .isInstanceOf(FulfillmentTaskIdempotencyConflictException.class);
        assertThat(outbox.fulfillmentNumbers).containsExactly("TASK-3");
    }

    private CreateFulfillmentTaskCommand command(String fulfillmentNo, String templateCode) {
        return new CreateFulfillmentTaskCommand(
                fulfillmentNo,
                "LOTTERY_REWARD",
                "DRAW-1",
                FulfillmentType.COUPON,
                11L,
                new CouponFulfillmentPayload(templateCode, 1),
                null
        );
    }

    private static final class InMemoryRepository implements FulfillmentTaskRepository {
        private final Map<String, FulfillmentTaskRecord> tasks = new HashMap<>();
        private final AtomicLong ids = new AtomicLong(100);

        @Override
        public Optional<FulfillmentTaskRecord> findByFulfillmentNo(String fulfillmentNo) {
            return Optional.ofNullable(tasks.get(fulfillmentNo));
        }

        @Override
        public FulfillmentTaskRecord insert(FulfillmentTaskRecord task) {
            if (tasks.containsKey(task.fulfillmentNo())) {
                throw new DuplicateFulfillmentTaskException(task.fulfillmentNo());
            }
            FulfillmentTaskRecord stored = task.withId(ids.incrementAndGet());
            tasks.put(task.fulfillmentNo(), stored);
            return stored;
        }
    }

    private static final class RecordingOutbox implements FulfillmentTaskReadyOutbox {
        private final java.util.List<String> fulfillmentNumbers = new java.util.ArrayList<>();

        @Override
        public void appendTaskReady(String fulfillmentNo) {
            fulfillmentNumbers.add(fulfillmentNo);
        }
    }
}

package com.dongqh.fulfillmentservice.service;

import com.dongqh.fulfillmentservice.enums.FulfillmentStatus;
import com.dongqh.fulfillmentservice.enums.FulfillmentType;
import com.dongqh.fulfillmentservice.domain.model.FulfillmentTaskView;
import com.dongqh.fulfillmentservice.persistence.FulfillmentTaskDetails;
import com.dongqh.fulfillmentservice.persistence.FulfillmentTaskOperationRepository;
import com.dongqh.fulfillmentservice.persistence.FulfillmentTaskOperationSnapshot;
import com.dongqh.fulfillmentservice.persistence.FulfillmentTaskQueryRepository;
import com.dongqh.fulfillmentservice.service.port.FulfillmentTaskReadyOutbox;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.ObjectMapper;

import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class FulfillmentTaskOperationServiceTests {

    @Test
    void retryingQuarantinedTaskClearsQuarantineAndAppendsReadyEvent() {
        MutableQueryRepository queryRepository = new MutableQueryRepository(
                details(FulfillmentStatus.QUARANTINED));
        FakeOperationRepository operations = new FakeOperationRepository(queryRepository,
                FulfillmentStatus.QUARANTINED);
        RecordingOutbox outbox = new RecordingOutbox();

        FulfillmentTaskView view = service(queryRepository, operations, outbox)
                .retryQuarantined(" TASK-1 ", 8, " operator note ");

        assertThat(view.status()).isEqualTo(FulfillmentStatus.PENDING);
        assertThat(operations.retryTaskId).isEqualTo(42L);
        assertThat(operations.resolution).isEqualTo("RETRY");
        assertThat(operations.operatorId).isEqualTo(8L);
        assertThat(operations.note).isEqualTo("operator note");
        assertThat(outbox.fulfillmentNumbers).containsExactly("TASK-1");
    }

    @Test
    void terminatingRetryableTaskClearsLeaseAndResolvesQuarantineWithoutOutbox() {
        MutableQueryRepository queryRepository = new MutableQueryRepository(
                details(FulfillmentStatus.RETRY_WAITING));
        FakeOperationRepository operations = new FakeOperationRepository(queryRepository,
                FulfillmentStatus.RETRY_WAITING);
        RecordingOutbox outbox = new RecordingOutbox();

        FulfillmentTaskView view = service(queryRepository, operations, outbox)
                .terminate("TASK-1", 9, "x".repeat(600));

        assertThat(view.status()).isEqualTo(FulfillmentStatus.TERMINATED);
        assertThat(operations.terminateTaskId).isEqualTo(42L);
        assertThat(operations.resolution).isEqualTo("TERMINATED");
        assertThat(operations.operatorId).isEqualTo(9L);
        assertThat(operations.note).hasSize(500);
        assertThat(outbox.fulfillmentNumbers).isEmpty();
    }

    @Test
    void refusesRetryAndTerminationForDisallowedStates() {
        for (FulfillmentStatus status : new FulfillmentStatus[]{
                FulfillmentStatus.PENDING,
                FulfillmentStatus.PROCESSING,
                FulfillmentStatus.SUCCEEDED,
                FulfillmentStatus.RETRY_WAITING,
                FulfillmentStatus.RECONCILING,
                FulfillmentStatus.TERMINATED}) {
            MutableQueryRepository queryRepository = new MutableQueryRepository(details(status));
            FakeOperationRepository operations = new FakeOperationRepository(queryRepository, status);
            RecordingOutbox outbox = new RecordingOutbox();
            FulfillmentTaskOperationService service = service(queryRepository, operations, outbox);

            assertThatThrownBy(() -> service.retryQuarantined("TASK-1", 10, null))
                    .isInstanceOf(FulfillmentTaskOperationNotAllowedException.class);
            assertThat(operations.retryTaskId).isNull();
            assertThat(outbox.fulfillmentNumbers).isEmpty();
        }

        for (FulfillmentStatus status : new FulfillmentStatus[]{
                FulfillmentStatus.PROCESSING, FulfillmentStatus.SUCCEEDED}) {
            MutableQueryRepository queryRepository = new MutableQueryRepository(details(status));
            FakeOperationRepository operations = new FakeOperationRepository(queryRepository, status);
            RecordingOutbox outbox = new RecordingOutbox();
            FulfillmentTaskOperationService service = service(queryRepository, operations, outbox);

            assertThatThrownBy(() -> service.terminate("TASK-1", 10, null))
                    .isInstanceOf(FulfillmentTaskOperationNotAllowedException.class);
            assertThat(operations.terminateTaskId).isNull();
            assertThat(outbox.fulfillmentNumbers).isEmpty();
        }
    }

    @Test
    void repeatedTerminationIsIdempotent() {
        MutableQueryRepository queryRepository = new MutableQueryRepository(
                details(FulfillmentStatus.TERMINATED));
        FakeOperationRepository operations = new FakeOperationRepository(queryRepository,
                FulfillmentStatus.TERMINATED);

        FulfillmentTaskView view = service(queryRepository, operations, new RecordingOutbox())
                .terminate("TASK-1", 11, null);

        assertThat(view.status()).isEqualTo(FulfillmentStatus.TERMINATED);
        assertThat(operations.terminateTaskId).isNull();
    }

    @Test
    void requiresExistingTaskAndPositiveOperatorId() {
        MutableQueryRepository queryRepository = new MutableQueryRepository(null);
        FakeOperationRepository operations = new FakeOperationRepository(queryRepository, null);
        FulfillmentTaskOperationService service = service(queryRepository, operations, new RecordingOutbox());

        assertThatThrownBy(() -> service.terminate("MISSING", 1, null))
                .isInstanceOf(FulfillmentTaskNotFoundException.class);
        queryRepository.details = details(FulfillmentStatus.RETRY_WAITING);
        operations.status = FulfillmentStatus.RETRY_WAITING;
        assertThatThrownBy(() -> service.terminate("TASK-1", 0, null))
                .isInstanceOf(IllegalArgumentException.class);
    }

    private static FulfillmentTaskOperationService service(
            MutableQueryRepository queryRepository,
            FakeOperationRepository operations,
            RecordingOutbox outbox
    ) {
        return new FulfillmentTaskOperationService(
                operations,
                new FulfillmentTaskReadService(queryRepository, new ObjectMapper()),
                outbox
        );
    }

    private static FulfillmentTaskDetails details(FulfillmentStatus status) {
        return new FulfillmentTaskDetails(
                42L, "TASK-1", "LOTTERY_REWARD", "DRAW-1", FulfillmentType.COUPON, 17L,
                "{\"couponTemplateCode\":\"WELCOME\",\"quantity\":1}", "0".repeat(64), status,
                2, 5, null, null, null, null, null, null, null, null);
    }

    private static final class MutableQueryRepository implements FulfillmentTaskQueryRepository {
        private FulfillmentTaskDetails details;

        private MutableQueryRepository(FulfillmentTaskDetails details) {
            this.details = details;
        }

        @Override
        public Optional<FulfillmentTaskDetails> findByFulfillmentNo(String fulfillmentNo) {
            return details == null ? Optional.empty() : Optional.of(details);
        }

        @Override
        public java.util.List<com.dongqh.fulfillmentservice.persistence.FulfillmentTaskStatus> findLotteryStatusByFulfillmentNos(
                java.util.Collection<String> fulfillmentNos) {
            return java.util.List.of();
        }

        @Override
        public java.util.List<FulfillmentTaskDetails> findPage(
                com.dongqh.fulfillmentservice.domain.model.FulfillmentTaskQuery query) {
