package com.dongqh.hmgateway.utils;

import com.hmall.common.exception.UnauthorizedException;

public final class AuthorizationContext {
    private static final ThreadLocal<String> AUTHORIZATION = new ThreadLocal<>();

    private AuthorizationContext() {
    }

    public static void set(String authorization) {
        AUTHORIZATION.set(authorization);
    }

    public static String require() {
        String authorization = AUTHORIZATION.get();
        if (authorization == null || authorization.isBlank()) {
            throw new UnauthorizedException("未登录");
        }
        return authorization;
    }

    public static void remove() {
        AUTHORIZATION.remove();
    }
}

package com.dongqh.hmgateway.utils;

import cn.hutool.core.exceptions.ValidateException;
import cn.hutool.jwt.JWT;
import cn.hutool.jwt.JWTValidator;
import cn.hutool.jwt.signers.JWTSigner;
import cn.hutool.jwt.signers.JWTSignerUtil;
import com.hmall.common.exception.UnauthorizedException;
import org.springframework.stereotype.Component;

import java.security.PublicKey;
import java.util.Date;

@Component
public class JwtTool {
    private final JWTSigner jwtSigner;

    public JwtTool(PublicKey publicKey) {
        this.jwtSigner = JWTSignerUtil.rs256(publicKey);
    }

    /**
     * 解析token
     *
     * @param token token
     * @return 解析刷新token得到的用户信息
     */
    public Long parseToken(String token) {
        // 1.校验token是否为空
        if (token == null) {
            throw new UnauthorizedException("未登录");
        }
        // 2.校验并解析jwt
        JWT jwt;
        try {
            jwt = JWT.of(token).setSigner(jwtSigner);
        } catch (Exception e) {
            throw new UnauthorizedException("无效的token", e);
        }
        // 2.校验jwt是否有效
        if (!jwt.verify()) {
            // 验证失败
            throw new UnauthorizedException("无效的token");
        }
        // 3.校验是否过期
        try {
            JWTValidator.of(jwt).validateDate();
        } catch (ValidateException e) {
            throw new UnauthorizedException("token已经过期");
        }
        // 4.数据格式校验
        Object userPayload = jwt.getPayload("user");
        if (userPayload == null) {
            // 数据为空
            throw new UnauthorizedException("无效的token");
        }

        // 5.数据解析
        try {
           return Long.valueOf(userPayload.toString());
        } catch (RuntimeException e) {
            // 数据格式有误
            throw new UnauthorizedException("无效的token");
        }
    }
}

package com.dongqh.hmgateway.filters;

import com.dongqh.hmgateway.config.AuthProperties;
import com.dongqh.hmgateway.utils.JwtTool;
import com.hmall.common.exception.UnauthorizedException;
import org.junit.jupiter.api.Test;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.mock.http.server.reactive.MockServerHttpRequest;
import org.springframework.mock.web.server.MockServerWebExchange;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

import java.util.List;
import java.util.concurrent.atomic.AtomicReference;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class AuthGlobalFilterTest {

    @Test
    void anonymousGetRouteIsMatchedByMethodAndDropsForgedUserInfo() {
        AuthProperties properties = properties("GET /items/**");
        JwtTool jwtTool = rejectingJwtTool();
        AuthGlobalFilter filter = new AuthGlobalFilter(properties, jwtTool);
        AtomicReference<ServerWebExchange> forwarded = new AtomicReference<>();

        MockServerWebExchange exchange = MockServerWebExchange.from(
                MockServerHttpRequest.get("/items/1").header("user-info", "999")
        );
        filter.filter(exchange, capture(forwarded)).block();

        assertThat(forwarded.get()).isNotNull();
        assertThat(forwarded.get().getRequest().getHeaders().getFirst("user-info")).isNull();
    }

    @Test
    void anonymousWriteToPublicReadPathIsRejected() {
        AuthProperties properties = properties("GET /items/**");
        AuthGlobalFilter filter = new AuthGlobalFilter(properties, rejectingJwtTool());
        AtomicReference<ServerWebExchange> forwarded = new AtomicReference<>();
        MockServerWebExchange exchange = MockServerWebExchange.from(
                MockServerHttpRequest.post("/items")
        );

        filter.filter(exchange, capture(forwarded)).block();

        assertThat(forwarded.get()).isNull();
        assertThat(exchange.getResponse().getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);
    }

    @Test
    void authenticatedRouteOverwritesForgedUserInfoWithVerifiedIdentity() {
        AuthProperties properties = properties();
        JwtTool jwtTool = mock(JwtTool.class);
        when(jwtTool.parseToken("valid-token")).thenReturn(42L);
        AuthGlobalFilter filter = new AuthGlobalFilter(properties, jwtTool);
        AtomicReference<ServerWebExchange> forwarded = new AtomicReference<>();
        MockServerWebExchange exchange = MockServerWebExchange.from(
                MockServerHttpRequest.get("/orders/me")
                        .header(HttpHeaders.AUTHORIZATION, "valid-token")
                        .header("user-info", "999")
        );

        filter.filter(exchange, capture(forwarded)).block();

        assertThat(forwarded.get()).isNotNull();
        assertThat(forwarded.get().getRequest().getHeaders().get("user-info"))
                .containsExactly("42");
    }

    @Test
    void authenticatedBearerTokenIsNormalizedForVerificationAndPreservedWhenForwarded() {
        AuthProperties properties = properties();
        JwtTool jwtTool = mock(JwtTool.class);
        when(jwtTool.parseToken(any())).thenAnswer(invocation -> {
            if ("valid-token".equals(invocation.getArgument(0))) {
                return 42L;
            }
            throw new UnauthorizedException("未登录");
        });
        AuthGlobalFilter filter = new AuthGlobalFilter(properties, jwtTool);
        AtomicReference<ServerWebExchange> forwarded = new AtomicReference<>();
        String authorization = "bEaReR valid-token";
        MockServerWebExchange exchange = MockServerWebExchange.from(
                MockServerHttpRequest.get("/orders/me")
                        .header(HttpHeaders.AUTHORIZATION, authorization)
                        .header("user-info", "999")
        );

        filter.filter(exchange, capture(forwarded)).block();

        assertThat(forwarded.get()).isNotNull();
        assertThat(forwarded.get().getRequest().getHeaders().get("user-info"))
                .containsExactly("42");
        assertThat(forwarded.get().getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION))
                .isEqualTo(authorization);
    }

    @Test
    void onlyExactPostLogisticsCallbackIsAnonymousAndSanitizesIdentity() {
        AuthGlobalFilter filter = new AuthGlobalFilter(
                properties("POST /api/shipping/callbacks/logistics"), rejectingJwtTool());
        AtomicReference<ServerWebExchange> forwarded = new AtomicReference<>();

        MockServerWebExchange post = MockServerWebExchange.from(
                MockServerHttpRequest.post("/api/shipping/callbacks/logistics")
                        .header("user-info", "999"));
        filter.filter(post, capture(forwarded)).block();
        assertThat(forwarded.get()).isNotNull();
        assertThat(forwarded.get().getRequest().getHeaders().getFirst("user-info")).isNull();

        forwarded.set(null);
        MockServerWebExchange get = MockServerWebExchange.from(
                MockServerHttpRequest.get("/api/shipping/callbacks/logistics"));
        filter.filter(get, capture(forwarded)).block();
        assertThat(forwarded.get()).isNull();
        assertThat(get.getResponse().getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);

        forwarded.set(null);
        MockServerWebExchange nestedPost = MockServerWebExchange.from(
                MockServerHttpRequest.post("/api/shipping/callbacks/logistics/extra"));
        filter.filter(nestedPost, capture(forwarded)).block();
        assertThat(forwarded.get()).isNull();
        assertThat(nestedPost.getResponse().getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);
    }

    @Test
    void paymentCallbackIsNotAnonymousWithoutJwt() {
        AuthGlobalFilter filter = new AuthGlobalFilter(
                properties("POST /api/shipping/callbacks/logistics"), rejectingJwtTool());
        AtomicReference<ServerWebExchange> forwarded = new AtomicReference<>();
        MockServerWebExchange exchange = MockServerWebExchange.from(
                MockServerHttpRequest.post("/callbacks/payments"));

        filter.filter(exchange, capture(forwarded)).block();

        assertThat(forwarded.get()).isNull();
        assertThat(exchange.getResponse().getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);
    }

    private AuthProperties properties(String... excludePaths) {
        AuthProperties properties = new AuthProperties();
        properties.setExcludePaths(List.of(excludePaths));
        return properties;
    }

    private JwtTool rejectingJwtTool() {
        JwtTool jwtTool = mock(JwtTool.class);
        when(jwtTool.parseToken(any())).thenThrow(new UnauthorizedException("未登录"));
        return jwtTool;
    }

    private GatewayFilterChain capture(AtomicReference<ServerWebExchange> forwarded) {
        return exchange -> {
            forwarded.set(exchange);
            return Mono.empty();
        };
    }
}

package com.dongqh.hmgateway;

import com.dongqh.hmgateway.config.AuthProperties;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.cloud.gateway.route.RouteDefinition;
import org.springframework.cloud.gateway.route.RouteDefinitionLocator;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest(properties = {
        "spring.cloud.nacos.discovery.enabled=false",
        "spring.cloud.nacos.discovery.register-enabled=false"
})
class HmGatewayApplicationTests {

    @Autowired
    private RouteDefinitionLocator routeDefinitionLocator;

    @Autowired
    private AuthProperties authProperties;

    @Test
    void contextLoads() {
    }

    @Test
    void routesMarketingDomainsToExtractedServices() {
        List<RouteDefinition> routeDefinitions = routeDefinitionLocator.getRouteDefinitions()
                .collectList()
                .blockOptional()
                .orElseThrow();
        Map<String, String> routes = routeDefinitions.stream()
                .collect(Collectors.toMap(RouteDefinition::getId, route -> route.getUri().toString()));

        assertEquals(Map.ofEntries(
                Map.entry("item-service", "lb://item-service"),
                Map.entry("cart-service", "lb://cart-service"),
                Map.entry("user-service", "lb://user-service"),
                Map.entry("trade-service", "lb://trade-service"),
                Map.entry("pay-service", "lb://pay-service"),
                Map.entry("points-service", "lb://points-service"),
                Map.entry("coupon-service", "lb://coupon-service"),
                Map.entry("membership-service", "lb://membership-service"),
                Map.entry("lottery-service", "lb://lottery-service"),
                Map.entry("fulfillment-service", "lb://fulfillment-service")
        ), routes);
        assertEquals(List.of(
                "item-service",
                "cart-service",
                "user-service",
                "trade-service",
                "pay-service",
                "points-service",
                "coupon-service",
                "membership-service",
                "lottery-service",
                "fulfillment-service"
        ), routeDefinitions.stream().map(RouteDefinition::getId).toList());
    }

    @Test
    void keepsAnonymousPaths() {
        assertTrue(authProperties.getExcludePaths().containsAll(java.util.List.of(
                "GET /search/**",
                "POST /search/filters",
                "POST /users/login",
                "GET /items/**",
                "GET /hi"
        )));
    }

}

