#toggle-button{
    display: none;
}
.button-label{
    position: relative;
    display: inline-block;
    width: 68px;
    background-color: #ccc;
    border: #ccc;
    border-radius: 30px;
    cursor: pointer;
    box-shadow:inset 0 0 3px 1px rgba(0, 0, 0, 0.4);
}
.circle{
    position: absolute;
    top: 0;
    left: 0;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background-color: #fff;
    box-shadow: 0 0 3px 1px rgba(0, 0, 0, 0.5);
}
.button-label .text {
    line-height: 20px;
    font-size: 12px;

    /*
    用来阻止页面文字被选中，出现蓝色
    可以将下面两行代码注释掉来查看区别
    */
    -webkit-user-select: none;
    user-select: none;
}
.on {
    color: #fff;
    display: none;
    text-indent: 0;
}
.off {
    color: #fff;
    display: inline-block;
    text-indent: 0;
}
.button-label .circle{
    left: 0;
    transition: all 0.3s;/*transition过度，时间为0.3秒*/
}

/*
以下是checked被选中后，紧跟checked标签后面label的样式。
例如：div+p 选择所有紧接着<div>元素之后的<p>元素
*/
#toggle-button:checked + label.button-label .circle{
    left: 49px;
}
#toggle-button:checked + label.button-label .on{
    display: inline-block;
}
#toggle-button:checked + label.button-label .off{
    display: none;
}
#toggle-button:checked + label.button-label{
    background-color: #FF8800;
}


.banner{
    width: 100%;
    display: flex;
    justify-content: space-between;
    padding-top: 10px;
}

.logo{
    width: 150px;
}

.container{
    width: 100%;
    height: 500px;
    background-color: #fff;
    /*border-bottom: #fff 3px solid;*/
    box-shadow: 0 1px 3px rgba(0,0,0,.1);
}
.tab-wrapper{
    position: relative;
    width: 100%;
    height: 60px;
    border-bottom: #a4a3a3 3px solid;
    /*background-color: #df3033;*/
}
.tab-wrapper .tab-radio{
    display: none;
}
.tab-handler{
    position: relative;
    z-index: 2;
    display: block;
    float: left;
    height: 60px;
    padding: 0 40px;
    color: #717181;
    font-size: 16px;
    line-height: 60px;
    /*transition: .3s;*/
    transform: scale(.9);
}
.tab-selected{
    color: #717181;
    border-bottom: #df3033 3px solid;
    background-color: #fff0f0;
    transform: scale(1);
}
.tab-wrapper .tab-content{
    position: absolute;
    top: 60px;
    left: 0;
    padding: 0 30px;
    color: #999;
    font-size: 14px;
    line-height: 1.618em;
    background-color: #fff;
    transition: transform .5s, opacity .7s;
    transform: translateY(20px);
}

.search-bar {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.search-box {
    display: flex;
    width: 35%;
}

.search-bar input {
    border: 1px solid #df3033;
    width: 85%;
    height: 28px;
    line-height: 28px;
    vertical-align: top;
    border-radius: .25rem 0 0 .25rem;
}

.search-bar button {
    width: 20%;
    border: 1px solid #df3033;
    background-color: #df3033;
    color: #fff;
    line-height: 28px;
    margin-left: -6px;
    border-radius: 0 .25rem .25rem 0;
}
.ad-mark {
    position: absolute;
    left: 5px;
    top: -10px;
}
#complete-box {
    margin-top: 28px;
    position: absolute;
    z-index: 99;
    text-align: left;
    border: 1px solid #f1f1f2;
    width: 336px;
    height: 120px;
    background-color: #fff;
}
em {
  color:#df3033;
}
#complete-box div {
    padding-left: 7px;
}

.btn {
    height: 34px;
    line-height: 34px;
    padding: 0 12px;
    font-size: 16px;
    font-family: "Arial", "PingFang SC", "Microsoft Yahei", "SimSun", sans-serif;
    color: #FFF;
    background: #df3033;
    border-color: #df3033;
    vertical-align: top;
    text-align: center;
    display: inline-block;
    box-sizing: content-box;
    cursor: pointer;
    border-radius: 3px;
}

em {
    color: red;
    font-style: normal;
}

.selected {
    color: red;
}

.filter-list {
    padding: 5px 0;
    background: #fff;
    border-radius: 3px;
    box-shadow: 0 1px 3px 1px rgba(0, 0, 0, 0.2);
}

.filter-box {
    display: flex;
    align-content: center;
    position: relative;
    line-height: 24px;
}

.f-key {
    font-size: 12px;
    color: #666;
    width: 10%;
    text-align: center;
    margin: auto;
    line-height: 100%;
}

.column-divider {
    width: 2px;
    border-radius: 1px;
    box-shadow: 1px 0 0 rgba(0, 0, 0, .2) inset, -1px 0 0 rgba(255, 255, 255, .2) inset;
}

.row-divider {
    margin: auto;
    width: 98%;
    border-radius: 1px;
    height: 3px;
    box-shadow: 0 1px 0 rgba(0, 0, 0, .2) inset, 0 -1px 0 rgba(255, 255, 255, .2) inset;
}

a {
    text-decoration: none;
    color: #999;
}

.filter-item a:hover {
    color: #df3033;
}

.filter-items {
    width: 85%;
    display: flex;
    flex-wrap: wrap;
    align-content: center;
}

.filter-item {
    width: 80px;
    line-height: 30px;
    font-size: 12px;
}

.btn-arrow {
    border-radius: 3px;
}

.btn-arrow,
.btn-arrow:visited,
.btn-arrow:link,
.btn-arrow:active {
    width: 46px;
    height: 23px;
    border: 1px solid #DDD;
    background: #FFF;
    line-height: 23px;
    font-family: "\5b8b\4f53";
    text-align: center;
    font-size: 16px;
    color: #AAA;
    text-decoration: none;
    out-line: none
}

.btn-arrow:hover {
    background-color: #df3033;
    color: whitesmoke;
}
.sort-item a{
    text-decoration:none;
}
.sort-item {
    display: inline;
    width: 50px;
    float: left;
    font-size: 13px;
}

.selected-ops {
    display: flex;
    align-items: center;
}

.open {
    font-size: 12px;
    margin-left: 10px;
    line-height: 24px;
    margin-bottom: 3px;
