	position: relative
}

.shopArea .shopcar a {
	padding: 4px 42px
}

.shopArea .car {
	background-image: url(../img/icons.png);
	background-position: 160px -81px;
	position: absolute;
	width: 30px;
	height: 30px;
	padding: 0 7px
}

.shopcar .btn-default {
	border: 1px solid #dfdfdf;
	background: #f7f7f7;
	border-radius: 0;
	font-size: 12px
}

.shopcarlist {
	width: 194px;
	margin: -1px 0 0 -70px;
	border: 1px solid #dadada;
	padding: 10px;
