package com.dongqh.lotteryservice.config;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.time.Duration;
import java.time.ZoneId;

@ConfigurationProperties(prefix = "luckyhub.lottery")
public record LotteryProperties(
        ZoneId zoneId,
        Duration lockWait,
        Duration processingTimeout,
        Duration reconcileInterval,
        Duration reconcileInitialDelay,
        int reconcileBatchSize,
        Duration outboxInterval,
        int outboxBatchSize
) {
    public LotteryProperties {
        if (zoneId == null) {
            throw new IllegalArgumentException("zoneId must not be null");
        }
        requirePositive(lockWait, "lockWait");
        requirePositive(processingTimeout, "processingTimeout");
        requirePositive(reconcileInterval, "reconcileInterval");
        if (reconcileInitialDelay == null || reconcileInitialDelay.isNegative()) {
            throw new IllegalArgumentException("reconcileInitialDelay must not be negative");
        }
        if (reconcileBatchSize <= 0) {
            throw new IllegalArgumentException("reconcileBatchSize must be positive");
        }
        requirePositive(outboxInterval, "outboxInterval");
        if (outboxBatchSize <= 0) {
            throw new IllegalArgumentException("outboxBatchSize must be positive");
        }
    }

    private static void requirePositive(Duration value, String name) {
        if (value == null || value.isZero() || value.isNegative()) {
            throw new IllegalArgumentException(name + " must be positive");
        }
    }
}

package com.dongqh.lotteryservice.config.prizecatalog;

import com.aliyun.sdk.service.oss2.OSSClient;
import com.aliyun.sdk.service.oss2.credentials.StaticCredentialsProvider;
import com.dongqh.lotteryservice.integration.prizecatalog.AliyunOssObjectStorageGateway;
import com.dongqh.lotteryservice.integration.prizecatalog.ObjectStorageGateway;
import com.dongqh.lotteryservice.integration.prizecatalog.UnavailableObjectStorageGateway;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration(proxyBeanMethods = false)
@EnableConfigurationProperties(OssProperties.class)
public class OssConfiguration {

    @Bean
    public ObjectStorageGateway objectStorageGateway(OssProperties properties) {
        if (!properties.enabled() || !properties.isComplete()) {
            return new UnavailableObjectStorageGateway();
        }
        OSSClient client = OSSClient.newBuilder()
                .region(properties.region())
                .endpoint(properties.endpoint())
                .credentialsProvider(new StaticCredentialsProvider(
                        properties.accessKeyId(), properties.accessKeySecret()))
                .build();
        return new AliyunOssObjectStorageGateway(client, properties.bucket());
    }
}

package com.dongqh.lotteryservice.config.prizecatalog;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.util.StringUtils;

@ConfigurationProperties(prefix = "luckyhub.oss")
public record OssProperties(
        boolean enabled,
        String region,
        String endpoint,
        String bucket,
        String accessKeyId,
        String accessKeySecret,
        String publicBaseUrl
) {

    public boolean isComplete() {
        return StringUtils.hasText(region)
                && StringUtils.hasText(endpoint)
                && StringUtils.hasText(bucket)
                && StringUtils.hasText(accessKeyId)
                && StringUtils.hasText(accessKeySecret)
                && StringUtils.hasText(publicBaseUrl);
    }

    public String normalizedPublicBaseUrl() {
        if (!StringUtils.hasText(publicBaseUrl)) {
            return "";
        }
        return publicBaseUrl.trim().replaceAll("/+$", "");
    }
}

