import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.convert.DurationStyle;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.Objects;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

@Component
@ConditionalOnProperty(prefix = "luckyhub.lottery.outbox", name = "enabled", havingValue = "true")
public class RabbitDrawEventPublisher implements DrawEventPublisher {
    private final RabbitTemplate rabbitTemplate;
    private final Duration confirmTimeout;

    @Autowired
    public RabbitDrawEventPublisher(RabbitTemplate rabbitTemplate,
                                    @Value("${luckyhub.lottery.outbox.publisher-confirm-timeout:5s}") String confirmTimeout) {
        this(rabbitTemplate, DurationStyle.detectAndParse(confirmTimeout));
    }

    public RabbitDrawEventPublisher(RabbitTemplate rabbitTemplate, Duration confirmTimeout) {
        this.rabbitTemplate = Objects.requireNonNull(rabbitTemplate, "rabbitTemplate must not be null");
        if (confirmTimeout == null || confirmTimeout.isZero() || confirmTimeout.isNegative()) {
            throw new IllegalArgumentException("confirmTimeout must be positive");
        }
        this.confirmTimeout = confirmTimeout;
    }

    @Override
    public void publish(DrawEventEnvelope event) {
        Objects.requireNonNull(event, "event must not be null");
        CorrelationData correlation = new CorrelationData(event.eventId().toString());
        rabbitTemplate.convertAndSend(LotteryRabbitTopology.EVENT_EXCHANGE,
                LotteryRabbitTopology.routingKey(event.eventType()), event, correlation);
        CorrelationData.Confirm confirm = awaitConfirm(event, correlation);
        ReturnedMessage returned = correlation.getReturned();
        if (returned != null) {
            throw new AmqpException("RabbitMQ returned unroutable lottery event "
                    + event.eventId() + ": " + returned.getReplyText());
        }
        if (!confirm.ack()) {
            String reason = confirm.reason() == null ? "unknown reason" : confirm.reason();
            throw new AmqpException("RabbitMQ NACK for lottery event " + event.eventId() + ": " + reason);
        }
    }

    private CorrelationData.Confirm awaitConfirm(DrawEventEnvelope event, CorrelationData correlation) {
        try {
            return correlation.getFuture().get(confirmTimeout.toMillis(), TimeUnit.MILLISECONDS);
        } catch (TimeoutException exception) {
            throw new AmqpException("RabbitMQ confirm timed out for lottery event " + event.eventId(), exception);
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            throw new AmqpException("Interrupted while waiting for RabbitMQ confirm for lottery event " + event.eventId(), exception);
        } catch (ExecutionException exception) {
            throw new AmqpException("RabbitMQ confirm failed for lottery event " + event.eventId(), exception.getCause());
        }
    }
}

package com.dongqh.lotteryservice.outbox.service;

import com.dongqh.lotteryservice.service.drawchance.DrawChanceReservationService;
import com.dongqh.lotteryservice.outbox.event.DrawConfirmedEvent;
import com.dongqh.lotteryservice.outbox.event.DrawEventEnvelope;
import com.dongqh.lotteryservice.outbox.event.DrawEventType;
import com.dongqh.lotteryservice.outbox.event.DrawReleaseRequestedEvent;
import com.dongqh.lotteryservice.outbox.event.PrizeFulfillmentRequestedEvent;
import com.dongqh.lotteryservice.outbox.mapper.MessageConsumeRecordMapper;
import com.dongqh.lotteryservice.reward.LotteryRewardDispatchService;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;

@Service
public class LotteryEventConsumeService {
    private final MessageConsumeRecordMapper consumeRecords;
    private final DrawChanceReservationService drawChances;
    private final LotteryRewardDispatchService rewards;
    private final ObjectMapper json;
    private final String consumerName;

    public LotteryEventConsumeService(MessageConsumeRecordMapper consumeRecords,
            DrawChanceReservationService drawChances,
            LotteryRewardDispatchService rewards, ObjectMapper json,
            @Value("${luckyhub.lottery.consumer-name:lottery-service}") String consumerName) {
        this.consumeRecords = consumeRecords;
        this.drawChances = drawChances;
        this.rewards = rewards;
        this.json = json;
        this.consumerName = consumerName;
    }

    @Transactional
    public void consume(DrawEventEnvelope event) {
        String eventId = event.eventId().toString();
        if (alreadyConsumed(eventId)) {
            return;
        }
        switch (event.eventType()) {
            case DRAW_CONFIRMED -> {
                event.payloadAs(DrawConfirmedEvent.class, json);
                drawChances.confirmIfReserved(event.requestId());
                consumeRecords.insertIfAbsent(eventId, consumerName);
            }
            case DRAW_RELEASE_REQUESTED -> {
                event.payloadAs(DrawReleaseRequestedEvent.class, json);
                drawChances.releaseIfReserved(event.requestId());
                consumeRecords.insertIfAbsent(eventId, consumerName);
            }
            case PRIZE_FULFILLMENT_REQUESTED -> rewards.dispatch(event,
                    event.payloadAs(PrizeFulfillmentRequestedEvent.class, json));
        }
    }

    private boolean alreadyConsumed(String eventId) {
        return consumeRecords.countByEventAndConsumer(eventId, consumerName) > 0;
    }
}

package com.dongqh.lotteryservice.outbox.service;

import com.dongqh.lotteryservice.outbox.event.DrawEventEnvelope;
import com.dongqh.lotteryservice.outbox.mapper.MessageOutboxMapper;
import com.dongqh.lotteryservice.outbox.model.MessageOutbox;
import com.dongqh.lotteryservice.outbox.publisher.DrawEventPublisher;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.convert.DurationStyle;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import tools.jackson.databind.ObjectMapper;

import java.time.Clock;
import java.time.Duration;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

@Service
@ConditionalOnProperty(prefix = "luckyhub.lottery.outbox", name = "enabled", havingValue = "true")
public class OutboxRelayService {
    private static final int MAX_ERROR_LENGTH = 500;
    private final MessageOutboxMapper mapper;
    private final DrawEventPublisher publisher;
    private final ObjectMapper json;
    private final int batchSize;
    private final Duration leaseDuration;
    private final Clock clock;

    @Autowired
    public OutboxRelayService(MessageOutboxMapper mapper, DrawEventPublisher publisher, ObjectMapper json,
                              @Value("${luckyhub.lottery.outbox-batch-size:100}") int batchSize,
                              @Value("${luckyhub.lottery.outbox.lease:30s}") String leaseDuration) {
        this(mapper, publisher, json, batchSize, DurationStyle.detectAndParse(leaseDuration), Clock.systemDefaultZone());
    }

    public OutboxRelayService(MessageOutboxMapper mapper, DrawEventPublisher publisher, ObjectMapper json,
                              int batchSize, Duration leaseDuration, Clock clock) {
        this.mapper = Objects.requireNonNull(mapper, "mapper must not be null");
        this.publisher = Objects.requireNonNull(publisher, "publisher must not be null");
        this.json = Objects.requireNonNull(json, "json must not be null");
        if (batchSize <= 0) throw new IllegalArgumentException("batchSize must be positive");
        if (leaseDuration == null || leaseDuration.isZero() || leaseDuration.isNegative()) {
            throw new IllegalArgumentException("leaseDuration must be positive");
        }
        this.batchSize = batchSize;
        this.leaseDuration = leaseDuration;
        this.clock = Objects.requireNonNull(clock, "clock must not be null");
    }

    public int relayBatch() {
        LocalDateTime now = LocalDateTime.now(clock).truncatedTo(ChronoUnit.MILLIS);
        List<MessageOutbox> rows = mapper.selectRelayCandidates(now, batchSize);
        int sent = 0;
        for (MessageOutbox row : rows) {
            String claimToken = UUID.randomUUID().toString();
            if (mapper.claimForRelay(row.getId(), claimToken, now, now.plus(leaseDuration)) != 1) continue;
            try {
                DrawEventEnvelope event = json.readValue(row.getPayload(), DrawEventEnvelope.class);
                publisher.publish(event);
                if (mapper.markSent(row.getId(), claimToken,
                        LocalDateTime.now(clock).truncatedTo(ChronoUnit.MILLIS)) == 1) sent++;
            } catch (Exception exception) {
                recordFailure(row, claimToken, now, exception);
            }
        }
        return sent;
    }

    @Scheduled(fixedDelayString = "${luckyhub.lottery.outbox-interval:5s}",
            initialDelayString = "${luckyhub.lottery.outbox-initial-delay:60s}")
    public void relayOutbox() {
        relayBatch();
    }

    private void recordFailure(MessageOutbox row, String claimToken, LocalDateTime now, Exception exception) {
        int retry = row.getRetryCount() == null ? 1 : row.getRetryCount() + 1;
        long delaySeconds = Math.min(300L, 1L << Math.min(retry, 8));
        String message = exception.getMessage() == null
                ? exception.getClass().getSimpleName() : exception.getMessage();
        if (message.length() > MAX_ERROR_LENGTH) message = message.substring(0, MAX_ERROR_LENGTH);
        mapper.markFailed(row.getId(), claimToken, message, now.plusSeconds(delaySeconds));
    }
}

package com.dongqh.lotteryservice.outbox.service;

import com.dongqh.lotteryservice.outbox.event.DrawEventEnvelope;
import com.dongqh.lotteryservice.outbox.mapper.MessageOutboxMapper;
import com.dongqh.lotteryservice.outbox.model.MessageOutbox;
import com.dongqh.lotteryservice.outbox.model.OutboxStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.util.Objects;

@Service
public class OutboxService {
    private static final String DRAW_ORDER_AGGREGATE = "LOTTERY_DRAW_ORDER";
    private final MessageOutboxMapper mapper;
    private final ObjectMapper json;

    public OutboxService(MessageOutboxMapper mapper, ObjectMapper json) {
        this.mapper = mapper;
        this.json = json;
    }

    @Transactional(propagation = Propagation.MANDATORY)
    public void append(DrawEventEnvelope event) {
        Objects.requireNonNull(event, "event must not be null");
        MessageOutbox outbox = new MessageOutbox();
        outbox.setEventId(event.eventId().toString());
        outbox.setEventType(event.eventType().name());
        outbox.setEventVersion(event.eventVersion());
        outbox.setAggregateType(DRAW_ORDER_AGGREGATE);
        outbox.setAggregateId(event.orderId().toString());
        outbox.setPayload(serialize(event));
        outbox.setStatus(OutboxStatus.PENDING);
        outbox.setRetryCount(0);
        mapper.insert(outbox);
    }

    private String serialize(DrawEventEnvelope event) {
        try {
            return json.writeValueAsString(event);
        } catch (JacksonException exception) {
            throw new IllegalArgumentException("Draw event cannot be serialized", exception);
        }
    }
}

package com.dongqh.lotteryservice.reward;

import com.dongqh.hmapi.dto.FulfillmentStatusChangedEventV1;
import com.dongqh.lotteryservice.domain.po.drawtransaction.UserBenefitRow;
import com.dongqh.lotteryservice.enums.drawtransaction.BenefitStatus;
import com.dongqh.lotteryservice.mapper.drawtransaction.UserBenefitMapper;
import com.dongqh.lotteryservice.outbox.mapper.LotteryRewardQuarantineMapper;
import com.dongqh.lotteryservice.outbox.mapper.MessageConsumeRecordMapper;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeType;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.EnumSet;
import java.util.Set;

@Service
public class LotteryFulfillmentStatusProjectionService {
    private static final String LOTTERY_SOURCE = "LOTTERY_BENEFIT";
    private static final String SAFE_GRANT_FAILURE = "权益履约失败";
    private static final Set<BenefitStatus> SHIPPING_STATUSES = EnumSet.of(
            BenefitStatus.CLAIM_PENDING, BenefitStatus.FULFILLING, BenefitStatus.SHIPPED,
            BenefitStatus.FULFILLMENT_FAILED);

    private final UserBenefitMapper benefits;
    private final LotteryRewardQuarantineMapper quarantines;
    private final MessageConsumeRecordMapper consumeRecords;
    private final String consumerName;

    public LotteryFulfillmentStatusProjectionService(
            UserBenefitMapper benefits,
            LotteryRewardQuarantineMapper quarantines,
            MessageConsumeRecordMapper consumeRecords,
            @Value("${luckyhub.lottery.fulfillment-status-consumer-name:lottery-fulfillment-status-projection}")
            String consumerName
    ) {
        if (consumerName == null || consumerName.isBlank()) {
            throw new IllegalArgumentException("consumerName must not be blank");
        }
        this.benefits = benefits;
        this.quarantines = quarantines;
        this.consumeRecords = consumeRecords;
        this.consumerName = consumerName;
    }

    @Transactional
    public void consume(FulfillmentStatusChangedEventV1 event) {
        validate(event);
        if (alreadyConsumed(event.eventId())) {
            return;
        }
        if (!LOTTERY_SOURCE.equals(event.sourceType())) {
            consumeRecords.insertIfAbsent(event.eventId(), consumerName);
            return;
        }

        Long benefitId = positiveId(event.sourceId());
        UserBenefitRow benefit = benefitId == null ? null : benefits.selectByIdForUpdate(benefitId);
        if (benefit == null || !matches(event, benefit, benefitId)) {
            quarantine(event, benefit, benefitId, RewardQuarantineReason.FULFILLMENT_TASK_IDENTITY_MISMATCH);
            consumeRecords.insertIfAbsent(event.eventId(), consumerName);
            return;
        }

        boolean projected = benefit.getRewardType() == RewardType.PRODUCT
                && benefit.getPrizeType() == PrizeType.PHYSICAL
                ? projectPhysical(event, benefit)
                : projectAsset(event, benefit);
        if (!projected) {
            quarantine(event, benefit, benefitId, RewardQuarantineReason.FULFILLMENT_STATUS_UNSUPPORTED);
        }
        consumeRecords.insertIfAbsent(event.eventId(), consumerName);
    }

    private boolean projectAsset(FulfillmentStatusChangedEventV1 event, UserBenefitRow benefit) {
        if (benefit.getRewardType() != RewardType.COUPON
                && benefit.getRewardType() != RewardType.POINTS
                && benefit.getRewardType() != RewardType.MEMBERSHIP) {
            return false;
        }
        if (benefit.getStatus() == BenefitStatus.AVAILABLE) {
            return true;
        }
        if (benefit.getStatus() != BenefitStatus.PENDING && benefit.getStatus() != BenefitStatus.GRANT_FAILED) {
            return false;
        }
        if ("SUCCEEDED".equals(event.status())) {
            return benefits.markAvailableAfterFulfillment(benefit.getId()) == 1;
        }
        if ("QUARANTINED".equals(event.status()) || "TERMINATED".equals(event.status())) {
            return benefits.markGrantFailedAfterFulfillment(benefit.getId(), SAFE_GRANT_FAILURE) == 1;
        }
        return false;
    }

    private boolean projectPhysical(FulfillmentStatusChangedEventV1 event, UserBenefitRow benefit) {
        if (benefit.getShippingOrderId() == null || event.shippingNo() == null || event.shippingNo().isBlank()) {
            return false;
        }
        BenefitStatus target = switch (event.status()) {
            case "FULFILLING" -> BenefitStatus.FULFILLING;
            case "SHIPPED", "IN_TRANSIT" -> BenefitStatus.SHIPPED;
            case "DELIVERED" -> BenefitStatus.DELIVERED;
            case "FAILED" -> BenefitStatus.FULFILLMENT_FAILED;
            case "TERMINATED" -> BenefitStatus.FULFILLMENT_TERMINATED;
            default -> null;
        };
        if (target == null || benefit.getStatus() == target) {
            return target != null;
        }
        if (!SHIPPING_STATUSES.contains(benefit.getStatus())
                && benefit.getStatus() != BenefitStatus.FULFILLMENT_TERMINATED
                && benefit.getStatus() != BenefitStatus.DELIVERED) {
            return false;
        }
        if (benefit.getStatus() == BenefitStatus.DELIVERED
                || benefit.getStatus() == BenefitStatus.FULFILLMENT_TERMINATED) {
            return target == BenefitStatus.DELIVERED && benefit.getStatus() == BenefitStatus.DELIVERED;
        }
        return benefits.transitionStatus(benefit.getId(), benefit.getStatus(), target) == 1;
    }

    private boolean matches(FulfillmentStatusChangedEventV1 event, UserBenefitRow benefit, Long benefitId) {
        if (!Long.toString(benefitId).equals(event.sourceId())
                || !Long.valueOf(benefitId).equals(benefit.getId())) {
            return false;
        }
        if (benefit.getRewardType() == RewardType.PRODUCT && benefit.getPrizeType() == PrizeType.PHYSICAL) {
            return benefit.getShippingOrderId() != null
                    && ("LOGISTICS-" + benefit.getShippingOrderId()).equals(event.fulfillmentNo());
        }
        return (benefit.getRewardType() == RewardType.COUPON
                || benefit.getRewardType() == RewardType.POINTS
                || benefit.getRewardType() == RewardType.MEMBERSHIP)
                && ("LOTTERY-BENEFIT-" + benefitId).equals(event.fulfillmentNo())
                && event.fulfillmentNo().equals(benefit.getFulfillmentNo());
    }

    private void quarantine(FulfillmentStatusChangedEventV1 event, UserBenefitRow benefit, Long benefitId,
                            RewardQuarantineReason reason) {
        quarantines.insertIfAbsent(event.eventId(), event.fulfillmentNo(), null,
                benefit == null ? null : benefit.getDrawRecordId(), benefitId,
                benefit == null ? null : benefit.getPrizeId(),
                benefit == null ? null : benefit.getRewardDefinitionId(), reason.name());
    }

    private boolean alreadyConsumed(String eventId) {
        return consumeRecords.countByEventAndConsumer(eventId, consumerName) > 0;
    }

    private Long positiveId(String value) {
        try {
            long parsed = Long.parseLong(value);
            return parsed > 0 ? parsed : null;
        } catch (NumberFormatException | NullPointerException ignored) {
            return null;
        }
    }

    private void validate(FulfillmentStatusChangedEventV1 event) {
        if (event == null || blank(event.eventId()) || event.eventId().length() > 64
                || blank(event.fulfillmentNo()) || event.fulfillmentNo().length() > 64
                || blank(event.sourceType()) || blank(event.sourceId()) || blank(event.status())
                || event.occurredAt() == null) {
            throw new IllegalArgumentException("Fulfillment 状态事件无效");
        }
    }

    private boolean blank(String value) {
        return value == null || value.isBlank();
    }
}

package com.dongqh.lotteryservice.reward;

import com.dongqh.hmapi.client.FulfillmentClient;
import com.dongqh.hmapi.dto.CreateFulfillmentTaskRequest;
import com.dongqh.hmapi.dto.FulfillmentCouponTaskPayload;
import com.dongqh.hmapi.dto.FulfillmentMembershipTaskPayload;
import com.dongqh.hmapi.dto.FulfillmentPointsTaskPayload;
import com.dongqh.hmapi.dto.FulfillmentTaskDTO;
import com.dongqh.lotteryservice.service.drawchance.DrawChanceReservationService;
import com.dongqh.lotteryservice.domain.po.draworder.DrawOrderRow;
import com.dongqh.lotteryservice.mapper.draworder.DrawOrderMapper;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.domain.po.drawtransaction.UserBenefitRow;
import com.dongqh.lotteryservice.enums.drawtransaction.BenefitStatus;
import com.dongqh.lotteryservice.mapper.drawtransaction.DrawRecordMapper;
import com.dongqh.lotteryservice.mapper.drawtransaction.UserBenefitMapper;
import com.dongqh.lotteryservice.domain.model.drawtransaction.CouponRewardPayload;
import com.dongqh.lotteryservice.domain.model.drawtransaction.MembershipRewardPayload;
import com.dongqh.lotteryservice.domain.model.drawtransaction.PointsRewardPayload;
import com.dongqh.lotteryservice.domain.model.drawtransaction.RewardSnapshot;
import com.dongqh.lotteryservice.outbox.event.DrawEventEnvelope;
import com.dongqh.lotteryservice.outbox.event.PrizeFulfillmentRequestedEvent;
import com.dongqh.lotteryservice.outbox.mapper.LotteryRewardQuarantineMapper;
import com.dongqh.lotteryservice.outbox.mapper.MessageConsumeRecordMapper;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeType;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.time.Duration;
import java.time.LocalDateTime;

@Service
public class LotteryRewardDispatchService {
    private static final String CONSUMER_NAME_DEFAULT = "lottery-service";
    private static final String FULFILLMENT_SOURCE = "LOTTERY_BENEFIT";

    private final DrawOrderMapper orders;
    private final DrawRecordMapper records;
    private final UserBenefitMapper benefits;
    private final LotteryRewardIdentityVerifier identities;
    private final LotteryRewardQuarantineMapper quarantines;
    private final MessageConsumeRecordMapper consumeRecords;
    private final FulfillmentClient fulfillment;
    private final DrawChanceReservationService drawChances;
    private final ObjectMapper json;
    private final String consumerName;
    private final Duration claimPeriod;

    public LotteryRewardDispatchService(DrawOrderMapper orders, DrawRecordMapper records,
            UserBenefitMapper benefits, LotteryRewardIdentityVerifier identities,
            LotteryRewardQuarantineMapper quarantines, MessageConsumeRecordMapper consumeRecords,
            FulfillmentClient fulfillment, DrawChanceReservationService drawChances, ObjectMapper json,
            @Value("${luckyhub.lottery.consumer-name:lottery-service}") String consumerName,
            @Value("${luckyhub.lottery.claim-period:7d}") Duration claimPeriod) {
        if (consumerName == null || consumerName.isBlank()) {
            throw new IllegalArgumentException("consumerName must not be blank");
        }
        if (claimPeriod == null || claimPeriod.isZero() || claimPeriod.isNegative()) {
            throw new IllegalArgumentException("claimPeriod must be positive");
        }
        this.orders = orders;
        this.records = records;
        this.benefits = benefits;
        this.identities = identities;
        this.quarantines = quarantines;
        this.consumeRecords = consumeRecords;
        this.fulfillment = fulfillment;
        this.drawChances = drawChances;
        this.json = json;
        this.consumerName = consumerName;
        this.claimPeriod = claimPeriod;
    }

    @Transactional
    public void dispatch(DrawEventEnvelope envelope, PrizeFulfillmentRequestedEvent payload) {
        String eventId = envelope.eventId().toString();
        UserBenefitRow benefit = benefits.selectByIdForUpdate(payload.benefitId());
        DrawRecordRow record = records.selectById(payload.drawRecordId());
        DrawOrderRow order = orders.selectById(envelope.orderId());

        ValidatedLotteryReward reward;
        try {
            reward = identities.validate(envelope, payload, order, record, benefit);
        } catch (RewardIdentityMismatchException mismatch) {
            if (!alreadyConsumed(eventId)) {
                quarantines.insertIfAbsent(eventId, envelope.requestId(), envelope.orderId(),
                        payload.drawRecordId(), payload.benefitId(), payload.prizeId(),
                        payload.rewardDefinitionId(), mismatch.reason().name());
                consumeRecords.insertIfAbsent(eventId, consumerName);
            }
            return;
        }
        if (alreadyConsumed(eventId)) {
            return;
        }
        if (reward.benefitStatus() != BenefitStatus.PENDING
                && reward.benefitStatus() != BenefitStatus.GRANT_FAILED) {
            throw new IllegalStateException("Lottery reward is not pending fulfillment");
        }

        RewardSnapshot snapshot = reward.rewardSnapshot();
        if (snapshot == null) {
            transitionLegacyBenefit(reward, benefit);
        } else {
            dispatchSnapshot(reward, benefit, snapshot);
        }
        consumeRecords.insertIfAbsent(eventId, consumerName);
    }

    private void dispatchSnapshot(ValidatedLotteryReward reward, UserBenefitRow benefit,
                                  RewardSnapshot snapshot) {
        switch (snapshot.rewardType()) {
            case COUPON -> {
                CouponRewardPayload frozen = read(snapshot, CouponRewardPayload.class);
                createFulfillment(reward, benefit, "COUPON",
                        new FulfillmentCouponTaskPayload(frozen.templateCode(), frozen.quantity(), frozen.templateId()));
            }
            case POINTS -> {
                PointsRewardPayload frozen = read(snapshot, PointsRewardPayload.class);
                createFulfillment(reward, benefit, "POINTS",
                        new FulfillmentPointsTaskPayload(frozen.points(), frozen.reason()));
            }
            case MEMBERSHIP -> {
                MembershipRewardPayload frozen = read(snapshot, MembershipRewardPayload.class);
                createFulfillment(reward, benefit, "MEMBERSHIP",
                        new FulfillmentMembershipTaskPayload(frozen.productCode(), frozen.durationDays(),
                                frozen.quantity(), frozen.membershipProductId()));
            }
            case PRODUCT -> transitionClaimPending(reward);
            case DRAW_CHANCE -> {
                drawChances.credit(reward.userId(), fulfillmentNo(reward.benefitId()), snapshot.quantity());
                transition(reward, BenefitStatus.AVAILABLE);
            }
        }
    }

    private void transitionLegacyBenefit(ValidatedLotteryReward reward, UserBenefitRow benefit) {
        if (benefit.getPrizeType() == PrizeType.PHYSICAL) {
            transitionClaimPending(reward);
        } else {
            transition(reward, BenefitStatus.AVAILABLE);
        }
    }

    private void createFulfillment(ValidatedLotteryReward reward, UserBenefitRow benefit,
                                   String type, Object payload) {
        String fulfillmentNo = fulfillmentNo(reward.benefitId());
        FulfillmentTaskDTO created = fulfillment.createTask(new CreateFulfillmentTaskRequest(
                fulfillmentNo, FULFILLMENT_SOURCE, Long.toString(reward.benefitId()), type,
                reward.userId(), write(payload), null));
        if (created == null || !fulfillmentNo.equals(created.fulfillmentNo())
                || !FULFILLMENT_SOURCE.equals(created.sourceType())
                || !Long.toString(reward.benefitId()).equals(created.sourceId())
                || !Long.valueOf(reward.userId()).equals(created.targetUserId())
                || !type.equals(created.fulfillmentType())) {
            throw new IllegalStateException("Fulfillment returned a mismatched task identity");
        }
        String boundNo = benefit.getFulfillmentNo();
        if (boundNo != null && !boundNo.equals(fulfillmentNo)) {
            throw new IllegalStateException("Lottery benefit is bound to another fulfillment task");
        }
        if (boundNo == null && benefits.bindFulfillmentNo(reward.benefitId(), fulfillmentNo) != 1) {
            throw new IllegalStateException("Lottery benefit fulfillment task could not be bound");
        }
    }

    private void transitionClaimPending(ValidatedLotteryReward reward) {
        if (benefits.markClaimPending(reward.benefitId(), reward.benefitStatus(),
                LocalDateTime.now().plus(claimPeriod)) != 1) {
            throw new IllegalStateException("Lottery physical benefit state changed concurrently");
        }
    }

    private void transition(ValidatedLotteryReward reward, BenefitStatus target) {
        if (benefits.transitionStatus(reward.benefitId(), reward.benefitStatus(), target) != 1) {
            throw new IllegalStateException("Lottery benefit state changed concurrently");
        }
    }

    private <T> T read(RewardSnapshot snapshot, Class<T> payloadType) {
        try {
            return json.readValue(snapshot.payloadJson(), payloadType);
        } catch (JacksonException exception) {
            throw new IllegalStateException("Frozen Lottery reward payload is invalid", exception);
        }
    }

    private String write(Object payload) {
        try {
            return json.writeValueAsString(payload);
        } catch (JacksonException exception) {
            throw new IllegalStateException("Fulfillment payload could not be serialized", exception);
        }
    }

    private boolean alreadyConsumed(String eventId) {
        return consumeRecords.countByEventAndConsumer(eventId, consumerName) > 0;
    }

    private String fulfillmentNo(long benefitId) {
        return "LOTTERY-BENEFIT-" + benefitId;
    }
}

package com.dongqh.lotteryservice.reward;

import com.dongqh.lotteryservice.domain.po.draworder.DrawOrderRow;
import com.dongqh.lotteryservice.enums.draworder.DrawOrderStatus;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.domain.po.drawtransaction.UserBenefitRow;
import com.dongqh.lotteryservice.domain.model.drawtransaction.RewardSnapshot;
import com.dongqh.lotteryservice.outbox.event.DrawEventEnvelope;
import com.dongqh.lotteryservice.outbox.event.DrawEventType;
import com.dongqh.lotteryservice.outbox.event.PrizeFulfillmentRequestedEvent;
import org.springframework.stereotype.Component;

import java.util.Objects;

/** Checks already loaded Lottery rows without reading or changing persistence state. */
@Component
public final class LotteryRewardIdentityVerifier {
    public ValidatedLotteryReward validate(DrawEventEnvelope envelope,
            PrizeFulfillmentRequestedEvent payload, DrawOrderRow order,
            DrawRecordRow record, UserBenefitRow benefit) {
        Objects.requireNonNull(envelope, "envelope");
        Objects.requireNonNull(payload, "payload");
        if (order == null || record == null || benefit == null) {
            throw mismatch(RewardQuarantineReason.IDENTITY_NOT_FOUND);
        }
        if (envelope.eventType() != DrawEventType.PRIZE_FULFILLMENT_REQUESTED
                || !Objects.equals(envelope.requestId(), order.getRequestId())
                || !Objects.equals(envelope.orderId(), order.getId())
                || !Objects.equals(envelope.userId(), order.getUserId())
                || !Objects.equals(envelope.activityId(), order.getActivityId())
                || order.getStatus() != DrawOrderStatus.SUCCESS) {
            throw mismatch(RewardQuarantineReason.ORDER_IDENTITY_MISMATCH);
        }
        if (!Objects.equals(order.getId(), record.getOrderId())
                || !Objects.equals(order.getRequestId(), record.getRequestId())
                || !Objects.equals(order.getUserId(), record.getUserId())
                || !Objects.equals(order.getActivityId(), record.getActivityId())
                || !Objects.equals(payload.drawRecordId(), record.getId())
                || !Objects.equals(payload.prizeId(), record.getPrizeId())
                || payload.prizeType() != record.getPrizeType()) {
            throw mismatch(RewardQuarantineReason.RECORD_IDENTITY_MISMATCH);
        }
        if (!Objects.equals(payload.benefitId(), benefit.getId())
                || !Objects.equals(record.getId(), benefit.getDrawRecordId())
                || !Objects.equals(record.getUserId(), benefit.getUserId())
                || !Objects.equals(record.getPrizeId(), benefit.getPrizeId())
                || record.getPrizeType() != benefit.getPrizeType()) {
            throw mismatch(RewardQuarantineReason.BENEFIT_IDENTITY_MISMATCH);
        }

        RewardSnapshot snapshot = validateReward(payload, record, benefit);
        return new ValidatedLotteryReward(benefit.getId(), record.getId(), order.getId(),
                order.getRequestId(), benefit.getUserId(), order.getActivityId(),
                benefit.getPrizeId(), benefit.getPrizeType(), benefit.getStatus(), snapshot);
    }

    private RewardSnapshot validateReward(PrizeFulfillmentRequestedEvent payload,
            DrawRecordRow record, UserBenefitRow benefit) {
        if (payload.rewardDefinitionId() == null) {
            if (record.getRewardDefinitionId() != null || benefit.getRewardDefinitionId() != null
                    || record.getRewardType() != null || benefit.getRewardType() != null
                    || record.getRewardFingerprint() != null || benefit.getRewardFingerprint() != null) {
                throw mismatch(RewardQuarantineReason.REWARD_DEFINITION_MISMATCH);
            }
            return null;
        }
        if (!Objects.equals(payload.rewardDefinitionId(), record.getRewardDefinitionId())
                || !Objects.equals(record.getRewardDefinitionId(), benefit.getRewardDefinitionId())) {
            throw mismatch(RewardQuarantineReason.REWARD_DEFINITION_MISMATCH);
        }
        if (payload.rewardType() != record.getRewardType()
                || record.getRewardType() != benefit.getRewardType()) {
            throw mismatch(RewardQuarantineReason.REWARD_TYPE_MISMATCH);
        }
        if (!Objects.equals(payload.rewardFingerprint(), record.getRewardFingerprint())
                || !Objects.equals(record.getRewardFingerprint(), benefit.getRewardFingerprint())) {
            throw mismatch(RewardQuarantineReason.REWARD_FINGERPRINT_MISMATCH);
        }
        if (!Objects.equals(record.getRewardTargetId(), benefit.getRewardTargetId())
                || !Objects.equals(record.getRewardQuantity(), benefit.getRewardQuantity())
                || !Objects.equals(record.getRewardPayload(), benefit.getRewardPayload())
                || benefit.getRewardQuantity() == null || benefit.getRewardQuantity() <= 0
                || benefit.getRewardPayload() == null || benefit.getRewardPayload().isBlank()) {
            throw mismatch(RewardQuarantineReason.BENEFIT_IDENTITY_MISMATCH);
        }
        return new RewardSnapshot(benefit.getRewardDefinitionId(),
                "FROZEN-" + benefit.getRewardDefinitionId(), benefit.getRewardType(),
                benefit.getRewardTargetId(), benefit.getRewardQuantity(),
                benefit.getRewardPayload(), benefit.getRewardFingerprint());
    }

    private RewardIdentityMismatchException mismatch(RewardQuarantineReason reason) {
        return new RewardIdentityMismatchException(reason);
    }
}

package com.dongqh.lotteryservice.reward;

public class RewardIdentityMismatchException extends RuntimeException {
    private final RewardQuarantineReason reason;

    public RewardIdentityMismatchException(RewardQuarantineReason reason) {
        super(reason.name());
        this.reason = reason;
    }

    public RewardQuarantineReason reason() { return reason; }
}

