package com.dongqh.lotteryservice.service.benefit;

import com.dongqh.lotteryservice.mapper.drawtransaction.UserBenefitMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;

@Service
public class BenefitClaimExpiryService {
    private static final Logger log = LoggerFactory.getLogger(BenefitClaimExpiryService.class);
    private static final int SCAN_PAGE_SIZE = 50;

    private final UserBenefitMapper benefits;
    private final BenefitClaimExpiryWorker worker;
    private long scanAfterId;

    public BenefitClaimExpiryService(UserBenefitMapper benefits, BenefitClaimExpiryWorker worker) {
        this.benefits = benefits;
        this.worker = worker;
    }

    public synchronized int expireDue(int limit, LocalDateTime now) {
        if (limit < 1 || limit > 1000 || now == null) {
            throw new IllegalArgumentException("过期批次参数不合法");
        }
        int expired = 0;
        int candidates = 0;
        int candidateBudget = (int) Math.min(1000L, Math.max(SCAN_PAGE_SIZE, (long) limit * 4));
        while (expired < limit && candidates < candidateBudget) {
            int queryLimit = Math.min(SCAN_PAGE_SIZE, candidateBudget - candidates);
            List<Long> ids = benefits.selectDueClaimIdsAfter(now, scanAfterId, queryLimit);
            if (ids.isEmpty()) {
                scanAfterId = 0;
                break;
            }
            int processedThisPage = 0;
            for (Long id : ids) {
                scanAfterId = id;
                candidates++;
                processedThisPage++;
                try {
                    if (worker.expireOne(id, now)) expired++;
                } catch (RuntimeException exception) {
                    logCandidateFailure(id, exception);
                }
                if (expired == limit || candidates == candidateBudget) break;
            }
            if (processedThisPage == ids.size() && ids.size() < queryLimit) {
                scanAfterId = 0;
                break;
            }
        }
        return expired;
    }

    private void logCandidateFailure(long benefitId, RuntimeException exception) {
        String errorType = exception.getClass().getSimpleName().replaceAll("[^A-Za-z0-9_$]", "_");
        if (errorType.isEmpty()) errorType = "RuntimeException";
        if (errorType.length() > 64) errorType = errorType.substring(0, 64);
        log.warn("Physical claim expiry candidate failed, benefitId={}, errorType={}", benefitId, errorType);
    }
}

package com.dongqh.lotteryservice.service.benefit;

import com.dongqh.lotteryservice.domain.po.activityprize.ActivityPrizeRow;
import com.dongqh.lotteryservice.mapper.activityprize.ActivityPrizeMapper;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.domain.po.drawtransaction.UserBenefitRow;
import com.dongqh.lotteryservice.enums.drawtransaction.BenefitStatus;
import com.dongqh.lotteryservice.mapper.drawtransaction.ActivityPrizeInventoryMapper;
import com.dongqh.lotteryservice.mapper.drawtransaction.DrawRecordMapper;
import com.dongqh.lotteryservice.mapper.drawtransaction.UserBenefitMapper;
import com.dongqh.lotteryservice.domain.model.drawtransaction.ProductRewardPayload;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeType;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.time.LocalDateTime;
import java.util.Objects;

@Service
public class BenefitClaimExpiryWorker {

    private final UserBenefitMapper benefits;
    private final DrawRecordMapper records;
    private final ActivityPrizeMapper activityPrizes;
    private final ActivityPrizeInventoryMapper inventory;
    private final ObjectMapper json;

    public BenefitClaimExpiryWorker(UserBenefitMapper benefits, DrawRecordMapper records,
                                    ActivityPrizeMapper activityPrizes,
                                    ActivityPrizeInventoryMapper inventory, ObjectMapper json) {
        this.benefits = benefits;
        this.records = records;
        this.activityPrizes = activityPrizes;
        this.inventory = inventory;
        this.json = json;
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW, isolation = Isolation.READ_COMMITTED)
    public boolean expireOne(long benefitId, LocalDateTime now) {
        UserBenefitRow benefit = benefits.selectByIdForUpdate(benefitId);
        if (benefit == null || benefit.getStatus() != BenefitStatus.CLAIM_PENDING
                || benefit.getClaimDeadline() == null || benefit.getClaimDeadline().isAfter(now)) {
            return false;
        }

        DrawRecordRow draw = benefit.getDrawRecordId() == null
                ? null : records.selectById(benefit.getDrawRecordId());
        ProductRewardPayload product = requireFrozenIdentity(benefit, draw);
        ActivityPrizeRow activityPrize = activityPrizes.lockByActivityAndPrize(
                draw.getActivityId(), draw.getPrizeId());
        if (activityPrize == null || activityPrize.getId() == null) {
            throw new IllegalStateException("活动奖品关系不存在");
        }
        if (inventory.incrementIfBelowTotal(activityPrize.getId()) != 1) {
            throw new IllegalStateException("奖品库存回补失败");
        }
        if (benefits.markClaimExpired(benefitId, now) != 1) {
            throw new IllegalStateException("权益过期状态转换失败");
        }
        return true;
    }

    private ProductRewardPayload requireFrozenIdentity(UserBenefitRow benefit, DrawRecordRow draw) {
        if (draw == null || benefit.getPrizeType() != PrizeType.PHYSICAL
                || benefit.getRewardType() != RewardType.PRODUCT
                || !Objects.equals(draw.getUserId(), benefit.getUserId())
                || !Objects.equals(draw.getPrizeId(), benefit.getPrizeId())
                || draw.getPrizeType() != benefit.getPrizeType()
                || !Objects.equals(draw.getRewardDefinitionId(), benefit.getRewardDefinitionId())
                || draw.getRewardType() != benefit.getRewardType()
                || !Objects.equals(draw.getRewardTargetId(), benefit.getRewardTargetId())
                || !Objects.equals(draw.getRewardQuantity(), benefit.getRewardQuantity())
                || !Objects.equals(draw.getRewardPayload(), benefit.getRewardPayload())
                || !Objects.equals(draw.getRewardFingerprint(), benefit.getRewardFingerprint())) {
            throw new IllegalStateException("冻结奖励身份不一致");
        }
        try {
            ProductRewardPayload product = json.readValue(benefit.getRewardPayload(), ProductRewardPayload.class);
            if (!Objects.equals(benefit.getRewardTargetId(), product.itemId())
                    || !Objects.equals(benefit.getRewardQuantity(), product.quantity())
                    || !Objects.equals(benefit.getQuantity(), product.quantity())) {
                throw new IllegalStateException("冻结商品奖励不一致");
            }
            return product;
        } catch (JacksonException | IllegalArgumentException exception) {
            throw new IllegalStateException("冻结商品奖励不可解析", exception);
        }
    }
}

package com.dongqh.lotteryservice.service.benefit;

import com.dongqh.hmapi.client.FulfillmentClient;
import com.dongqh.hmapi.dto.FulfillmentShippingOrderDTO;
import com.dongqh.hmapi.dto.FulfillmentTaskStatusDTO;
import com.dongqh.lotteryservice.domain.vo.benefit.BenefitView;
import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.domain.po.drawtransaction.UserBenefitRow;
import com.dongqh.lotteryservice.enums.drawtransaction.BenefitStatus;
import com.dongqh.lotteryservice.mapper.drawtransaction.DrawRecordMapper;
import com.dongqh.lotteryservice.mapper.drawtransaction.UserBenefitMapper;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeType;
import com.dongqh.lotteryservice.domain.vo.prizecatalog.PageResponse;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
public class LotteryBenefitQueryService {
    private static final long MAX_PAGE = 1_000_000L;
    private static final LocalDate MYSQL_MIN_DATE = LocalDate.of(1000, 1, 1);
    private static final LocalDate MAX_SAFE_END_DATE = LocalDate.of(9999, 12, 30);

    private final UserBenefitMapper benefits;
    private final DrawRecordMapper records;
    private final FulfillmentClient fulfillment;

    public LotteryBenefitQueryService(UserBenefitMapper benefits, DrawRecordMapper records,
                                     FulfillmentClient fulfillment) {
        this.benefits = benefits;
        this.records = records;
        this.fulfillment = fulfillment;
    }

    public PageResponse<BenefitView> pageMine(long userId, long page, long size, BenefitStatus status,
                                               PrizeType prizeType, LocalDate startDate, LocalDate endDate) {
        long offset = validate(userId, page, size, startDate, endDate);
        LocalDateTime startTime = startDate == null ? null : startDate.atStartOfDay();
        LocalDateTime endTime = endDate == null ? null : endDate.plusDays(1).atStartOfDay();
        List<UserBenefitRow> rows = benefits.selectMinePage(userId, status, prizeType,
                startTime, endTime, size, offset);
        long total = benefits.countMine(userId, status, prizeType, startTime, endTime);
        List<BenefitView> views = toViews(rows);
        long pages = total == 0 ? 0 : (total - 1) / size + 1;
        return new PageResponse<>(views, total, page, size, pages);
    }

    public BenefitView getMine(long userId, long benefitId) {
        if (userId <= 0 || benefitId <= 0) {
            throw error(LotteryErrorCode.BENEFIT_QUERY_INVALID);
        }
        UserBenefitRow benefit = benefits.selectById(benefitId);
        if (benefit == null) {
            throw error(LotteryErrorCode.BENEFIT_NOT_FOUND);
        }
        if (!Objects.equals(benefit.getUserId(), userId)) {
            throw error(LotteryErrorCode.BENEFIT_ACCESS_DENIED);
        }
        return toViews(List.of(benefit)).get(0);
    }

    private List<BenefitView> toViews(List<UserBenefitRow> rows) {
        if (rows.isEmpty()) {
            return List.of();
        }
        List<Long> recordIds = rows.stream().map(UserBenefitRow::getDrawRecordId)
                .filter(Objects::nonNull).distinct().toList();
        Map<Long, DrawRecordRow> recordById = recordIds.isEmpty() ? Map.of()
                : records.selectBatchIds(recordIds).stream()
                .collect(Collectors.toMap(DrawRecordRow::getId, Function.identity()));

        List<String> fulfillmentNos = rows.stream().map(UserBenefitRow::getFulfillmentNo)
                .filter(value -> value != null && !value.isBlank()).distinct().toList();
        Map<String, String> taskStatusByNo = fulfillmentNos.isEmpty() ? Map.of()
                : fulfillment.getLotteryTaskStatuses(fulfillmentNos).stream()
                .collect(Collectors.toMap(FulfillmentTaskStatusDTO::fulfillmentNo,
                        FulfillmentTaskStatusDTO::status, (first, ignored) -> first));

        List<Long> shippingIds = rows.stream().map(UserBenefitRow::getShippingOrderId)
                .filter(Objects::nonNull).distinct().toList();
        Map<Long, FulfillmentShippingOrderDTO> shippingById = shippingIds.isEmpty() ? Map.of()
                : fulfillment.getShippingOrdersByIds(shippingIds).stream()
                .filter(order -> order.id() != null)
                .collect(Collectors.toMap(FulfillmentShippingOrderDTO::id, Function.identity(),
                        (first, ignored) -> first));

        return rows.stream().map(benefit -> {
            DrawRecordRow record = benefit.getDrawRecordId() == null
                    ? null : recordById.get(benefit.getDrawRecordId());
            FulfillmentShippingOrderDTO shipping = benefit.getShippingOrderId() == null
                    ? null : shippingById.get(benefit.getShippingOrderId());
            String taskStatus = benefit.getFulfillmentNo() == null
                    ? null : taskStatusByNo.get(benefit.getFulfillmentNo());
            return new BenefitView(benefit.getId(), benefit.getDrawRecordId(), benefit.getUserId(),
                    benefit.getPrizeId(), benefit.getPrizeType(), record == null ? null : record.getPrizeName(),
                    record == null ? null : record.getPrizeImageUrl(), benefit.getQuantity(), benefit.getStatus(),
                    benefit.getObtainedAt(), benefit.getExpireAt(), benefit.getRewardDefinitionId(),
                    benefit.getRewardType(), benefit.getRewardQuantity(), benefit.getFulfillmentNo(),
                    taskStatus,
                    shipping == null ? null : shipping.shippingNo(),
                    shipping == null ? null : shipping.status());
        }).toList();
    }

    private long validate(long userId, long page, long size, LocalDate startDate, LocalDate endDate) {
        if (userId <= 0 || page < 1 || page > MAX_PAGE || size < 1 || size > 100
                || invalidDate(startDate, false) || invalidDate(endDate, true)
                || (startDate != null && endDate != null && startDate.isAfter(endDate))) {
            throw error(LotteryErrorCode.BENEFIT_QUERY_INVALID);
        }
        try {
            return Math.multiplyExact(page - 1, size);
        } catch (ArithmeticException exception) {
            throw error(LotteryErrorCode.BENEFIT_QUERY_INVALID);
        }
    }

    private boolean invalidDate(LocalDate date, boolean end) {
        if (date == null) return false;
        LocalDate max = end ? MAX_SAFE_END_DATE : MAX_SAFE_END_DATE.plusDays(1);
        return date.isBefore(MYSQL_MIN_DATE) || date.isAfter(max);
    }

    private LotteryDomainException error(LotteryErrorCode code) {
        return new LotteryDomainException(code);
    }
}

package com.dongqh.lotteryservice.service.benefit;

import com.dongqh.hmapi.client.FulfillmentClient;
import com.dongqh.hmapi.dto.CreateFulfillmentShippingOrderRequest;
import com.dongqh.hmapi.dto.FulfillmentShippingOrderDTO;
import com.dongqh.lotteryservice.domain.dto.benefit.ClaimPhysicalBenefitCommand;
import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.domain.po.draworder.DrawOrderRow;
import com.dongqh.lotteryservice.enums.draworder.DrawOrderStatus;
import com.dongqh.lotteryservice.mapper.draworder.DrawOrderMapper;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.domain.po.drawtransaction.UserBenefitRow;
import com.dongqh.lotteryservice.enums.drawtransaction.BenefitStatus;
import com.dongqh.lotteryservice.mapper.drawtransaction.DrawRecordMapper;
import com.dongqh.lotteryservice.mapper.drawtransaction.UserBenefitMapper;
import com.dongqh.lotteryservice.domain.model.drawtransaction.ProductRewardPayload;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeType;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

@Service
public class LotteryPhysicalBenefitClaimService {
    private static final String SOURCE_TYPE = "LOTTERY_BENEFIT";

    private final UserBenefitMapper benefits;
    private final DrawRecordMapper records;
    private final DrawOrderMapper orders;
    private final FulfillmentClient fulfillment;
    private final ObjectMapper json;

    public LotteryPhysicalBenefitClaimService(UserBenefitMapper benefits, DrawRecordMapper records,
                                              DrawOrderMapper orders, FulfillmentClient fulfillment,
                                              ObjectMapper json) {
        this.benefits = benefits;
        this.records = records;
        this.orders = orders;
        this.fulfillment = fulfillment;
        this.json = json;
    }

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public FulfillmentShippingOrderDTO claim(long userId, long benefitId, String authorization,
                                             ClaimPhysicalBenefitCommand command) {
        if (userId <= 0 || benefitId <= 0 || authorization == null || authorization.isBlank()) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_NOT_ALLOWED);
        }
        String requestId = normalizeRequestId(command);
        UserBenefitRow benefit = benefits.selectByIdForUpdate(benefitId);
        if (benefit == null) {
            throw error(LotteryErrorCode.BENEFIT_NOT_FOUND);
        }
        if (!Objects.equals(benefit.getUserId(), userId)) {
            throw error(LotteryErrorCode.BENEFIT_ACCESS_DENIED);
        }
        ProductRewardPayload product = frozenProduct(benefit);
        verifyDrawIdentity(benefit, userId);

        LocalDateTime now = LocalDateTime.now().truncatedTo(ChronoUnit.MILLIS);
        if (benefit.getShippingOrderId() == null) {
            if (benefit.getStatus() != BenefitStatus.CLAIM_PENDING) {
                throw error(LotteryErrorCode.BENEFIT_CLAIM_NOT_ALLOWED);
            }
            if (benefit.getClaimDeadline() == null || !now.isBefore(benefit.getClaimDeadline())) {
                throw error(LotteryErrorCode.BENEFIT_CLAIM_EXPIRED);
            }
        } else if (!claimLifecycle(benefit.getStatus())) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_NOT_ALLOWED);
        }

        FulfillmentShippingOrderDTO shipping = fulfillment.createShippingOrder(authorization,
                new CreateFulfillmentShippingOrderRequest(SOURCE_TYPE, Long.toString(benefitId), userId,
                        command.addressId(), product.itemId(), itemCode(product.itemId()), product.itemName(),
                        product.itemImage(), product.quantity(), requestId));
        if (shipping == null || shipping.id() == null || shipping.id() <= 0
                || !("LOGISTICS-" + shipping.id()).equals(shipping.fulfillmentNo())
                || shipping.shippingNo() == null || shipping.shippingNo().isBlank()
                || shipping.addressSnapshotId() == null || shipping.addressSnapshotId() <= 0) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_IDENTITY_CONFLICT);
        }
        if (benefit.getShippingOrderId() != null && !benefit.getShippingOrderId().equals(shipping.id())) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_IDENTITY_CONFLICT);
        }
        if (benefit.getShippingOrderId() == null
                && benefits.markClaimed(benefitId, shipping.id(), now) != 1) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_IDENTITY_CONFLICT);
        }
        return shipping;
    }

    private ProductRewardPayload frozenProduct(UserBenefitRow benefit) {
        if (benefit.getPrizeType() != PrizeType.PHYSICAL || benefit.getRewardType() != RewardType.PRODUCT
                || benefit.getRewardTargetId() == null || benefit.getRewardQuantity() == null
                || benefit.getRewardPayload() == null || benefit.getQuantity() == null) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_NOT_ALLOWED);
        }
        try {
            ProductRewardPayload product = json.readValue(benefit.getRewardPayload(), ProductRewardPayload.class);
            if (!Objects.equals(benefit.getRewardTargetId(), product.itemId())
                    || benefit.getRewardQuantity() != product.quantity()
                    || !Objects.equals(benefit.getQuantity(), product.quantity())) {
                throw error(LotteryErrorCode.BENEFIT_CLAIM_IDENTITY_CONFLICT);
            }
            return product;
        } catch (JacksonException | IllegalArgumentException exception) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_IDENTITY_CONFLICT);
        }
    }

    private void verifyDrawIdentity(UserBenefitRow benefit, long userId) {
        DrawRecordRow record = benefit.getDrawRecordId() == null ? null : records.selectById(benefit.getDrawRecordId());
        DrawOrderRow order = record == null || record.getOrderId() == null
                ? null : orders.selectById(record.getOrderId());
        if (record == null || order == null || order.getStatus() != DrawOrderStatus.SUCCESS
                || !Objects.equals(order.getUserId(), userId)
                || !Objects.equals(record.getUserId(), userId)
                || !Objects.equals(record.getId(), benefit.getDrawRecordId())
                || !Objects.equals(record.getPrizeId(), benefit.getPrizeId())
                || record.getPrizeType() != benefit.getPrizeType()
                || !Objects.equals(record.getRewardDefinitionId(), benefit.getRewardDefinitionId())
                || record.getRewardType() != benefit.getRewardType()
                || !Objects.equals(record.getRewardTargetId(), benefit.getRewardTargetId())
                || !Objects.equals(record.getRewardQuantity(), benefit.getRewardQuantity())
                || !Objects.equals(record.getRewardPayload(), benefit.getRewardPayload())
                || !Objects.equals(record.getRewardFingerprint(), benefit.getRewardFingerprint())) {
            throw error(LotteryErrorCode.BENEFIT_CLAIM_IDENTITY_CONFLICT);
        }
    }

    private boolean claimLifecycle(BenefitStatus status) {
        return status == BenefitStatus.CLAIMED || status == BenefitStatus.FULFILLING
                || status == BenefitStatus.SHIPPED || status == BenefitStatus.DELIVERED
                || status == BenefitStatus.FULFILLMENT_FAILED || status == BenefitStatus.FULFILLMENT_TERMINATED;
    }

    private String normalizeRequestId(ClaimPhysicalBenefitCommand command) {
        if (command == null || command.addressId() == null || command.addressId() <= 0
                || command.requestId() == null || command.requestId().isBlank()) {
            throw error(LotteryErrorCode.BENEFIT_QUERY_INVALID);
        }
        String raw = command.requestId().trim();
        try {
            String normalized = UUID.fromString(raw).toString();
            if (!normalized.equalsIgnoreCase(raw)) {
                throw new IllegalArgumentException();
            }
            return normalized;
        } catch (IllegalArgumentException exception) {
            throw error(LotteryErrorCode.BENEFIT_QUERY_INVALID);
        }
    }

    private String itemCode(long itemId) {
        return "HMALL-ITEM-" + itemId;
    }

    private LotteryDomainException error(LotteryErrorCode code) {
        return new LotteryDomainException(code);
    }
}

package com.dongqh.lotteryservice.service.drawchance;

import com.dongqh.hmapi.client.UserClient;
import com.dongqh.lotteryservice.domain.po.drawchance.DrawChanceAccountRow;
import com.dongqh.lotteryservice.domain.po.drawchance.DrawChanceLedgerRow;
import com.dongqh.lotteryservice.domain.po.drawchance.DrawChanceReservationRow;
import com.dongqh.lotteryservice.enums.drawchance.DrawChanceBusinessType;
import com.dongqh.lotteryservice.enums.drawchance.DrawChanceDirection;
import com.dongqh.lotteryservice.enums.drawchance.DrawChanceReservationStatus;
import com.dongqh.lotteryservice.mapper.drawchance.DrawChanceAccountMapper;
import com.dongqh.lotteryservice.mapper.drawchance.DrawChanceLedgerMapper;
import com.dongqh.lotteryservice.mapper.drawchance.DrawChanceReservationMapper;
import com.dongqh.lotteryservice.domain.model.drawchance.DrawChanceReservationCommand;
import com.dongqh.lotteryservice.domain.model.drawchance.DrawChanceReservationResult;
import com.dongqh.lotteryservice.domain.vo.drawchance.DrawChanceAccountView;
import com.dongqh.lotteryservice.domain.po.draworder.DrawOrderRow;
import com.dongqh.lotteryservice.enums.draworder.DrawOrderStatus;
import com.dongqh.lotteryservice.mapper.draworder.DrawOrderMapper;
import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Objects;

@Service
public class DrawChanceReservationService {
    private final DrawChanceAccountMapper accounts;
    private final DrawChanceLedgerMapper ledgers;
    private final DrawChanceReservationMapper reservations;
    private final DrawOrderMapper orders;
    private final UserClient users;

    @Autowired
    public DrawChanceReservationService(DrawChanceAccountMapper accounts, DrawChanceLedgerMapper ledgers,
                                       DrawChanceReservationMapper reservations, DrawOrderMapper orders,
                                       UserClient users) {
        this.accounts = accounts;
        this.ledgers = ledgers;
        this.reservations = reservations;
        this.orders = orders;
        this.users = users;
    }

    public DrawChanceReservationService(DrawChanceAccountMapper accounts, DrawChanceLedgerMapper ledgers,
                                       DrawChanceReservationMapper reservations, DrawOrderMapper orders) {
        this(accounts, ledgers, reservations, orders, null);
    }

    @Transactional
    public void credit(long userId, String businessId, long chances) {
        if (userId <= 0 || businessId == null || businessId.isBlank() || businessId.length() > 100 || chances <= 0) {
            throw error(LotteryErrorCode.DRAW_CHANCE_INVALID_REQUEST);
        }
        if (users != null && !Boolean.TRUE.equals(users.isEnabled(userId))) {
            throw error(LotteryErrorCode.DRAW_CHANCE_USER_UNAVAILABLE);
        }
        DrawChanceAccountRow account = lockAccount(userId);
        DrawChanceLedgerRow existing = ledgers.selectBusiness(DrawChanceBusinessType.LOTTERY_REWARD, businessId);
        if (existing != null) {
            if (!Objects.equals(existing.getUserId(), userId) || !Objects.equals(existing.getAmount(), chances)
                    || existing.getDirection() != DrawChanceDirection.CREDIT) {
                throw error(LotteryErrorCode.DRAW_CHANCE_IDENTITY_CONFLICT);
            }
            return;
        }
        long available = exactAdd(account.getAvailableBalance(), chances);
        updateAccount(account, available, account.getReservedBalance());
        insertLedger(userId, DrawChanceBusinessType.LOTTERY_REWARD, businessId,
                DrawChanceDirection.CREDIT, chances, available, account.getReservedBalance());
    }

    public DrawChanceAccountView get(long userId) {
        if (userId <= 0) throw error(LotteryErrorCode.DRAW_CHANCE_INVALID_REQUEST);
        DrawChanceAccountRow account = accounts.selectByUserId(userId);
        return account == null ? new DrawChanceAccountView(userId, 0, 0)
                : new DrawChanceAccountView(userId, account.getAvailableBalance(), account.getReservedBalance());
    }

    /**
     * 预留奖励抽奖次数。requestId 唯一约束负责幂等，账户行锁负责余额并发安全。
     */
    @Transactional
    public DrawChanceReservationResult reserve(DrawChanceReservationCommand command) {
        DrawChanceReservationRow candidate = new DrawChanceReservationRow();
        candidate.setRequestId(command.requestId());
        candidate.setUserId(command.userId());
        candidate.setActivityId(command.activityId());
        candidate.setDrawDate(command.drawDate());
        candidate.setDrawCount(command.drawCount());
        int inserted = reservations.insertIfAbsent(candidate);
        DrawChanceReservationRow reservation = reservations.lockByRequestId(command.requestId());
        requireSameIdentity(reservation, command);
        if (inserted == 0) {
            return result(reservation, true);
        }

        DrawChanceAccountRow account = lockAccount(command.userId());
        long bonus = Math.min(account.getAvailableBalance(), command.drawCount());
        if (bonus > 0) {
            updateAccount(account, account.getAvailableBalance() - bonus,
                    exactAdd(account.getReservedBalance(), bonus));
            if (reservations.setBonus(reservation.getId(), bonus) != 1) {
                throw balanceError();
            }
            reservation.setBonusReserved(bonus);
        }
        return result(reservation, false);
    }

    @Transactional
    public void confirm(String requestId) {
        settle(requestId, DrawChanceReservationStatus.CONFIRMED);
    }

    @Transactional
    public void release(String requestId) {
        settle(requestId, DrawChanceReservationStatus.RELEASED);
    }

    @Transactional
    public boolean confirmIfReserved(String requestId) {
        return settleIfPresent(requestId, DrawChanceReservationStatus.CONFIRMED);
    }

    @Transactional
    public boolean releaseIfReserved(String requestId) {
        return settleIfPresent(requestId, DrawChanceReservationStatus.RELEASED);
    }

    @Transactional
    public int reconcileExpired(int limit, LocalDateTime cutoff) {
        if (limit <= 0 || limit > 1000 || cutoff == null) {
            throw error(LotteryErrorCode.DRAW_CHANCE_INVALID_REQUEST);
        }
        int settled = 0;
        for (DrawChanceReservationRow reservation : reservations.lockExpired(limit, cutoff)) {
            DrawOrderRow order = orders.selectByRequestIdForUpdate(reservation.getRequestId());
            if (order != null && order.getStatus() == DrawOrderStatus.SUCCESS) {
                settleLocked(reservation, DrawChanceReservationStatus.CONFIRMED);
                settled++;
            } else if (order != null && order.getStatus() == DrawOrderStatus.FAILED) {
                settleLocked(reservation, DrawChanceReservationStatus.RELEASED);
                settled++;
            } else if (order == null) {
                settleLocked(reservation, DrawChanceReservationStatus.RELEASED);
                settled++;
            }
        }
        return settled;
    }

    private void settle(String requestId, DrawChanceReservationStatus target) {
        if (!settleIfPresent(requestId, target)) {
            throw error(LotteryErrorCode.DRAW_CHANCE_RESERVATION_NOT_FOUND);
        }
    }

    private boolean settleIfPresent(String requestId, DrawChanceReservationStatus target) {
        if (requestId == null || requestId.isBlank() || requestId.length() > 64) {
            throw error(LotteryErrorCode.DRAW_CHANCE_INVALID_REQUEST);
        }
        DrawChanceReservationRow reservation = reservations.lockByRequestId(requestId);
        if (reservation == null) {
            return false;
        }
        if (reservation.getStatus() == target) {
            return true;
        }
        if (reservation.getStatus() != DrawChanceReservationStatus.RESERVED) {
            throw error(LotteryErrorCode.DRAW_CHANCE_TERMINAL_STATE_CONFLICT);
        }
        settleLocked(reservation, target);
        return true;
    }

    private void settleLocked(DrawChanceReservationRow reservation, DrawChanceReservationStatus target) {
        long bonus = reservation.getBonusReserved();
        if (bonus > 0) {
            DrawChanceAccountRow account = lockAccount(reservation.getUserId());
            if (account.getReservedBalance() < bonus) {
                throw balanceError();
            }
            long available = account.getAvailableBalance();
            DrawChanceBusinessType type;
            DrawChanceDirection direction;
            if (target == DrawChanceReservationStatus.RELEASED) {
                available = exactAdd(available, bonus);
                type = DrawChanceBusinessType.DRAW_RELEASE;
                direction = DrawChanceDirection.CREDIT;
            } else {
                type = DrawChanceBusinessType.DRAW_CONSUME;
                direction = DrawChanceDirection.DEBIT;
            }
            long reserved = account.getReservedBalance() - bonus;
            updateAccount(account, available, reserved);
            insertLedger(reservation.getUserId(), type, reservation.getRequestId(), direction,
                    bonus, available, reserved);
        }
        if (reservations.settle(reservation.getId(), target) != 1) {
            throw balanceError();
        }
        reservation.setStatus(target);
    }

    private DrawChanceReservationResult result(DrawChanceReservationRow reservation, boolean duplicate) {
        long cumulative = reservations.sumActiveBonus(reservation.getUserId(),
                reservation.getActivityId(), reservation.getDrawDate());
        return new DrawChanceReservationResult(reservation.getRequestId(), reservation.getActivityId(),
                reservation.getUserId(), reservation.getDrawCount(), reservation.getDrawDate(),
                reservation.getBonusReserved(), cumulative, reservation.getStatus(), duplicate);
    }

    private void requireSameIdentity(DrawChanceReservationRow reservation, DrawChanceReservationCommand command) {
        if (reservation == null || !Objects.equals(reservation.getUserId(), command.userId())
                || !Objects.equals(reservation.getActivityId(), command.activityId())
                || !Objects.equals(reservation.getDrawCount(), command.drawCount())
                || !Objects.equals(reservation.getDrawDate(), command.drawDate())) {
            throw error(LotteryErrorCode.DRAW_CHANCE_IDENTITY_CONFLICT);
        }
    }

    private DrawChanceAccountRow lockAccount(long userId) {
        accounts.insertIfAbsent(userId);
        DrawChanceAccountRow account = accounts.lockByUserId(userId);
        if (account == null) {
            throw balanceError();
        }
        return account;
    }

    private void updateAccount(DrawChanceAccountRow account, long available, long reserved) {
        if (available < 0 || reserved < 0
                || accounts.updateBalances(account.getId(), available, reserved) != 1) {
            throw balanceError();
        }
        account.setAvailableBalance(available);
        account.setReservedBalance(reserved);
    }

    private void insertLedger(long userId, DrawChanceBusinessType type, String businessId,
                              DrawChanceDirection direction, long amount, long available, long reserved) {
        DrawChanceLedgerRow ledger = new DrawChanceLedgerRow();
        ledger.setUserId(userId);
        ledger.setBusinessType(type);
        ledger.setBusinessId(businessId);
        ledger.setDirection(direction);
        ledger.setAmount(amount);
        ledger.setAvailableAfter(available);
        ledger.setReservedAfter(reserved);
        ledgers.insert(ledger);
    }

    private long exactAdd(long left, long right) {
        try {
            return Math.addExact(left, right);
        } catch (ArithmeticException exception) {
            throw balanceError();
        }
    }

    private LotteryDomainException balanceError() {
        return error(LotteryErrorCode.DRAW_CHANCE_BALANCE_INVALID);
    }

    private LotteryDomainException error(LotteryErrorCode code) {
        return new LotteryDomainException(code);
    }
}

package com.dongqh.lotteryservice.service.draweligibility;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.dongqh.hmapi.client.CouponClient;
import com.dongqh.hmapi.client.ItemClient;
import com.dongqh.hmapi.client.MembershipClient;
import com.dongqh.hmapi.dto.CouponRewardTemplateDTO;
import com.dongqh.hmapi.dto.ItemDTO;
import com.dongqh.hmapi.dto.MembershipRewardProductDTO;
import com.dongqh.lotteryservice.enums.activityprize.ActivityStatus;
import com.dongqh.lotteryservice.domain.po.activityprize.ActivityPrizeRow;
import com.dongqh.lotteryservice.domain.po.activityprize.ActivityRow;
import com.dongqh.lotteryservice.mapper.activityprize.ActivityMapper;
import com.dongqh.lotteryservice.mapper.activityprize.ActivityPrizeMapper;
import com.dongqh.lotteryservice.domain.model.drawtransaction.CouponRewardPayload;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawChanceRewardPayload;
import com.dongqh.lotteryservice.domain.model.draweligibility.EligibilitySnapshot;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawPrizeSnapshot;
import com.dongqh.lotteryservice.domain.model.drawtransaction.MembershipRewardPayload;
import com.dongqh.lotteryservice.domain.model.drawtransaction.PointsRewardPayload;
import com.dongqh.lotteryservice.domain.model.drawtransaction.ProductRewardPayload;
import com.dongqh.lotteryservice.domain.model.drawtransaction.RewardSnapshot;
import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import com.dongqh.lotteryservice.domain.po.prizecatalog.PrizeRow;
import com.dongqh.lotteryservice.domain.po.prizecatalog.RewardDefinitionRow;
import com.dongqh.lotteryservice.mapper.prizecatalog.PrizeCatalogMapper;
import com.dongqh.lotteryservice.mapper.prizecatalog.RewardDefinitionMapper;
import com.dongqh.lotteryservice.config.LotteryProperties;
import org.springframework.stereotype.Service;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
public class DrawEligibilityService {
    private static final int ENABLED = 1;
    private static final long MAX_DISCRETE_QUANTITY = 100;

    private final ActivityMapper activities;
    private final ActivityPrizeMapper activityPrizes;
    private final PrizeCatalogMapper prizes;
    private final RewardDefinitionMapper rewardDefinitions;
    private final ItemClient items;
    private final CouponClient coupons;
    private final MembershipClient memberships;
    private final ObjectMapper json;
    private final Clock clock;

    public DrawEligibilityService(ActivityMapper activities, ActivityPrizeMapper activityPrizes,
                                  PrizeCatalogMapper prizes, RewardDefinitionMapper rewardDefinitions,
                                  ItemClient items, CouponClient coupons, MembershipClient memberships,
                                  ObjectMapper json, LotteryProperties properties) {
        this.activities = activities;
        this.activityPrizes = activityPrizes;
        this.prizes = prizes;
        this.rewardDefinitions = rewardDefinitions;
        this.items = items;
        this.coupons = coupons;
        this.memberships = memberships;
        this.json = json;
        this.clock = Clock.system(properties.zoneId());
    }

    public EligibilitySnapshot load(long activityId) {
        ActivityRow activity = activities.selectById(activityId);
        if (activity == null) throw error(LotteryErrorCode.ACTIVITY_NOT_FOUND);
        LocalDateTime now = LocalDateTime.now(clock).truncatedTo(ChronoUnit.MILLIS);
        if (activity.getStatus() != ActivityStatus.RUNNING || activity.getStartTime() == null
                || activity.getEndTime() == null || now.isBefore(activity.getStartTime())
                || !now.isBefore(activity.getEndTime())) {
            throw error(LotteryErrorCode.ACTIVITY_NOT_AVAILABLE);
        }

        List<ActivityPrizeRow> relations = activityPrizes.selectList(new LambdaQueryWrapper<ActivityPrizeRow>()
                .eq(ActivityPrizeRow::getActivityId, activityId)
                .orderByAsc(ActivityPrizeRow::getSortOrder)
                .orderByAsc(ActivityPrizeRow::getId));
        List<Long> prizeIds = relations.stream().map(ActivityPrizeRow::getPrizeId).distinct().toList();
        Map<Long, PrizeRow> prizeById = prizeIds.isEmpty() ? Map.of()
                : byId(prizes.selectByIds(prizeIds), PrizeRow::getId);
        List<Long> definitionIds = prizeById.values().stream().map(PrizeRow::getRewardDefinitionId)
                .filter(Objects::nonNull).distinct().toList();
        Map<Long, RewardDefinitionRow> definitions = definitionIds.isEmpty() ? Map.of()
                : byId(rewardDefinitions.selectByIds(definitionIds), RewardDefinitionRow::getId);
        TargetIndex targets = loadTargets(definitions.values().stream().toList());

        List<DrawPrizeSnapshot> snapshots = relations.stream().map(relation -> {
            PrizeRow prize = prizeById.get(relation.getPrizeId());
            if (prize == null) throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
            RewardSnapshot reward = reward(prize, definitions, targets);
            return new DrawPrizeSnapshot(relation.getId(), prize.getId(), prize.getPrizeName(),
                    prize.getPrizeType(), prize.getImageUrl(), relation.getWeight(),
                    relation.getRemainingStock(), Integer.valueOf(ENABLED).equals(prize.getStatus()), reward);
        }).toList();

        int noWinWeight = activity.getNoWinWeight() == null ? 0 : activity.getNoWinWeight();
        if (noWinWeight < 0 || (snapshots.isEmpty() && noWinWeight == 0)) {
            throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        }
        return new EligibilitySnapshot(activityId, noWinWeight, snapshots, now);
    }

    private TargetIndex loadTargets(List<RewardDefinitionRow> definitions) {
        List<Long> couponIds = targetIds(definitions, RewardType.COUPON);
        List<Long> membershipIds = targetIds(definitions, RewardType.MEMBERSHIP);
        List<Long> itemIds = targetIds(definitions, RewardType.PRODUCT);
        Map<Long, CouponRewardTemplateDTO> couponById = couponIds.stream().collect(Collectors.toMap(
                Function.identity(), coupons::getRewardTemplate));
        Map<Long, MembershipRewardProductDTO> membershipById = membershipIds.stream().collect(Collectors.toMap(
                Function.identity(), memberships::getRewardProduct));
        Map<Long, ItemDTO> itemById = itemIds.isEmpty() ? Map.of()
                : items.queryItemByIds(itemIds).stream().filter(Objects::nonNull)
                .filter(item -> item.getId() != null)
                .collect(Collectors.toMap(ItemDTO::getId, Function.identity(), (left, right) -> left));
        return new TargetIndex(couponById, membershipById, itemById);
    }

    private List<Long> targetIds(List<RewardDefinitionRow> definitions, RewardType type) {
        return definitions.stream().filter(item -> item.getRewardType() == type)
                .map(RewardDefinitionRow::getTargetId).filter(Objects::nonNull).distinct().toList();
    }

    private RewardSnapshot reward(PrizeRow prize, Map<Long, RewardDefinitionRow> definitions, TargetIndex targets) {
        if (prize.getRewardDefinitionId() == null) return null;
        RewardDefinitionRow definition = definitions.get(prize.getRewardDefinitionId());
        if (definition == null || !Integer.valueOf(ENABLED).equals(definition.getStatus())
                || definition.getRewardCode() == null || definition.getRewardCode().isBlank()
                || definition.getRewardType() == null || definition.getQuantity() == null) {
            throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        }
        Object payload;
        try {
            payload = payload(definition, targets);
        } catch (ArithmeticException exception) {
            throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        }
        String payloadJson;
        try {
            payloadJson = json.writeValueAsString(payload);
        } catch (JacksonException exception) {
            throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        }
        String identity = definition.getId() + "\n" + definition.getRewardCode() + "\n"
                + definition.getRewardType() + "\n" + Objects.toString(definition.getTargetId(), "")
                + "\n" + definition.getQuantity() + "\n" + payloadJson;
        return new RewardSnapshot(definition.getId(), definition.getRewardCode(), definition.getRewardType(),
                definition.getTargetId(), definition.getQuantity(), payloadJson, digest(identity));
    }

    private Object payload(RewardDefinitionRow definition, TargetIndex targets) {
        long quantity = definition.getQuantity();
        if (quantity <= 0) throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        return switch (definition.getRewardType()) {
            case POINTS -> {
                if (definition.getTargetId() != null) throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
                yield new PointsRewardPayload(quantity, "抽奖奖励");
            }
            case DRAW_CHANCE -> {
                requireDiscrete(definition);
                if (definition.getTargetId() != null) throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
                yield new DrawChanceRewardPayload(Math.toIntExact(quantity));
            }
            case COUPON -> {
                requireDiscrete(definition);
                CouponRewardTemplateDTO template = targets.coupons().get(requiredTarget(definition));
                if (template == null || !Integer.valueOf(ENABLED).equals(template.status())) {
                    throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
                }
                yield new CouponRewardPayload(template.id(), template.templateCode(), Math.toIntExact(quantity));
            }
            case MEMBERSHIP -> {
                requireDiscrete(definition);
                MembershipRewardProductDTO product = targets.memberships().get(requiredTarget(definition));
                if (product == null || !Integer.valueOf(ENABLED).equals(product.status())
                        || product.durationDays() == null || product.durationDays() <= 0) {
                    throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
                }
                int count = Math.toIntExact(quantity);
                yield new MembershipRewardPayload(product.id(), product.productCode(), product.membershipLevel(),
                        Math.multiplyExact(product.durationDays(), count), count);
            }
            case PRODUCT -> {
                requireDiscrete(definition);
                ItemDTO item = targets.items().get(requiredTarget(definition));
                if (item == null || !Integer.valueOf(ENABLED).equals(item.getStatus())
                        || item.getStock() == null || item.getStock() <= 0 || item.getPrice() == null) {
                    throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
                }
                yield new ProductRewardPayload(item.getId(), item.getName(), item.getImage(), item.getPrice(),
                        Math.toIntExact(quantity));
            }
        };
    }

    private void requireDiscrete(RewardDefinitionRow definition) {
        if (definition.getQuantity() > MAX_DISCRETE_QUANTITY) {
            throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        }
    }

    private long requiredTarget(RewardDefinitionRow definition) {
        if (definition.getTargetId() == null || definition.getTargetId() <= 0) {
            throw error(LotteryErrorCode.DRAW_WEIGHT_INVALID);
        }
        return definition.getTargetId();
    }

    private String digest(String value) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException(exception);
        }
    }

    private <T> Map<Long, T> byId(List<T> values, Function<T, Long> idExtractor) {
        return values.stream().collect(Collectors.toMap(idExtractor, Function.identity()));
    }

    private LotteryDomainException error(LotteryErrorCode code) {
        return new LotteryDomainException(code);
    }

    private record TargetIndex(Map<Long, CouponRewardTemplateDTO> coupons,
                               Map<Long, MembershipRewardProductDTO> memberships,
                               Map<Long, ItemDTO> items) {
    }
}

package com.dongqh.lotteryservice.service.draworder;

import com.dongqh.lotteryservice.domain.po.draworder.DrawOrderRow;
import com.dongqh.lotteryservice.enums.draworder.DrawOrderStatus;
import com.dongqh.lotteryservice.mapper.draworder.DrawOrderMapper;
import com.dongqh.lotteryservice.domain.model.draworder.NewDrawOrder;
import com.dongqh.lotteryservice.outbox.event.DrawEventEnvelope;
import com.dongqh.lotteryservice.outbox.event.DrawEventType;
import com.dongqh.lotteryservice.outbox.event.DrawReleaseRequestedEvent;
import com.dongqh.lotteryservice.outbox.service.OutboxService;
import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;

import java.time.LocalDateTime;
import java.util.Objects;

@Service
public class DrawOrderLifecycleService {
    private static final int MAX_REASON_LENGTH = 500;
    private static final String DEFAULT_SAFE_REASON = "DRAW_TRANSACTION_FAILED";

    private final DrawOrderMapper orderMapper;
    private final OutboxService outboxService;
    private final ObjectMapper objectMapper;

    public DrawOrderLifecycleService(DrawOrderMapper orderMapper, OutboxService outboxService,
                                     ObjectMapper objectMapper) {
        this.orderMapper = orderMapper;
        this.outboxService = outboxService;
        this.objectMapper = objectMapper;
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public DrawOrderRow createProcessing(NewDrawOrder command) {
        Objects.requireNonNull(command, "command must not be null");
        DrawOrderRow existing = orderMapper.selectByRequestId(command.requestId());
        if (existing != null) {
            validateIdentity(existing, command);
            return existing;
        }

        DrawOrderRow order = new DrawOrderRow();
        order.setRequestId(command.requestId());
        order.setUserId(command.userId());
        order.setActivityId(command.activityId());
        order.setDrawCount(command.drawCount());
        order.setDrawDate(command.drawDate());
        order.setStatus(DrawOrderStatus.PROCESSING);
        orderMapper.insertProcessingIfAbsent(order);

        DrawOrderRow persisted = orderMapper.selectByRequestIdForUpdate(command.requestId());
        validateIdentity(persisted, command);
        return persisted;
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void markFailed(long orderId, String safeReason) {
        if (orderId <= 0) {
            throw new IllegalArgumentException("orderId must be positive");
        }
        orderMapper.markFailedIfProcessing(orderId, normalizeReason(safeReason));
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void markFailedAndRequestRelease(DrawOrderRow order, String safeReason, LocalDateTime occurredAt) {
        Objects.requireNonNull(order, "order must not be null");
        Objects.requireNonNull(occurredAt, "occurredAt must not be null");
        String reason = normalizeReason(safeReason);
        if (orderMapper.markFailedIfProcessing(order.getId(), reason) != 1) {
            return;
        }
        outboxService.append(DrawEventEnvelope.create(
                DrawEventType.DRAW_RELEASE_REQUESTED, order.getRequestId(), order.getUserId(),
                order.getActivityId(), order.getId(), occurredAt,
                new DrawReleaseRequestedEvent(order.getDrawCount(), order.getDrawDate(), reason), objectMapper));
    }

    private void validateIdentity(DrawOrderRow order, NewDrawOrder command) {
        if (order == null
                || !Objects.equals(order.getUserId(), command.userId())
                || !Objects.equals(order.getActivityId(), command.activityId())
                || !Objects.equals(order.getDrawCount(), command.drawCount())) {
            throw new LotteryDomainException(LotteryErrorCode.IDEMPOTENCY_CONFLICT);
        }
    }

    private String normalizeReason(String reason) {
        String normalized = reason == null ? "" : reason.trim();
        if (normalized.isEmpty()) {
            normalized = DEFAULT_SAFE_REASON;
        }
        return normalized.length() <= MAX_REASON_LENGTH ? normalized : normalized.substring(0, MAX_REASON_LENGTH);
    }
}

package com.dongqh.lotteryservice.service.draworder;

import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.domain.po.draworder.DrawOrderRow;
import com.dongqh.lotteryservice.enums.draworder.DrawOrderStatus;
import com.dongqh.lotteryservice.mapper.draworder.DrawOrderMapper;
import com.dongqh.lotteryservice.domain.vo.draworder.DrawOrderView;
import com.dongqh.lotteryservice.domain.vo.draworder.DrawRecordView;
import com.dongqh.lotteryservice.domain.vo.draworder.DrawResultView;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.enums.drawtransaction.DrawResultType;
import com.dongqh.lotteryservice.mapper.drawtransaction.DrawRecordMapper;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import com.dongqh.lotteryservice.domain.vo.prizecatalog.PageResponse;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

@Service
public class LotteryDrawQueryService {
    private static final long MAX_PAGE = 1_000_000L;
    private static final LocalDate MYSQL_MIN_DATE = LocalDate.of(1000, 1, 1);
    private static final LocalDate MAX_SAFE_END_DATE = LocalDate.of(9999, 12, 30);

    private final DrawOrderMapper orders;
    private final DrawRecordMapper records;

    public LotteryDrawQueryService(DrawOrderMapper orders, DrawRecordMapper records) {
        this.orders = orders;
        this.records = records;
    }

    public PageResponse<DrawOrderView> pageMyOrders(long userId, long page, long size, Long activityId,
                                                     DrawOrderStatus status, LocalDate drawDate) {
        long offset = validatePage(page, size);
        if (userId <= 0 || (activityId != null && activityId <= 0)
                || (drawDate != null && (drawDate.isBefore(MYSQL_MIN_DATE)
                || drawDate.isAfter(MAX_SAFE_END_DATE.plusDays(1))))) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        List<DrawOrderRow> rows = orders.selectMinePage(userId, activityId, status, drawDate, size, offset);
        long total = orders.countMine(userId, activityId, status, drawDate);
        Map<Long, List<DrawRecordRow>> resultRows = rows.isEmpty() ? Map.of()
                : records.selectByOrderIds(rows.stream().map(DrawOrderRow::getId).toList()).stream()
                .collect(Collectors.groupingBy(DrawRecordRow::getOrderId));
        List<DrawOrderView> views = rows.stream().map(order -> new DrawOrderView(order.getId(),
                order.getRequestId(), order.getActivityId(), order.getDrawCount(), order.getDrawDate(),
                order.getStatus(), order.getFailReason(), order.getCompletedAt(),
                resultRows.getOrDefault(order.getId(), List.of()).stream().map(this::resultView).toList()))
                .toList();
        return orderPage(views, total, page, size);
    }

    public PageResponse<DrawOrderView> pageOrders(Long userId, long page, long size, Long activityId,
                                                  DrawOrderStatus status, LocalDate drawDate) {
        long offset = validatePage(page, size);
        if ((userId != null && userId <= 0) || (activityId != null && activityId <= 0)
                || (drawDate != null && (drawDate.isBefore(MYSQL_MIN_DATE)
                || drawDate.isAfter(MAX_SAFE_END_DATE.plusDays(1))))) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        List<DrawOrderRow> rows = orders.selectAdminPage(userId, activityId, status, drawDate, size, offset);
        long total = orders.countAdmin(userId, activityId, status, drawDate);
        Map<Long, List<DrawRecordRow>> resultRows = rows.isEmpty() ? Map.of()
                : records.selectByOrderIds(rows.stream().map(DrawOrderRow::getId).toList()).stream()
                .collect(Collectors.groupingBy(DrawRecordRow::getOrderId));
        List<DrawOrderView> views = rows.stream().map(order -> new DrawOrderView(order.getId(),
                order.getRequestId(), order.getActivityId(), order.getDrawCount(), order.getDrawDate(),
                order.getStatus(), order.getFailReason(), order.getCompletedAt(),
                resultRows.getOrDefault(order.getId(), List.of()).stream().map(this::resultView).toList()))
                .toList();
        return orderPage(views, total, page, size);
    }

    public PageResponse<DrawRecordView> pageMyRecords(long userId, long page, long size, Long activityId,
                                                       DrawResultType resultType, LocalDate startDate,
                                                       LocalDate endDate) {
        long offset = validatePage(page, size);
        if (userId <= 0 || (activityId != null && activityId <= 0)
                || invalidDate(startDate, false) || invalidDate(endDate, true)
                || (startDate != null && endDate != null && startDate.isAfter(endDate))) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        LocalDateTime startTime = startDate == null ? null : startDate.atStartOfDay();
        LocalDateTime endTime = endDate == null ? null : endDate.plusDays(1).atStartOfDay();
        List<DrawRecordRow> rows = records.selectMinePage(userId, activityId, resultType,
                startTime, endTime, size, offset);
        long total = records.countMine(userId, activityId, resultType, startTime, endTime);
        return recordPage(rows.stream().map(this::recordView).toList(), total, page, size);
    }

    public PageResponse<DrawRecordView> pageRecords(Long userId, long page, long size, Long activityId,
                                                     DrawResultType resultType, LocalDate startDate,
                                                     LocalDate endDate) {
        long offset = validatePage(page, size);
        if ((userId != null && userId <= 0) || (activityId != null && activityId <= 0)
                || invalidDate(startDate, false) || invalidDate(endDate, true)
                || (startDate != null && endDate != null && startDate.isAfter(endDate))) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        LocalDateTime startTime = startDate == null ? null : startDate.atStartOfDay();
        LocalDateTime endTime = endDate == null ? null : endDate.plusDays(1).atStartOfDay();
        List<DrawRecordRow> rows = records.selectAdminPage(userId, activityId, resultType,
                startTime, endTime, size, offset);
        long total = records.countAdmin(userId, activityId, resultType, startTime, endTime);
        return recordPage(rows.stream().map(this::recordView).toList(), total, page, size);
    }

    private boolean invalidDate(LocalDate date, boolean end) {
        if (date == null) return false;
        LocalDate max = end ? MAX_SAFE_END_DATE : MAX_SAFE_END_DATE.plusDays(1);
        return date.isBefore(MYSQL_MIN_DATE) || date.isAfter(max);
    }

    private long validatePage(long page, long size) {
        if (page < 1 || page > MAX_PAGE || size < 1 || size > 100) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        try {
            return Math.multiplyExact(page - 1, size);
        } catch (ArithmeticException exception) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
    }

    private DrawResultView resultView(DrawRecordRow row) {
        return new DrawResultView(row.getId(), row.getSequenceNo(), row.getResultType(), row.getPrizeId(),
                row.getPrizeName(), row.getPrizeType(), row.getPrizeImageUrl(), row.getBenefitId(),
                row.getRewardType() == RewardType.PRODUCT ? row.getRewardTargetId() : null);
    }

    private DrawRecordView recordView(DrawRecordRow row) {
        return new DrawRecordView(row.getId(), row.getOrderId(), row.getRequestId(), row.getSequenceNo(),
                row.getUserId(), row.getActivityId(), row.getResultType(), row.getPrizeId(), row.getPrizeName(),
                row.getPrizeType(), row.getPrizeImageUrl(), row.getBenefitId(), row.getDrawTime());
    }

    private PageResponse<DrawOrderView> orderPage(List<DrawOrderView> records, long total, long page, long size) {
        return new PageResponse<>(records, total, page, size, pages(total, size));
    }

    private PageResponse<DrawRecordView> recordPage(List<DrawRecordView> records, long total, long page, long size) {
        return new PageResponse<>(records, total, page, size, pages(total, size));
    }

    private long pages(long total, long size) {
        return total == 0 ? 0 : ((total - 1) / size) + 1;
    }
}

package com.dongqh.lotteryservice.service.draworder;

import com.dongqh.lotteryservice.config.LotteryProperties;
import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.enums.drawchance.DrawChanceReservationStatus;
import com.dongqh.lotteryservice.domain.model.drawchance.DrawChanceReservationCommand;
import com.dongqh.lotteryservice.domain.model.drawchance.DrawChanceReservationResult;
import com.dongqh.lotteryservice.service.drawchance.DrawChanceReservationService;
import com.dongqh.lotteryservice.service.draweligibility.DrawEligibilityService;
import com.dongqh.lotteryservice.domain.model.draweligibility.EligibilitySnapshot;
import com.dongqh.lotteryservice.domain.dto.draworder.DrawCommand;
import com.dongqh.lotteryservice.domain.po.draworder.DrawOrderRow;
import com.dongqh.lotteryservice.enums.draworder.DrawOrderStatus;
import com.dongqh.lotteryservice.mapper.draworder.DrawOrderMapper;
import com.dongqh.lotteryservice.domain.model.draworder.NewDrawOrder;
import com.dongqh.lotteryservice.domain.vo.draworder.DrawOrderView;
import com.dongqh.lotteryservice.domain.vo.draworder.DrawResultView;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.enums.drawtransaction.DrawResultType;
import com.dongqh.lotteryservice.mapper.drawtransaction.DrawRecordMapper;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawExecutionContext;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawExecutionResult;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawResultItem;
import com.dongqh.lotteryservice.domain.model.drawtransaction.RewardSnapshot;
import com.dongqh.lotteryservice.service.drawtransaction.DrawTransactionService;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import com.dongqh.lotteryservice.lock.DrawLockService;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import com.hmall.common.utils.UserContext;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

@Service
public class LotteryDrawService {
    private static final Logger log = LoggerFactory.getLogger(LotteryDrawService.class);

    private final DrawOrderMapper orders;
    private final DrawRecordMapper records;
    private final DrawEligibilityService eligibility;
    private final DrawLockService locks;
    private final DrawOrderLifecycleService lifecycle;
    private final DrawTransactionService transactions;
    private final DrawChanceReservationService drawChances;

    public LotteryDrawService(DrawOrderMapper orders, DrawRecordMapper records,
                              DrawEligibilityService eligibility, DrawLockService locks,
                              DrawOrderLifecycleService lifecycle,
                              DrawTransactionService transactions, DrawChanceReservationService drawChances) {
        this.orders = orders;
        this.records = records;
        this.eligibility = eligibility;
        this.locks = locks;
        this.lifecycle = lifecycle;
        this.transactions = transactions;
        this.drawChances = drawChances;
    }

    /**
     * 执行一次抽奖请求：校验请求、预留次数、创建订单、完成抽奖并返回结果。
     * 每个 requestId 只能对应一个抽奖订单，失败时由生命周期服务负责补偿。
     */
    public DrawOrderView draw(DrawCommand command) {
        validate(command);
        Long contextUserId = UserContext.getUser();
        if (contextUserId == null || contextUserId <= 0) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_ACCESS_DENIED);
        }
        long userId = contextUserId;
        DrawOrderRow existing = orders.selectByRequestId(command.requestId());
        if (existing != null) return resolveExisting(existing, command, userId);

        EligibilitySnapshot snapshot = eligibility.load(command.activityId());
        LocalDate drawDate = snapshot.snapshotTime().toLocalDate();
        DrawOrderRow[] createdOrder = new DrawOrderRow[1];
        try {
            LockedDraw locked = locks.execute(command.activityId(), userId, () -> {
                DrawOrderRow second = orders.selectByRequestId(command.requestId());
                if (second != null) return new LockedDraw(resolveExisting(second, command, userId), null, null);

                DrawChanceReservationCommand chanceCommand = new DrawChanceReservationCommand(
                        command.requestId(), command.activityId(), userId, command.drawCount(), drawDate);

                DrawChanceReservationResult bonus = drawChances.reserve(chanceCommand);
                requireActiveChance(bonus);

                DrawOrderRow processing;
                try {
                    processing = lifecycle.createProcessing(new NewDrawOrder(command.requestId(), userId,
                            command.activityId(), command.drawCount(), drawDate));
                } catch (RuntimeException error) {
                    drawChances.release(command.requestId());
                    throw error;
                }
                createdOrder[0] = processing;
                return new LockedDraw(null, processing, drawDate);
            });

            if (locked.existingView() != null) return locked.existingView();
            DrawOrderRow order = locked.order();
            DrawExecutionResult result = transactions.execute(new DrawExecutionContext(order.getId(),
                    command.requestId(), userId, command.activityId(), command.drawCount(),
                    locked.drawDate(), snapshot.noWinWeight(), snapshot.prizes(),
                    snapshot.snapshotTime()));
            return fromExecution(order, result);
        } catch (LotteryDomainException error) {
            compensateIfNeeded(createdOrder[0], snapshot.snapshotTime());
            throw error;
        } catch (RuntimeException error) {
            compensateIfNeeded(createdOrder[0], snapshot.snapshotTime());
            throw new LotteryDomainException(LotteryErrorCode.DRAW_TRANSACTION_FAILED);
        }
    }

    public DrawOrderView getByRequestId(String requestId) {
        validateRequestId(requestId);
        Long userId = UserContext.getUser();
        if (userId == null || userId <= 0) throw new LotteryDomainException(LotteryErrorCode.DRAW_ACCESS_DENIED);
        DrawOrderRow order = orders.selectByRequestId(requestId);
        if (order == null) throw new LotteryDomainException(LotteryErrorCode.DRAW_ORDER_FAILED);
        if (!userId.equals(order.getUserId())) throw new LotteryDomainException(LotteryErrorCode.DRAW_ACCESS_DENIED);
        return toStoredView(order);
    }

    private DrawOrderView resolveExisting(DrawOrderRow order, DrawCommand command, long userId) {
        if (!Long.valueOf(userId).equals(order.getUserId())) {
            throw new LotteryDomainException(LotteryErrorCode.IDEMPOTENCY_CONFLICT);
        }
        if (!command.activityId().equals(order.getActivityId())
                || !command.drawCount().equals(order.getDrawCount())) {
            throw new LotteryDomainException(LotteryErrorCode.IDEMPOTENCY_CONFLICT);
        }
        if (order.getStatus() == DrawOrderStatus.PROCESSING) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_ORDER_PROCESSING);
        }
        if (order.getStatus() == DrawOrderStatus.FAILED) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_ORDER_FAILED);
        }
        return toStoredView(order);
    }

    private DrawOrderView toStoredView(DrawOrderRow order) {
        List<DrawResultView> resultViews = order.getStatus() == DrawOrderStatus.SUCCESS
                ? records.selectByOrderId(order.getId()).stream().map(this::toView).toList() : List.of();
        return new DrawOrderView(order.getId(), order.getRequestId(), order.getActivityId(), order.getDrawCount(),
                order.getDrawDate(), order.getStatus(), order.getFailReason(), order.getCompletedAt(), resultViews);
    }

    private DrawOrderView fromExecution(DrawOrderRow order, DrawExecutionResult result) {
        List<DrawResultView> items = result.items().stream().map(this::toView).toList();
        return new DrawOrderView(order.getId(), order.getRequestId(), order.getActivityId(), order.getDrawCount(),
                order.getDrawDate(), result.status(), null, result.completedAt(), items);
    }

    private DrawResultView toView(DrawResultItem item) {
        RewardSnapshot reward = item.rewardSnapshot();
        Long itemId = reward != null && reward.rewardType() == RewardType.PRODUCT ? reward.targetId() : null;
        return new DrawResultView(item.recordId(), item.sequenceNo(), item.resultType(), item.prizeId(),
                item.prizeName(), item.prizeType(), item.prizeImageUrl(), item.benefitId(), itemId);
    }

    private DrawResultView toView(DrawRecordRow row) {
        Long itemId = row.getRewardType() == RewardType.PRODUCT ? row.getRewardTargetId() : null;
        return new DrawResultView(row.getId(), row.getSequenceNo(), row.getResultType(), row.getPrizeId(),
                row.getPrizeName(), row.getPrizeType(), row.getPrizeImageUrl(), row.getBenefitId(), itemId);
    }

    private void compensateIfNeeded(DrawOrderRow order, LocalDateTime occurredAt) {
        if (order == null) return;
        try {
            lifecycle.markFailedAndRequestRelease(order, "DRAW_TRANSACTION_FAILED", occurredAt);
        } catch (RuntimeException compensationError) {
            log.error("Failed to compensate lottery draw, requestId={}, orderId={}",
                    order.getRequestId(), order.getId(), compensationError);
        }
    }

    private void requireActiveChance(DrawChanceReservationResult reservation) {
        if (reservation == null || reservation.status() != DrawChanceReservationStatus.RESERVED) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_ORDER_FAILED);
        }
    }

    private void validate(DrawCommand command) {
        if (command == null || command.activityId() == null || command.activityId() <= 0
                || command.drawCount() == null || (command.drawCount() != 1 && command.drawCount() != 10)) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        validateRequestId(command.requestId());
    }

    private void validateRequestId(String requestId) {
        if (requestId == null || requestId.isBlank() || requestId.length() > 64) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        try {
            if (!UUID.fromString(requestId).toString().equalsIgnoreCase(requestId)) {
                throw new IllegalArgumentException();
            }
        } catch (IllegalArgumentException error) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
    }

    private record LockedDraw(DrawOrderView existingView, DrawOrderRow order,
                              LocalDate drawDate) {
    }
}

package com.dongqh.lotteryservice.service.drawtransaction;

import com.dongqh.lotteryservice.algorithm.DrawCandidate;
import com.dongqh.lotteryservice.algorithm.PrizeWeightSnapshot;
import com.dongqh.lotteryservice.algorithm.WeightedDrawEngine;
import com.dongqh.lotteryservice.enums.draworder.DrawOrderStatus;
import com.dongqh.lotteryservice.mapper.draworder.DrawOrderMapper;
import com.dongqh.lotteryservice.domain.po.drawtransaction.DrawRecordRow;
import com.dongqh.lotteryservice.domain.po.drawtransaction.UserBenefitRow;
import com.dongqh.lotteryservice.enums.drawtransaction.BenefitStatus;
import com.dongqh.lotteryservice.enums.drawtransaction.DrawResultType;
import com.dongqh.lotteryservice.mapper.drawtransaction.ActivityPrizeInventoryMapper;
import com.dongqh.lotteryservice.mapper.drawtransaction.DrawRecordMapper;
import com.dongqh.lotteryservice.mapper.drawtransaction.UserBenefitMapper;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawExecutionContext;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawExecutionResult;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawPrizeSnapshot;
import com.dongqh.lotteryservice.domain.model.drawtransaction.DrawResultItem;
import com.dongqh.lotteryservice.domain.model.drawtransaction.RewardSnapshot;
import com.dongqh.lotteryservice.exception.LotteryDomainException;
import com.dongqh.lotteryservice.enums.LotteryErrorCode;
import com.dongqh.lotteryservice.outbox.event.DrawConfirmedEvent;
import com.dongqh.lotteryservice.outbox.event.DrawEventEnvelope;
import com.dongqh.lotteryservice.outbox.event.DrawEventType;
import com.dongqh.lotteryservice.outbox.event.PrizeFulfillmentRequestedEvent;
import com.dongqh.lotteryservice.outbox.service.OutboxService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;

import java.util.ArrayList;
import java.util.List;

@Service
public class DrawTransactionService {
    private final WeightedDrawEngine drawEngine;
    private final ActivityPrizeInventoryMapper inventoryMapper;
    private final DrawOrderMapper orderMapper;
    private final DrawRecordMapper recordMapper;
    private final UserBenefitMapper benefitMapper;
    private final OutboxService outboxService;
    private final ObjectMapper objectMapper;

    public DrawTransactionService(WeightedDrawEngine drawEngine, ActivityPrizeInventoryMapper inventoryMapper,
                                  DrawOrderMapper orderMapper, DrawRecordMapper recordMapper,
                                  UserBenefitMapper benefitMapper, OutboxService outboxService,
                                  ObjectMapper objectMapper) {
        this.drawEngine = drawEngine;
        this.inventoryMapper = inventoryMapper;
        this.orderMapper = orderMapper;
        this.recordMapper = recordMapper;
        this.benefitMapper = benefitMapper;
        this.outboxService = outboxService;
        this.objectMapper = objectMapper;
    }

    @Transactional(propagation = Propagation.REQUIRED)
    public DrawExecutionResult execute(DrawExecutionContext context) {
        List<PrizeWeightSnapshot> weights = context.prizes().stream()
                .map(DrawPrizeSnapshot::toWeightSnapshot)
                .toList();
        List<DrawResultItem> results = new ArrayList<>(context.drawCount());

        for (int sequence = 1; sequence <= context.drawCount(); sequence++) {

            DrawCandidate candidate = drawEngine.select(weights, context.noWinWeight());

            DrawPrizeSnapshot wonPrize = resolveFinalWin(candidate, context.prizes());

            results.add(persistResult(context, sequence, wonPrize));
        }

        if (orderMapper.markSuccessIfProcessing(context.orderId(), context.drawTime()) != 1) {
            throw new LotteryDomainException(LotteryErrorCode.DRAW_TRANSACTION_FAILED);
        }

        appendConfirmedEvent(context);
        results.stream()
                .filter(item -> item.resultType() == DrawResultType.WIN)
                .forEach(item -> appendFulfillmentEvent(context, item));

        return new DrawExecutionResult(context.orderId(), context.requestId(), DrawOrderStatus.SUCCESS,
                context.drawTime(), results);
    }

    private DrawPrizeSnapshot resolveFinalWin(DrawCandidate candidate, List<DrawPrizeSnapshot> snapshots) {
        if (candidate.type() == DrawCandidate.Type.NO_WIN) {
            return null;
        }
        DrawPrizeSnapshot snapshot = snapshots.stream()
                .filter(prize -> prize.activityPrizeId() == candidate.activityPrizeId()
                        && prize.prizeId() == candidate.prizeId())
                .findFirst()
                .orElseThrow(() -> new LotteryDomainException(LotteryErrorCode.DRAW_TRANSACTION_FAILED));
        return inventoryMapper.decrementIfAvailable(snapshot.activityPrizeId()) == 1 ? snapshot : null;
    }

    private DrawResultItem persistResult(DrawExecutionContext context, int sequence, DrawPrizeSnapshot prize) {
        DrawRecordRow record = new DrawRecordRow();
        record.setOrderId(context.orderId());
        record.setRequestId(context.requestId());
        record.setSequenceNo(sequence);
        record.setUserId(context.userId());
        record.setActivityId(context.activityId());
        record.setResultType(prize == null ? DrawResultType.NO_WIN : DrawResultType.WIN);
        record.setDrawTime(context.drawTime());
        if (prize != null) {
            record.setPrizeId(prize.prizeId());
            record.setPrizeName(prize.prizeName());
            record.setPrizeType(prize.prizeType());
            record.setPrizeImageUrl(prize.prizeImageUrl());
            copyReward(prize.rewardSnapshot(), record);
        }
        recordMapper.insert(record);

        Long benefitId = prize == null ? null : persistPendingBenefit(context, record, prize);
        return new DrawResultItem(record.getId(), sequence, record.getResultType(), record.getPrizeId(),
                record.getPrizeName(), record.getPrizeType(), record.getPrizeImageUrl(), benefitId,
                prize == null ? null : prize.rewardSnapshot());
    }

    private Long persistPendingBenefit(DrawExecutionContext context, DrawRecordRow record,
                                      DrawPrizeSnapshot prize) {
        UserBenefitRow benefit = new UserBenefitRow();
        benefit.setDrawRecordId(record.getId());
        benefit.setUserId(context.userId());
        benefit.setPrizeId(prize.prizeId());
        benefit.setPrizeType(prize.prizeType());
        copyReward(prize.rewardSnapshot(), benefit);
        benefit.setQuantity(1);
        benefit.setStatus(BenefitStatus.PENDING);
        benefit.setObtainedAt(context.drawTime());
        benefitMapper.insert(benefit);
        return benefit.getId();
    }

    private void copyReward(RewardSnapshot reward, DrawRecordRow record) {
        if (reward == null) return;
        record.setRewardDefinitionId(reward.rewardDefinitionId());
        record.setRewardType(reward.rewardType());
        record.setRewardTargetId(reward.targetId());
        record.setRewardQuantity(reward.quantity());
        record.setRewardPayload(reward.payloadJson());
        record.setRewardFingerprint(reward.fingerprint());
    }

    private void copyReward(RewardSnapshot reward, UserBenefitRow benefit) {
        if (reward == null) return;
        benefit.setRewardDefinitionId(reward.rewardDefinitionId());
        benefit.setRewardType(reward.rewardType());
        benefit.setRewardTargetId(reward.targetId());
        benefit.setRewardQuantity(reward.quantity());
        benefit.setRewardPayload(reward.payloadJson());
        benefit.setRewardFingerprint(reward.fingerprint());
    }

    private void appendConfirmedEvent(DrawExecutionContext context) {
        outboxService.append(DrawEventEnvelope.create(DrawEventType.DRAW_CONFIRMED,
                context.requestId(), context.userId(), context.activityId(), context.orderId(),
                context.drawTime(), new DrawConfirmedEvent(context.drawCount(), context.drawDate()), objectMapper));
    }

    private void appendFulfillmentEvent(DrawExecutionContext context, DrawResultItem item) {
        RewardSnapshot reward = item.rewardSnapshot();
        outboxService.append(DrawEventEnvelope.create(DrawEventType.PRIZE_FULFILLMENT_REQUESTED,
                context.requestId(), context.userId(), context.activityId(), context.orderId(), context.drawTime(),
                new PrizeFulfillmentRequestedEvent(item.benefitId(), item.recordId(), item.prizeId(), item.prizeType(),
                        reward == null ? null : reward.rewardDefinitionId(),
                        reward == null ? null : reward.rewardType(),
                        reward == null ? null : reward.fingerprint()), objectMapper));
    }
}

package com.dongqh.lotteryservice.service.prizecatalog;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.dongqh.lotteryservice.exception.prizecatalog.PrizeCatalogException;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeErrorCode;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeLevel;
import com.dongqh.lotteryservice.enums.prizecatalog.PrizeType;
import com.dongqh.lotteryservice.domain.model.prizecatalog.RewardPrizeTypeMapping;
import com.dongqh.lotteryservice.domain.dto.prizecatalog.CreatePrizeCommand;
import com.dongqh.lotteryservice.domain.dto.prizecatalog.PrizeQuery;
import com.dongqh.lotteryservice.domain.dto.prizecatalog.UpdatePrizeCommand;
import com.dongqh.lotteryservice.domain.po.prizecatalog.PrizeRow;
import com.dongqh.lotteryservice.domain.po.prizecatalog.RewardDefinitionRow;
import com.dongqh.lotteryservice.mapper.prizecatalog.PrizeCatalogMapper;
import com.dongqh.lotteryservice.mapper.prizecatalog.RewardDefinitionMapper;
import com.dongqh.lotteryservice.domain.vo.prizecatalog.PageResponse;
import com.dongqh.lotteryservice.domain.vo.prizecatalog.PrizeView;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

import java.util.List;

@Service
public class PrizeCatalogService {
    private static final int ENABLED = 1;
    private static final int DISABLED = 0;

    private final PrizeCatalogMapper mapper;
    private final RewardDefinitionMapper rewards;

    public PrizeCatalogService(PrizeCatalogMapper mapper, RewardDefinitionMapper rewards) {
        this.mapper = mapper;
        this.rewards = rewards;
    }

    @Transactional
    public PrizeView create(CreatePrizeCommand command) {
        PrizeRow prize = new PrizeRow();
        apply(prize, command.prizeName(), command.prizeType(), command.prizeLevel(),
                command.imageUrl(), command.description(), command.stackable());
        prize.setRewardDefinitionId(requireCompatibleReward(command.rewardDefinitionId(), command.prizeType()).getId());
        prize.setStatus(ENABLED);
        mapper.insert(prize);
        return toView(prize);
    }

    public PrizeView getById(long id) {
        return toView(requirePrize(id));
    }

    public PageResponse<PrizeView> page(PrizeQuery query) {
        String name = normalize(query.getName());
        LambdaQueryWrapper<PrizeRow> wrapper = new LambdaQueryWrapper<PrizeRow>()
                .like(name != null, PrizeRow::getPrizeName, name)
                .eq(query.getType() != null, PrizeRow::getPrizeType, query.getType())
                .eq(query.getStatus() != null, PrizeRow::getStatus, query.getStatus())
                .orderByDesc(PrizeRow::getCreatedAt)
                .orderByDesc(PrizeRow::getId);
        Page<PrizeRow> result = mapper.selectPage(new Page<>(query.getPage(), query.getSize()), wrapper);
        List<PrizeView> records = result.getRecords().stream().map(this::toView).toList();
        return new PageResponse<>(records, result.getTotal(), result.getCurrent(), result.getSize(), result.getPages());
    }

    @Transactional
    public PrizeView update(long id, UpdatePrizeCommand command) {
        PrizeRow prize = requirePrize(id);
        apply(prize, command.prizeName(), command.prizeType(), command.prizeLevel(),
                command.imageUrl(), command.description(), command.stackable());
        if (command.rewardDefinitionId() != null) {
            if (prize.getRewardDefinitionId() != null
                    && !prize.getRewardDefinitionId().equals(command.rewardDefinitionId())) {
                throw new PrizeCatalogException(PrizeErrorCode.REWARD_BINDING_INVALID);
            }
            prize.setRewardDefinitionId(requireCompatibleReward(command.rewardDefinitionId(), command.prizeType()).getId());
        } else if (prize.getRewardDefinitionId() != null) {
            requireCompatibleReward(prize.getRewardDefinitionId(), command.prizeType());
        }
        mapper.updateById(prize);
        return toView(prize);
    }

    @Transactional
    public void disable(long id) {
        PrizeRow prize = requirePrize(id);
        if (Integer.valueOf(DISABLED).equals(prize.getStatus())) return;
        prize.setStatus(DISABLED);
        mapper.updateById(prize);
    }

    private PrizeRow requirePrize(long id) {
        PrizeRow prize = mapper.selectById(id);
        if (prize == null) throw new PrizeCatalogException(PrizeErrorCode.PRIZE_NOT_FOUND);
        return prize;
    }

    private void apply(PrizeRow prize, String prizeName, PrizeType prizeType, PrizeLevel prizeLevel,
                       String imageUrl, String description, Boolean stackable) {
        prize.setPrizeName(prizeName.trim());
        prize.setPrizeType(prizeType);
        prize.setPrizeLevel(prizeLevel);
        prize.setImageUrl(normalize(imageUrl));
        prize.setDescription(normalize(description));
        prize.setStackable(stackable);
    }

    private String normalize(String value) {
        return StringUtils.hasText(value) ? value.trim() : null;
    }

    private RewardDefinitionRow requireCompatibleReward(Long rewardId, PrizeType prizeType) {
        if (rewardId == null) throw new PrizeCatalogException(PrizeErrorCode.REWARD_BINDING_INVALID);
        RewardDefinitionRow reward = rewards.selectById(rewardId);
        if (reward == null || !Integer.valueOf(ENABLED).equals(reward.getStatus())
                || !RewardPrizeTypeMapping.matches(reward.getRewardType(), prizeType)) {
            throw new PrizeCatalogException(PrizeErrorCode.REWARD_BINDING_INVALID);
        }
        return reward;
    }

    private PrizeView toView(PrizeRow prize) {
        RewardDefinitionRow reward = prize.getRewardDefinitionId() == null
                ? null : rewards.selectById(prize.getRewardDefinitionId());
        return new PrizeView(prize.getId(), prize.getPrizeName(), prize.getPrizeType(), prize.getPrizeLevel(),
                prize.getImageUrl(), prize.getDescription(), prize.getStackable(), prize.getStatus(),
                prize.getCreatedAt(), prize.getUpdatedAt(), prize.getRewardDefinitionId(),
                reward == null ? null : reward.getRewardType());
    }
}

package com.dongqh.lotteryservice.service.prizecatalog;

import com.dongqh.lotteryservice.config.prizecatalog.OssProperties;
import com.dongqh.lotteryservice.domain.image.prizecatalog.PrizeImageValidator;
import com.dongqh.lotteryservice.domain.image.prizecatalog.ValidatedImage;
import com.dongqh.lotteryservice.integration.prizecatalog.ObjectStorageGateway;
import com.dongqh.lotteryservice.domain.vo.prizecatalog.ImageUploadView;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import java.time.LocalDate;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.UUID;

@Service
public class PrizeImageService {

    private static final DateTimeFormatter PATH_DATE = DateTimeFormatter.ofPattern("yyyy/MM");

    private final PrizeImageValidator validator;
    private final ObjectStorageGateway gateway;
    private final OssProperties properties;

    public PrizeImageService(PrizeImageValidator validator, ObjectStorageGateway gateway,
                             OssProperties properties) {
        this.validator = validator;
        this.gateway = gateway;
        this.properties = properties;
    }

    public ImageUploadView upload(MultipartFile file) {
        ValidatedImage image = validator.validate(file);
        String objectKey = "prizes/%s/%s.%s".formatted(
                LocalDate.now(ZoneOffset.UTC).format(PATH_DATE), UUID.randomUUID(), image.extension());
        gateway.put(objectKey, image.content(), image.contentType());
        return new ImageUploadView(properties.normalizedPublicBaseUrl() + "/" + objectKey, objectKey);
    }
}

package com.dongqh.lotteryservice.service.prizecatalog;

import com.dongqh.hmapi.client.CouponClient;
import com.dongqh.hmapi.client.ItemClient;
import com.dongqh.hmapi.client.MembershipClient;
import com.dongqh.hmapi.dto.CouponRewardTemplateDTO;
import com.dongqh.hmapi.dto.ItemDTO;
import com.dongqh.hmapi.dto.MembershipRewardProductDTO;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardDefinitionErrorCode;
import com.dongqh.lotteryservice.exception.prizecatalog.RewardDefinitionException;
import com.dongqh.lotteryservice.enums.prizecatalog.RewardType;
import com.dongqh.lotteryservice.domain.dto.prizecatalog.CreateRewardDefinitionCommand;
import com.dongqh.lotteryservice.domain.po.prizecatalog.RewardDefinitionRow;
import com.dongqh.lotteryservice.mapper.prizecatalog.RewardDefinitionMapper;
import com.dongqh.lotteryservice.domain.vo.prizecatalog.RewardDefinitionView;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.util.List;

@Service
public class RewardDefinitionAdminService {
    private static final int ENABLED = 1;
    private final RewardDefinitionMapper rewards;
    private final ItemClient items;
    private final CouponClient coupons;
    private final MembershipClient memberships;
    private final ObjectMapper json;

    public RewardDefinitionAdminService(RewardDefinitionMapper rewards, ItemClient items, CouponClient coupons,
                                       MembershipClient memberships, ObjectMapper json) {
        this.rewards = rewards;
        this.items = items;
        this.coupons = coupons;
        this.memberships = memberships;
        this.json = json;
    }

    @Transactional
    public RewardDefinitionView create(CreateRewardDefinitionCommand command) {
        if (command == null || command.rewardType() == null || command.quantity() == null
                || command.quantity() <= 0
                || (command.rewardType() != RewardType.POINTS && command.quantity() > 100)) {
            throw error(RewardDefinitionErrorCode.REWARD_TARGET_INVALID);
        }
        validateTarget(command.rewardType(), command.targetId());
        RewardDefinitionRow row = new RewardDefinitionRow();
        row.setRewardCode(command.rewardCode().trim());
        row.setRewardName(command.rewardName().trim());
        row.setRewardType(command.rewardType());
        row.setTargetId(command.targetId());
        row.setQuantity(command.quantity());
        row.setConfigSnapshot(normalizeJson(command.configSnapshot()));
        row.setStatus(ENABLED);
        try {
            rewards.insert(row);
        } catch (DuplicateKeyException duplicate) {
            throw error(RewardDefinitionErrorCode.REWARD_CODE_DUPLICATE);
        }
        return view(rewards.selectById(row.getId()));
    }

    public RewardDefinitionView get(long id) {
        RewardDefinitionRow row = rewards.selectById(id);
        if (row == null) throw error(RewardDefinitionErrorCode.REWARD_NOT_FOUND);
        return view(row);
    }

    private void validateTarget(RewardType type, Long targetId) {
        boolean required = type == RewardType.PRODUCT || type == RewardType.COUPON || type == RewardType.MEMBERSHIP;
        if (required != (targetId != null) || targetId != null && targetId <= 0) {
            throw error(RewardDefinitionErrorCode.REWARD_TARGET_INVALID);
        }
        if (type == RewardType.PRODUCT) {
            List<ItemDTO> found = items.queryItemByIds(List.of(targetId));
            ItemDTO item = found == null ? null : found.stream()
                    .filter(value -> value != null && targetId.equals(value.getId())).findFirst().orElse(null);
            if (item == null || !Integer.valueOf(ENABLED).equals(item.getStatus())
                    || item.getStock() == null || item.getStock() <= 0) {
                throw error(RewardDefinitionErrorCode.REWARD_TARGET_INVALID);
            }
        } else if (type == RewardType.COUPON) {
            CouponRewardTemplateDTO template = coupons.getRewardTemplate(targetId);
            if (template == null || !Integer.valueOf(ENABLED).equals(template.status())) {
                throw error(RewardDefinitionErrorCode.REWARD_TARGET_INVALID);
            }
        } else if (type == RewardType.MEMBERSHIP) {
            MembershipRewardProductDTO product = memberships.getRewardProduct(targetId);
            if (product == null || !Integer.valueOf(ENABLED).equals(product.status())) {
                throw error(RewardDefinitionErrorCode.REWARD_TARGET_INVALID);
            }
        }
    }

    private String normalizeJson(String value) {
        if (!StringUtils.hasText(value)) return null;
        try {
            return json.writeValueAsString(json.readTree(value));
        } catch (JacksonException exception) {
            throw error(RewardDefinitionErrorCode.REWARD_CONFIG_INVALID);
        }
    }

    private RewardDefinitionView view(RewardDefinitionRow row) {
        return new RewardDefinitionView(row.getId(), row.getRewardCode(), row.getRewardName(), row.getRewardType(),
                row.getTargetId(), row.getQuantity(), normalizeJson(row.getConfigSnapshot()), row.getStatus(),
                row.getCreatedAt(), row.getUpdatedAt());
    }

    private RewardDefinitionException error(RewardDefinitionErrorCode code) {
        return new RewardDefinitionException(code);
    }
}

package com.dongqh.lotteryservice.service.reconciliation;

import com.dongqh.lotteryservice.config.LotteryProperties;
import com.dongqh.lotteryservice.service.drawchance.DrawChanceReservationService;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Objects;

@Service
public class LotteryReconciliationService {
    private final DrawChanceReservationService drawChances;
    private final java.time.Duration processingTimeout;
    private final ZoneId zoneId;
    private final int batchSize;

    public LotteryReconciliationService(DrawChanceReservationService drawChances,
                                        LotteryProperties properties) {
        this.drawChances = Objects.requireNonNull(drawChances);
        this.processingTimeout = Objects.requireNonNull(properties.processingTimeout());
        this.zoneId = Objects.requireNonNull(properties.zoneId());
        this.batchSize = properties.reconcileBatchSize();
    }

    public ReconciliationSummary reconcile(Instant now) {
        Objects.requireNonNull(now, "now must not be null");
        LocalDateTime cutoff = LocalDateTime.ofInstant(now, zoneId).minus(processingTimeout);
        int settled = drawChances.reconcileExpired(batchSize, cutoff);
        return new ReconciliationSummary(0, 0, 0, 0, 0, 0, settled);
    }

    public record ReconciliationSummary(int scanned, int confirmed, int released, int timedOut,
                                         int deferred, int failed, int settledDrawChances) {
    }
}

