@ExtendWith(MockitoExtension.class)
class OrderServiceDeliveryTest {

    @Mock
    private IItemService itemService;
    @Mock
    private IOrderDetailService detailService;
    @Mock
    private ICartService cartService;
    @Mock
    private IOrderLogisticsService logisticsService;
    @Mock
    private IAddressService addressService;
    @Mock
    private MembershipBenefitClient membershipBenefitClient;
    @Mock
    private CouponCheckoutClient couponCheckoutClient;
    @Spy
    @InjectMocks
    private OrderServiceImpl orderService;

    @AfterEach
    void clearUser() {
        UserContext.removeUser();
    }

    @Test
    void returnsCarrierTrackingNumberAndAddressSnapshotFromHmallLogistics() {
        Order order = new Order().setId(42L).setUserId(7L).setStatus(3);
        OrderLogistics logistics = new OrderLogistics()
                .setOrderId(42L)
                .setLogisticsCompany("顺丰速运")
                .setLogisticsNumber("SF1234567890")
                .setContact("李四")
                .setMobile("13838411438")
                .setProvince("上海")
                .setCity("上海")
                .setTown("浦东新区")
                .setStreet("航头镇航头路 1 号");
        UserContext.setUser(7L);
        doReturn(order).when(orderService).getById(42L);
        when(logisticsService.getById(42L)).thenReturn(logistics);

        OrderVO result = orderService.queryOrderById(42L);

        assertThat(result.getDelivery().getCarrier()).isEqualTo("顺丰速运");
        assertThat(result.getDelivery().getTrackingNumber()).isEqualTo("SF1234567890");
        assertThat(result.getDelivery().getAddressSnapshot().getContact()).isEqualTo("李四");
        assertThat(result.getDelivery().getAddressSnapshot().getFullAddress())
                .isEqualTo("上海上海浦东新区航头镇航头路 1 号");
    }

    @Test
    void freezesOwnedAddressIntoOrderLogisticsWhenCreatingOrder() {
        ItemDTO item = new ItemDTO();
        item.setId(1001L);
        item.setName("RIMOWA 旅行箱");
        item.setPrice(1300);
        when(itemService.queryItemByIds(eq(Set.of(1001L)))).thenReturn(List.of(item));
        when(membershipBenefitClient.getActiveBenefit()).thenReturn(
                new MembershipBenefitView("GOLD", 9500, LocalDateTime.now().plusDays(30)));
        Address address = new Address().setId(8L).setUserId(7L).setContact("李四")
                .setMobile("13838411438").setProvince("上海").setCity("上海")
                .setTown("浦东新区").setStreet("航头镇航头路 1 号");
        when(addressService.getById(8L)).thenReturn(address);
        doAnswer(invocation -> true).when(orderService).save(any(Order.class));
        UserContext.setUser(7L);
        OrderFormDTO form = new OrderFormDTO();
        form.setAddressId(8L);
        form.setPaymentType(3);
        form.setDetails(List.of(new OrderDetailDTO().setItemId(1001L).setNum(1)));

        Long orderId = orderService.createOrder(form);

        verify(addressService).getById(8L);
        org.mockito.ArgumentCaptor<OrderLogistics> captor =
                org.mockito.ArgumentCaptor.forClass(OrderLogistics.class);
        verify(logisticsService).save(captor.capture());
        OrderLogistics snapshot = captor.getValue();
        assertThat(snapshot.getOrderId()).isEqualTo(orderId);
        assertThat(snapshot.getContact()).isEqualTo("李四");
        assertThat(snapshot.getMobile()).isEqualTo("13838411438");
        assertThat(snapshot.getProvince()).isEqualTo("上海");
        assertThat(snapshot.getCity()).isEqualTo("上海");
        assertThat(snapshot.getTown()).isEqualTo("浦东新区");
        assertThat(snapshot.getStreet()).isEqualTo("航头镇航头路 1 号");
    }

    @Test
    void rejectsAddressOwnedByAnotherUserBeforeCreatingOrder() {
        when(addressService.getById(8L)).thenReturn(new Address().setId(8L).setUserId(9L));
        UserContext.setUser(7L);
        OrderFormDTO form = new OrderFormDTO();
        form.setAddressId(8L);
        form.setDetails(List.of(new OrderDetailDTO().setItemId(1001L).setNum(1)));

        assertThatThrownBy(() -> orderService.createOrder(form))
                .isInstanceOf(com.hmall.common.exception.BadRequestException.class)
                .hasMessage("收货地址不存在");
        verify(orderService, never()).save(any(Order.class));
        verify(logisticsService, never()).save(any(OrderLogistics.class));
    }

    @Test
    void rejectsReadingAnotherUsersOrder() {
        doReturn(new Order().setId(9001L).setUserId(9L)).when(orderService).getById(9001L);
        UserContext.setUser(7L);

        assertThatThrownBy(() -> orderService.queryOrderById(9001L))
                .isInstanceOf(com.hmall.common.exception.BadRequestException.class)
                .hasMessage("订单不存在");
        verify(logisticsService, never()).getById(9001L);
    }

    @Test
    void queriesOnlyCurrentUsersOrdersByStatusNewestFirst() {
        UserContext.setUser(7L);
        doAnswer(invocation -> {
            Page<Order> page = invocation.getArgument(0);
            AbstractWrapper<Order, ?, ?> wrapper = invocation.getArgument(1);
            assertThat(wrapper.getSqlSegment()).contains("user_id", "status", "create_time");
            assertThat(wrapper.getParamNameValuePairs().values()).contains(7L, 2);
            page.setTotal(2);
            page.setRecords(List.of(
                    new Order().setId(102L).setUserId(7L).setStatus(2).setTotalFee(1200),
                    new Order().setId(101L).setUserId(7L).setStatus(2).setTotalFee(900)));
            return page;
        }).when(orderService).page(any(Page.class), any(AbstractWrapper.class));

        PageDTO<OrderVO> result = orderService.queryMyOrders(
                new PageQuery().setPageNo(1).setPageSize(20), 2);

        assertThat(result.getTotal()).isEqualTo(2);
        assertThat(result.getList()).extracting(OrderVO::getId).containsExactly(102L, 101L);
        assertThat(result.getList()).allSatisfy(order -> {
            assertThat(order.getUserId()).isEqualTo(7L);
            assertThat(order.getStatus()).isEqualTo(2);
        });
    }
}

package com.hmall.service.impl;

import com.hmall.common.exception.BizIllegalException;
import com.hmall.common.utils.UserContext;
import com.hmall.domain.dto.PayOrderFormDTO;
import com.hmall.domain.po.Order;
import com.hmall.domain.po.PayOrder;
import com.hmall.enums.PayStatus;
import com.hmall.integration.marketing.CouponCheckoutClient;
import com.hmall.service.IOrderService;
import com.hmall.service.IUserService;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import java.time.LocalDateTime;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;

class PayOrderServiceSecurityTest {

    @AfterEach
    void clearUser() {
        UserContext.removeUser();
    }

    @Test
    void rejectsPaymentOwnedByAnotherUser() {
        Fixture fixture = fixture(waitingPayOrder(99L, 500), waitingOrder(99L, 500));
        UserContext.setUser(42L);

        assertThatThrownBy(() -> fixture.service.tryPayOrderByBalance(form()))
                .isInstanceOf(BizIllegalException.class);
        verify(fixture.userService, never()).deductMoney(any(), any());
    }

    @Test
    void rejectsWhenBusinessOrderAmountDoesNotMatchPayment() {
        Fixture fixture = fixture(waitingPayOrder(42L, 500), waitingOrder(42L, 600));
        UserContext.setUser(42L);

        assertThatThrownBy(() -> fixture.service.tryPayOrderByBalance(form()))
                .isInstanceOf(BizIllegalException.class);
        verify(fixture.userService, never()).deductMoney(any(), any());
    }

    @Test
    void casFailureNeverDeductsBalance() {
        Fixture fixture = fixture(waitingPayOrder(42L, 500), waitingOrder(42L, 500));
        doReturn(false).when(fixture.service).markPayOrderSuccess(eq(100L), any(LocalDateTime.class));
        UserContext.setUser(42L);

        assertThatThrownBy(() -> fixture.service.tryPayOrderByBalance(form()))
                .isInstanceOf(BizIllegalException.class);
        verify(fixture.userService, never()).deductMoney(any(), any());
    }

    @Test
    void validOwnerPaysOnlyAfterBothOrdersAreValidated() {
        Fixture fixture = fixture(waitingPayOrder(42L, 500), waitingOrder(42L, 500));
        doReturn(true).when(fixture.service).markPayOrderSuccess(eq(100L), any(LocalDateTime.class));
        doReturn(true).when(fixture.service).markBusinessOrderPaid(any(Order.class), any(LocalDateTime.class));
        UserContext.setUser(42L);

        assertThatCode(() -> fixture.service.tryPayOrderByBalance(form())).doesNotThrowAnyException();
        verify(fixture.userService).deductMoney("pw", 500);
        verify(fixture.service).markBusinessOrderPaid(any(Order.class), any(LocalDateTime.class));
    }

    @Test
    void successfulPaymentMarksReservedCouponUsedForTheSameOrder() {
        Order order = waitingOrder(42L, 500).setCouponId(77L);
        Fixture fixture = fixture(waitingPayOrder(42L, 500), order);
        doReturn(true).when(fixture.service).markPayOrderSuccess(eq(100L), any(LocalDateTime.class));
        doReturn(true).when(fixture.service).markBusinessOrderPaid(any(Order.class), any(LocalDateTime.class));
        UserContext.setUser(42L);

        fixture.service.tryPayOrderByBalance(form());

        verify(fixture.couponClient).use(77L, 200L);
    }

    @Test
    void paymentReloadsAfterBusinessOrderLockSoPreCouponReadCannotChargeOldAmount() {
        Fixture fixture = fixture(waitingPayOrder(42L, 9500), waitingOrder(42L, 8500));
        com.hmall.mapper.PayOrderMapper mapper = org.mockito.Mockito.mock(com.hmall.mapper.PayOrderMapper.class);
        org.springframework.test.util.ReflectionTestUtils.setField(fixture.service,"baseMapper",mapper);
        org.mockito.Mockito.when(mapper.selectOne(any())).thenReturn(waitingPayOrder(42L,8500));
        doReturn(true).when(fixture.service).markPayOrderSuccess(eq(100L),any(LocalDateTime.class));
        doReturn(true).when(fixture.service).markBusinessOrderPaid(any(Order.class),any(LocalDateTime.class));
        UserContext.setUser(42L);
        fixture.service.tryPayOrderByBalance(form());
        verify(fixture.userService).deductMoney("pw",8500);
        verify(fixture.userService,never()).deductMoney("pw",9500);
    }

    @Test
    void paymentCreationIgnoresBrowserAmountAndLocksAuthoritativeOrder() {
        IUserService users = mock(IUserService.class);
        IOrderService orders = mock(IOrderService.class);
        PayOrderServiceImpl service = spy(new PayOrderServiceImpl(users,orders,mock(CouponCheckoutClient.class)));
        org.mockito.Mockito.when(orders.lockOrder(200L)).thenReturn(waitingOrder(42L,8500));
        doReturn(null).when(service).queryByBizOrderNo(200L);
        org.mockito.Mockito.doAnswer(i -> { ((PayOrder)i.getArgument(0)).setId(100L); return true; })
                .when(service).save(any(PayOrder.class));
        UserContext.setUser(42L);
        service.applyPayOrder(com.hmall.domain.dto.PayApplyDTO.builder().bizOrderNo(200L)
                .amount(1).payChannelCode("balance").payType(3).orderInfo("item").build());
        verify(orders).lockOrder(200L);
        verify(service).save(org.mockito.ArgumentMatchers.argThat(p -> p.getAmount() == 8500));
    }

    private Fixture fixture(PayOrder payOrder, Order order) {
        IUserService userService = mock(IUserService.class);
        IOrderService orderService = mock(IOrderService.class);
        CouponCheckoutClient couponClient = mock(CouponCheckoutClient.class);
        PayOrderServiceImpl service = spy(new PayOrderServiceImpl(userService, orderService, couponClient));
        doReturn(payOrder).when(service).getById(100L);
        doReturn(order).when(orderService).getById(200L);
        doReturn(order).when(orderService).lockOrder(200L);
        com.hmall.mapper.PayOrderMapper mapper = mock(com.hmall.mapper.PayOrderMapper.class);
        org.springframework.test.util.ReflectionTestUtils.setField(service,"baseMapper",mapper);
        org.mockito.Mockito.when(mapper.selectOne(any())).thenReturn(payOrder);
        return new Fixture(service, userService, couponClient);
    }

    private PayOrder waitingPayOrder(Long userId, Integer amount) {
        return new PayOrder()
                .setId(100L)
                .setBizOrderNo(200L)
                .setBizUserId(userId)
                .setAmount(amount)
                .setStatus(PayStatus.WAIT_BUYER_PAY.getValue());
    }

    private Order waitingOrder(Long userId, Integer amount) {
        return new Order()
                .setId(200L)
                .setUserId(userId)
                .setTotalFee(amount)
                .setStatus(1);
    }

    private PayOrderFormDTO form() {
        return PayOrderFormDTO.builder().id(100L).pw("pw").build();
    }

    private static class Fixture {
        private final PayOrderServiceImpl service;
        private final IUserService userService;
        private final CouponCheckoutClient couponClient;

        private Fixture(PayOrderServiceImpl service, IUserService userService,
                        CouponCheckoutClient couponClient) {
            this.service = service;
            this.userService = userService;
            this.couponClient = couponClient;
        }
    }
}

package com.hmall.service.impl;

import com.hmall.common.exception.BizIllegalException;
import com.hmall.common.utils.UserContext;
import com.hmall.config.JwtProperties;
