    & docker exec -e "MYSQL_PWD=$rootPassword" $mysqlContainer mysql -uroot -Nse `
        "CREATE DATABASE ``$SchemaName`` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;"
    if ($LASTEXITCODE -ne 0) { throw '创建临时数据库失败。' }
