    public enum Type {
        PRIZE_CANDIDATE,
        NO_WIN
    }

    public static DrawCandidate prize(long activityPrizeId, long prizeId) {
        return new DrawCandidate(Type.PRIZE_CANDIDATE, activityPrizeId, prizeId);
    }

