package com.dongqh.luckyhub.domain.support.reward;

import com.dongqh.luckyhub.enums.prize.PrizeType;
import com.dongqh.luckyhub.enums.reward.RewardType;

public final class RewardPrizeTypeMapping {
    private RewardPrizeTypeMapping() {}
    public static PrizeType toPrizeType(RewardType type) {
        if (type == null) throw new IllegalArgumentException("奖励类型不能为空");
        return switch (type) {
            case PRODUCT -> PrizeType.PHYSICAL;
            case COUPON -> PrizeType.COUPON;
            case POINTS -> PrizeType.POINTS;
            case MEMBERSHIP -> PrizeType.MEMBERSHIP;
            case DRAW_CHANCE -> PrizeType.DRAW_CHANCE;
        };
    }
    public static boolean matches(RewardType type, PrizeType prizeType) {
        return type != null && prizeType != null && toPrizeType(type) == prizeType;
    }
}

package com.dongqh.luckyhub.domain.support.shipping;

public final class AddressMasker {

    private AddressMasker() {
    }

    public static String maskReceiver(String receiver) {
        int firstCodePointEnd = receiver.offsetByCodePoints(0, 1);
        return receiver.codePointCount(0, receiver.length()) == 1
                ? "*"
                : receiver.substring(0, firstCodePointEnd) + "*";
    }

    public static String maskPhone(String phone) {
        return phone.substring(0, 3) + "****" + phone.substring(phone.length() - 4);
    }

    public static String maskRegion(String province, String city, String district) {
        return province + city + district + "***";
    }
}

