                         @Param("expected") BenefitStatus expected,
                         @Param("target") BenefitStatus target);

    @Update("""
            UPDATE user_benefit
            SET status = 'GRANT_FAILED', grant_error = #{safeError},
                updated_at = CURRENT_TIMESTAMP(3)
            WHERE id = #{id} AND status IN ('PENDING', 'GRANT_FAILED')
            """)
