package com.dongqh.luckyhub.security.auth;

import com.dongqh.luckyhub.enums.auth.AuthErrorCode;
import com.dongqh.luckyhub.common.exception.BusinessException;

/** Extracts either a bare JWT or an RFC 6750-style Bearer JWT. */
public final class AuthorizationTokenExtractor {

    private static final String BEARER = "Bearer";

    private AuthorizationTokenExtractor() {
    }

    public static String extract(String authorization) {
        if (authorization == null || authorization.isBlank()) {
            throw invalidToken();
        }

        String value = authorization.trim();
        if (value.length() >= BEARER.length()
                && value.regionMatches(true, 0, BEARER, 0, BEARER.length())) {
            if (value.length() == BEARER.length()) {
                throw invalidToken();
            }
            if (Character.isWhitespace(value.charAt(BEARER.length()))) {
                String token = value.substring(BEARER.length()).trim();
                if (token.isBlank()) {
                    throw invalidToken();
                }
                return token;
            }
        }

        return value;
    }

    private static BusinessException invalidToken() {
        return new BusinessException(AuthErrorCode.INVALID_TOKEN);
    }
}

package com.dongqh.luckyhub.security.auth;

import com.dongqh.luckyhub.enums.auth.AuthErrorCode;
import com.dongqh.luckyhub.domain.model.auth.LoginPrincipal;
import com.dongqh.luckyhub.common.exception.BusinessException;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.PublicKey;
import java.security.cert.CertificateFactory;
import java.security.spec.X509EncodedKeySpec;
import java.security.KeyFactory;
import java.util.Base64;

/** Verifies the RS256 access tokens issued by Black Horse Mall. */
@Service
public class HmallJwtService {

    private final PublicKey publicKey;

    @Autowired
    public HmallJwtService(
            @Value("${luckyhub.security.hmall-jwt.public-key:classpath:hmall-public.pem}")
            Resource publicKeyResource
    ) {
        this(loadPublicKey(publicKeyResource));
    }

    public HmallJwtService(PublicKey publicKey) {
        if (publicKey == null || !"RSA".equalsIgnoreCase(publicKey.getAlgorithm())) {
            throw new IllegalArgumentException("Hmall JWT public key must be RSA");
        }
        this.publicKey = publicKey;
    }

    public LoginPrincipal parse(String token) {
        if (token == null || token.isBlank()) {
            throw invalidToken();
        }

        try {
            Jws<Claims> signedClaims = Jwts.parser()
                    .verifyWith(publicKey)
                    .build()
                    .parseSignedClaims(token);
            if (!"RS256".equals(signedClaims.getHeader().getAlgorithm())) {
                throw invalidToken();
            }
            Claims claims = signedClaims.getPayload();

            if (claims.getExpiration() == null) {
                throw invalidToken();
            }

            Long userId = parseUserId(claims.get("user"));

            return new LoginPrincipal(
                    userId,
                    userId.toString(),
                    null
            );
        } catch (JwtException | IllegalArgumentException | ArithmeticException exception) {
            throw invalidToken();
        }
    }

    private static Long parseUserId(Object claim) {
        if (claim == null) {
            throw invalidToken();
        }
        if (claim instanceof Number number) {
            return new BigDecimal(number.toString()).longValueExact();
        }
        return Long.valueOf(claim.toString());
    }

    private static PublicKey loadPublicKey(Resource resource) {
        try {
            byte[] bytes = resource.getInputStream().readAllBytes();
            String pem = new String(bytes, StandardCharsets.US_ASCII);
            if (pem.contains("-----BEGIN CERTIFICATE-----")) {
                return CertificateFactory.getInstance("X.509")
                        .generateCertificate(new java.io.ByteArrayInputStream(bytes))
                        .getPublicKey();
            }

            String encoded = pem
                    .replace("-----BEGIN PUBLIC KEY-----", "")
                    .replace("-----END PUBLIC KEY-----", "")
                    .replaceAll("\\s", "");
            byte[] der = Base64.getDecoder().decode(encoded);
            return KeyFactory.getInstance("RSA")
                    .generatePublic(new X509EncodedKeySpec(der));
        } catch (IOException | GeneralSecurityException | IllegalArgumentException exception) {
            throw new IllegalStateException("Unable to load Hmall JWT public key", exception);
        }
    }

    private static BusinessException invalidToken() {
        return new BusinessException(AuthErrorCode.INVALID_TOKEN);
    }
}

package com.dongqh.luckyhub.security.auth;

import com.dongqh.luckyhub.enums.auth.AuthErrorCode;
import com.dongqh.luckyhub.domain.model.auth.AuthenticatedUser;
import com.dongqh.luckyhub.domain.model.auth.JwtPayload;
import com.dongqh.luckyhub.domain.model.auth.LoginPrincipal;
import com.dongqh.luckyhub.common.exception.BusinessException;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.io.Decoders;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;

import javax.crypto.SecretKey;
import java.time.Instant;
import java.util.Date;
import java.util.UUID;

@Service
public class JwtService {

    private final SecretKey secretKey;
    private final long expireSeconds;
    private final HmallJwtService hmallJwtService;

    @Autowired
    public JwtService(
            @Value("${luckyhub.security.jwt.secret}") String secret,
            @Value("${luckyhub.security.jwt.expiration}") long expireSeconds,
            HmallJwtService hmallJwtService
    ) {
        this.secretKey = Keys.hmacShaKeyFor(
                Decoders.BASE64.decode(secret)
        );
        this.expireSeconds = expireSeconds;
        this.hmallJwtService = hmallJwtService;
    }

    /** Compatibility constructor retained for original LuckyHub unit tests. */
    public JwtService(String secret, long expireSeconds) {
        this(
                secret,
                expireSeconds,
                new HmallJwtService(new ClassPathResource("hmall-public.pem"))
        );
    }

    public String generate(
            AuthenticatedUser user,
            String sessionId
    ) {
        Instant now = Instant.now();
        Instant expiration = now.plusSeconds(expireSeconds);

        return Jwts.builder()
                .subject(user.userId().toString())
                .id(sessionId)
                .claim("username", user.username())
                .issuedAt(Date.from(now))
                .expiration(Date.from(expiration))
                .signWith(secretKey)
                .compact();
    }

    public JwtPayload parse(String token) {
        LoginPrincipal principal = hmallJwtService.parse(token);
        return new JwtPayload(
                principal.userId(),
                principal.username(),
                principal.sessionId()
        );
    }

    public String newSessionId() {
        return UUID.randomUUID().toString();
    }

    public long getExpireSeconds() {
        return expireSeconds;
    }

    private BusinessException invalidToken() {
        return new BusinessException(
                AuthErrorCode.INVALID_TOKEN
        );
    }
}

package com.dongqh.luckyhub.security.auth;

import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

import java.nio.charset.StandardCharsets;

@Service
public class PasswordService {

    private static final int BCRYPT_MAX_PASSWORD_BYTES = 72;

    private final PasswordEncoder passwordEncoder;

    public PasswordService(PasswordEncoder passwordEncoder) {
        this.passwordEncoder = passwordEncoder;
    }

    public String hash(String rawPassword) {
        validateForHashing(rawPassword);
        return passwordEncoder.encode(rawPassword);
    }

    public boolean matches(String rawPassword, String encodedPassword) {
        if (!isValidRawPassword(rawPassword) || encodedPassword == null || encodedPassword.isBlank()) {
            return false;
        }
        try {
            return passwordEncoder.matches(rawPassword, encodedPassword);
        } catch (IllegalArgumentException exception) {
            return false;
        }
    }

    public boolean needsUpgrade(String encodedPassword) {
        if (encodedPassword == null || encodedPassword.isBlank()) {
            return false;
        }
        try {
            return passwordEncoder.upgradeEncoding(encodedPassword);
        } catch (IllegalArgumentException exception) {
            return true;
        }
    }

    private void validateForHashing(String rawPassword) {
        if (rawPassword == null || rawPassword.isBlank()) {
            throw new IllegalArgumentException("密码不能为空");
        }
        if (utf8Length(rawPassword) > BCRYPT_MAX_PASSWORD_BYTES) {
            throw new IllegalArgumentException("密码不能超过72个UTF-8字节");
        }
    }

    private boolean isValidRawPassword(String rawPassword) {
        return rawPassword != null
                && !rawPassword.isBlank()
                && utf8Length(rawPassword) <= BCRYPT_MAX_PASSWORD_BYTES;
    }

    private int utf8Length(String value) {
        return value.getBytes(StandardCharsets.UTF_8).length;
    }
}

package com.dongqh.luckyhub.security.auth;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

import java.time.Duration;

@Service
public class SessionService {

    private static final String KEY_PREFIX =
            "luckyhub:auth:session:";

    @Autowired
    private StringRedisTemplate redisTemplate;


    public void create(
            String sessionId,
            Long userId,
            long expireSeconds
    ) {
        redisTemplate.opsForValue().set(
                buildKey(sessionId),
                userId.toString(),
                Duration.ofSeconds(expireSeconds)
        );
    }

    public boolean isValid(
            String sessionId,
            Long userId
    ) {
        String storedUserId = redisTemplate.opsForValue()
                .get(buildKey(sessionId));

        return userId.toString().equals(storedUserId);
    }

    public void remove(String sessionId) {
        redisTemplate.delete(buildKey(sessionId));
    }

    private String buildKey(String sessionId) {
        return KEY_PREFIX + sessionId;
    }
}

