package com.dongqh.luckyhub.service.auth;

import com.dongqh.luckyhub.enums.auth.AuthErrorCode;
import com.dongqh.luckyhub.domain.model.auth.LoginPrincipal;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.mapper.coupon.UserCouponMapper;
import com.dongqh.luckyhub.mapper.rbac.SysUserMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class HmallUserProjectionServiceImpl implements HmallUserProjectionService {

    private final SysUserMapper userMapper;
    private final UserCouponMapper userCouponMapper;

    public HmallUserProjectionServiceImpl(
            SysUserMapper userMapper,
            UserCouponMapper userCouponMapper
    ) {
        this.userMapper = userMapper;
        this.userCouponMapper = userCouponMapper;
    }

    @Override
    @Transactional
    public void ensureActiveHmallUser(LoginPrincipal principal) {
        if (principal == null || principal.userId() == null || principal.userId() <= 0) {
            throw new BusinessException(AuthErrorCode.INVALID_TOKEN);
        }
        long userId = principal.userId();
        if (userMapper.selectById(userId) == null) {
            userMapper.insertHmallProjection(
                    userId,
                    "hmall:" + userId,
                    "商城用户 " + userId
            );
        }
        userMapper.insertDefaultUserRole(userId);
        userCouponMapper.issueHmallCheckoutCoupons(userId);
        userCouponMapper.recordHmallCheckoutCouponIssues(userId);
    }
}

package com.dongqh.luckyhub.service.auth.Impl;

import ch.qos.logback.core.joran.util.beans.BeanUtil;
import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import com.dongqh.luckyhub.domain.dto.auth.LoginCommand;
import com.dongqh.luckyhub.enums.auth.AuthErrorCode;
import com.dongqh.luckyhub.domain.model.auth.AuthenticatedUser;
import com.dongqh.luckyhub.security.auth.PasswordService;
import com.dongqh.luckyhub.service.auth.AuthenticationService;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.po.rbac.SysUser;
import com.dongqh.luckyhub.mapper.rbac.SysUserMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Service
public class AuthenticationServiceImpl implements AuthenticationService {

    @Autowired
    private  SysUserMapper userMapper;
    @Autowired
    private  PasswordService passwordService;



    @Override
    public AuthenticatedUser authenticate(LoginCommand command) {
        SysUser user = userMapper.selectOne(
                Wrappers.<SysUser>lambdaQuery()
                        .eq(SysUser::getUsername, command.username())
                        .last("LIMIT 1")
        );
        // 用户不存在
        if(user == null ||
            !passwordService.matches(command.password(), user.getPassword())
        ) {
            throw new BusinessException(AuthErrorCode.INVALID_CREDENTIALS);
        }

        if(!Integer.valueOf(1).equals(user.getStatus())){
            throw new BusinessException(AuthErrorCode.USER_DISABLED);
        }
        return new AuthenticatedUser(
                user.getId(),
                user.getUsername(),
                user.getNickname()
        );

    }
}

package com.dongqh.luckyhub.service.auth.Impl;

import com.dongqh.luckyhub.domain.dto.auth.LoginCommand;
import com.dongqh.luckyhub.domain.model.auth.AuthenticatedUser;
import com.dongqh.luckyhub.security.auth.JwtService;
import com.dongqh.luckyhub.security.auth.SessionService;
import com.dongqh.luckyhub.service.auth.AuthenticationService;
import com.dongqh.luckyhub.service.auth.LoginService;
import com.dongqh.luckyhub.domain.vo.auth.LoginView;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;


@Service
public class LoginServiceImpl implements LoginService {

    @Autowired
    private AuthenticationService authenticationService;
    @Autowired
    private JwtService jwtService;
    @Autowired
    private SessionService sessionService;

    @Override
    public LoginView login(LoginCommand command) {
        // 验证是否可以登录
        AuthenticatedUser  user =
                authenticationService.authenticate(command);
        //生成sessionId
        String sessionId = jwtService.newSessionId();
        //将SessionId保存到redis
        sessionService.create(sessionId, user.userId(), jwtService.getExpireSeconds());
        //生成JWT
        String token = jwtService.generate(user, sessionId);
        //封装成LoginView




        return new LoginView(
                user.userId(),
                user.username(),
                user.nickname(),
                token,
                "Bearer",
                jwtService.getExpireSeconds()
        );
    }

    @Override
    public void logout(String sessionId) {
        sessionService.remove(sessionId);
    }


}

