public interface BenefitQueryService { PageResponse<BenefitView> page(BenefitQuery query); BenefitView getById(long id); }

package com.dongqh.luckyhub.service.benefit;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.dongqh.luckyhub.domain.dto.benefit.BenefitQuery;
import com.dongqh.luckyhub.domain.po.benefit.UserBenefit;
import com.dongqh.luckyhub.enums.benefit.BenefitErrorCode;
import com.dongqh.luckyhub.mapper.benefit.UserBenefitMapper;
import com.dongqh.luckyhub.domain.vo.benefit.BenefitView;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.common.enums.CommonErrorCode;
import com.dongqh.luckyhub.common.result.PageResponse;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawRecord;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawRecordMapper;
import com.dongqh.luckyhub.domain.po.fulfillment.FulfillmentTask;
import com.dongqh.luckyhub.mapper.fulfillment.FulfillmentTaskMapper;
import com.dongqh.luckyhub.domain.po.shipping.ShippingOrder;
import com.dongqh.luckyhub.mapper.shipping.ShippingOrderMapper;
import com.dongqh.luckyhub.service.scope.DataScopeService;
import com.dongqh.luckyhub.service.scope.UserDataScope;
import org.springframework.stereotype.Service;

import java.util.*;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service
public class BenefitQueryServiceImpl implements BenefitQueryService {
    private static final long MAX_PAGE=1_000_000L;
    private static final LocalDate MYSQL_MIN_DATE=LocalDate.of(1000,1,1);
    private static final LocalDate MAX_SAFE_END_DATE=LocalDate.of(9999,12,30);
    private final UserBenefitMapper benefitMapper; private final LotteryDrawRecordMapper recordMapper;
    private final FulfillmentTaskMapper fulfillmentTaskMapper;
    private final ShippingOrderMapper shippingOrderMapper;
    private final DataScopeService dataScopeService;
    public BenefitQueryServiceImpl(UserBenefitMapper benefitMapper, LotteryDrawRecordMapper recordMapper,
                                   FulfillmentTaskMapper fulfillmentTaskMapper, ShippingOrderMapper shippingOrderMapper,
                                   DataScopeService dataScopeService) {
        this.benefitMapper=benefitMapper; this.recordMapper=recordMapper;
        this.fulfillmentTaskMapper=fulfillmentTaskMapper; this.shippingOrderMapper=shippingOrderMapper; this.dataScopeService=dataScopeService;
    }
    @Override public PageResponse<BenefitView> page(BenefitQuery query) {
        validate(query);
        UserDataScope scope=dataScopeService.resolveUserScope(query.getUserId());
        LambdaQueryWrapper<UserBenefit> wrapper=new LambdaQueryWrapper<UserBenefit>()
                .eq(!scope.all(),UserBenefit::getUserId,scope.userId())
                .eq(query.getStatus()!=null,UserBenefit::getStatus,query.getStatus())
                .eq(query.getPrizeType()!=null,UserBenefit::getPrizeType,query.getPrizeType())
                .ge(query.getStartDate()!=null,UserBenefit::getObtainedAt,query.getStartDate()==null?null:query.getStartDate().atStartOfDay())
                .lt(query.getEndDate()!=null,UserBenefit::getObtainedAt,endExclusive(query.getEndDate()))
                .orderByDesc(UserBenefit::getObtainedAt).orderByDesc(UserBenefit::getId);
        Page<UserBenefit> page=benefitMapper.selectPage(Page.of(query.getPage(),query.getSize()),wrapper);
        Map<Long,LotteryDrawRecord> records=records(page.getRecords());
        Map<String,FulfillmentTask> tasks=tasks(page.getRecords());
        List<BenefitView> views=page.getRecords().stream().map(b->toView(b,records.get(b.getDrawRecordId()),
                b.getFulfillmentNo()==null?null:tasks.get(b.getFulfillmentNo()))).toList();
        return new PageResponse<>(views,page.getTotal(),page.getCurrent(),page.getSize(),page.getPages());
    }
    private void validate(BenefitQuery query){
        if(query.getPage()<1||query.getPage()>MAX_PAGE||query.getSize()<1||query.getSize()>100)throw invalidQuery();
        try{Math.multiplyExact(query.getPage()-1,query.getSize());}catch(ArithmeticException exception){throw invalidQuery();}
        validateDate(query.getStartDate(),false);validateDate(query.getEndDate(),true);
        if(query.getStartDate()!=null&&query.getEndDate()!=null&&query.getStartDate().isAfter(query.getEndDate()))throw invalidQuery();
    }
    private void validateDate(LocalDate date,boolean safeEnd){if(date==null)return;LocalDate maximum=safeEnd?MAX_SAFE_END_DATE:MAX_SAFE_END_DATE.plusDays(1);if(date.isBefore(MYSQL_MIN_DATE)||date.isAfter(maximum))throw invalidQuery();}
    private LocalDateTime endExclusive(LocalDate date){return date==null?null:date.plusDays(1).atStartOfDay();}
    private BusinessException invalidQuery(){return new BusinessException(CommonErrorCode.INVALID_PARAMETER,"查询条件超出支持范围");}
    @Override public BenefitView getById(long id) {
        UserBenefit benefit=benefitMapper.selectById(id);
        if(benefit==null) throw new BusinessException(BenefitErrorCode.BENEFIT_NOT_FOUND);
        dataScopeService.resolveUserScope(benefit.getUserId());
        FulfillmentTask task=benefit.getFulfillmentNo()==null?null:fulfillmentTaskMapper.selectOne(
                new LambdaQueryWrapper<FulfillmentTask>().eq(FulfillmentTask::getFulfillmentNo,benefit.getFulfillmentNo()));
        return toView(benefit,recordMapper.selectById(benefit.getDrawRecordId()),task);
    }
    private Map<Long,LotteryDrawRecord> records(List<UserBenefit> benefits){
        if(benefits.isEmpty()) return Map.of();
        return recordMapper.selectBatchIds(benefits.stream().map(UserBenefit::getDrawRecordId).toList()).stream()
                .collect(Collectors.toMap(LotteryDrawRecord::getId,Function.identity()));
    }
    private Map<String,FulfillmentTask> tasks(List<UserBenefit> benefits){
        List<String> numbers=benefits.stream().map(UserBenefit::getFulfillmentNo)
                .filter(Objects::nonNull).distinct().toList();
        if(numbers.isEmpty())return Map.of();
        return fulfillmentTaskMapper.selectList(new LambdaQueryWrapper<FulfillmentTask>()
                        .in(FulfillmentTask::getFulfillmentNo,numbers)).stream()
                .collect(Collectors.toMap(FulfillmentTask::getFulfillmentNo,Function.identity()));
    }
    private BenefitView toView(UserBenefit benefit,LotteryDrawRecord record,FulfillmentTask task){
        ShippingOrder shipping=benefit.getShippingOrderId()==null?null:shippingOrderMapper.selectById(benefit.getShippingOrderId());
        return new BenefitView(benefit.getId(),benefit.getDrawRecordId(),benefit.getUserId(),benefit.getPrizeId(),
                benefit.getPrizeType(),record==null?null:record.getPrizeName(),record==null?null:record.getPrizeImageUrl(),
                benefit.getQuantity(),benefit.getStatus(),benefit.getObtainedAt(),benefit.getExpireAt(),
                benefit.getRewardDefinitionId(),benefit.getRewardType(),benefit.getRewardQuantity(),
                benefit.getFulfillmentNo(),task==null?null:task.getStatus(),
                shipping==null?null:shipping.getShippingNo(),shipping==null?null:shipping.getStatus());
    }
}

package com.dongqh.luckyhub.service.benefit.impl;

import com.dongqh.luckyhub.enums.benefit.BenefitStatus;
import com.dongqh.luckyhub.service.benefit.LotteryRewardProjectionService;
import com.dongqh.luckyhub.domain.dto.coupon.IssueCouponCommand;
import com.dongqh.luckyhub.service.coupon.CouponService;
import com.dongqh.luckyhub.enums.fulfillment.FulfillmentStatus;
import com.dongqh.luckyhub.enums.fulfillment.FulfillmentType;
import com.dongqh.luckyhub.domain.model.fulfillment.CouponFulfillmentPayload;
import com.dongqh.luckyhub.domain.model.fulfillment.MembershipFulfillmentPayload;
import com.dongqh.luckyhub.domain.model.fulfillment.PointsFulfillmentPayload;
import com.dongqh.luckyhub.domain.dto.membership.PurchaseMembershipCommand;
import com.dongqh.luckyhub.service.membership.MembershipService;
import com.dongqh.luckyhub.domain.dto.points.PointsMutationCommand;
import com.dongqh.luckyhub.enums.points.PointsBusinessType;
import com.dongqh.luckyhub.service.points.PointsAccountService;
import com.dongqh.luckyhub.enums.reward.RewardType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;

@Service
public class LotteryRewardProjectionServiceImpl implements LotteryRewardProjectionService {
    private static final int MAX_BATCH = 100;
    private static final int MAX_QUANTITY = 100;
    private static final String PROVIDER_FAILURE = "权益发放失败";
    private static final String LOCAL_FAILURE = "本地资产投影失败";

    private final JdbcTemplate jdbc;
    private final CouponService coupons;
    private final PointsAccountService points;
    private final MembershipService memberships;
    private final ObjectMapper json;
    private final TransactionTemplate transactions;

    public LotteryRewardProjectionServiceImpl(JdbcTemplate jdbc, CouponService coupons,
            PointsAccountService points, MembershipService memberships, ObjectMapper json,
            PlatformTransactionManager transactionManager) {
        this.jdbc = jdbc;
        this.coupons = coupons;
        this.points = points;
        this.memberships = memberships;
        this.json = json;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    @Override
    public int projectBatch(int limit) {
        if (limit <= 0) return 0;
        List<Long> benefitIds = jdbc.queryForList("""
                SELECT b.id
                FROM user_benefit b
                JOIN fulfillment_task t ON t.fulfillment_no=b.fulfillment_no
                WHERE t.source_type='LOTTERY_BENEFIT'
                  AND b.status IN ('PENDING','GRANT_FAILED')
                  AND t.status IN ('SUCCEEDED','QUARANTINED','TERMINATED')
                ORDER BY b.id
                LIMIT ?
                """, Long.class, Math.min(limit, MAX_BATCH));
        benefitIds.forEach(this::project);
        return benefitIds.size();
    }

    @Override
    public void project(long benefitId) {
        if (benefitId <= 0) throw new IllegalArgumentException("benefitId必须为正数");
        try {
            transactions.executeWithoutResult(ignored -> projectLocked(benefitId));
        } catch (RuntimeException failure) {
            transactions.executeWithoutResult(ignored -> markLocalFailure(benefitId));
        }
    }

    private void projectLocked(long benefitId) {
        ProjectionRow row = lock(benefitId);
        if (row == null || row.benefitStatus == BenefitStatus.AVAILABLE) return;
        if (row.benefitStatus != BenefitStatus.PENDING
                && row.benefitStatus != BenefitStatus.GRANT_FAILED) return;
        requireIdentity(row);
        if (row.fulfillmentStatus == FulfillmentStatus.QUARANTINED
                || row.fulfillmentStatus == FulfillmentStatus.TERMINATED) {
            markFailure(row.benefitId, PROVIDER_FAILURE);
            return;
        }
        if (row.fulfillmentStatus != FulfillmentStatus.SUCCEEDED) return;

        switch (row.rewardType) {
            case COUPON -> projectCoupons(row);
            case POINTS -> projectPoints(row);
            case MEMBERSHIP -> projectMembership(row);
            default -> throw new IllegalStateException("该奖励类型不需要履约投影");
        }
        int changed = jdbc.update("""
                UPDATE user_benefit SET status='AVAILABLE',grant_error=NULL,
                  updated_at=CURRENT_TIMESTAMP(3)
                WHERE id=? AND status IN ('PENDING','GRANT_FAILED')
                """, row.benefitId);
        if (changed != 1) throw new IllegalStateException("权益状态并发冲突");
    }

    private void projectCoupons(ProjectionRow row) {
        CouponFulfillmentPayload payload = read(row.requestPayload, CouponFulfillmentPayload.class);
        int quantity = bounded(row.rewardQuantity);
        if (payload.quantity() != quantity || row.rewardTargetId == null) {
            throw new IllegalStateException("优惠券冻结快照不一致");
        }
        for (int index = 1; index <= quantity; index++) {
            coupons.issue(new IssueCouponCommand(
                    row.fulfillmentNo + "-C-" + index,
                    "LR-C-" + row.benefitId + "-" + index,
                    row.rewardTargetId, row.userId));
        }
    }

    private void projectPoints(ProjectionRow row) {
        PointsFulfillmentPayload payload = read(row.requestPayload, PointsFulfillmentPayload.class);
        if (payload.points() != row.rewardQuantity) {
            throw new IllegalStateException("积分冻结快照不一致");
        }
        points.credit(new PointsMutationCommand(row.userId, PointsBusinessType.LOTTERY_REWARD,
                row.fulfillmentNo, payload.points(), "抽奖奖励"));
    }

    private void projectMembership(ProjectionRow row) {
        read(row.requestPayload, MembershipFulfillmentPayload.class);
        int quantity = bounded(row.rewardQuantity);
        if (row.rewardTargetId == null) throw new IllegalStateException("会员冻结快照缺少产品");
        for (int index = 1; index <= quantity; index++) {
            memberships.purchase(new PurchaseMembershipCommand(
                    row.fulfillmentNo + "-M-" + index, row.rewardTargetId, row.userId));
        }
    }

    private void requireIdentity(ProjectionRow row) {
        if (!"LOTTERY_BENEFIT".equals(row.sourceType)
                || !Long.toString(row.benefitId).equals(row.sourceId)
                || !row.userId.equals(row.targetUserId)
                || expectedType(row.rewardType) != row.fulfillmentType) {
            throw new IllegalStateException("履约任务与权益身份不一致");
        }
    }

    private FulfillmentType expectedType(RewardType rewardType) {
        return switch (rewardType) {
            case COUPON -> FulfillmentType.COUPON;
            case POINTS -> FulfillmentType.POINTS;
            case MEMBERSHIP -> FulfillmentType.MEMBERSHIP;
            default -> throw new IllegalStateException("奖励类型不支持投影");
        };
    }

    private int bounded(long quantity) {
        if (quantity <= 0 || quantity > MAX_QUANTITY) {
            throw new IllegalStateException("单个奖励投影数量必须在1到100之间");
        }
        return Math.toIntExact(quantity);
    }

    private <T> T read(String payload, Class<T> type) {
        try {
            return json.readValue(payload, type);
        } catch (JacksonException error) {
            throw new IllegalStateException("履约快照无法解析", error);
        }
    }

    private ProjectionRow lock(long benefitId) {
        return jdbc.query("""
                SELECT b.id,b.user_id,b.reward_type,b.reward_target_id,b.reward_quantity,
                  b.fulfillment_no,b.status benefit_status,
                  t.source_type,t.source_id,t.fulfillment_type,t.target_user_id,
                  CAST(t.request_payload AS CHAR) request_payload,t.status fulfillment_status
                FROM user_benefit b
                LEFT JOIN fulfillment_task t ON t.fulfillment_no=b.fulfillment_no
                WHERE b.id=? FOR UPDATE
                """, rs -> rs.next() ? row(rs) : null, benefitId);
    }

    private ProjectionRow row(ResultSet rs) throws SQLException {
        String rewardType = rs.getString("reward_type");
        String fulfillmentType = rs.getString("fulfillment_type");
        String fulfillmentStatus = rs.getString("fulfillment_status");
        Object target = rs.getObject("reward_target_id");
        Object quantity = rs.getObject("reward_quantity");
        Object targetUser = rs.getObject("target_user_id");
        return new ProjectionRow(
                rs.getLong("id"), rs.getLong("user_id"),
                rewardType == null ? null : RewardType.valueOf(rewardType),
                target == null ? null : ((Number) target).longValue(),
                quantity == null ? 0 : ((Number) quantity).longValue(),
                rs.getString("fulfillment_no"), BenefitStatus.valueOf(rs.getString("benefit_status")),
                rs.getString("source_type"), rs.getString("source_id"),
                fulfillmentType == null ? null : FulfillmentType.valueOf(fulfillmentType),
                targetUser == null ? null : ((Number) targetUser).longValue(),
                rs.getString("request_payload"),
                fulfillmentStatus == null ? null : FulfillmentStatus.valueOf(fulfillmentStatus));
    }

    private void markLocalFailure(long benefitId) {
        jdbc.update("""
                UPDATE user_benefit SET status='GRANT_FAILED',grant_error=?,
                  updated_at=CURRENT_TIMESTAMP(3)
                WHERE id=? AND status IN ('PENDING','GRANT_FAILED')
                """, LOCAL_FAILURE, benefitId);
    }

    private void markFailure(long benefitId, String safeError) {
        jdbc.update("""
                UPDATE user_benefit SET status='GRANT_FAILED',grant_error=?,
                  updated_at=CURRENT_TIMESTAMP(3)
                WHERE id=? AND status IN ('PENDING','GRANT_FAILED')
                """, safeError, benefitId);
    }

    private record ProjectionRow(long benefitId, Long userId, RewardType rewardType,
            Long rewardTargetId, long rewardQuantity, String fulfillmentNo,
            BenefitStatus benefitStatus, String sourceType, String sourceId,
            FulfillmentType fulfillmentType, Long targetUserId, String requestPayload,
            FulfillmentStatus fulfillmentStatus) {
    }
}

