@Service
public class CouponCheckoutServiceImpl implements CouponCheckoutService {
    private static final int FULL_PRICE_BASIS_POINTS = 10_000;

    private final CouponTemplateMapper templates;
    private final UserCouponMapper coupons;
    private final HmallCatalogClient catalog;
    private final MembershipService memberships;

    public CouponCheckoutServiceImpl(CouponTemplateMapper templates,
                                     UserCouponMapper coupons,
                                     HmallCatalogClient catalog,
                                     MembershipService memberships) {
        this.templates = templates;
        this.coupons = coupons;
        this.catalog = catalog;
        this.memberships = memberships;
    }

    @Override
    public List<ApplicableCouponView> listApplicable(long userId, CouponCheckoutCommand command) {
        Basket basket = loadBasket(userId, command.items());
        List<UserCoupon> mine = coupons.selectList(new LambdaQueryWrapper<UserCoupon>()
                .eq(UserCoupon::getUserId, userId)
                .eq(UserCoupon::getStatus, UserCouponStatus.AVAILABLE)
                .le(UserCoupon::getValidFrom, LocalDateTime.now())
                .gt(UserCoupon::getValidUntil, LocalDateTime.now())
                .orderByAsc(UserCoupon::getValidUntil));
        if (mine.isEmpty()) {
            return List.of();
        }
        Map<Long, CouponTemplate> byId = templates.selectBatchIds(mine.stream()
                        .map(UserCoupon::getTemplateId)
                        .distinct()
                        .toList())
                .stream()
                .collect(Collectors.toMap(CouponTemplate::getId, Function.identity()));
        List<ApplicableCouponView> result = new ArrayList<>();
        for (UserCoupon coupon : mine) {
            CouponTemplate template = byId.get(coupon.getTemplateId());
            Long discount = calculateDiscount(template, basket);
            if (discount != null) {
                result.add(new ApplicableCouponView(
                        coupon.getId().toString(), template.getTemplateName(), template.getThresholdCent(), discount,
                        template.getScopeType(), scopeValue(template), coupon.getValidUntil(),
                        Boolean.TRUE.equals(template.getStackableWithMembership())));
            }
        }
        return result;
    }

    @Override
    @Transactional
    public CouponLockSnapshot reserve(long userId, ReserveCouponCommand command) {
        UserCoupon coupon = coupons.selectById(command.couponId());
        if (coupon == null || !Long.valueOf(userId).equals(coupon.getUserId())) {
            throw error(CouponErrorCode.COUPON_NOT_FOUND);
        }
        CouponTemplate template = templates.selectById(coupon.getTemplateId());
        Basket basket = loadBasket(userId, command.items());
        Long discount = calculateDiscount(template, basket);
        if (discount == null) {
            throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);
        }
        if (coupon.getStatus() == UserCouponStatus.LOCKED
                && command.orderNo().equals(coupon.getLockedOrderNo())) {
            return snapshot(coupon, template, discount);
        }
        if (coupon.getStatus() != UserCouponStatus.AVAILABLE) {
            throw error(CouponErrorCode.COUPON_UNAVAILABLE);
        }
        if (coupons.lock(coupon.getId(), userId, command.orderNo()) != 1) {
            UserCoupon winner = coupons.selectById(coupon.getId());
            if (winner != null && winner.getStatus() == UserCouponStatus.LOCKED
                    && command.orderNo().equals(winner.getLockedOrderNo())) {
                return snapshot(winner, template, discount);
            }
            throw error(CouponErrorCode.COUPON_STATE_CONFLICT);
        }
        return snapshot(coupon, template, discount);
    }

    @Override
    @Transactional
    public void use(long userId, long couponId, String orderNo) {
        UserCoupon coupon = ownedCoupon(userId, couponId);
        if (coupon.getStatus() == UserCouponStatus.USED && orderNo.equals(coupon.getUsedOrderNo())) {
            return;
        }
        if (coupons.use(couponId, orderNo) != 1) {
            throw error(CouponErrorCode.COUPON_STATE_CONFLICT);
        }
    }

    @Override
    @Transactional
    public void release(long userId, long couponId, String orderNo) {
        UserCoupon coupon = ownedCoupon(userId, couponId);
        if (coupon.getStatus() == UserCouponStatus.AVAILABLE) {
            return;
        }
        if (coupons.release(couponId, orderNo) != 1) {
            throw error(CouponErrorCode.COUPON_STATE_CONFLICT);
        }
    }

    private Basket loadBasket(long userId, List<CouponCheckoutItemCommand> commands) {
        if (commands == null || commands.isEmpty()) {
            throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);
        }
        int basisPoints = memberships.activeBenefit(userId)
                .map(ActiveMembershipBenefit::discountBasisPoints)
                .filter(value -> value != null && value > 0 && value <= FULL_PRICE_BASIS_POINTS)
                .orElse(FULL_PRICE_BASIS_POINTS);
        List<BasketLine> lines = new ArrayList<>();
        long grossTotal = 0L;
        for (CouponCheckoutItemCommand command : commands) {
            if (command == null || command.itemId() <= 0 || command.quantity() <= 0) {
                throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);
            }
            HmallItemView item = catalog.getItem(command.itemId());
            if (item == null || item.price() == null || item.price() <= 0
                    || item.stock() == null || item.stock() < command.quantity()
                    || !Integer.valueOf(1).equals(item.status())) {
                throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);
            }
            long gross = Math.multiplyExact(item.price().longValue(), command.quantity());
            grossTotal = Math.addExact(grossTotal, gross);
            lines.add(new BasketLine(item, gross));
        }
        return new Basket(lines, basisPoints, discounted(grossTotal, basisPoints));
    }

    private Long calculateDiscount(CouponTemplate template, Basket basket) {
        LocalDateTime now = LocalDateTime.now();
        if (template == null || template.getStatus() == null || template.getStatus() != 1
                || template.getValidFrom() == null || template.getValidUntil() == null
                || now.isBefore(template.getValidFrom()) || !now.isBefore(template.getValidUntil())
                || template.getScopeType() == null || template.getApplicableProductId() != null
                || template.getDiscountCent() == null || template.getDiscountCent() <= 0
                || template.getThresholdCent() == null
                || (basket.hasMembershipDiscount() && !Boolean.TRUE.equals(template.getStackableWithMembership()))) {
            return null;
        }
        long eligibleAmount = eligibleAmount(template, basket);
        if (eligibleAmount <= 0 || eligibleAmount < template.getThresholdCent()) {
            return null;
        }
        return Math.min(template.getDiscountCent(), eligibleAmount);
    }

    private long eligibleAmount(CouponTemplate template, Basket basket) {
        if (template.getScopeType() == CouponScopeType.ALL) {
            return basket.discountedTotal();
        }
        long eligibleGross = 0L;
        for (BasketLine line : basket.lines()) {
            boolean matches = switch (template.getScopeType()) {
                case ITEM -> template.getHmallItemId() != null
                        && template.getHmallItemId().equals(line.item().id());
                case CATEGORY -> sameText(template.getHmallCategory(), line.item().category());
                case BRAND -> sameText(template.getHmallBrand(), line.item().brand());
                case ALL -> true;
            };
            if (matches) {
                eligibleGross = Math.addExact(eligibleGross, line.grossAmount());
            }
        }
        return discounted(eligibleGross, basket.membershipBasisPoints());
    }

    private long discounted(long amount, int basisPoints) {
        return (Math.multiplyExact(amount, basisPoints) + FULL_PRICE_BASIS_POINTS - 1)
                / FULL_PRICE_BASIS_POINTS;
    }

    private boolean sameText(String expected, String actual) {
        return expected != null && actual != null && expected.trim().equalsIgnoreCase(actual.trim());
    }

    private String scopeValue(CouponTemplate template) {
        return switch (template.getScopeType()) {
            case ALL -> "全部商品";
            case ITEM -> String.valueOf(template.getHmallItemId());
            case CATEGORY -> template.getHmallCategory();
            case BRAND -> template.getHmallBrand();
        };
    }

    private CouponLockSnapshot snapshot(UserCoupon coupon, CouponTemplate template, long discount) {
        return new CouponLockSnapshot(coupon.getId(), template.getId(), template.getTemplateName(), discount);
    }

    private UserCoupon ownedCoupon(long userId, long couponId) {
        UserCoupon coupon = coupons.selectById(couponId);
        if (coupon == null || !Long.valueOf(userId).equals(coupon.getUserId())) {
            throw error(CouponErrorCode.COUPON_NOT_FOUND);
        }
        return coupon;
    }

    private BusinessException error(CouponErrorCode code) {
        return new BusinessException(code);
    }

    private record BasketLine(HmallItemView item, long grossAmount) {
    }

    private record Basket(List<BasketLine> lines, int membershipBasisPoints, long discountedTotal) {
        boolean hasMembershipDiscount() {
            return membershipBasisPoints < FULL_PRICE_BASIS_POINTS;
        }
    }
}

package com.dongqh.luckyhub.service.coupon.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.dongqh.luckyhub.common.exception.BusinessException; import com.dongqh.luckyhub.common.result.PageResponse; import com.dongqh.luckyhub.domain.dto.coupon.*; import com.dongqh.luckyhub.domain.po.coupon.*; import com.dongqh.luckyhub.enums.coupon.*; import com.dongqh.luckyhub.mapper.coupon.*; import com.dongqh.luckyhub.domain.model.coupon.CouponLockSnapshot; import com.dongqh.luckyhub.service.coupon.CouponService; import com.dongqh.luckyhub.domain.vo.coupon.*; import com.dongqh.luckyhub.domain.hmall.integration.HmallCatalogClient; import com.dongqh.luckyhub.domain.hmall.integration.HmallItemView; import com.dongqh.luckyhub.domain.po.rbac.SysUser; import com.dongqh.luckyhub.mapper.rbac.SysUserMapper; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.time.LocalDateTime; import java.util.Map; import java.util.function.Function; import java.util.stream.Collectors;
@Service public class CouponServiceImpl implements CouponService {
 private final CouponTemplateMapper templates;private final UserCouponMapper coupons;private final CouponIssueRecordMapper issues;private final SysUserMapper users;private final HmallCatalogClient catalog;
 public CouponServiceImpl(CouponTemplateMapper t,UserCouponMapper c,CouponIssueRecordMapper i,SysUserMapper u,HmallCatalogClient catalog){templates=t;coupons=c;issues=i;users=u;this.catalog=catalog;}
 @Transactional public CouponTemplateView createTemplate(CreateCouponTemplateCommand c){validate(c);CouponTemplate t=new CouponTemplate();t.setTemplateCode(c.templateCode().trim());t.setTemplateName(c.templateName().trim());t.setCouponType(c.couponType());t.setThresholdCent(c.thresholdCent());t.setDiscountCent(c.discountCent());t.setApplicableProductId(c.applicableProductId());t.setScopeType(c.scopeType());t.setHmallItemId(c.hmallItemId());t.setHmallCategory(normalizeCategory(c.hmallCategory()));t.setHmallBrand(normalizeCategory(c.hmallBrand()));t.setValidFrom(c.validFrom());t.setValidUntil(c.validUntil());t.setPerUserLimit(c.perUserLimit());t.setStackableWithMembership(c.stackableWithMembership());t.setStatus(1);try{templates.insert(t);}catch(DuplicateKeyException e){throw error(CouponErrorCode.TEMPLATE_DUPLICATE);}return view(t);}
 @Transactional(isolation=Isolation.READ_COMMITTED) public UserCouponView issue(IssueCouponCommand c){String b=c.businessNo().trim();CouponIssueRecord old=issues.selectOne(new LambdaQueryWrapper<CouponIssueRecord>().eq(CouponIssueRecord::getBusinessNo,b));if(old!=null)return existingIssue(old,c);CouponTemplate t=templates.lockById(c.templateId());if(t==null||t.getStatus()!=1)throw error(CouponErrorCode.TEMPLATE_NOT_FOUND);SysUser u=users.selectById(c.userId());if(u==null||u.getStatus()!=1)throw error(CouponErrorCode.COUPON_UNAVAILABLE);long count=issues.selectCount(new LambdaQueryWrapper<CouponIssueRecord>().eq(CouponIssueRecord::getUserId,c.userId()).eq(CouponIssueRecord::getTemplateId,c.templateId()));if(count>=t.getPerUserLimit())throw error(CouponErrorCode.ISSUE_LIMIT);UserCoupon uc=new UserCoupon();uc.setCouponNo(c.couponNo().trim());uc.setTemplateId(t.getId());uc.setUserId(c.userId());uc.setStatus(UserCouponStatus.AVAILABLE);uc.setValidFrom(t.getValidFrom());uc.setValidUntil(t.getValidUntil());uc.setVersion(0);CouponIssueRecord record=new CouponIssueRecord();record.setBusinessNo(b);record.setTemplateId(t.getId());record.setUserId(c.userId());try{coupons.insert(uc);record.setUserCouponId(uc.getId());issues.insert(record);}catch(DuplicateKeyException e){throw error(CouponErrorCode.COUPON_IDEMPOTENCY_CONFLICT);}return view(uc,t);}
 public UserCouponView getMine(long userId,long id){UserCoupon c=coupons.selectById(id);if(c==null||!c.getUserId().equals(userId))throw error(CouponErrorCode.COUPON_NOT_FOUND);return view(c,templates.selectById(c.getTemplateId()));}
 public PageResponse<UserCouponView> pageMine(long userId,long page,long size){Page<UserCoupon> p=coupons.selectPage(new Page<>(page,size),new LambdaQueryWrapper<UserCoupon>().eq(UserCoupon::getUserId,userId).orderByDesc(UserCoupon::getCreatedAt).orderByDesc(UserCoupon::getId));Map<Long,CouponTemplate> byId=templates.selectBatchIds(p.getRecords().stream().map(UserCoupon::getTemplateId).distinct().toList()).stream().collect(Collectors.toMap(CouponTemplate::getId,Function.identity()));return new PageResponse<>(p.getRecords().stream().map(c->view(c,byId.get(c.getTemplateId()))).toList(),p.getTotal(),p.getCurrent(),p.getSize(),p.getPages());}
 @Transactional public CouponLockSnapshot lockForOrder(long userId,long id,String orderNo,Long productId,long amount,boolean member){UserCoupon c=coupons.selectById(id);if(c==null||!c.getUserId().equals(userId))throw error(CouponErrorCode.COUPON_NOT_FOUND);CouponTemplate t=templates.selectById(c.getTemplateId());if(c.getStatus()==UserCouponStatus.LOCKED&&orderNo.equals(c.getLockedOrderNo()))return snapshot(c,t,amount,productId,member);if(c.getStatus()!=UserCouponStatus.AVAILABLE)throw error(CouponErrorCode.COUPON_UNAVAILABLE);validateApplicable(t,amount,productId,member);if(coupons.lock(id,userId,orderNo)!=1){UserCoupon winner=coupons.selectById(id);if(winner!=null&&winner.getStatus()==UserCouponStatus.LOCKED&&orderNo.equals(winner.getLockedOrderNo()))return snapshot(winner,t,amount,productId,member);throw error(CouponErrorCode.COUPON_STATE_CONFLICT);}return snapshot(c,t,amount,productId,member);}
 @Transactional public void useForOrder(long id,String orderNo){UserCoupon c=coupons.selectById(id);if(c!=null&&c.getStatus()==UserCouponStatus.USED&&orderNo.equals(c.getUsedOrderNo()))return;if(coupons.use(id,orderNo)!=1)throw error(CouponErrorCode.COUPON_STATE_CONFLICT);}
 @Transactional public void releaseForOrder(long id,String orderNo){UserCoupon c=coupons.selectById(id);if(c!=null&&c.getStatus()==UserCouponStatus.AVAILABLE)return;if(coupons.release(id,orderNo)!=1)throw error(CouponErrorCode.COUPON_STATE_CONFLICT);}
 @Transactional public int expireAvailable(){return coupons.expireAvailable();}
 private UserCouponView existingIssue(CouponIssueRecord old,IssueCouponCommand c){if(!old.getTemplateId().equals(c.templateId())||!old.getUserId().equals(c.userId()))throw error(CouponErrorCode.COUPON_IDEMPOTENCY_CONFLICT);UserCoupon uc=coupons.selectById(old.getUserCouponId());if(!uc.getCouponNo().equals(c.couponNo().trim()))throw error(CouponErrorCode.COUPON_IDEMPOTENCY_CONFLICT);return view(uc,templates.selectById(uc.getTemplateId()));}
 private CouponLockSnapshot snapshot(UserCoupon c,CouponTemplate t,long amount,Long productId,boolean member){validateApplicable(t,amount,productId,member);return new CouponLockSnapshot(c.getId(),t.getId(),t.getTemplateName(),Math.min(t.getDiscountCent(),amount));}
 private void validateApplicable(CouponTemplate t,long amount,Long productId,boolean member){LocalDateTime now=LocalDateTime.now();if(t==null||t.getStatus()!=1||now.isBefore(t.getValidFrom())||!now.isBefore(t.getValidUntil())||amount<t.getThresholdCent()||(t.getApplicableProductId()!=null&&!t.getApplicableProductId().equals(productId))||(t.getScopeType()==CouponScopeType.ITEM&&!t.getHmallItemId().equals(productId))||t.getScopeType()==CouponScopeType.CATEGORY||(member&&!t.getStackableWithMembership()))throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);}
 private void validate(CreateCouponTemplateCommand c){if(!c.validUntil().isAfter(c.validFrom())||(c.couponType()==CouponType.NO_THRESHOLD&&c.thresholdCent()!=0)||(c.couponType()==CouponType.THRESHOLD&&c.thresholdCent()<=0))throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);if(c.scopeType()==null)return;String category=normalizeCategory(c.hmallCategory());String brand=normalizeCategory(c.hmallBrand());if(c.applicableProductId()!=null||(c.scopeType()==CouponScopeType.ALL&&(c.hmallItemId()!=null||category!=null||brand!=null))||(c.scopeType()==CouponScopeType.ITEM&&(c.hmallItemId()==null||category!=null||brand!=null))||(c.scopeType()==CouponScopeType.CATEGORY&&(category==null||c.hmallItemId()!=null||brand!=null))||(c.scopeType()==CouponScopeType.BRAND&&(brand==null||c.hmallItemId()!=null||category!=null)))throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);if(c.scopeType()==CouponScopeType.ITEM){HmallItemView item=catalog.getItem(c.hmallItemId());if(item==null||!item.availableForReward())throw error(CouponErrorCode.COUPON_NOT_APPLICABLE);}}
 private String normalizeCategory(String category){return category==null||category.isBlank()?null:category.trim();}
 private CouponTemplateView view(CouponTemplate t){return new CouponTemplateView(t.getId(),t.getTemplateCode(),t.getTemplateName(),t.getCouponType(),t.getThresholdCent(),t.getDiscountCent(),t.getApplicableProductId(),t.getScopeType(),t.getHmallItemId(),t.getHmallCategory(),t.getHmallBrand(),t.getValidFrom(),t.getValidUntil(),t.getPerUserLimit(),t.getStackableWithMembership(),t.getStatus());}
 private UserCouponView view(UserCoupon c,CouponTemplate t){return new UserCouponView(c.getId(),c.getCouponNo(),c.getTemplateId(),t==null?null:t.getTemplateName(),t==null?null:t.getCouponType(),t==null?null:t.getThresholdCent(),t==null?null:t.getDiscountCent(),t==null?null:t.getScopeType(),t==null?null:t.getHmallItemId(),t==null?null:t.getHmallCategory(),t==null?null:t.getHmallBrand(),c.getUserId(),c.getStatus(),c.getValidFrom(),c.getValidUntil(),c.getLockedOrderNo(),c.getUsedOrderNo());}
 private BusinessException error(CouponErrorCode e){return new BusinessException(e);}
}

