package com.dongqh.luckyhub.service.fulfillment.impl;
import com.dongqh.luckyhub.common.exception.BusinessException;import com.dongqh.luckyhub.config.fulfillment.FulfillmentProperties;import com.dongqh.luckyhub.enums.fulfillment.*;import com.dongqh.luckyhub.domain.model.fulfillment.FulfillmentClaim;import com.dongqh.luckyhub.service.fulfillment.FulfillmentStateService;import com.dongqh.luckyhub.domain.gateway.integration.GatewayResult;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.sql.Timestamp;import java.time.*;import java.util.*;
@Service public class FulfillmentStateServiceImpl implements FulfillmentStateService {
 private final JdbcTemplate jdbc;private final FulfillmentProperties properties;public FulfillmentStateServiceImpl(JdbcTemplate jdbc,FulfillmentProperties properties){this.jdbc=jdbc;this.properties=properties;}
 @Transactional public Optional<FulfillmentClaim> claimReady(String fulfillmentNo,Duration leaseDuration){if(fulfillmentNo==null||fulfillmentNo.isBlank())throw new IllegalArgumentException("fulfillmentNo不能为空");validateLease(leaseDuration);LocalDateTime now=LocalDateTime.now(),until=now.plus(leaseDuration);Row row=jdbc.query("SELECT id,fulfillment_no,fulfillment_type,target_user_id,request_payload,status FROM fulfillment_task WHERE fulfillment_no=? AND status='PENDING' AND (next_attempt_at IS NULL OR next_attempt_at<=?) FOR UPDATE",rs->rs.next()?row(rs):null,fulfillmentNo.trim(),Timestamp.valueOf(now));return row==null?Optional.empty():claim(row,now,until);}
 @Transactional public List<FulfillmentClaim> claimCompensationDue(int limit,Duration leaseDuration,Duration pendingGrace){validate(limit,leaseDuration);if(pendingGrace==null||pendingGrace.isZero()||pendingGrace.isNegative())throw new IllegalArgumentException("pendingGrace必须为正数");LocalDateTime now=LocalDateTime.now(),until=now.plus(leaseDuration),pendingBefore=now.minus(pendingGrace);List<Row> rows=jdbc.query("""
  SELECT id,fulfillment_no,fulfillment_type,target_user_id,request_payload,status FROM fulfillment_task
  WHERE ((status IN ('RETRY_WAITING','RECONCILING') AND (next_attempt_at IS NULL OR next_attempt_at<=?))
     OR (status='PENDING' AND (next_attempt_at IS NULL OR next_attempt_at<=?) AND created_at<=?))
  ORDER BY id LIMIT ? FOR UPDATE SKIP LOCKED
  """,(rs,n)->row(rs),Timestamp.valueOf(now),Timestamp.valueOf(now),Timestamp.valueOf(pendingBefore),limit);List<FulfillmentClaim> claims=new ArrayList<>();for(Row row:rows)claim(row,now,until).ifPresent(claims::add);return List.copyOf(claims);}
 @Transactional public List<FulfillmentClaim> claimDue(int limit,Duration leaseDuration){if(limit<1||limit>1000||leaseDuration==null||leaseDuration.isZero()||leaseDuration.isNegative())throw new IllegalArgumentException("领取参数不合法");LocalDateTime now=LocalDateTime.now(),until=now.plus(leaseDuration);List<Row> rows=jdbc.query("""
  SELECT id,fulfillment_no,fulfillment_type,target_user_id,request_payload,status FROM fulfillment_task
  WHERE status IN ('PENDING','RETRY_WAITING','RECONCILING') AND (next_attempt_at IS NULL OR next_attempt_at<=?)
  ORDER BY id LIMIT ? FOR UPDATE SKIP LOCKED
  """,(rs,n)->new Row(rs.getLong(1),rs.getString(2),FulfillmentType.valueOf(rs.getString(3)),rs.getLong(4),rs.getString(5),FulfillmentStatus.valueOf(rs.getString(6))),Timestamp.valueOf(now),limit);List<FulfillmentClaim> claims=new ArrayList<>();for(Row row:rows){String token=UUID.randomUUID().toString();int changed=jdbc.update("UPDATE fulfillment_task SET status='PROCESSING',lease_token=?,lease_until=? WHERE id=? AND status=?",token,Timestamp.valueOf(until),row.id,row.status.name());if(changed==1)claims.add(new FulfillmentClaim(row.id,row.no,row.type,row.user,row.payload,row.status==FulfillmentStatus.RECONCILING?AttemptOperation.QUERY:AttemptOperation.EXECUTE,token,now,until));}return List.copyOf(claims);}
 @Transactional public void recordResult(FulfillmentClaim claim,GatewayResult result,long durationMs){if(claim==null||result==null||durationMs<0)throw new IllegalArgumentException("结果参数不合法");TaskRow task=jdbc.query("SELECT status,lease_token,attempt_count,max_attempts FROM fulfillment_task WHERE id=? FOR UPDATE",rs->rs.next()?new TaskRow(FulfillmentStatus.valueOf(rs.getString(1)),rs.getString(2),rs.getInt(3),rs.getInt(4)):null,claim.taskId());if(task==null||task.status!=FulfillmentStatus.PROCESSING||!Objects.equals(task.token,claim.leaseToken()))throw new BusinessException(FulfillmentErrorCode.LEASE_CONFLICT);Integer sequence=jdbc.queryForObject("SELECT COALESCE(MAX(sequence_no),0)+1 FROM fulfillment_attempt WHERE task_id=?",Integer.class,claim.taskId());int executionAttempts=task.attempts+(claim.operation()==AttemptOperation.EXECUTE?1:0);FailureCategory category=category(result.outcome());LocalDateTime finished=LocalDateTime.now();jdbc.update("INSERT INTO fulfillment_attempt(task_id,fulfillment_no,sequence_no,operation,outcome,started_at,finished_at,duration_ms,external_reference,error_category,error_code,error_message) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",claim.taskId(),claim.fulfillmentNo(),sequence,claim.operation().name(),result.outcome().name(),Timestamp.valueOf(claim.claimedAt()),Timestamp.valueOf(finished),durationMs,result.externalReference(),category==null?null:category.name(),result.errorCode(),result.safeMessage());Transition transition=transition(result,claim.operation(),executionAttempts,task.maxAttempts,finished);jdbc.update("UPDATE fulfillment_task SET status=?,attempt_count=?,next_attempt_at=?,lease_token=NULL,lease_until=NULL,external_reference=COALESCE(?,external_reference),last_error_category=?,last_error_code=?,last_error_message=?,completed_at=? WHERE id=?",transition.status.name(),executionAttempts,transition.next==null?null:Timestamp.valueOf(transition.next),result.externalReference(),category==null?null:category.name(),result.errorCode(),result.safeMessage(),transition.completed==null?null:Timestamp.valueOf(transition.completed),claim.taskId());if(transition.status==FulfillmentStatus.QUARANTINED)jdbc.update("INSERT INTO fulfillment_quarantine(task_id,fulfillment_no,reason,error_category,error_code,error_message,quarantined_at) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE reason=VALUES(reason),error_category=VALUES(error_category),error_code=VALUES(error_code),error_message=VALUES(error_message),quarantined_at=VALUES(quarantined_at),resolved_at=NULL,resolution=NULL,resolved_by=NULL,resolution_note=NULL",claim.taskId(),claim.fulfillmentNo(),"履约失败",category==null?null:category.name(),result.errorCode(),result.safeMessage(),Timestamp.valueOf(finished));}
 @Transactional public int recoverExpiredLeases(int limit){if(limit<1||limit>1000)throw new IllegalArgumentException("limit必须为1到1000");return jdbc.update("UPDATE fulfillment_task SET status='RECONCILING',next_attempt_at=NOW(3),lease_token=NULL,lease_until=NULL,last_error_category='UNKNOWN',last_error_code='LEASE_EXPIRED',last_error_message='履约租约过期，转入安全对账' WHERE status='PROCESSING' AND lease_until<NOW(3) ORDER BY id LIMIT ?",limit);}
 private Optional<FulfillmentClaim> claim(Row row,LocalDateTime now,LocalDateTime until){String token=UUID.randomUUID().toString();int changed=jdbc.update("UPDATE fulfillment_task SET status='PROCESSING',lease_token=?,lease_until=? WHERE id=? AND status=?",token,Timestamp.valueOf(until),row.id,row.status.name());return changed==1?Optional.of(new FulfillmentClaim(row.id,row.no,row.type,row.user,row.payload,row.status==FulfillmentStatus.RECONCILING?AttemptOperation.QUERY:AttemptOperation.EXECUTE,token,now,until)):Optional.empty();}
 private Row row(java.sql.ResultSet rs)throws java.sql.SQLException{return new Row(rs.getLong(1),rs.getString(2),FulfillmentType.valueOf(rs.getString(3)),rs.getLong(4),rs.getString(5),FulfillmentStatus.valueOf(rs.getString(6)));}
 private void validate(int limit,Duration leaseDuration){if(limit<1||limit>1000)throw new IllegalArgumentException("limit必须为1到1000");validateLease(leaseDuration);}private void validateLease(Duration leaseDuration){if(leaseDuration==null||leaseDuration.isZero()||leaseDuration.isNegative())throw new IllegalArgumentException("leaseDuration必须为正数");}
 private Transition transition(GatewayResult r,AttemptOperation op,int attempts,int max,LocalDateTime now){return switch(r.outcome()){case SUCCEEDED->new Transition(FulfillmentStatus.SUCCEEDED,null,now);case UNKNOWN->new Transition(FulfillmentStatus.RECONCILING,now,null);case RETRYABLE_FAILURE->attempts>=max?new Transition(FulfillmentStatus.QUARANTINED,null,null):new Transition(FulfillmentStatus.RETRY_WAITING,now.plus(backoff(attempts)),null);case PERMANENT_FAILURE->new Transition(FulfillmentStatus.QUARANTINED,null,null);case NOT_FOUND->op==AttemptOperation.QUERY?new Transition(FulfillmentStatus.PENDING,now,null):new Transition(FulfillmentStatus.RETRY_WAITING,now.plus(backoff(attempts)),null);};}
 private Duration backoff(int attempts){long multiplier=1L<<Math.min(30,Math.max(0,attempts-1));Duration calculated;try{calculated=properties.baseDelay().multipliedBy(multiplier);}catch(ArithmeticException e){calculated=properties.maxDelay();}return calculated.compareTo(properties.maxDelay())>0?properties.maxDelay():calculated;}
 private FailureCategory category(GatewayOutcome o){return switch(o){case RETRYABLE_FAILURE->FailureCategory.RETRYABLE;case PERMANENT_FAILURE->FailureCategory.PERMANENT;case UNKNOWN->FailureCategory.UNKNOWN;default->null;};}
 private record Row(long id,String no,FulfillmentType type,long user,String payload,FulfillmentStatus status){}private record TaskRow(FulfillmentStatus status,String token,int attempts,int maxAttempts){}private record Transition(FulfillmentStatus status,LocalDateTime next,LocalDateTime completed){}
}

package com.dongqh.luckyhub.service.fulfillment.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.dongqh.luckyhub.common.exception.BusinessException; import com.dongqh.luckyhub.common.result.PageResponse; import com.dongqh.luckyhub.domain.dto.fulfillment.*; import com.dongqh.luckyhub.domain.po.fulfillment.FulfillmentTask; import com.dongqh.luckyhub.enums.fulfillment.*; import com.dongqh.luckyhub.mapper.fulfillment.FulfillmentTaskMapper; import com.dongqh.luckyhub.messaging.fulfillment.outbox.FulfillmentOutboxService; import com.dongqh.luckyhub.domain.model.fulfillment.*; import com.dongqh.luckyhub.service.fulfillment.FulfillmentTaskService; import com.dongqh.luckyhub.domain.vo.fulfillment.FulfillmentTaskView; import org.springframework.dao.DuplicateKeyException; import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Isolation;import org.springframework.transaction.annotation.Transactional; import tools.jackson.core.JacksonException; import tools.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;import java.security.*;import java.time.LocalDateTime;import java.util.HexFormat;
@Service public class FulfillmentTaskServiceImpl implements FulfillmentTaskService {
 private final FulfillmentTaskMapper mapper;private final ObjectMapper json;private final JdbcTemplate jdbc;private final FulfillmentOutboxService outbox;public FulfillmentTaskServiceImpl(FulfillmentTaskMapper mapper,ObjectMapper json,JdbcTemplate jdbc,FulfillmentOutboxService outbox){this.mapper=mapper;this.json=json;this.jdbc=jdbc;this.outbox=outbox;}
 @Transactional(isolation=Isolation.READ_COMMITTED) public FulfillmentTaskView create(CreateFulfillmentTaskCommand c){String payload=write(c.payload());String fingerprint=digest(c.sourceType()+"\n"+c.sourceId()+"\n"+c.fulfillmentType()+"\n"+c.targetUserId()+"\n"+c.maxAttempts()+"\n"+payload);FulfillmentTask old=find(c.fulfillmentNo());if(old!=null)return existing(old,fingerprint);FulfillmentTask t=new FulfillmentTask();t.setFulfillmentNo(c.fulfillmentNo());t.setSourceType(c.sourceType());t.setSourceId(c.sourceId());t.setFulfillmentType(c.fulfillmentType());t.setTargetUserId(c.targetUserId());t.setRequestPayload(payload);t.setRequestFingerprint(fingerprint);t.setStatus(FulfillmentStatus.PENDING);t.setAttemptCount(0);t.setMaxAttempts(c.maxAttempts());t.setNextAttemptAt(LocalDateTime.now());t.setVersion(0);try{mapper.insert(t);}catch(DuplicateKeyException race){return existing(find(c.fulfillmentNo()),fingerprint);}outbox.appendTaskReady(t.getFulfillmentNo());return view(t);}
 public FulfillmentTaskView get(String no){FulfillmentTask task=find(required(no));if(task==null)throw error(FulfillmentErrorCode.TASK_NOT_FOUND);return view(task);}
 public PageResponse<FulfillmentTaskView> page(FulfillmentTaskQuery q){Page<FulfillmentTask> p=mapper.selectPage(new Page<>(q.getPage(),q.getSize()),new LambdaQueryWrapper<FulfillmentTask>().eq(q.getFulfillmentType()!=null,FulfillmentTask::getFulfillmentType,q.getFulfillmentType()).eq(q.getStatus()!=null,FulfillmentTask::getStatus,q.getStatus()).eq(q.getTargetUserId()!=null,FulfillmentTask::getTargetUserId,q.getTargetUserId()).eq(q.getSourceType()!=null&&!q.getSourceType().isBlank(),FulfillmentTask::getSourceType,q.getSourceType()).eq(q.getSourceId()!=null&&!q.getSourceId().isBlank(),FulfillmentTask::getSourceId,q.getSourceId()).orderByDesc(FulfillmentTask::getCreatedAt).orderByDesc(FulfillmentTask::getId));return new PageResponse<>(p.getRecords().stream().map(this::view).toList(),p.getTotal(),p.getCurrent(),p.getSize(),p.getPages());}
 @Transactional public FulfillmentTaskView retryQuarantined(String no,long operator,String note){State row=lock(required(no));if(row==null)throw error(FulfillmentErrorCode.TASK_NOT_FOUND);if(row.status!=FulfillmentStatus.QUARANTINED)throw error(FulfillmentErrorCode.OPERATION_NOT_ALLOWED);jdbc.update("UPDATE fulfillment_task SET status='PENDING',next_attempt_at=NOW(3),max_attempts=LEAST(100,attempt_count+5),lease_token=NULL,lease_until=NULL,last_error_category=NULL,last_error_code=NULL,last_error_message=NULL WHERE id=?",row.id);jdbc.update("UPDATE fulfillment_quarantine SET resolved_at=NOW(3),resolution='RETRY',resolved_by=?,resolution_note=? WHERE task_id=?",operator,safe(note),row.id);outbox.appendTaskReady(no);return get(no);}
 @Transactional public FulfillmentTaskView terminate(String no,long operator,String note){State row=lock(required(no));if(row==null)throw error(FulfillmentErrorCode.TASK_NOT_FOUND);if(row.status==FulfillmentStatus.TERMINATED)return get(no);if(row.status==FulfillmentStatus.SUCCEEDED||row.status==FulfillmentStatus.PROCESSING)throw error(FulfillmentErrorCode.OPERATION_NOT_ALLOWED);jdbc.update("UPDATE fulfillment_task SET status='TERMINATED',next_attempt_at=NULL,lease_token=NULL,lease_until=NULL,completed_at=NOW(3) WHERE id=?",row.id);jdbc.update("UPDATE fulfillment_quarantine SET resolved_at=NOW(3),resolution='TERMINATED',resolved_by=?,resolution_note=? WHERE task_id=?",operator,safe(note),row.id);return get(no);}
 private FulfillmentTaskView existing(FulfillmentTask task,String fingerprint){if(task==null||!task.getRequestFingerprint().equals(fingerprint))throw error(FulfillmentErrorCode.IDEMPOTENCY_CONFLICT);return view(task);}
 private FulfillmentTask find(String no){return mapper.selectOne(new LambdaQueryWrapper<FulfillmentTask>().eq(FulfillmentTask::getFulfillmentNo,no));}
 private FulfillmentTaskView view(FulfillmentTask t){return new FulfillmentTaskView(t.getId(),t.getFulfillmentNo(),t.getSourceType(),t.getSourceId(),t.getFulfillmentType(),t.getTargetUserId(),read(t.getFulfillmentType(),t.getRequestPayload()),t.getRequestFingerprint(),t.getStatus(),t.getAttemptCount(),t.getMaxAttempts(),t.getNextAttemptAt(),t.getExternalReference(),t.getLastErrorCategory(),t.getLastErrorCode(),t.getLastErrorMessage(),t.getCompletedAt(),t.getCreatedAt(),t.getUpdatedAt());}
 private String write(FulfillmentPayload p){try{return json.writeValueAsString(p);}catch(JacksonException e){throw error(FulfillmentErrorCode.INVALID_PAYLOAD);}}
 private FulfillmentPayload read(FulfillmentType type,String value){try{return switch(type){case COUPON->json.readValue(value,CouponFulfillmentPayload.class);case POINTS->json.readValue(value,PointsFulfillmentPayload.class);case MEMBERSHIP->json.readValue(value,MembershipFulfillmentPayload.class);case LOGISTICS->json.readValue(value,LogisticsFulfillmentPayload.class);};}catch(JacksonException e){throw error(FulfillmentErrorCode.INVALID_PAYLOAD);}}
 private String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private String required(String v){if(v==null||v.isBlank())throw error(FulfillmentErrorCode.INVALID_PAYLOAD);return v.trim();}private BusinessException error(FulfillmentErrorCode c){return new BusinessException(c);}
 private State lock(String no){return jdbc.query("SELECT id,status FROM fulfillment_task WHERE fulfillment_no=? FOR UPDATE",rs->rs.next()?new State(rs.getLong(1),FulfillmentStatus.valueOf(rs.getString(2))):null,no);}private String safe(String note){if(note==null||note.isBlank())return null;String value=note.trim();return value.substring(0,Math.min(500,value.length()));}private record State(long id,FulfillmentStatus status){}
}

package com.dongqh.luckyhub.service.inventory;

public interface ActivityPrizeInventoryService {

    boolean decrementIfAvailable(long activityPrizeId);

    void returnExpiredClaim(long activityPrizeId, long hmallItemId, String businessNo);
}

package com.dongqh.luckyhub.service.inventory;

import com.dongqh.luckyhub.mapper.inventory.ActivityPrizeInventoryMapper;
import com.dongqh.luckyhub.domain.channel.inventory.entity.InventoryLedger;
import com.dongqh.luckyhub.domain.channel.inventory.enums.InventoryOperation;
import com.dongqh.luckyhub.domain.channel.inventory.mapper.InventoryLedgerMapper;
import org.springframework.stereotype.Service;

@Service
public class ActivityPrizeInventoryServiceImpl implements ActivityPrizeInventoryService {

    private final ActivityPrizeInventoryMapper inventoryMapper;
    private final InventoryLedgerMapper ledgers;

    public ActivityPrizeInventoryServiceImpl(ActivityPrizeInventoryMapper inventoryMapper,
                                             InventoryLedgerMapper ledgers) {
        this.inventoryMapper = inventoryMapper;
        this.ledgers = ledgers;
    }

    @Override
    public boolean decrementIfAvailable(long activityPrizeId) {
        return inventoryMapper.decrementIfAvailable(activityPrizeId) == 1;
    }

    @Override
    public void returnExpiredClaim(long activityPrizeId, long hmallItemId, String businessNo) {
        InventoryLedger ledger = new InventoryLedger();
        ledger.setBusinessNo(businessNo);
        ledger.setHmallItemId(hmallItemId);
        ledger.setChannelCode("LOTTERY");
        ledger.setOperation(InventoryOperation.CLAIM_RETURN);
        ledger.setQuantity(1);
        if (ledgers.claim(ledger) == 0) return;
        if (inventoryMapper.incrementIfBelowTotal(activityPrizeId) != 1) {
            throw new IllegalStateException("奖品库存回补失败");
        }
    }
}

