import com.dongqh.luckyhub.messaging.lottery.event.PrizeFulfillmentRequestedEvent;
import com.dongqh.luckyhub.domain.model.lottery.ValidatedLotteryReward;
import com.dongqh.luckyhub.service.lottery.LotteryRewardDispatchService;
import com.dongqh.luckyhub.service.lottery.LotteryRewardIdentityService;
import com.dongqh.luckyhub.service.lottery.RewardIdentityMismatchException;
import com.dongqh.luckyhub.domain.model.reward.CouponRewardPayload;
import com.dongqh.luckyhub.domain.model.reward.MembershipRewardPayload;
import com.dongqh.luckyhub.domain.model.reward.PointsRewardPayload;
import com.dongqh.luckyhub.config.shipping.ShippingProperties;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.time.LocalDateTime;
import java.time.Duration;
import java.time.temporal.ChronoUnit;

@Service
public class LotteryRewardDispatchServiceImpl implements LotteryRewardDispatchService {
    private final LotteryRewardIdentityService identities;
    private final BenefitFulfillmentService legacyFulfillment;
    private final FulfillmentTaskService tasks;
    private final DrawChanceService drawChances;
    private final UserBenefitMapper benefits;
    private final LotteryRewardQuarantineMapper quarantines;
    private final MessageConsumeRecordMapper consumeRecords;
    private final ObjectMapper json;
    private final String consumerName;
    private final Duration claimPeriod;

    @Autowired
    public LotteryRewardDispatchServiceImpl(LotteryRewardIdentityService identities,
            BenefitFulfillmentService legacyFulfillment, FulfillmentTaskService tasks,
            DrawChanceService drawChances, UserBenefitMapper benefits,
            LotteryRewardQuarantineMapper quarantines, MessageConsumeRecordMapper consumeRecords,
            ObjectMapper json, MessagingProperties properties, ShippingProperties shippingProperties) {
        this.identities = identities; this.legacyFulfillment = legacyFulfillment;
        this.tasks = tasks; this.drawChances = drawChances; this.benefits = benefits;
        this.quarantines = quarantines; this.consumeRecords = consumeRecords;
        this.json = json; this.consumerName = properties.logicalConsumerName();
        this.claimPeriod = shippingProperties.claimPeriod();
    }

    public LotteryRewardDispatchServiceImpl(LotteryRewardIdentityService identities,
            BenefitFulfillmentService legacyFulfillment, FulfillmentTaskService tasks,
            DrawChanceService drawChances, UserBenefitMapper benefits,
            LotteryRewardQuarantineMapper quarantines, MessageConsumeRecordMapper consumeRecords,
            ObjectMapper json, MessagingProperties properties) {
        this.identities = identities; this.legacyFulfillment = legacyFulfillment;
        this.tasks = tasks; this.drawChances = drawChances; this.benefits = benefits;
        this.quarantines = quarantines; this.consumeRecords = consumeRecords;
        this.json = json; this.consumerName = properties.logicalConsumerName();
        this.claimPeriod = Duration.ofDays(7);
    }

    @Override
    @Transactional
    public void dispatch(DrawEventEnvelope envelope, PrizeFulfillmentRequestedEvent payload) {
        String eventId = envelope.eventId().toString();
        ValidatedLotteryReward reward;
        try {
            reward = identities.validate(envelope, payload);
        } catch (RewardIdentityMismatchException mismatch) {
            if (alreadyConsumed(eventId)) return;
            quarantine(envelope, payload, mismatch);
            recordConsumed(eventId);
            return;
        }
        // Identity validation locks the benefit row. Recheck after that lock so concurrent
        // deliveries serialize before creating a task or writing any reward side effect.
        if (alreadyConsumed(eventId)) return;
        if (reward.rewardSnapshot() == null) {
            legacyFulfillment.fulfill(reward.benefitId(), eventId);
            return;
        }
        if (reward.benefitStatus() != BenefitStatus.PENDING
                && reward.benefitStatus() != BenefitStatus.GRANT_FAILED) {
            throw new BusinessException(BenefitErrorCode.BENEFIT_STATE_CONFLICT);
        }

        String fulfillmentNo = "LOTTERY-BENEFIT-" + reward.benefitId();
        switch (reward.rewardSnapshot().rewardType()) {
            case COUPON -> {
                CouponRewardPayload frozen = couponPayload(reward);
                createTask(reward, fulfillmentNo, FulfillmentType.COUPON,
                        new CouponFulfillmentPayload(frozen.templateCode(), frozen.quantity()));
            }
            case POINTS -> {
                PointsRewardPayload frozen = pointsPayload(reward);
                createTask(reward, fulfillmentNo, FulfillmentType.POINTS,
                        new PointsFulfillmentPayload(frozen.points(), frozen.reason()));
            }
            case MEMBERSHIP -> {
                MembershipRewardPayload frozen = membershipPayload(reward);
                createTask(reward, fulfillmentNo, FulfillmentType.MEMBERSHIP,
                        new MembershipFulfillmentPayload(frozen.productCode(), frozen.durationDays()));
            }
            case PRODUCT -> transitionProduct(reward);
            case DRAW_CHANCE -> {
                drawChances.credit(reward.userId(), fulfillmentNo, reward.rewardSnapshot().quantity());
                transition(reward, BenefitStatus.AVAILABLE);
            }
        }
        recordConsumed(eventId);
    }

    private void createTask(ValidatedLotteryReward reward, String fulfillmentNo,
                            FulfillmentType type,
                            com.dongqh.luckyhub.domain.model.fulfillment.FulfillmentPayload payload) {
        tasks.create(new CreateFulfillmentTaskCommand(fulfillmentNo, "LOTTERY_BENEFIT",
                Long.toString(reward.benefitId()), type, reward.userId(), payload, null));
        benefits.bindFulfillmentNo(reward.benefitId(), fulfillmentNo);
    }

    private CouponRewardPayload couponPayload(ValidatedLotteryReward reward) {
        return read(reward, CouponRewardPayload.class);
    }
    private PointsRewardPayload pointsPayload(ValidatedLotteryReward reward) {
        return read(reward, PointsRewardPayload.class);
    }
    private MembershipRewardPayload membershipPayload(ValidatedLotteryReward reward) {
        return read(reward, MembershipRewardPayload.class);
    }
    private <T> T read(ValidatedLotteryReward reward, Class<T> type) {
        try { return json.readValue(reward.rewardSnapshot().payloadJson(), type); }
        catch (JacksonException error) { throw new IllegalStateException("冻结奖励载荷无法解析", error); }
    }

    private void transition(ValidatedLotteryReward reward, BenefitStatus target) {
        if (benefits.transitionStatus(reward.benefitId(), reward.benefitStatus(), target) != 1) {
            throw new BusinessException(BenefitErrorCode.BENEFIT_STATE_CONFLICT);
        }
    }

    private void transitionProduct(ValidatedLotteryReward reward) {
        LocalDateTime deadline = LocalDateTime.now().truncatedTo(ChronoUnit.MILLIS).plus(claimPeriod);
        if (benefits.markClaimPending(reward.benefitId(), reward.benefitStatus(), deadline) != 1) {
            throw new BusinessException(BenefitErrorCode.BENEFIT_STATE_CONFLICT);
        }
    }

    private void quarantine(DrawEventEnvelope envelope, PrizeFulfillmentRequestedEvent payload,
                            RewardIdentityMismatchException mismatch) {
        LotteryRewardQuarantine row = new LotteryRewardQuarantine();
        row.setEventId(envelope.eventId().toString()); row.setRequestId(envelope.requestId());
        row.setOrderId(envelope.orderId()); row.setDrawRecordId(payload.drawRecordId());
        row.setBenefitId(payload.benefitId()); row.setPrizeId(payload.prizeId());
        row.setRewardDefinitionId(payload.rewardDefinitionId()); row.setReasonCode(mismatch.reason().name());
        row.setStatus(RewardQuarantineStatus.OPEN); row.setQuarantinedAt(LocalDateTime.now());
        quarantines.insert(row);
    }

    private boolean alreadyConsumed(String eventId) {
        return consumeRecords.selectCount(new LambdaQueryWrapper<MessageConsumeRecord>()
                .eq(MessageConsumeRecord::getEventId, eventId)
                .eq(MessageConsumeRecord::getConsumerName, consumerName)) > 0;
    }

    private void recordConsumed(String eventId) {
        MessageConsumeRecord record = new MessageConsumeRecord();
        record.setEventId(eventId); record.setConsumerName(consumerName);
        record.setConsumedAt(LocalDateTime.now()); consumeRecords.insert(record);
    }
}

package com.dongqh.luckyhub.service.lottery.impl;

import com.dongqh.luckyhub.mapper.benefit.UserBenefitMapper;
import com.dongqh.luckyhub.enums.lottery.DrawOrderStatus;
import com.dongqh.luckyhub.enums.lottery.RewardQuarantineReason;
import com.dongqh.luckyhub.messaging.lottery.event.DrawEventEnvelope;
import com.dongqh.luckyhub.messaging.lottery.event.PrizeFulfillmentRequestedEvent;
import com.dongqh.luckyhub.domain.model.lottery.LotteryRewardIdentityRow;
import com.dongqh.luckyhub.domain.model.lottery.ValidatedLotteryReward;
import com.dongqh.luckyhub.service.lottery.LotteryRewardIdentityService;
import com.dongqh.luckyhub.service.lottery.RewardIdentityMismatchException;
import com.dongqh.luckyhub.domain.model.reward.RewardSnapshot;
import org.springframework.stereotype.Service;

import java.util.Objects;

@Service
public class LotteryRewardIdentityServiceImpl implements LotteryRewardIdentityService {
    private final UserBenefitMapper benefits;

    public LotteryRewardIdentityServiceImpl(UserBenefitMapper benefits) {
        this.benefits = benefits;
    }

    @Override
    public ValidatedLotteryReward validate(DrawEventEnvelope envelope,
                                           PrizeFulfillmentRequestedEvent payload) {
        LotteryRewardIdentityRow row = benefits.lockLotteryRewardIdentity(payload.benefitId());
        if (row == null) throw mismatch(RewardQuarantineReason.IDENTITY_NOT_FOUND);
        if (!Objects.equals(envelope.requestId(), row.getRequestId())
                || !Objects.equals(envelope.orderId(), row.getOrderId())
                || !Objects.equals(envelope.userId(), row.getOrderUserId())
                || !Objects.equals(envelope.activityId(), row.getOrderActivityId())
                || row.getOrderStatus() != DrawOrderStatus.SUCCESS) {
            throw mismatch(RewardQuarantineReason.ORDER_IDENTITY_MISMATCH);
        }
        if (!Objects.equals(row.getOrderUserId(), row.getRecordUserId())
                || !Objects.equals(row.getOrderActivityId(), row.getRecordActivityId())
                || !Objects.equals(payload.drawRecordId(), row.getDrawRecordId())
                || !Objects.equals(payload.prizeId(), row.getRecordPrizeId())
                || payload.prizeType() != row.getRecordPrizeType()) {
            throw mismatch(RewardQuarantineReason.RECORD_IDENTITY_MISMATCH);
        }
        if (!Objects.equals(payload.benefitId(), row.getBenefitId())
                || !Objects.equals(row.getRecordUserId(), row.getBenefitUserId())
                || !Objects.equals(row.getRecordPrizeId(), row.getBenefitPrizeId())
                || row.getRecordPrizeType() != row.getBenefitPrizeType()) {
            throw mismatch(RewardQuarantineReason.BENEFIT_IDENTITY_MISMATCH);
        }

        RewardSnapshot snapshot = validateRewardIdentity(payload, row);
        return new ValidatedLotteryReward(row.getBenefitId(), row.getDrawRecordId(), row.getOrderId(),
                row.getRequestId(), row.getBenefitUserId(), row.getOrderActivityId(),
                row.getBenefitPrizeId(), row.getBenefitPrizeType(), row.getBenefitStatus(), snapshot);
    }

    private RewardSnapshot validateRewardIdentity(PrizeFulfillmentRequestedEvent payload,
                                                   LotteryRewardIdentityRow row) {
        if (payload.rewardDefinitionId() == null) {
            if (row.getRecordRewardDefinitionId() != null || row.getBenefitRewardDefinitionId() != null
                    || row.getRecordRewardType() != null || row.getBenefitRewardType() != null
                    || row.getRecordRewardFingerprint() != null || row.getBenefitRewardFingerprint() != null) {
                throw mismatch(RewardQuarantineReason.REWARD_DEFINITION_MISMATCH);
            }
            return null;
        }
        if (!Objects.equals(payload.rewardDefinitionId(), row.getRecordRewardDefinitionId())
                || !Objects.equals(row.getRecordRewardDefinitionId(), row.getBenefitRewardDefinitionId())) {
            throw mismatch(RewardQuarantineReason.REWARD_DEFINITION_MISMATCH);
        }
        if (payload.rewardType() != row.getRecordRewardType()
                || row.getRecordRewardType() != row.getBenefitRewardType()) {
            throw mismatch(RewardQuarantineReason.REWARD_TYPE_MISMATCH);
        }
        if (!Objects.equals(payload.rewardFingerprint(), row.getRecordRewardFingerprint())
                || !Objects.equals(row.getRecordRewardFingerprint(), row.getBenefitRewardFingerprint())) {
            throw mismatch(RewardQuarantineReason.REWARD_FINGERPRINT_MISMATCH);
        }
        if (!Objects.equals(row.getRecordRewardTargetId(), row.getBenefitRewardTargetId())
                || !Objects.equals(row.getRecordRewardQuantity(), row.getBenefitRewardQuantity())
                || !jsonEquals(row.getRecordRewardPayload(), row.getBenefitRewardPayload())) {
            throw mismatch(RewardQuarantineReason.BENEFIT_IDENTITY_MISMATCH);
        }
        if (row.getBenefitRewardQuantity() == null || row.getBenefitRewardPayload() == null) {
            throw mismatch(RewardQuarantineReason.BENEFIT_IDENTITY_MISMATCH);
        }
        return new RewardSnapshot(row.getBenefitRewardDefinitionId(), "FROZEN-" + row.getBenefitRewardDefinitionId(),
                row.getBenefitRewardType(), row.getBenefitRewardTargetId(), row.getBenefitRewardQuantity(),
                row.getBenefitRewardPayload(), row.getBenefitRewardFingerprint());
    }

    private boolean jsonEquals(String left, String right) {
        return Objects.equals(left, right);
    }

    private RewardIdentityMismatchException mismatch(RewardQuarantineReason reason) {
        return new RewardIdentityMismatchException(reason);
    }
}

package com.dongqh.luckyhub.service.lottery.impl;

import com.dongqh.luckyhub.domain.context.auth.LoginContext;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.dto.drawchance.DrawChanceReservationCommand;
import com.dongqh.luckyhub.enums.drawchance.DrawChanceReservationStatus;
import com.dongqh.luckyhub.domain.model.drawchance.DrawChanceReservationResult;
import com.dongqh.luckyhub.service.drawchance.DrawChanceService;
import com.dongqh.luckyhub.domain.dto.lottery.DrawCommand;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawOrder;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawRecord;
import com.dongqh.luckyhub.enums.lottery.DrawOrderStatus;
import com.dongqh.luckyhub.enums.lottery.LotteryErrorCode;
import com.dongqh.luckyhub.domain.lock.lottery.DrawLockService;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawOrderMapper;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawRecordMapper;
import com.dongqh.luckyhub.domain.model.lottery.DrawExecutionContext;
import com.dongqh.luckyhub.domain.model.lottery.DrawExecutionResult;
import com.dongqh.luckyhub.domain.model.lottery.NewDrawOrder;
import com.dongqh.luckyhub.service.lottery.DrawEligibilityService;
import com.dongqh.luckyhub.service.lottery.DrawOrderLifecycleService;
import com.dongqh.luckyhub.service.lottery.DrawTransactionService;
import com.dongqh.luckyhub.service.lottery.LotteryService;
import com.dongqh.luckyhub.domain.vo.lottery.DrawOrderView;
import com.dongqh.luckyhub.domain.vo.lottery.DrawResultView;
import com.dongqh.luckyhub.enums.reward.RewardType;
import org.springframework.stereotype.Service;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.LocalDateTime;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

@Service
public class LotteryServiceImpl implements LotteryService {
    private static final Logger log = LoggerFactory.getLogger(LotteryServiceImpl.class);
    private final LotteryDrawOrderMapper orderMapper;
    private final LotteryDrawRecordMapper recordMapper;
    private final DrawEligibilityService eligibilityService;
    private final DrawLockService lockService;
    private final DrawOrderLifecycleService lifecycleService;
    private final DrawTransactionService transactionService;
    private final DrawChanceService drawChanceService;

    public LotteryServiceImpl(LotteryDrawOrderMapper orderMapper,
                              LotteryDrawRecordMapper recordMapper,
                              DrawEligibilityService eligibilityService,
                              DrawLockService lockService,
                              DrawOrderLifecycleService lifecycleService,
                              DrawTransactionService transactionService,
                              DrawChanceService drawChanceService) {
        this.orderMapper = orderMapper;
        this.recordMapper = recordMapper;
        this.eligibilityService = eligibilityService;
        this.lockService = lockService;
        this.lifecycleService = lifecycleService;
        this.transactionService = transactionService;
        this.drawChanceService = drawChanceService;
    }

    @Override
    public DrawOrderView draw(DrawCommand command) {
        validate(command);
        long userId = LoginContext.require().userId();
        LotteryDrawOrder existing = orderMapper.selectByRequestId(command.requestId());
        if (existing != null) return resolveExisting(existing, command, userId, false);

        DrawEligibilityService.EligibilitySnapshot snapshot = eligibilityService.load(command.activityId());
        LocalDate drawDate = snapshot.snapshotTime().toLocalDate();
        LotteryDrawOrder[] createdOrder = new LotteryDrawOrder[1];
        try {
            LockedDraw locked = lockService.execute(command.activityId(), userId, () -> {
                LotteryDrawOrder second = orderMapper.selectByRequestId(command.requestId());
                if (second != null) {
                    return new LockedDraw(resolveExisting(second, command, userId, false), null, null);
                }
                DrawChanceReservationResult bonus = drawChanceService.reserve(
                        new DrawChanceReservationCommand(command.requestId(), command.activityId(),
                                userId, command.drawCount(), drawDate));
                requireActiveBonusReservation(bonus);
                LotteryDrawOrder processing;
                try {
                    processing = lifecycleService.createProcessing(new NewDrawOrder(
                            command.requestId(), userId, command.activityId(), command.drawCount(),
                            drawDate));
                } catch (RuntimeException error) {
                    drawChanceService.release(command.requestId());
                    throw error;
                }
                createdOrder[0] = processing;
                return new LockedDraw(null, processing, drawDate);
            });
            if (locked.existingView() != null) return locked.existingView();
            LotteryDrawOrder order = locked.order();
            DrawExecutionResult result = transactionService.execute(new DrawExecutionContext(
                    order.getId(), command.requestId(), userId, command.activityId(), command.drawCount(),
                    locked.drawDate(), snapshot.noWinWeight(), snapshot.prizes(),
                    snapshot.snapshotTime()));
            return fromExecution(order, result);
        } catch (BusinessException error) {
            compensateIfNeeded(createdOrder[0], snapshot.snapshotTime());
            throw error;
        } catch (RuntimeException error) {
            compensateIfNeeded(createdOrder[0], snapshot.snapshotTime());
            throw new BusinessException(LotteryErrorCode.DRAW_TRANSACTION_FAILED);
        }
    }

    private void requireActiveBonusReservation(DrawChanceReservationResult reservation) {
        if (reservation == null || reservation.status() != DrawChanceReservationStatus.RESERVED) {
            throw new BusinessException(LotteryErrorCode.DRAW_ORDER_FAILED);
        }
    }

    @Override
    public DrawOrderView getByRequestId(String requestId) {
        validateRequestId(requestId);
        long userId = LoginContext.require().userId();
        LotteryDrawOrder order = orderMapper.selectByRequestId(requestId);
        if (order == null) throw new BusinessException(LotteryErrorCode.DRAW_ORDER_FAILED);
        if (!Long.valueOf(userId).equals(order.getUserId())) {
            throw new BusinessException(LotteryErrorCode.DRAW_ACCESS_DENIED);
        }
        return toStoredView(order);
    }

    private DrawOrderView resolveExisting(LotteryDrawOrder order, DrawCommand command,
                                          long userId, boolean reading) {
        if (!Long.valueOf(userId).equals(order.getUserId())) {
            throw new BusinessException(reading ? LotteryErrorCode.DRAW_ACCESS_DENIED
                    : LotteryErrorCode.IDEMPOTENCY_CONFLICT);
        }
        if (!command.activityId().equals(order.getActivityId())
                || !command.drawCount().equals(order.getDrawCount())) {
            throw new BusinessException(LotteryErrorCode.IDEMPOTENCY_CONFLICT);
        }
        if (order.getStatus() == DrawOrderStatus.PROCESSING) {
            throw new BusinessException(LotteryErrorCode.DRAW_ORDER_PROCESSING);
        }
        if (order.getStatus() == DrawOrderStatus.FAILED) {
            throw new BusinessException(LotteryErrorCode.DRAW_ORDER_FAILED);
        }
        return toStoredView(order);
    }

    private DrawOrderView toStoredView(LotteryDrawOrder order) {
        List<DrawResultView> results = order.getStatus() == DrawOrderStatus.SUCCESS
                ? recordMapper.selectByOrderId(order.getId()).stream().map(this::toView).toList()
                : List.of();
        return new DrawOrderView(order.getId(), order.getRequestId(), order.getActivityId(),
                order.getDrawCount(), order.getDrawDate(), order.getStatus(), order.getFailReason(),
                order.getCompletedAt(), results);
    }

    private DrawOrderView fromExecution(LotteryDrawOrder order, DrawExecutionResult result) {
        List<DrawResultView> items = result.items().stream().map(item -> new DrawResultView(
                item.recordId(), item.sequenceNo(), item.resultType(), item.prizeId(), item.prizeName(),
                item.prizeType(), item.prizeImageUrl(), item.benefitId(),
                item.rewardSnapshot() != null && item.rewardSnapshot().rewardType() == RewardType.PRODUCT
                        ? item.rewardSnapshot().targetId() : null)).toList();
        return new DrawOrderView(order.getId(), order.getRequestId(), order.getActivityId(),
                order.getDrawCount(), order.getDrawDate(), result.status(), null,
                result.completedAt(), items);
    }

    private DrawResultView toView(LotteryDrawRecord record) {
        return new DrawResultView(record.getId(), record.getSequenceNo(), record.getResultType(),
                record.getPrizeId(), record.getPrizeName(), record.getPrizeType(),
                record.getPrizeImageUrl(), record.getBenefitId(), productItemId(record));
    }

    private Long productItemId(LotteryDrawRecord record) {
        return record.getRewardType() == RewardType.PRODUCT ? record.getRewardTargetId() : null;
    }

    private void compensateIfNeeded(LotteryDrawOrder order, LocalDateTime occurredAt) {
        if (order != null) {
            try {
                lifecycleService.markFailedAndRequestRelease(
                        order, "DRAW_TRANSACTION_FAILED", occurredAt);
            } catch (RuntimeException compensationError) {
                // The reservation timeout index remains the final reconciliation safety net.
                log.error("Failed to compensate lottery draw, requestId={}, orderId={}",
                        order.getRequestId(), order.getId(), compensationError);
            }
        }
    }

    private void validate(DrawCommand command) {
        if (command == null || command.activityId() == null || command.activityId() <= 0
                || command.drawCount() == null || (command.drawCount() != 1 && command.drawCount() != 10)) {
            throw new BusinessException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        validateRequestId(command.requestId());
    }

    private void validateRequestId(String requestId) {
        if (requestId == null || requestId.isBlank() || requestId.length() > 64) {
            throw new BusinessException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
        try {
            if (!UUID.fromString(requestId).toString().equalsIgnoreCase(requestId)) {
                throw new IllegalArgumentException();
            }
        } catch (IllegalArgumentException error) {
            throw new BusinessException(LotteryErrorCode.DRAW_PARAMETER_INVALID);
        }
    }

    private record LockedDraw(DrawOrderView existingView, LotteryDrawOrder order,
                              LocalDate drawDate) {
    }
}

