@Service public class CashOrderServiceImpl implements CashOrderService {
 private final MallOrderMapper mapper;private final CatalogService catalog;private final MembershipService memberships;private final CouponService coupons;private final ChannelInventoryService inventory;private final OrderPricingService pricing;private final ShippingAddressSnapshotService snapshots;private final ShippingOrderMapper shippingOrders;
 public CashOrderServiceImpl(MallOrderMapper m,CatalogService c,MembershipService ms,CouponService cs,ChannelInventoryService i,OrderPricingService p,ShippingAddressSnapshotService s,ShippingOrderMapper so){mapper=m;catalog=c;memberships=ms;coupons=cs;inventory=i;pricing=p;snapshots=s;shippingOrders=so;}
 @Transactional(isolation=Isolation.READ_COMMITTED) public CashOrderView create(long userId,CreateCashOrderCommand c){String no=c.orderNo().trim();MallOrder old=find(no);if(old!=null)return existing(old,userId,c);PurchasableSkuSnapshot sku=catalog.findPurchasableSku(c.skuId()).orElseThrow(()->error(OrderErrorCode.SKU_UNAVAILABLE));validateAddressShape(sku.productType(),c.addressId());ActiveMembershipBenefit member=memberships.activeBenefit(userId).orElse(null);OrderPriceQuote preliminary=pricing.quote(sku,c.quantity(),member,null);CouponLockSnapshot coupon=c.userCouponId()==null?null:coupons.lockForOrder(userId,c.userCouponId(),no,sku.productId(),preliminary.amountAfterMembershipCent(),member!=null);OrderPriceQuote quote=pricing.quote(sku,c.quantity(),member,coupon);MallOrder o=build(no,userId,c,sku,quote);try{mapper.insert(o);}catch(DuplicateKeyException e){return existing(find(no),userId,c);}if(c.addressId()!=null){ShippingAddressSnapshot snapshot=snapshots.create(userId,c.addressId(),ShippingSourceType.CASH_ORDER,String.valueOf(o.getId()));if(mapper.attachAddressSnapshot(o.getId(),snapshot.getId())!=1)throw shippingError(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);o.setAddressSnapshotId(snapshot.getId());}inventory.reserve(new ReserveChannelStockCommand(sku.skuId(),"MALL",c.quantity(),no));return view(o);}
 public CashOrderView get(long userId,String no){MallOrder o=find(no.trim());if(o==null)throw error(OrderErrorCode.ORDER_NOT_FOUND);if(!o.getUserId().equals(userId))throw error(OrderErrorCode.ACCESS_DENIED);return view(o);}
 public PageResponse<CashOrderView> page(long userId,CashOrderQuery q){Page<MallOrder> p=mapper.selectPage(new Page<>(q.getPage(),q.getSize()),new LambdaQueryWrapper<MallOrder>().eq(MallOrder::getUserId,userId).eq(q.getStatus()!=null,MallOrder::getStatus,q.getStatus()).orderByDesc(MallOrder::getCreatedAt).orderByDesc(MallOrder::getId));return new PageResponse<>(p.getRecords().stream().map(this::view).toList(),p.getTotal(),p.getCurrent(),p.getSize(),p.getPages());}
 @Transactional public CashOrderView cancel(long userId,String no,String reason){MallOrder o=mapper.lockByOrderNo(no.trim());if(o==null)throw error(OrderErrorCode.ORDER_NOT_FOUND);if(!o.getUserId().equals(userId))throw error(OrderErrorCode.ACCESS_DENIED);return cancelLocked(o,reason);}
 @Transactional public int cancelExpired(int limit){int n=0;for(MallOrder o:mapper.findExpired(LocalDateTime.now(),limit)){MallOrder locked=mapper.lockByOrderNo(o.getOrderNo());if(locked!=null&&locked.getStatus()==CashOrderStatus.PENDING_PAYMENT){cancelLocked(locked,"支付超时");n++;}}return n;}
 private CashOrderView cancelLocked(MallOrder o,String reason){if(o.getStatus()==CashOrderStatus.CANCELLED)return view(o);if(o.getStatus()!=CashOrderStatus.PENDING_PAYMENT)throw error(OrderErrorCode.STATE_CONFLICT);if(mapper.cancel(o.getOrderNo(),reason)!=1)throw error(OrderErrorCode.STATE_CONFLICT);inventory.release(o.getOrderNo());if(o.getUserCouponId()!=null)coupons.releaseForOrder(o.getUserCouponId(),o.getOrderNo());return view(find(o.getOrderNo()));}
 private MallOrder build(String no,long user,CreateCashOrderCommand c,PurchasableSkuSnapshot s,OrderPriceQuote q){MallOrder o=new MallOrder();o.setOrderNo(no);o.setUserId(user);o.setSkuId(s.skuId());o.setQuantity(c.quantity());o.setProductCode(s.productCode());o.setProductName(s.productName());o.setSkuCode(s.skuCode());o.setSkuName(s.skuName());o.setProductType(s.productType());o.setImageUrl(s.imageUrl());o.setUnitPriceCent(s.cashPriceCent());o.setOriginalAmountCent(q.originalAmountCent());o.setMembershipLevel(q.membershipLevel());o.setMembershipDiscountBasisPoints(q.membershipDiscountBasisPoints());o.setMembershipDiscountCent(q.membershipDiscountCent());o.setAmountAfterMembershipCent(q.amountAfterMembershipCent());o.setUserCouponId(q.userCouponId());o.setCouponTemplateId(q.couponTemplateId());o.setCouponName(q.couponName());o.setCouponDiscountCent(q.couponDiscountCent());o.setPayableAmountCent(q.payableAmountCent());o.setStatus(CashOrderStatus.PENDING_PAYMENT);o.setPaymentDeadline(LocalDateTime.now().plusMinutes(30).truncatedTo(ChronoUnit.MILLIS));return o;}
 private CashOrderView existing(MallOrder o,long user,CreateCashOrderCommand c){if(o==null||!o.getUserId().equals(user)||!o.getSkuId().equals(c.skuId())||!o.getQuantity().equals(c.quantity())||!Objects.equals(o.getUserCouponId(),c.userCouponId())||!sameAddress(o,c.addressId()))throw error(OrderErrorCode.IDEMPOTENCY_CONFLICT);return view(o);}
 private MallOrder find(String no){return mapper.selectOne(new LambdaQueryWrapper<MallOrder>().eq(MallOrder::getOrderNo,no));}
 private CashOrderView view(MallOrder o){ShippingOrder so=o.getShippingOrderId()==null?null:shippingOrders.selectById(o.getShippingOrderId());return new CashOrderView(o.getId(),o.getOrderNo(),o.getUserId(),o.getSkuId(),o.getQuantity(),o.getProductCode(),o.getProductName(),o.getSkuCode(),o.getSkuName(),o.getProductType(),o.getImageUrl(),o.getUnitPriceCent(),o.getOriginalAmountCent(),o.getMembershipLevel(),o.getMembershipDiscountBasisPoints(),o.getMembershipDiscountCent(),o.getAmountAfterMembershipCent(),o.getUserCouponId(),o.getCouponTemplateId(),o.getCouponName(),o.getCouponDiscountCent(),o.getPayableAmountCent(),o.getStatus(),o.getPaymentDeadline(),o.getPaidAt(),o.getCancelledAt(),o.getCancelReason(),o.getCreatedAt(),o.getUpdatedAt(),snapshotView(o.getAddressSnapshotId()),o.getShippingOrderId(),so==null?null:so.getShippingNo(),so==null?null:so.getStatus());}
 private void validateAddressShape(ProductType type,Long addressId){if((type==ProductType.PHYSICAL)!=(addressId!=null))throw shippingError(ShippingErrorCode.SHIPPING_REQUEST_INVALID);}
 private boolean sameAddress(MallOrder o,Long addressId){if(o.getAddressSnapshotId()==null)return addressId==null;return addressId!=null&&Objects.equals(snapshots.require(o.getAddressSnapshotId()).getAddressId(),addressId);}
 private ShippingAddressSnapshotView snapshotView(Long id){if(id==null)return null;ShippingAddressSnapshot s=snapshots.require(id);return new ShippingAddressSnapshotView(s.getId(),s.getSnapshotNo(),s.getReceiverMasked(),s.getPhoneMasked(),s.getRegionMasked());}
 private BusinessException error(OrderErrorCode e){return new BusinessException(e);}
 private BusinessException shippingError(ShippingErrorCode e){return new BusinessException(e);}
}

package com.dongqh.luckyhub.service.payment.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.service.coupon.CouponService;
import com.dongqh.luckyhub.domain.channel.inventory.service.ChannelInventoryService;
import com.dongqh.luckyhub.domain.po.order.MallOrder;
import com.dongqh.luckyhub.enums.order.CashOrderStatus;
import com.dongqh.luckyhub.mapper.order.MallOrderMapper;
import com.dongqh.luckyhub.domain.dto.payment.CreatePaymentCommand;
import com.dongqh.luckyhub.domain.dto.payment.PaymentCallbackCommand;
import com.dongqh.luckyhub.domain.po.payment.PaymentOrder;
import com.dongqh.luckyhub.enums.payment.PaymentErrorCode;
import com.dongqh.luckyhub.enums.payment.PaymentResult;
import com.dongqh.luckyhub.enums.payment.PaymentStatus;
import com.dongqh.luckyhub.mapper.payment.PaymentOrderMapper;
import com.dongqh.luckyhub.service.payment.PaymentService;
import com.dongqh.luckyhub.domain.vo.payment.PaymentView;
import com.dongqh.luckyhub.enums.catalog.ProductType;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.enums.shipping.ShippingSourceType;
import com.dongqh.luckyhub.domain.model.shipping.CreateShippingOrderCommand;
import com.dongqh.luckyhub.service.shipping.ShippingOrderService;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.HexFormat;
import java.util.Objects;

@Service
public class PaymentServiceImpl implements PaymentService {

    private static final String SIMULATION_SECRET = "local-simulation-only";

    private final PaymentOrderMapper paymentMapper;
    private final MallOrderMapper orderMapper;
    private final ChannelInventoryService inventory;
    private final CouponService coupons;
    private final ShippingOrderService shippingOrders;

    public PaymentServiceImpl(PaymentOrderMapper paymentMapper, MallOrderMapper orderMapper,
                              ChannelInventoryService inventory, CouponService coupons,
                              ShippingOrderService shippingOrders) {
        this.paymentMapper = paymentMapper;
        this.orderMapper = orderMapper;
        this.inventory = inventory;
        this.coupons = coupons;
        this.shippingOrders = shippingOrders;
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public PaymentView create(long userId, CreatePaymentCommand command) {
        String paymentNo = command.paymentNo().trim();
        String orderNo = command.orderNo().trim();
        PaymentOrder existing = find(paymentNo);
        if (existing != null) {
            return existing(existing, userId, orderNo);
        }

        MallOrder order = orderMapper.lockByOrderNo(orderNo);
        if (order == null || !Objects.equals(order.getUserId(), userId)
                || order.getStatus() != CashOrderStatus.PENDING_PAYMENT
                || !order.getPaymentDeadline().isAfter(LocalDateTime.now())) {
            throw error(PaymentErrorCode.ORDER_NOT_PAYABLE);
        }
        PaymentOrder payment = new PaymentOrder();
        payment.setPaymentNo(paymentNo);
        payment.setOrderNo(orderNo);
        payment.setUserId(userId);
        payment.setAmountCent(order.getPayableAmountCent());
        payment.setStatus(PaymentStatus.PENDING);
        try {
            paymentMapper.insert(payment);
        } catch (DuplicateKeyException exception) {
            return existing(find(paymentNo), userId, orderNo);
        }
        return view(payment);
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public PaymentView callback(PaymentCallbackCommand command) {
        String paymentNo = command.paymentNo().trim();
        PaymentOrder payment = paymentMapper.lockByPaymentNo(paymentNo);
        if (payment == null) {
            throw error(PaymentErrorCode.PAYMENT_NOT_FOUND);
        }
        verifySignature(payment, command);
        if (payment.getStatus() == PaymentStatus.SUCCESS) {
            if (command.result() != PaymentResult.SUCCESS) {
                throw error(PaymentErrorCode.PAYMENT_STATE_CONFLICT);
            }
            return view(payment);
        }
        if (payment.getStatus() == PaymentStatus.FAILED) {
            if (command.result() != PaymentResult.FAILURE) {
                throw error(PaymentErrorCode.PAYMENT_STATE_CONFLICT);
            }
            return view(payment);
        }

        if (command.result() == PaymentResult.PROCESSING) {
            payment.setCallbackResult(PaymentResult.PROCESSING);
            paymentMapper.updateById(payment);
            return view(payment);
        }
        if (command.result() == PaymentResult.FAILURE) {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setCallbackResult(PaymentResult.FAILURE);
            payment.setFailureReason(command.failureReason());
            paymentMapper.updateById(payment);
            return view(payment);
        }

        MallOrder order = orderMapper.lockByOrderNo(payment.getOrderNo());
        if (order == null || order.getStatus() != CashOrderStatus.PENDING_PAYMENT
                || !Objects.equals(order.getUserId(), payment.getUserId())) {
            throw error(PaymentErrorCode.ORDER_NOT_PAYABLE);
        }
        if (!Objects.equals(order.getPayableAmountCent(), payment.getAmountCent())) {
            throw error(PaymentErrorCode.AMOUNT_MISMATCH);
        }
        inventory.confirm(order.getOrderNo());
        if (order.getUserCouponId() != null) {
            coupons.useForOrder(order.getUserCouponId(), order.getOrderNo());
        }
        if (orderMapper.markPaid(order.getOrderNo()) != 1) {
            throw error(PaymentErrorCode.ORDER_NOT_PAYABLE);
        }
        payment.setStatus(PaymentStatus.SUCCESS);
        payment.setCallbackResult(PaymentResult.SUCCESS);
        payment.setFailureReason(null);
        payment.setPaidAt(LocalDateTime.now().truncatedTo(ChronoUnit.MILLIS));
        paymentMapper.updateById(payment);
        if (order.getProductType() == ProductType.PHYSICAL) {
            if (order.getAddressSnapshotId() == null) {
                throw new BusinessException(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
            }
            var shipping = shippingOrders.create(new CreateShippingOrderCommand(
                    ShippingSourceType.CASH_ORDER, String.valueOf(order.getId()), order.getUserId(),
                    order.getAddressSnapshotId(), order.getSkuCode(), order.getProductName(),
                    order.getImageUrl(), order.getQuantity(), null));
            if (orderMapper.attachShippingOrder(order.getId(), shipping.id()) != 1) {
                throw new BusinessException(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
            }
        }
        return view(payment);
    }

    @Override
    public String signForSimulation(String paymentNo, PaymentResult result, long amountCent) {
        String payload = paymentNo.trim() + "|" + result.name() + "|" + amountCent + "|" + SIMULATION_SECRET;
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(payload.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("SHA-256 unavailable", exception);
        }
    }

    @Override
    public PaymentView simulate(String paymentNo, PaymentResult result, String failureReason) {
        PaymentOrder payment = find(paymentNo.trim());
        if (payment == null) {
            throw error(PaymentErrorCode.PAYMENT_NOT_FOUND);
        }
        String signature = signForSimulation(payment.getPaymentNo(), result, payment.getAmountCent());
        return callback(new PaymentCallbackCommand(payment.getPaymentNo(), result, failureReason, signature));
    }

    @Override
    public PaymentView simulateForUser(long userId, String paymentNo) {
        PaymentOrder payment = find(paymentNo == null ? "" : paymentNo.trim());
        if (payment == null || !Objects.equals(payment.getUserId(), userId)) {
            throw error(PaymentErrorCode.PAYMENT_NOT_FOUND);
        }
        return simulate(payment.getPaymentNo(), PaymentResult.SUCCESS, null);
    }

    private void verifySignature(PaymentOrder payment, PaymentCallbackCommand command) {
        byte[] expected = signForSimulation(payment.getPaymentNo(), command.result(), payment.getAmountCent())
                .getBytes(StandardCharsets.UTF_8);
        byte[] actual = command.signature().getBytes(StandardCharsets.UTF_8);
        if (!MessageDigest.isEqual(expected, actual)) {
            throw error(PaymentErrorCode.SIGNATURE_INVALID);
        }
    }

    private PaymentView existing(PaymentOrder payment, long userId, String orderNo) {
        if (payment == null || !Objects.equals(payment.getUserId(), userId)
                || !Objects.equals(payment.getOrderNo(), orderNo)) {
            throw error(PaymentErrorCode.PAYMENT_DUPLICATE);
        }
        return view(payment);
    }

    private PaymentOrder find(String paymentNo) {
        return paymentMapper.selectOne(new LambdaQueryWrapper<PaymentOrder>()
                .eq(PaymentOrder::getPaymentNo, paymentNo));
    }

    private PaymentView view(PaymentOrder payment) {
        return new PaymentView(payment.getId(), payment.getPaymentNo(), payment.getOrderNo(),
                payment.getUserId(), payment.getAmountCent(), payment.getStatus(),
                payment.getCallbackResult(), payment.getFailureReason(), payment.getPaidAt(),
                payment.getCreatedAt(), payment.getUpdatedAt());
    }

    private BusinessException error(PaymentErrorCode errorCode) {
        return new BusinessException(errorCode);
    }
}

package com.dongqh.luckyhub.service.payment;

import com.dongqh.luckyhub.domain.dto.payment.CreatePaymentCommand;
import com.dongqh.luckyhub.domain.dto.payment.PaymentCallbackCommand;
import com.dongqh.luckyhub.enums.payment.PaymentResult;
import com.dongqh.luckyhub.domain.vo.payment.PaymentView;

public interface PaymentService {
    PaymentView create(long userId, CreatePaymentCommand command);

    PaymentView callback(PaymentCallbackCommand command);

    String signForSimulation(String paymentNo, PaymentResult result, long amountCent);

    PaymentView simulate(String paymentNo, PaymentResult result, String failureReason);

    PaymentView simulateForUser(long userId, String paymentNo);
}

package com.dongqh.luckyhub.service.points.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.dto.points.AdminPointsAdjustmentCommand;
import com.dongqh.luckyhub.domain.dto.points.PointsMutationCommand;
import com.dongqh.luckyhub.domain.dto.points.PointsReversalCommand;
import com.dongqh.luckyhub.domain.po.points.PointsAccount;
import com.dongqh.luckyhub.domain.po.points.PointsLedger;
import com.dongqh.luckyhub.enums.points.PointsBusinessType;
import com.dongqh.luckyhub.enums.points.PointsDirection;
import com.dongqh.luckyhub.enums.points.PointsErrorCode;
import com.dongqh.luckyhub.mapper.points.PointsAccountMapper;
import com.dongqh.luckyhub.mapper.points.PointsLedgerMapper;
import com.dongqh.luckyhub.service.points.PointsAccountService;
import com.dongqh.luckyhub.domain.vo.points.PointsAccountView;
import com.dongqh.luckyhub.domain.vo.points.PointsLedgerView;
import com.dongqh.luckyhub.domain.po.rbac.SysUser;
import com.dongqh.luckyhub.mapper.rbac.SysUserMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.interceptor.TransactionAspectSupport;

import java.util.EnumSet;
import java.util.Objects;
import java.util.Set;

@Service
public class PointsAccountServiceImpl implements PointsAccountService {

    private static final int ENABLED = 1;
    private static final int MAX_BUSINESS_ID_LENGTH = 100;
    private static final int MAX_REMARK_LENGTH = 500;
    private static final Set<PointsBusinessType> CREDIT_TYPES = EnumSet.of(
            PointsBusinessType.LOTTERY_REWARD,
            PointsBusinessType.ORDER_REWARD,
            PointsBusinessType.MEMBERSHIP_BONUS
    );

    private final SysUserMapper userMapper;
    private final PointsAccountMapper accountMapper;
    private final PointsLedgerMapper ledgerMapper;

    public PointsAccountServiceImpl(
            SysUserMapper userMapper,
            PointsAccountMapper accountMapper,
            PointsLedgerMapper ledgerMapper
    ) {
        this.userMapper = userMapper;
        this.accountMapper = accountMapper;
        this.ledgerMapper = ledgerMapper;
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public PointsLedgerView credit(PointsMutationCommand command) {
        ValidMutation mutation = validateMutation(command, CREDIT_TYPES);
        return mutate(mutation, PointsDirection.CREDIT);
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public PointsLedgerView debit(PointsMutationCommand command) {
        ValidMutation mutation = validateMutation(command, Set.of(PointsBusinessType.REDEMPTION));
        return mutate(mutation, PointsDirection.DEBIT);
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public PointsLedgerView reverseDebit(PointsReversalCommand command) {
        ValidReversal reversal = validateReversal(command);
        requireEnabledUser(reversal.userId());
        accountMapper.ensureAccount(reversal.userId());

        PointsLedger original = findLedger(reversal.originalBusinessType(), reversal.originalBusinessId());
        if (original == null) {
            throw error(PointsErrorCode.POINTS_LEDGER_NOT_FOUND);
        }
        if (!Objects.equals(original.getUserId(), reversal.userId())
                || original.getDirection() != PointsDirection.DEBIT
                || original.getBusinessType() != PointsBusinessType.REDEMPTION) {
            throw error(PointsErrorCode.POINTS_REVERSAL_CONFLICT);
        }

        PointsLedger existingByBusiness = findLedger(
                PointsBusinessType.REVERSAL, reversal.reversalBusinessId());
        if (existingByBusiness != null) {
            validateReversalLedger(existingByBusiness, original, reversal);
            return view(existingByBusiness);
        }
        PointsLedger existingForOriginal = findReversal(original.getId());
        if (existingForOriginal != null) {
            validateReversalLedger(existingForOriginal, original, reversal);
            return view(existingForOriginal);
        }

        if (accountMapper.creditIfNoOverflow(reversal.userId(), original.getAmount()) != 1) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        PointsAccount account = requireAccount(reversal.userId());
        PointsLedger ledger = new PointsLedger();
        ledger.setUserId(reversal.userId());
        ledger.setBusinessType(PointsBusinessType.REVERSAL);
        ledger.setBusinessId(reversal.reversalBusinessId());
        ledger.setDirection(PointsDirection.CREDIT);
        ledger.setAmount(original.getAmount());
        ledger.setBalanceAfter(account.getBalance());
        ledger.setReversalOfLedgerId(original.getId());
        ledger.setRemark(reversal.remark());

        if (ledgerMapper.claim(ledger) == 1) {
            return view(requireLedger(PointsBusinessType.REVERSAL, reversal.reversalBusinessId()));
        }

        PointsLedger winner = findLedger(PointsBusinessType.REVERSAL, reversal.reversalBusinessId());
        if (winner == null) {
            winner = findReversal(original.getId());
        }
        validateReversalLedger(winner, original, reversal);
        markRollbackOnly();
        return view(winner);
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public PointsLedgerView adjust(AdminPointsAdjustmentCommand command) {
        if (command == null || command.delta() == null
                || command.delta() == 0L || command.delta() == Long.MIN_VALUE) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        PointsDirection direction = command.delta() > 0
                ? PointsDirection.CREDIT : PointsDirection.DEBIT;
        long amount;
        try {
            amount = direction == PointsDirection.CREDIT
                    ? command.delta() : Math.negateExact(command.delta());
        } catch (ArithmeticException exception) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        ValidMutation mutation = validateMutation(new PointsMutationCommand(
                        command.userId(), PointsBusinessType.MANUAL_ADJUSTMENT,
                        command.businessId(), amount, command.reason()),
                Set.of(PointsBusinessType.MANUAL_ADJUSTMENT));
        return mutate(mutation, direction);
    }

    @Override
    public PointsAccountView get(long userId) {
        requireEnabledUser(userId);
        PointsAccount account = findAccount(userId);
        if (account == null) {
            return new PointsAccountView(userId, 0L, null);
        }
        return accountView(account);
    }

    private PointsLedgerView mutate(ValidMutation mutation, PointsDirection direction) {
        requireEnabledUser(mutation.userId());
        accountMapper.ensureAccount(mutation.userId());
        PointsLedger existing = findLedger(mutation.businessType(), mutation.businessId());
        if (existing != null) {
            validateLedger(existing, mutation, direction);
            return view(existing);
        }

        int updated = direction == PointsDirection.CREDIT
                ? accountMapper.creditIfNoOverflow(mutation.userId(), mutation.amount())
                : accountMapper.debitIfSufficient(mutation.userId(), mutation.amount());
        if (updated != 1) {
            throw error(direction == PointsDirection.CREDIT
                    ? PointsErrorCode.POINTS_AMOUNT_INVALID
                    : PointsErrorCode.POINTS_INSUFFICIENT);
        }

        PointsAccount account = requireAccount(mutation.userId());
        PointsLedger ledger = new PointsLedger();
        ledger.setUserId(mutation.userId());
        ledger.setBusinessType(mutation.businessType());
        ledger.setBusinessId(mutation.businessId());
        ledger.setDirection(direction);
        ledger.setAmount(mutation.amount());
        ledger.setBalanceAfter(account.getBalance());
        ledger.setRemark(mutation.remark());

        if (ledgerMapper.claim(ledger) == 1) {
            return view(requireLedger(mutation.businessType(), mutation.businessId()));
        }

        PointsLedger winner = requireLedger(mutation.businessType(), mutation.businessId());
        validateLedger(winner, mutation, direction);
        markRollbackOnly();
        return view(winner);
    }

    private ValidMutation validateMutation(
            PointsMutationCommand command,
            Set<PointsBusinessType> allowedTypes
    ) {
        if (command == null || command.userId() == null || command.userId() <= 0
                || command.businessType() == null || !allowedTypes.contains(command.businessType())
                || command.amount() == null || command.amount() <= 0) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        return new ValidMutation(
                command.userId(), command.businessType(),
                normalizeRequired(command.businessId(), MAX_BUSINESS_ID_LENGTH),
                command.amount(), normalizeOptional(command.remark(), MAX_REMARK_LENGTH)
        );
    }

    private ValidReversal validateReversal(PointsReversalCommand command) {
        if (command == null || command.userId() == null || command.userId() <= 0
                || command.originalBusinessType() != PointsBusinessType.REDEMPTION) {
            throw error(PointsErrorCode.POINTS_REVERSAL_CONFLICT);
        }
        return new ValidReversal(
                command.userId(), command.originalBusinessType(),
                normalizeRequired(command.originalBusinessId(), MAX_BUSINESS_ID_LENGTH),
                normalizeRequired(command.reversalBusinessId(), MAX_BUSINESS_ID_LENGTH),
                normalizeOptional(command.remark(), MAX_REMARK_LENGTH)
        );
    }

    private void requireEnabledUser(long userId) {
        SysUser user = userMapper.selectById(userId);
        if (user == null || !Integer.valueOf(ENABLED).equals(user.getStatus())) {
            throw error(PointsErrorCode.POINTS_USER_UNAVAILABLE);
        }
    }

    private PointsAccount findAccount(long userId) {
        return accountMapper.selectOne(new LambdaQueryWrapper<PointsAccount>()
                .eq(PointsAccount::getUserId, userId));
    }

    private PointsAccount requireAccount(long userId) {
        PointsAccount account = findAccount(userId);
        if (account == null) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        return account;
    }

    private PointsLedger findLedger(PointsBusinessType businessType, String businessId) {
        return ledgerMapper.selectOne(new LambdaQueryWrapper<PointsLedger>()
                .eq(PointsLedger::getBusinessType, businessType)
                .eq(PointsLedger::getBusinessId, businessId));
    }

    private PointsLedger requireLedger(PointsBusinessType businessType, String businessId) {
        PointsLedger ledger = findLedger(businessType, businessId);
        if (ledger == null) {
            throw error(PointsErrorCode.POINTS_IDEMPOTENCY_CONFLICT);
        }
        return ledger;
    }

    private PointsLedger findReversal(long originalLedgerId) {
        return ledgerMapper.selectOne(new LambdaQueryWrapper<PointsLedger>()
                .eq(PointsLedger::getReversalOfLedgerId, originalLedgerId));
    }

    private void validateLedger(
            PointsLedger ledger,
            ValidMutation mutation,
            PointsDirection direction
    ) {
        if (!Objects.equals(ledger.getUserId(), mutation.userId())
                || ledger.getBusinessType() != mutation.businessType()
                || !Objects.equals(ledger.getBusinessId(), mutation.businessId())
                || ledger.getDirection() != direction
                || !Objects.equals(ledger.getAmount(), mutation.amount())
                || ledger.getReversalOfLedgerId() != null) {
            throw error(PointsErrorCode.POINTS_IDEMPOTENCY_CONFLICT);
        }
    }

    private void validateReversalLedger(
            PointsLedger ledger,
            PointsLedger original,
            ValidReversal reversal
    ) {
        if (ledger == null
                || !Objects.equals(ledger.getUserId(), reversal.userId())
                || ledger.getBusinessType() != PointsBusinessType.REVERSAL
                || !Objects.equals(ledger.getBusinessId(), reversal.reversalBusinessId())
                || ledger.getDirection() != PointsDirection.CREDIT
                || !Objects.equals(ledger.getAmount(), original.getAmount())
                || !Objects.equals(ledger.getReversalOfLedgerId(), original.getId())) {
            throw error(PointsErrorCode.POINTS_REVERSAL_CONFLICT);
        }
    }

    private String normalizeRequired(String value, int maxLength) {
        if (value == null) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        String normalized = value.trim();
        if (normalized.isEmpty() || normalized.length() > maxLength) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        return normalized;
    }

    private String normalizeOptional(String value, int maxLength) {
        if (value == null) {
            return null;
        }
        String normalized = value.trim();
        if (normalized.length() > maxLength) {
            throw error(PointsErrorCode.POINTS_AMOUNT_INVALID);
        }
        return normalized.isEmpty() ? null : normalized;
    }

    private PointsAccountView accountView(PointsAccount account) {
        return new PointsAccountView(
                account.getUserId(), account.getBalance(), account.getUpdatedAt());
    }

    private PointsLedgerView view(PointsLedger ledger) {
        return new PointsLedgerView(
                ledger.getId(), ledger.getUserId(), ledger.getBusinessType(),
                ledger.getBusinessId(), ledger.getDirection(), ledger.getAmount(),
                ledger.getBalanceAfter(), ledger.getReversalOfLedgerId(), ledger.getRemark(),
                ledger.getCreatedAt()
        );
    }

    private void markRollbackOnly() {
        TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
    }

    private BusinessException error(PointsErrorCode errorCode) {
        return new BusinessException(errorCode);
    }

    private record ValidMutation(
            long userId,
            PointsBusinessType businessType,
            String businessId,
            long amount,
            String remark
    ) {
    }

    private record ValidReversal(
            long userId,
            PointsBusinessType originalBusinessType,
            String originalBusinessId,
            String reversalBusinessId,
            String remark
    ) {
    }
}

