package com.dongqh.luckyhub.service.shipping.impl;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.config.shipping.ShippingProperties;
import com.dongqh.luckyhub.domain.crypto.shipping.LogisticsCallbackSigner;
import com.dongqh.luckyhub.domain.dto.shipping.LogisticsCallbackCommand;
import com.dongqh.luckyhub.domain.po.shipping.ShippingCallbackReceipt;
import com.dongqh.luckyhub.domain.po.shipping.ShippingOrder;
import com.dongqh.luckyhub.domain.po.shipping.ShippingTrackingEvent;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.enums.shipping.ShippingSourceType;
import com.dongqh.luckyhub.enums.shipping.ShippingStatus;
import com.dongqh.luckyhub.enums.shipping.TrackingEventType;
import com.dongqh.luckyhub.mapper.shipping.ShippingCallbackReceiptMapper;
import com.dongqh.luckyhub.mapper.shipping.ShippingOrderMapper;
import com.dongqh.luckyhub.mapper.shipping.ShippingTrackingEventMapper;
import com.dongqh.luckyhub.service.shipping.LogisticsCallbackService;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.time.format.DateTimeFormatter;
import java.util.HexFormat;
import java.util.Objects;
import java.util.regex.Pattern;

@Service
public class LogisticsCallbackServiceImpl implements LogisticsCallbackService {
    private static final DateTimeFormatter EVENT_TIME_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME;
    private static final Pattern SIGNED_IDENTIFIER =
            Pattern.compile("[A-Za-z0-9][A-Za-z0-9._:-]{0,99}");

    private final LogisticsCallbackSigner signer;
    private final ShippingProperties properties;
    private final ShippingCallbackReceiptMapper receipts;
    private final ShippingOrderMapper orders;
    private final ShippingTrackingEventMapper events;
    private final JdbcTemplate jdbc;
    private final TransactionTemplate transactions;

    public LogisticsCallbackServiceImpl(
            LogisticsCallbackSigner signer,
            ShippingProperties properties,
            ShippingCallbackReceiptMapper receipts,
            ShippingOrderMapper orders,
            ShippingTrackingEventMapper events,
            JdbcTemplate jdbc,
            PlatformTransactionManager transactionManager
    ) {
        this.signer = signer;
        this.properties = properties;
        this.receipts = receipts;
        this.orders = orders;
        this.events = events;
        this.jdbc = jdbc;
        this.transactions = new TransactionTemplate(transactionManager);
        this.transactions.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
    }

    @Override
    public void handle(LogisticsCallbackCommand command) {
        validate(command);
        if (!withinWindow(command.timestampEpochSecond()) || !signer.verify(command)) {
            throw error(ShippingErrorCode.CALLBACK_SIGNATURE_INVALID);
        }
        ShippingErrorCode failure = transactions.execute(status -> process(command));
        if (failure != null) throw error(failure);
    }

    private ShippingErrorCode process(LogisticsCallbackCommand command) {
        LocalDateTime receivedAt = LocalDateTime.now().truncatedTo(ChronoUnit.MILLIS);
        String nonceDigest = digest(command.nonce());
        String signatureDigest = digest(command.signature());
        ShippingCallbackReceipt receipt = receipt(command, nonceDigest, signatureDigest, receivedAt);
        try {
            receipts.insert(receipt);
        } catch (DuplicateKeyException duplicate) {
            ShippingCallbackReceipt existing = receipts.selectByCallbackId(command.callbackId());
            if (existing != null && sameReceipt(existing, command, nonceDigest, signatureDigest)) {
                return "REJECTED".equals(existing.getStatus())
                        ? rejectedCode(existing.getErrorCode()) : null;
            }
            return ShippingErrorCode.CALLBACK_REPLAYED;
        }

        ShippingOrder order = orders.lockByWaybillNo(command.waybillNo());
        if (order == null) {
            reject(receipt, ShippingErrorCode.SHIPPING_NOT_FOUND, receivedAt);
            return ShippingErrorCode.SHIPPING_NOT_FOUND;
        }
        if (!callbackAllowed(order.getStatus())) {
            reject(receipt, ShippingErrorCode.SHIPPING_STATE_CONFLICT, receivedAt);
            return ShippingErrorCode.SHIPPING_STATE_CONFLICT;
        }

        insertEvent(order, command, receivedAt);
        advance(order, command.eventType(), receivedAt);
        receipt.setStatus("PROCESSED");
        receipt.setProcessedAt(receivedAt);
        receipts.updateById(receipt);
        return null;
    }

    private void insertEvent(ShippingOrder order, LogisticsCallbackCommand command, LocalDateTime receivedAt) {
        ShippingTrackingEvent event = new ShippingTrackingEvent();
        event.setShippingOrderId(order.getId());
        event.setProviderEventId(providerEventId(command));
        event.setWaybillNo(command.waybillNo());
        event.setEventType(command.eventType());
        event.setLocationSummary(normalizeOptional(command.locationSummary()));
        event.setDescription(normalizeOptional(command.description()));
        event.setEventTime(databaseTime(command.eventTime()));
        event.setReceivedAt(receivedAt);
        try {
            events.insert(event);
        } catch (DuplicateKeyException ignored) {
            // The provider event identity is deterministic; a second callback is idempotent.
        }
    }

    private void advance(ShippingOrder order, TrackingEventType eventType, LocalDateTime now) {
        ShippingStatus target = targetStatus(eventType);
        if (rank(target) <= rank(order.getStatus())) return;
        LocalDateTime deliveredAt = target == ShippingStatus.DELIVERED ? now : order.getDeliveredAt();
        int changed = jdbc.update("""
                UPDATE shipping_order
                SET status=?, delivered_at=?, version=version+1, updated_at=CURRENT_TIMESTAMP(3)
                WHERE id=? AND version=? AND status=?
                """, target.name(), deliveredAt, order.getId(), order.getVersion(), order.getStatus().name());
        if (changed != 1) throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        if (target == ShippingStatus.DELIVERED
                && order.getSourceType() == ShippingSourceType.LOTTERY_BENEFIT) {
            jdbc.update("""
                    UPDATE user_benefit SET status='DELIVERED', updated_at=CURRENT_TIMESTAMP(3)
                    WHERE id=? AND status IN ('CLAIMED','FULFILLING','SHIPPED')
                    """, Long.valueOf(order.getSourceId()));
        }
    }

    private ShippingCallbackReceipt receipt(
            LogisticsCallbackCommand command, String nonceDigest,
            String signatureDigest, LocalDateTime receivedAt
    ) {
        ShippingCallbackReceipt receipt = new ShippingCallbackReceipt();
        receipt.setCallbackId(command.callbackId());
        receipt.setNonceDigest(nonceDigest);
        receipt.setSignatureDigest(signatureDigest);
        receipt.setWaybillNo(command.waybillNo());
        receipt.setEventType(command.eventType());
        receipt.setEventTime(databaseTime(command.eventTime()));
        receipt.setStatus("RECEIVED");
        receipt.setReceivedAt(receivedAt);
        return receipt;
    }

    private void reject(ShippingCallbackReceipt receipt, ShippingErrorCode code, LocalDateTime processedAt) {
        receipt.setStatus("REJECTED");
        receipt.setErrorCode(Integer.toString(code.code()));
        receipt.setErrorMessage(code.message());
        receipt.setProcessedAt(processedAt);
        receipts.updateById(receipt);
    }

    private boolean sameReceipt(
            ShippingCallbackReceipt existing, LogisticsCallbackCommand command,
            String nonceDigest, String signatureDigest
    ) {
        return Objects.equals(existing.getNonceDigest(), nonceDigest)
                && Objects.equals(existing.getSignatureDigest(), signatureDigest)
                && Objects.equals(existing.getWaybillNo(), command.waybillNo())
                && existing.getEventType() == command.eventType()
                && Objects.equals(existing.getEventTime(), databaseTime(command.eventTime()));
    }

    private boolean withinWindow(long timestamp) {
        long now = Instant.now().getEpochSecond();
        long window = properties.callbackWindow().getSeconds();
        return timestamp >= now - window && timestamp <= now + window;
    }

    private void validate(LogisticsCallbackCommand command) {
        if (command == null
                || invalidSignedIdentifier(command.callbackId())
                || invalidSignedIdentifier(command.nonce())
                || invalidSignedIdentifier(command.waybillNo())
                || command.eventType() == null
                || command.eventTime() == null
                || invalidOptional(command.locationSummary(), 200)
                || invalidOptional(command.description(), 500)
                || invalid(command.signature(), 100)) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
    }

    private boolean invalid(String value, int max) {
        return value == null || value.isBlank() || value.length() > max;
    }

    private boolean invalidSignedIdentifier(String value) {
        return value == null || !SIGNED_IDENTIFIER.matcher(value).matches();
    }

    private boolean invalidOptional(String value, int max) {
        return value != null && value.length() > max;
    }

    private String normalizeOptional(String value) {
        if (value == null || value.isBlank()) return null;
        return value.trim();
    }

    private boolean callbackAllowed(ShippingStatus status) {
        return status == ShippingStatus.SHIPPED
                || status == ShippingStatus.IN_TRANSIT
                || status == ShippingStatus.DELIVERED;
    }

    private ShippingStatus targetStatus(TrackingEventType type) {
        return switch (type) {
            case PICKED_UP -> ShippingStatus.SHIPPED;
            case IN_TRANSIT, OUT_FOR_DELIVERY -> ShippingStatus.IN_TRANSIT;
            case DELIVERED -> ShippingStatus.DELIVERED;
        };
    }

    private int rank(ShippingStatus status) {
        return switch (status) {
            case READY -> 0;
            case FULFILLING -> 1;
            case SHIPPED -> 2;
            case IN_TRANSIT -> 3;
            case DELIVERED -> 4;
            case FAILED, TERMINATED -> -1;
        };
    }

    private String providerEventId(LogisticsCallbackCommand command) {
        return digest(command.waybillNo() + '\n' + command.eventType().name() + '\n'
                + EVENT_TIME_FORMAT.format(command.eventTime()));
    }

    private ShippingErrorCode rejectedCode(String storedCode) {
        for (ShippingErrorCode candidate : ShippingErrorCode.values()) {
            if (Integer.toString(candidate.code()).equals(storedCode)) {
                return candidate;
            }
        }
        return ShippingErrorCode.CALLBACK_REPLAYED;
    }

    private LocalDateTime databaseTime(LocalDateTime value) {
        return value.truncatedTo(ChronoUnit.MILLIS);
    }

    private String digest(String value) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("SHA-256不可用", exception);
        }
    }

    private BusinessException error(ShippingErrorCode code) {
        return new BusinessException(code);
    }
}

package com.dongqh.luckyhub.service.shipping.impl;

import com.dongqh.luckyhub.mapper.benefit.UserBenefitMapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.service.shipping.PhysicalClaimExpiryService;
import com.dongqh.luckyhub.service.shipping.PhysicalClaimExpiryWorker;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;

@Service
public class PhysicalClaimExpiryServiceImpl implements PhysicalClaimExpiryService {
    private static final Logger log = LoggerFactory.getLogger(PhysicalClaimExpiryServiceImpl.class);
    private static final int SCAN_PAGE_SIZE = 50;
    private final UserBenefitMapper benefits;
    private final PhysicalClaimExpiryWorker worker;
    private long scanAfterId;

    public PhysicalClaimExpiryServiceImpl(UserBenefitMapper benefits,
                                          PhysicalClaimExpiryWorker worker) {
        this.benefits = benefits;
        this.worker = worker;
    }

    @Override
    public synchronized int expireDue(int limit, LocalDateTime now) {
        if (limit < 1 || limit > 1000 || now == null) throw new IllegalArgumentException("过期批次参数不合法");
        int expired = 0;
        int candidates = 0;
        int candidateBudget = candidateBudget(limit);
        while (expired < limit && candidates < candidateBudget) {
            int queryLimit = Math.min(SCAN_PAGE_SIZE, candidateBudget - candidates);
            List<Long> ids = benefits.selectDueClaimIdsAfter(now, scanAfterId, queryLimit);
            if (ids.isEmpty()) {
                scanAfterId = 0;
                break;
            }
            int processedThisPage = 0;
            for (Long id : ids) {
                scanAfterId = id;
                candidates++;
                processedThisPage++;
                try {
                    if (worker.expireOne(id, now)) expired++;
                } catch (RuntimeException exception) {
                    logCandidateFailure(id, exception);
                }
                if (expired == limit || candidates == candidateBudget) break;
            }
            if (processedThisPage == ids.size() && ids.size() < queryLimit) {
                scanAfterId = 0;
                break;
            }
        }
        return expired;
    }

    private int candidateBudget(int limit) {
        return (int) Math.min(1000L, Math.max(SCAN_PAGE_SIZE, (long) limit * 4));
    }

    private void logCandidateFailure(long benefitId, RuntimeException exception) {
        String errorType = exception.getClass().getSimpleName().replaceAll("[^A-Za-z0-9_$]", "_");
        if (errorType.isEmpty()) errorType = "RuntimeException";
        if (errorType.length() > 64) errorType = errorType.substring(0, 64);
        String errorCode = exception instanceof BusinessException businessException
                ? Integer.toString(businessException.getErrorCode().code())
                : "-";
        log.warn("Physical claim expiry candidate failed, benefitId={}, errorType={}, errorCode={}",
                benefitId, errorType, errorCode);
    }
}

package com.dongqh.luckyhub.service.shipping.impl;

import com.dongqh.luckyhub.domain.po.activity.MarketingActivityPrize;
import com.dongqh.luckyhub.mapper.activity.MarketingActivityPrizeMapper;
import com.dongqh.luckyhub.domain.po.benefit.UserBenefit;
import com.dongqh.luckyhub.enums.benefit.BenefitStatus;
import com.dongqh.luckyhub.mapper.benefit.UserBenefitMapper;
import com.dongqh.luckyhub.service.inventory.ActivityPrizeInventoryService;
import com.dongqh.luckyhub.domain.po.lottery.LotteryDrawRecord;
import com.dongqh.luckyhub.mapper.lottery.LotteryDrawRecordMapper;
import com.dongqh.luckyhub.enums.prize.PrizeType;
import com.dongqh.luckyhub.enums.reward.RewardType;
import com.dongqh.luckyhub.domain.model.reward.ProductRewardPayload;
import com.dongqh.luckyhub.service.shipping.PhysicalClaimExpiryWorker;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.core.JacksonException;
import tools.jackson.databind.ObjectMapper;

import java.time.LocalDateTime;
import java.util.Objects;

@Service
public class PhysicalClaimExpiryWorkerImpl implements PhysicalClaimExpiryWorker {
    private final UserBenefitMapper benefits;
    private final LotteryDrawRecordMapper drawRecords;
    private final MarketingActivityPrizeMapper activityPrizes;
    private final ActivityPrizeInventoryService inventory;
    private final ObjectMapper json;

    public PhysicalClaimExpiryWorkerImpl(UserBenefitMapper benefits,
                                         LotteryDrawRecordMapper drawRecords,
                                         MarketingActivityPrizeMapper activityPrizes,
                                         ActivityPrizeInventoryService inventory,
                                         ObjectMapper json) {
        this.benefits = benefits;
        this.drawRecords = drawRecords;
        this.activityPrizes = activityPrizes;
        this.inventory = inventory;
        this.json = json;
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRES_NEW, isolation = Isolation.READ_COMMITTED)
    public boolean expireOne(long benefitId, LocalDateTime now) {
        UserBenefit benefit = benefits.selectByIdForUpdate(benefitId);
        if (benefit == null || benefit.getStatus() != BenefitStatus.CLAIM_PENDING
                || benefit.getClaimDeadline() == null || benefit.getClaimDeadline().isAfter(now)) {
            return false;
        }
        LotteryDrawRecord draw = drawRecords.selectById(benefit.getDrawRecordId());
        ProductRewardPayload product = requireFrozenIdentity(benefit, draw);
        MarketingActivityPrize activityPrize = activityPrizes.lockByActivityAndPrize(
                draw.getActivityId(), draw.getPrizeId());
        if (activityPrize == null) throw new IllegalStateException("活动奖品关系不存在");
        inventory.returnExpiredClaim(activityPrize.getId(), product.itemId(), "CLAIM-EXPIRE-" + benefitId);
        if (benefits.markClaimExpired(benefitId, now) != 1) {
            throw new IllegalStateException("权益过期状态转换失败");
        }
        return true;
    }

    private ProductRewardPayload requireFrozenIdentity(UserBenefit benefit, LotteryDrawRecord draw) {
        if (draw == null || benefit.getPrizeType() != PrizeType.PHYSICAL
                || benefit.getRewardType() != RewardType.PRODUCT
                || !Objects.equals(draw.getUserId(), benefit.getUserId())
                || !Objects.equals(draw.getPrizeId(), benefit.getPrizeId())
                || draw.getPrizeType() != benefit.getPrizeType()
                || !Objects.equals(draw.getRewardDefinitionId(), benefit.getRewardDefinitionId())
                || draw.getRewardType() != benefit.getRewardType()
                || !Objects.equals(draw.getRewardTargetId(), benefit.getRewardTargetId())
                || !Objects.equals(draw.getRewardQuantity(), benefit.getRewardQuantity())
                || !Objects.equals(draw.getRewardPayload(), benefit.getRewardPayload())
                || !Objects.equals(draw.getRewardFingerprint(), benefit.getRewardFingerprint())) {
            throw new IllegalStateException("冻结奖励身份不一致");
        }
        try {
            ProductRewardPayload product = json.readValue(benefit.getRewardPayload(), ProductRewardPayload.class);
            if (!Objects.equals(benefit.getRewardTargetId(), product.itemId())
                    || benefit.getRewardQuantity() != product.quantity()
                    || !Objects.equals(benefit.getQuantity(), product.quantity())) {
                throw new IllegalStateException("冻结商品奖励不一致");
            }
            return product;
        } catch (JacksonException | IllegalArgumentException exception) {
            throw new IllegalStateException("冻结商品奖励不可解析", exception);
        }
    }
}

