    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView claim(long userId, long benefitId, ClaimPhysicalBenefitCommand command) {
        String requestId = normalizeRequest(command);
        UserBenefit benefit = benefits.selectByIdForUpdate(benefitId);
        if (benefit == null || !Objects.equals(benefit.getUserId(), userId)) {
            throw error(ShippingErrorCode.CLAIM_NOT_ALLOWED);
        }
        ShippingOrder existing = shippingOrderMapper.lockBySource(
                ShippingSourceType.LOTTERY_BENEFIT, Long.toString(benefitId));
        if (existing != null) {
            validateExistingLifecycle(benefit, existing);
            ProductRewardPayload product = validateFrozenProduct(
                    benefit, ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
            requireDrawIdentity(benefit, ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
            return existing(existing, command.addressId(), requestId, benefit, product);
        }
        ProductRewardPayload product = validateFrozenProduct(benefit, ShippingErrorCode.CLAIM_NOT_ALLOWED);
        LotteryDrawRecord draw = requireDrawIdentity(benefit, ShippingErrorCode.CLAIM_NOT_ALLOWED);
        if (benefit.getStatus() != BenefitStatus.CLAIM_PENDING || benefit.getShippingOrderId() != null) {
            throw error(ShippingErrorCode.CLAIM_NOT_ALLOWED);
        }
        LocalDateTime now = LocalDateTime.now().truncatedTo(ChronoUnit.MILLIS);
        if (benefit.getClaimDeadline() == null || !now.isBefore(benefit.getClaimDeadline())) {
            throw error(ShippingErrorCode.CLAIM_EXPIRED);
        }

        String sourceId = Long.toString(benefitId);
        ShippingAddressSnapshot snapshot = snapshots.create(userId, command.addressId(),
                ShippingSourceType.LOTTERY_BENEFIT, sourceId);
        ShippingOrderView order = shippingOrders.create(new CreateShippingOrderCommand(
                ShippingSourceType.LOTTERY_BENEFIT, sourceId, userId, snapshot.getId(),
                product.itemId(), itemCode(product.itemId()), product.itemName(), product.itemImage(),
                product.quantity(), requestId));
        if (benefits.markClaimed(benefitId, order.id(), now) != 1) {
            throw error(ShippingErrorCode.CLAIM_NOT_ALLOWED);
        }
        return order;
    }

    private ShippingOrderView existing(ShippingOrder order, long addressId, String requestId,
                                       UserBenefit benefit, ProductRewardPayload product) {
        ShippingAddressSnapshot snapshot = snapshots.require(order.getAddressSnapshotId());
        if (!Objects.equals(order.getTargetUserId(), benefit.getUserId())
                || !Objects.equals(order.getClaimRequestId(), requestId)
                || !Objects.equals(snapshot.getAddressId(), addressId)
                || !Objects.equals(order.getSkuCode(), itemCode(product.itemId()))
                || !Objects.equals(order.getProductName(), product.itemName())
                || !Objects.equals(order.getQuantity(), product.quantity())) {
            throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
        return shippingOrders.getForUser(benefit.getUserId(), order.getShippingNo());
    }

    private void validateExistingLifecycle(UserBenefit benefit, ShippingOrder order) {
        if (!Objects.equals(benefit.getShippingOrderId(), order.getId())) {
            throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
        BenefitStatus status = benefit.getStatus();
        if (status != BenefitStatus.CLAIMED && status != BenefitStatus.FULFILLING
                && status != BenefitStatus.SHIPPED && status != BenefitStatus.DELIVERED
                && status != BenefitStatus.FULFILLMENT_FAILED
                && status != BenefitStatus.FULFILLMENT_TERMINATED) {
            throw error(ShippingErrorCode.CLAIM_NOT_ALLOWED);
        }
    }

    private ProductRewardPayload validateFrozenProduct(UserBenefit benefit, ShippingErrorCode invalidCode) {
        if (benefit.getPrizeType() != PrizeType.PHYSICAL || benefit.getRewardType() != RewardType.PRODUCT
                || benefit.getRewardTargetId() == null || benefit.getRewardQuantity() == null
                || benefit.getRewardPayload() == null) {
            throw error(invalidCode);
        }
        try {
            ProductRewardPayload product = json.readValue(benefit.getRewardPayload(), ProductRewardPayload.class);
            if (!Objects.equals(benefit.getRewardTargetId(), product.itemId())
                    || benefit.getRewardQuantity() != product.quantity()
                    || !Objects.equals(benefit.getQuantity(), product.quantity())) {
                throw error(invalidCode);
            }
            return product;
        } catch (JacksonException | IllegalArgumentException exception) {
            throw error(invalidCode);
        }
    }

    private LotteryDrawRecord requireDrawIdentity(UserBenefit benefit, ShippingErrorCode invalidCode) {
        LotteryDrawRecord draw = drawRecords.selectById(benefit.getDrawRecordId());
        if (draw == null || !Objects.equals(draw.getUserId(), benefit.getUserId())
                || !Objects.equals(draw.getPrizeId(), benefit.getPrizeId())
                || draw.getPrizeType() != benefit.getPrizeType()
                || !Objects.equals(draw.getRewardDefinitionId(), benefit.getRewardDefinitionId())
                || draw.getRewardType() != benefit.getRewardType()
                || !Objects.equals(draw.getRewardTargetId(), benefit.getRewardTargetId())
                || !Objects.equals(draw.getRewardQuantity(), benefit.getRewardQuantity())
                || !Objects.equals(draw.getRewardPayload(), benefit.getRewardPayload())
                || !Objects.equals(draw.getRewardFingerprint(), benefit.getRewardFingerprint())) {
            throw error(invalidCode);
        }
        return draw;
    }

    private String itemCode(long itemId) {
        return "HMALL-ITEM-" + itemId;
    }

    private String normalizeRequest(ClaimPhysicalBenefitCommand command) {
        if (command == null || command.addressId() == null || command.addressId() <= 0
                || command.requestId() == null) throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        String raw = command.requestId().trim();
        try {
            String normalized = UUID.fromString(raw).toString();
            if (!normalized.equalsIgnoreCase(raw)) throw new IllegalArgumentException();
            return normalized;
        } catch (IllegalArgumentException exception) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
    }

    private BusinessException error(ShippingErrorCode code) {
        return new BusinessException(code);
    }
}

package com.dongqh.luckyhub.service.shipping.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.crypto.shipping.AddressCipher;
import com.dongqh.luckyhub.domain.dto.shipping.CreateShippingAddressCommand;
import com.dongqh.luckyhub.domain.dto.shipping.UpdateShippingAddressCommand;
import com.dongqh.luckyhub.domain.po.shipping.UserShippingAddress;
import com.dongqh.luckyhub.enums.shipping.AddressStatus;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.mapper.shipping.UserShippingAddressMapper;
import com.dongqh.luckyhub.service.shipping.ShippingAddressService;
import com.dongqh.luckyhub.domain.support.shipping.AddressMasker;
import com.dongqh.luckyhub.domain.vo.shipping.ShippingAddressView;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;

@Service
public class ShippingAddressServiceImpl implements ShippingAddressService {

    private final UserShippingAddressMapper mapper;
    private final AddressCipher cipher;

    public ShippingAddressServiceImpl(UserShippingAddressMapper mapper, AddressCipher cipher) {
        this.mapper = mapper;
        this.cipher = cipher;
    }

    @Override
    @Transactional
    public ShippingAddressView create(long userId, CreateShippingAddressCommand command) {
        lockUser(userId);
        List<UserShippingAddress> active = mapper.lockActiveByUser(userId);
        boolean makeDefault = active.isEmpty() || command.defaultAddress();
        if (makeDefault && !active.isEmpty()) {
            clearDefaults(userId);
        }
        SensitiveAddress address = normalize(command.receiverName(), command.phone(), command.province(),
                command.city(), command.district(), command.detail());
        UserShippingAddress entity = new UserShippingAddress();
        entity.setUserId(userId);
        writeSensitive(entity, address);
        entity.setIsDefault(makeDefault ? 1 : 0);
        entity.setStatus(AddressStatus.ACTIVE);
        entity.setVersion(0);
        mapper.insert(entity);
        return view(mapper.selectById(entity.getId()));
    }

    @Override
    @Transactional(readOnly = true)
    public List<ShippingAddressView> list(long userId) {
        return mapper.selectList(new LambdaQueryWrapper<UserShippingAddress>()
                        .eq(UserShippingAddress::getUserId, userId)
                        .eq(UserShippingAddress::getStatus, AddressStatus.ACTIVE)
                        .orderByDesc(UserShippingAddress::getIsDefault)
                        .orderByDesc(UserShippingAddress::getId))
                .stream().map(this::view).toList();
    }

    @Override
    @Transactional
    public ShippingAddressView update(long userId, long addressId, UpdateShippingAddressCommand command) {
        lockUser(userId);
        UserShippingAddress entity = requireOwnedActive(userId, addressId);
        if (command.defaultAddress()) {
            clearDefaults(userId);
        }
        SensitiveAddress address = normalize(command.receiverName(), command.phone(), command.province(),
                command.city(), command.district(), command.detail());
        writeSensitive(entity, address);
        entity.setIsDefault(command.defaultAddress() ? 1 : 0);
        updateLocked(entity);
        return view(mapper.selectById(addressId));
    }

    @Override
    @Transactional
    public void delete(long userId, long addressId) {
        lockUser(userId);
        UserShippingAddress entity = requireOwnedActive(userId, addressId);
        entity.setStatus(AddressStatus.DELETED);
        entity.setIsDefault(0);
        entity.setDeletedAt(LocalDateTime.now());
        updateLocked(entity);
    }

    @Override
    @Transactional
    public ShippingAddressView makeDefault(long userId, long addressId) {
        lockUser(userId);
        UserShippingAddress entity = requireOwnedActive(userId, addressId);
        clearDefaults(userId);
        entity.setIsDefault(1);
        updateLocked(entity);
        return view(mapper.selectById(addressId));
    }

    @Override
    public UserShippingAddress requireOwnedActive(long userId, long addressId) {
        UserShippingAddress entity = mapper.selectById(addressId);
        if (entity == null || entity.getStatus() != AddressStatus.ACTIVE) {
            throw error(ShippingErrorCode.ADDRESS_NOT_FOUND);
        }
        if (!Long.valueOf(userId).equals(entity.getUserId())) {
            throw error(ShippingErrorCode.ADDRESS_ACCESS_DENIED);
        }
        return entity;
    }

    private void lockUser(long userId) {
        if (mapper.lockUserRow(userId) == null) {
            throw error(ShippingErrorCode.ADDRESS_INVALID);
        }
    }

    private void clearDefaults(long userId) {
        mapper.update(null, new LambdaUpdateWrapper<UserShippingAddress>()
                .eq(UserShippingAddress::getUserId, userId)
                .eq(UserShippingAddress::getStatus, AddressStatus.ACTIVE)
                .eq(UserShippingAddress::getIsDefault, 1)
                .set(UserShippingAddress::getIsDefault, 0));
    }

    private void updateLocked(UserShippingAddress entity) {
        int updated = mapper.update(entity, new LambdaUpdateWrapper<UserShippingAddress>()
                .eq(UserShippingAddress::getId, entity.getId())
                .eq(UserShippingAddress::getUserId, entity.getUserId())
                .eq(UserShippingAddress::getStatus, AddressStatus.ACTIVE));
        if (updated != 1) {
            throw error(ShippingErrorCode.ADDRESS_STATE_CONFLICT);
        }
    }

    private SensitiveAddress normalize(String receiver, String phone, String province,
                                       String city, String district, String detail) {
        return new SensitiveAddress(receiver.trim(), phone.trim(), province.trim(), city.trim(),
                district.trim(), detail.trim());
    }

    private void writeSensitive(UserShippingAddress entity, SensitiveAddress address) {
        entity.setReceiverCiphertext(cipher.encrypt(address.receiver()));
        entity.setPhoneCiphertext(cipher.encrypt(address.phone()));
        entity.setProvinceCiphertext(cipher.encrypt(address.province()));
        entity.setCityCiphertext(cipher.encrypt(address.city()));
        entity.setDistrictCiphertext(cipher.encrypt(address.district()));
        entity.setDetailCiphertext(cipher.encrypt(address.detail()));
        entity.setReceiverMasked(AddressMasker.maskReceiver(address.receiver()));
        entity.setPhoneMasked(AddressMasker.maskPhone(address.phone()));
        entity.setRegionMasked(AddressMasker.maskRegion(address.province(), address.city(), address.district()));
    }

    private ShippingAddressView view(UserShippingAddress entity) {
        return new ShippingAddressView(entity.getId(), entity.getReceiverMasked(), entity.getPhoneMasked(),
                entity.getRegionMasked(), entity.getIsDefault() == 1, entity.getStatus(),
                entity.getCreatedAt(), entity.getUpdatedAt());
    }

    private BusinessException error(ShippingErrorCode code) {
        return new BusinessException(code);
    }

    private record SensitiveAddress(String receiver, String phone, String province,
                                    String city, String district, String detail) {
    }
}

package com.dongqh.luckyhub.service.shipping.impl;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.hmall.integration.HmallAddressClient;
import com.dongqh.luckyhub.domain.hmall.integration.HmallAddressView;
import com.dongqh.luckyhub.domain.crypto.shipping.AddressCipher;
import com.dongqh.luckyhub.domain.po.shipping.ShippingAddressSnapshot;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.enums.shipping.ShippingSourceType;
import com.dongqh.luckyhub.mapper.shipping.ShippingAddressSnapshotMapper;
import com.dongqh.luckyhub.service.shipping.ShippingAddressSnapshotService;
import com.dongqh.luckyhub.domain.support.shipping.AddressMasker;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;

import java.util.Objects;
import java.util.UUID;

@Service
public class ShippingAddressSnapshotServiceImpl implements ShippingAddressSnapshotService {
    private final ShippingAddressSnapshotMapper mapper;
    private final HmallAddressClient addresses;
    private final AddressCipher cipher;

    public ShippingAddressSnapshotServiceImpl(
            ShippingAddressSnapshotMapper mapper,
            HmallAddressClient addresses,
            AddressCipher cipher
    ) {
        this.mapper = mapper;
        this.addresses = addresses;
        this.cipher = cipher;
    }

    @Override
    public ShippingAddressSnapshot create(
            long userId,
            long addressId,
            ShippingSourceType sourceType,
            String sourceId
    ) {
        HmallAddressView address = addresses.getAddress(addressId);
        if (address == null || !Objects.equals(address.id(), addressId)) {
            throw new BusinessException(ShippingErrorCode.ADDRESS_NOT_FOUND);
        }
        ShippingAddressSnapshot candidate = copy(userId, addressId, sourceType, sourceId, address);
        ShippingAddressSnapshot existing = mapper.selectBySource(sourceType, sourceId);
        if (existing != null) {
            return requireEqual(existing, candidate);
        }
        try {
            mapper.insert(candidate);
            return candidate;
        } catch (DuplicateKeyException exception) {
            ShippingAddressSnapshot winner = mapper.selectBySource(sourceType, sourceId);
            if (winner == null) {
                throw exception;
            }
            return requireEqual(winner, candidate);
        }
    }

    @Override
    public ShippingAddressSnapshot require(long snapshotId) {
        ShippingAddressSnapshot snapshot = mapper.selectById(snapshotId);
        if (snapshot == null) {
            throw new BusinessException(ShippingErrorCode.SHIPPING_NOT_FOUND);
        }
        return snapshot;
    }

    private ShippingAddressSnapshot copy(
            long userId,
            long addressId,
            ShippingSourceType sourceType,
            String sourceId,
            HmallAddressView address
    ) {
        ShippingAddressSnapshot snapshot = new ShippingAddressSnapshot();
        snapshot.setSnapshotNo("ADDRESS-" + UUID.randomUUID());
        snapshot.setUserId(userId);
        snapshot.setAddressId(addressId);
        snapshot.setSourceType(sourceType);
        snapshot.setSourceId(sourceId);
        snapshot.setReceiverCiphertext(cipher.encrypt(required(address.contact())));
        snapshot.setPhoneCiphertext(cipher.encrypt(required(address.mobile())));
        snapshot.setProvinceCiphertext(cipher.encrypt(required(address.province())));
        snapshot.setCityCiphertext(cipher.encrypt(required(address.city())));
        snapshot.setDistrictCiphertext(cipher.encrypt(required(address.town())));
        snapshot.setDetailCiphertext(cipher.encrypt(required(address.street())));
        snapshot.setReceiverMasked(AddressMasker.maskReceiver(address.contact()));
        snapshot.setPhoneMasked(AddressMasker.maskPhone(address.mobile()));
        snapshot.setRegionMasked(AddressMasker.maskRegion(address.province(), address.city(), address.town()));
        return snapshot;
    }

    private String required(String value) {
        if (value == null || value.isBlank()) {
            throw new BusinessException(ShippingErrorCode.ADDRESS_INVALID);
        }
        return value.trim();
    }

    private ShippingAddressSnapshot requireEqual(
            ShippingAddressSnapshot existing,
            ShippingAddressSnapshot candidate
    ) {
        if (!Objects.equals(existing.getUserId(), candidate.getUserId())
                || !Objects.equals(existing.getAddressId(), candidate.getAddressId())
                || existing.getSourceType() != candidate.getSourceType()
                || !Objects.equals(existing.getSourceId(), candidate.getSourceId())
                || !samePlaintext(existing.getReceiverCiphertext(), candidate.getReceiverCiphertext())
                || !samePlaintext(existing.getPhoneCiphertext(), candidate.getPhoneCiphertext())
                || !samePlaintext(existing.getProvinceCiphertext(), candidate.getProvinceCiphertext())
                || !samePlaintext(existing.getCityCiphertext(), candidate.getCityCiphertext())
                || !samePlaintext(existing.getDistrictCiphertext(), candidate.getDistrictCiphertext())
                || !samePlaintext(existing.getDetailCiphertext(), candidate.getDetailCiphertext())
                || !Objects.equals(existing.getReceiverMasked(), candidate.getReceiverMasked())
                || !Objects.equals(existing.getPhoneMasked(), candidate.getPhoneMasked())
                || !Objects.equals(existing.getRegionMasked(), candidate.getRegionMasked())) {
            throw new BusinessException(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
        return existing;
    }

    private boolean samePlaintext(String leftCiphertext, String rightCiphertext) {
        return Objects.equals(cipher.decrypt(leftCiphertext), cipher.decrypt(rightCiphertext));
    }
}

package com.dongqh.luckyhub.service.shipping.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.common.result.PageResponse;
import com.dongqh.luckyhub.enums.fulfillment.FulfillmentStatus;
import com.dongqh.luckyhub.service.fulfillment.FulfillmentTaskService;
import com.dongqh.luckyhub.domain.vo.fulfillment.FulfillmentTaskView;
import com.dongqh.luckyhub.domain.dto.shipping.ShippingOrderQuery;
import com.dongqh.luckyhub.domain.po.shipping.ShippingAddressSnapshot;
import com.dongqh.luckyhub.domain.po.shipping.ShippingOrder;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.enums.shipping.ShippingStatus;
import com.dongqh.luckyhub.mapper.shipping.ShippingAddressSnapshotMapper;
import com.dongqh.luckyhub.mapper.shipping.ShippingOrderMapper;
import com.dongqh.luckyhub.mapper.shipping.ShippingTrackingEventMapper;
import com.dongqh.luckyhub.service.shipping.ShippingAdminService;
import com.dongqh.luckyhub.service.shipping.ShippingOrderService;
import com.dongqh.luckyhub.service.shipping.ShippingProjectionWorker;
import com.dongqh.luckyhub.domain.vo.shipping.ShippingOrderView;
import com.dongqh.luckyhub.domain.vo.shipping.ShippingTrackingView;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Objects;
import java.util.regex.Pattern;

@Service
public class ShippingAdminServiceImpl implements ShippingAdminService {
    private static final Logger log = LoggerFactory.getLogger(ShippingAdminServiceImpl.class);
    private static final int MAX_SCAN = 100;
    private static final Pattern UNSAFE_NOTE = Pattern.compile("(?i)(?:"
            + "[\\p{Cc}\\p{Cf}\\{\\}\\[\\]]"
            + "|[\\w.+-]+@[\\w.-]+\\.[A-Za-z]{2,}"
            + "|(?<!\\d)1[3-9]\\d{9}(?!\\d)"
            + "|(?<!\\d)(?:\\d{17}[0-9Xx]|\\d{15})(?!\\d)"
            + "|(?<!\\d)0\\d{2,3}[- ]?\\d{7,8}(?!\\d)"
            + "|\\b(?:exception|payload|ciphertext|secret|authorization|provider\\s+response)\\b"
            + "|异常堆栈|原始响应|供应商响应|密文|明文|密钥|秘密|授权头|签名"
            + "|收件人|姓名|联系人|手机号|手机号码|电话号码|电话|座机|身份证|证件号|住址|详细地址"
            + "|(?:省|自治区|特别行政区).{0,30}(?:市|州).{0,30}(?:区|县).{0,50}(?:路|街|道|巷|弄|号|栋|单元|室)"
            + ")");
    private static final Pattern SAFE_NOTE = Pattern.compile("^(?:(?:"
            + "人工核验通过|已核对安全数据|已核对商品资料|确认可重试|可以重新发货"
            + "|用户申请终止|停止处理|重复任务|无需继续履约|隔离任务已核验|系统已恢复"
            + "|运维确认|安全原因|工单\\s*[：:#-]?\\s*[A-Za-z0-9_-]{1,32}"
            + ")[\\s，。；、,;]*)+$");

    private final ShippingOrderMapper orders;
    private final ShippingAddressSnapshotMapper snapshots;
    private final ShippingTrackingEventMapper trackingEvents;
    private final FulfillmentTaskService fulfillment;
    private final ShippingOrderService shippingOrders;
    private final ShippingProjectionWorker projectionWorker;

    public ShippingAdminServiceImpl(ShippingOrderMapper orders, ShippingAddressSnapshotMapper snapshots,
                                    FulfillmentTaskService fulfillment, ShippingOrderService shippingOrders) {
        this(orders, snapshots, null, fulfillment, shippingOrders, null);
    }

    public ShippingAdminServiceImpl(ShippingOrderMapper orders, ShippingAddressSnapshotMapper snapshots,
                                    FulfillmentTaskService fulfillment, ShippingOrderService shippingOrders,
                                    ShippingProjectionWorker projectionWorker) {
        this(orders, snapshots, null, fulfillment, shippingOrders, projectionWorker);
    }

    public ShippingAdminServiceImpl(ShippingOrderMapper orders, ShippingAddressSnapshotMapper snapshots,
                                    ShippingTrackingEventMapper trackingEvents,
                                    FulfillmentTaskService fulfillment, ShippingOrderService shippingOrders) {
        this(orders, snapshots, trackingEvents, fulfillment, shippingOrders, null);
    }

    @Autowired
    public ShippingAdminServiceImpl(ShippingOrderMapper orders, ShippingAddressSnapshotMapper snapshots,
                                    ShippingTrackingEventMapper trackingEvents,
                                    FulfillmentTaskService fulfillment, ShippingOrderService shippingOrders,
                                    ShippingProjectionWorker projectionWorker) {
        this.orders = orders;
        this.snapshots = snapshots;
        this.trackingEvents = trackingEvents;
        this.fulfillment = fulfillment;
        this.shippingOrders = shippingOrders;
        this.projectionWorker = projectionWorker;
    }

    @Override
    public PageResponse<ShippingOrderView> page(ShippingOrderQuery query) {
        Page<ShippingOrder> page = orders.selectPage(new Page<>(query.getPage(), query.getSize()),
                new LambdaQueryWrapper<ShippingOrder>()
                        .eq(query.getStatus() != null, ShippingOrder::getStatus, query.getStatus())
                        .eq(query.getSourceType() != null, ShippingOrder::getSourceType, query.getSourceType())
                        .eq(hasText(query.getSourceId()), ShippingOrder::getSourceId, trimmed(query.getSourceId()))
                        .eq(query.getTargetUserId() != null, ShippingOrder::getTargetUserId, query.getTargetUserId())
                        .eq(hasText(query.getWaybillNo()), ShippingOrder::getWaybillNo, trimmed(query.getWaybillNo()))
                        .orderByDesc(ShippingOrder::getCreatedAt).orderByDesc(ShippingOrder::getId));
        return new PageResponse<>(page.getRecords().stream().map(this::view).toList(), page.getTotal(),
                page.getCurrent(), page.getSize(), page.getPages());
    }

    @Override
    public ShippingOrderView get(String shippingNo) {
        ShippingOrder order = orders.selectByShippingNo(requiredNo(shippingNo));
        if (order == null) throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
        return view(order);
    }

    @Override
    public List<ShippingTrackingView.TrackingEvent> tracking(String shippingNo) {
        ShippingOrder order = orders.selectByShippingNo(requiredNo(shippingNo));
        if (order == null) throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
        return Objects.requireNonNull(trackingEvents,
                        "ShippingTrackingEventMapper is required for tracking queries")
                .selectByShippingOrderId(order.getId()).stream()
                .map(event -> new ShippingTrackingView.TrackingEvent(
                        event.getEventType(), event.getEventTime(),
                        null, safeTrackingDescription(event.getEventType())))
                .toList();
    }

    private String safeTrackingDescription(com.dongqh.luckyhub.enums.shipping.TrackingEventType eventType) {
        return switch (eventType) {
            case PICKED_UP -> "包裹已揽收";
            case IN_TRANSIT -> "包裹运输中";
            case OUT_FOR_DELIVERY -> "包裹派送中";
            case DELIVERED -> "包裹已签收";
        };
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView retry(String shippingNo, long operatorId, String note) {
        ShippingOrder order = lock(shippingNo);
        if (order.getStatus() != ShippingStatus.FAILED || order.getFulfillmentNo() == null) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        String validatedNote = safeNote(note);
        FulfillmentTaskView task = fulfillment.get(order.getFulfillmentNo());
        if (task.status() != FulfillmentStatus.QUARANTINED) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        fulfillment.retryQuarantined(order.getFulfillmentNo(), positiveOperator(operatorId), validatedNote);
        shippingOrders.projectFulfillmentState(order.getFulfillmentNo());
        return get(order.getShippingNo());
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView terminate(String shippingNo, long operatorId, String note) {
        ShippingOrder order = lock(shippingNo);
        if (order.getFulfillmentNo() == null || order.getStatus() == ShippingStatus.SHIPPED
                || order.getStatus() == ShippingStatus.IN_TRANSIT || order.getStatus() == ShippingStatus.DELIVERED
                || order.getStatus() == ShippingStatus.TERMINATED) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        String validatedNote = safeNote(note);
        FulfillmentTaskView task = fulfillment.get(order.getFulfillmentNo());
        if (task.status() == FulfillmentStatus.PROCESSING || task.status() == FulfillmentStatus.SUCCEEDED
                || task.status() == FulfillmentStatus.TERMINATED) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        fulfillment.terminate(order.getFulfillmentNo(), positiveOperator(operatorId), validatedNote);
        shippingOrders.projectFulfillmentState(order.getFulfillmentNo());
        return get(order.getShippingNo());
    }

    @Override
    public int projectPending() {
        List<Long> candidates = orders.selectProjectionCandidateIds(MAX_SCAN);
        int projected = 0;
        for (Long id : candidates) {
            try {
                if (projectionWorker.projectOne(id)) projected++;
            } catch (RuntimeException ignored) {
                log.warn("单条物流状态投影失败 shippingOrderId={}", id);
            }
        }
        return projected;
    }

    private ShippingOrder lock(String shippingNo) {
        ShippingOrder order = orders.lockByShippingNo(requiredNo(shippingNo));
        if (order == null) throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
        return order;
    }

    private ShippingOrderView view(ShippingOrder order) {
        ShippingAddressSnapshot snapshot = snapshots.selectById(order.getAddressSnapshotId());
        return new ShippingOrderView(order.getId(), order.getShippingNo(), order.getSourceType(), order.getSourceId(),
                order.getTargetUserId(), order.getAddressSnapshotId(), order.getSkuCode(), order.getProductName(),
                order.getImageUrl(), order.getQuantity(), order.getFulfillmentNo(), order.getCarrierCode(),
                order.getCarrierName(), order.getWaybillNo(), order.getStatus(), order.getLastErrorCode(),
                order.getLastErrorMessage(), order.getShippedAt(), order.getDeliveredAt(), order.getFailedAt(),
                order.getTerminatedAt(), order.getCreatedAt(), order.getUpdatedAt(),
                snapshot == null ? null : snapshot.getReceiverMasked(),
                snapshot == null ? null : snapshot.getPhoneMasked(),
                snapshot == null ? null : snapshot.getRegionMasked());
    }

    private String requiredNo(String value) {
        String normalized = trimmed(value);
        if (normalized == null || normalized.isBlank() || normalized.length() > 64) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        return normalized;
    }

    private long positiveOperator(long value) {
        if (value <= 0) throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        return value;
    }

    private String safeNote(String note) {
        String normalized = trimmed(note);
        if (normalized == null || normalized.isBlank()) return null;
        if (UNSAFE_NOTE.matcher(normalized).find() || !SAFE_NOTE.matcher(normalized).matches()) {
            throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        }
        return normalized.substring(0, Math.min(500, normalized.length()));
    }

    private boolean hasText(String value) { return value != null && !value.isBlank(); }
    private String trimmed(String value) { return value == null ? null : value.trim(); }
    private BusinessException error(ShippingErrorCode code) { return new BusinessException(code); }
}

package com.dongqh.luckyhub.service.shipping.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.dto.fulfillment.CreateFulfillmentTaskCommand;
import com.dongqh.luckyhub.enums.fulfillment.FulfillmentStatus;
import com.dongqh.luckyhub.enums.fulfillment.FulfillmentType;
import com.dongqh.luckyhub.domain.model.fulfillment.LogisticsFulfillmentPayload;
import com.dongqh.luckyhub.service.fulfillment.FulfillmentTaskService;
import com.dongqh.luckyhub.domain.vo.fulfillment.FulfillmentTaskView;
import com.dongqh.luckyhub.domain.po.shipping.ShippingAddressSnapshot;
import com.dongqh.luckyhub.domain.po.shipping.ShippingOrder;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.enums.shipping.ShippingSourceType;
import com.dongqh.luckyhub.enums.shipping.ShippingStatus;
import com.dongqh.luckyhub.mapper.shipping.ShippingOrderMapper;
import com.dongqh.luckyhub.domain.model.shipping.CreateShippingOrderCommand;
import com.dongqh.luckyhub.service.shipping.ShippingAddressSnapshotService;
import com.dongqh.luckyhub.service.shipping.ShippingOrderService;
import com.dongqh.luckyhub.domain.vo.shipping.ShippingOrderView;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

@Service
public class ShippingOrderServiceImpl implements ShippingOrderService {
    private static final int MAX_ATTEMPTS = 5;
    private final ShippingOrderMapper mapper;
    private final ShippingAddressSnapshotService snapshots;
    private final FulfillmentTaskService fulfillmentTasks;
    private final JdbcTemplate jdbc;

    public ShippingOrderServiceImpl(
            ShippingOrderMapper mapper,
            ShippingAddressSnapshotService snapshots,
            FulfillmentTaskService fulfillmentTasks,
            JdbcTemplate jdbc
    ) {
        this.mapper = mapper;
        this.snapshots = snapshots;
        this.fulfillmentTasks = fulfillmentTasks;
        this.jdbc = jdbc;
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public ShippingOrderView create(CreateShippingOrderCommand command) {
        ShippingAddressSnapshot snapshot = snapshots.require(command.addressSnapshotId());
        validateSnapshot(command, snapshot);
        ShippingOrder existing = findBySource(command.sourceType(), command.sourceId());
        if (existing != null) return view(requireEqual(existing, command));

        ShippingOrder order = candidate(command);
        try {
            mapper.insert(order);
        } catch (DuplicateKeyException exception) {
            ShippingOrder winner = findBySource(command.sourceType(), command.sourceId());
            if (winner == null && command.claimRequestId() != null) {
                winner = mapper.selectByClaimRequestId(command.claimRequestId());
            }
            if (winner == null) throw exception;
            return view(requireEqual(winner, command));
        }

        order.setFulfillmentNo("LOGISTICS-" + order.getId());
        order.setStatus(ShippingStatus.FULFILLING);
        if (jdbc.update("""
                UPDATE shipping_order
                SET fulfillment_no=?, status='FULFILLING', version=version+1,
                    updated_at=CURRENT_TIMESTAMP(3)
                WHERE id=? AND fulfillment_no IS NULL AND status='READY'
                """, order.getFulfillmentNo(), order.getId()) != 1) {
            throw error(ShippingErrorCode.SHIPPING_STATE_CONFLICT);
        }
        fulfillmentTasks.create(new CreateFulfillmentTaskCommand(
                order.getFulfillmentNo(), command.sourceType().name(), command.sourceId(),
                FulfillmentType.LOGISTICS, command.targetUserId(),
                new LogisticsFulfillmentPayload(order.getId(), command.skuCode(), command.quantity(),
                        snapshot.getReceiverMasked(), snapshot.getPhoneMasked(), snapshot.getRegionMasked()),
                MAX_ATTEMPTS));
        return view(mapper.selectById(order.getId()));
    }

    @Override
    public ShippingOrderView getForUser(long userId, String shippingNo) {
        ShippingOrder order = mapper.selectOne(new LambdaQueryWrapper<ShippingOrder>()
                .eq(ShippingOrder::getShippingNo, required(shippingNo)));
        if (order == null || !Objects.equals(order.getTargetUserId(), userId)) {
            throw error(ShippingErrorCode.SHIPPING_NOT_FOUND);
        }
        return view(order);
    }

    @Override
    @Transactional(isolation = Isolation.READ_COMMITTED)
    public void projectFulfillmentState(String fulfillmentNo) {
        ShippingOrder order = mapper.selectOne(new LambdaQueryWrapper<ShippingOrder>()
                .eq(ShippingOrder::getFulfillmentNo, required(fulfillmentNo)));
        if (order == null) return;
        if (order.getStatus() == ShippingStatus.DELIVERED
                || order.getStatus() == ShippingStatus.TERMINATED) return;
        ShippingStatus observedStatus = order.getStatus();
        Integer observedVersion = order.getVersion();
        FulfillmentTaskView task = fulfillmentTasks.get(fulfillmentNo);
        LocalDateTime now = LocalDateTime.now().truncatedTo(ChronoUnit.MILLIS);
        if (task.status() == FulfillmentStatus.SUCCEEDED) {
            if (order.getStatus() == ShippingStatus.SHIPPED
                    || order.getStatus() == ShippingStatus.IN_TRANSIT
                    || order.getStatus() == ShippingStatus.DELIVERED) return;
            order.setCarrierCode("SIMULATOR");
            order.setCarrierName("模拟物流");
            order.setWaybillNo(bounded(task.externalReference(), 100));
            order.setStatus(ShippingStatus.SHIPPED);
            order.setShippedAt(order.getShippedAt() == null ? now : order.getShippedAt());
            order.setLastErrorCode(null);
            order.setLastErrorMessage(null);
            order.setFailedAt(null);
        } else if (task.status() == FulfillmentStatus.QUARANTINED) {
            if (order.getStatus() != ShippingStatus.FULFILLING) return;
            order.setStatus(ShippingStatus.FAILED);
            order.setLastErrorCode(defaulted(task.lastErrorCode(), "FULFILLMENT_QUARANTINED", 64));
            order.setLastErrorMessage(defaulted(task.lastErrorMessage(), "物流履约已安全隔离", 500));
            order.setFailedAt(now);
        } else if (task.status() == FulfillmentStatus.TERMINATED) {
            if (order.getStatus() == ShippingStatus.SHIPPED
                    || order.getStatus() == ShippingStatus.IN_TRANSIT
                    || order.getStatus() == ShippingStatus.DELIVERED) return;
            order.setStatus(ShippingStatus.TERMINATED);
            order.setLastErrorCode(defaulted(task.lastErrorCode(), "FULFILLMENT_TERMINATED", 64));
            order.setLastErrorMessage(defaulted(task.lastErrorMessage(), "物流履约已安全终止", 500));
            order.setTerminatedAt(now);
        } else if (order.getStatus() == ShippingStatus.FAILED) {
            order.setStatus(ShippingStatus.FULFILLING);
            order.setLastErrorCode(null);
            order.setLastErrorMessage(null);
            order.setFailedAt(null);
        } else {
            return;
        }
        if (jdbc.update("""
                UPDATE shipping_order
                SET carrier_code=?, carrier_name=?, waybill_no=?, status=?,
                    last_error_code=?, last_error_message=?, shipped_at=?, failed_at=?,
                    terminated_at=?, version=version+1, updated_at=CURRENT_TIMESTAMP(3)
                WHERE id=? AND version=? AND status=?
                  AND status NOT IN ('DELIVERED','TERMINATED')
                """, order.getCarrierCode(), order.getCarrierName(), order.getWaybillNo(),
                order.getStatus().name(), order.getLastErrorCode(), order.getLastErrorMessage(),
                order.getShippedAt(), order.getFailedAt(), order.getTerminatedAt(), order.getId(),
                observedVersion, observedStatus.name()) != 1) {
            // Another state transition won the race. Its newer projection is authoritative;
            // a later scheduler pass can converge any still-applicable fulfillment state.
            return;
        }
        projectLotterySource(order);
    }

    private ShippingOrder candidate(CreateShippingOrderCommand command) {
        ShippingOrder order = new ShippingOrder();
        order.setShippingNo("SHIPPING-" + UUID.randomUUID());
        order.setSourceType(command.sourceType());
        order.setSourceId(command.sourceId());
        order.setTargetUserId(command.targetUserId());
        order.setAddressSnapshotId(command.addressSnapshotId());
        order.setHmallItemId(command.hmallItemId());
        order.setSkuCode(command.skuCode());
        order.setProductName(command.productName());
        order.setImageUrl(command.imageUrl());
        order.setQuantity(command.quantity());
        order.setClaimRequestId(command.claimRequestId());
        order.setStatus(ShippingStatus.READY);
        order.setVersion(0);
        return order;
    }

    private void validateSnapshot(CreateShippingOrderCommand command, ShippingAddressSnapshot snapshot) {
        if (!Objects.equals(snapshot.getUserId(), command.targetUserId())
                || snapshot.getSourceType() != command.sourceType()
                || !Objects.equals(snapshot.getSourceId(), command.sourceId())) {
            throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
    }

    private ShippingOrder requireEqual(ShippingOrder order, CreateShippingOrderCommand command) {
        if (order.getSourceType() != command.sourceType()
                || !Objects.equals(order.getSourceId(), command.sourceId())
                || !Objects.equals(order.getTargetUserId(), command.targetUserId())
                || !Objects.equals(order.getAddressSnapshotId(), command.addressSnapshotId())
                || !Objects.equals(order.getHmallItemId(), command.hmallItemId())
                || !Objects.equals(order.getSkuCode(), command.skuCode())
                || !Objects.equals(order.getProductName(), command.productName())
                || !Objects.equals(order.getImageUrl(), command.imageUrl())
                || !Objects.equals(order.getQuantity(), command.quantity())
                || !Objects.equals(order.getClaimRequestId(), command.claimRequestId())) {
            throw error(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT);
        }
        return order;
    }

    private ShippingOrder findBySource(ShippingSourceType type, String sourceId) {
        return mapper.selectOne(new LambdaQueryWrapper<ShippingOrder>()
                .eq(ShippingOrder::getSourceType, type)
                .eq(ShippingOrder::getSourceId, sourceId));
    }

    private void projectLotterySource(ShippingOrder order) {
        if (order.getSourceType() != ShippingSourceType.LOTTERY_BENEFIT) return;
        if (order.getStatus() == ShippingStatus.FAILED) {
            jdbc.update("UPDATE user_benefit SET status='FULFILLMENT_FAILED' WHERE id=? AND status IN ('CLAIMED','FULFILLING')",
                    Long.valueOf(order.getSourceId()));
        } else if (order.getStatus() == ShippingStatus.TERMINATED) {
            jdbc.update("UPDATE user_benefit SET status='FULFILLMENT_TERMINATED' WHERE id=? AND status IN ('CLAIMED','FULFILLING','FULFILLMENT_FAILED')",
                    Long.valueOf(order.getSourceId()));
        } else if (order.getStatus() == ShippingStatus.FULFILLING) {
            jdbc.update("UPDATE user_benefit SET status='FULFILLING' WHERE id=? AND status='FULFILLMENT_FAILED'",
                    Long.valueOf(order.getSourceId()));
        } else if (order.getStatus() == ShippingStatus.SHIPPED) {
            jdbc.update("UPDATE user_benefit SET status='SHIPPED' WHERE id=? AND status IN ('CLAIMED','FULFILLING','FULFILLMENT_FAILED')",
                    Long.valueOf(order.getSourceId()));
        }
    }

    private ShippingOrderView view(ShippingOrder order) {
        return new ShippingOrderView(order.getId(), order.getShippingNo(), order.getSourceType(),
                order.getSourceId(), order.getTargetUserId(), order.getAddressSnapshotId(),
                order.getHmallItemId(), order.getSkuCode(), order.getProductName(), order.getImageUrl(), order.getQuantity(),
                order.getFulfillmentNo(), order.getCarrierCode(), order.getCarrierName(),
                order.getWaybillNo(), order.getStatus(), order.getLastErrorCode(),
                order.getLastErrorMessage(), order.getShippedAt(), order.getDeliveredAt(),
                order.getFailedAt(), order.getTerminatedAt(), order.getCreatedAt(), order.getUpdatedAt(),
                null, null, null);
    }

    private String required(String value) {
        if (value == null || value.isBlank()) throw error(ShippingErrorCode.SHIPPING_REQUEST_INVALID);
        return value.trim();
    }

    private String bounded(String value, int max) {
        if (value == null || value.isBlank()) return null;
        String normalized = value.trim();
        return normalized.substring(0, Math.min(max, normalized.length()));
    }

    private String defaulted(String value, String fallback, int max) {
        String bounded = bounded(value, max);
        return bounded == null ? fallback : bounded;
    }

    private BusinessException error(ShippingErrorCode code) {
        return new BusinessException(code);
    }
}

package com.dongqh.luckyhub.service.shipping.impl;

import com.dongqh.luckyhub.domain.po.shipping.ShippingOrder;
import com.dongqh.luckyhub.enums.shipping.ShippingStatus;
import com.dongqh.luckyhub.mapper.shipping.ShippingOrderMapper;
import com.dongqh.luckyhub.service.shipping.ShippingOrderService;
import com.dongqh.luckyhub.service.shipping.ShippingProjectionWorker;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ShippingProjectionWorkerImpl implements ShippingProjectionWorker {
    private final ShippingOrderMapper orders;
    private final ShippingOrderService shippingOrders;

    public ShippingProjectionWorkerImpl(ShippingOrderMapper orders, ShippingOrderService shippingOrders) {
        this.orders = orders;
        this.shippingOrders = shippingOrders;
    }

    @Override
    @Transactional(propagation = Propagation.REQUIRES_NEW, isolation = Isolation.READ_COMMITTED)
    public boolean projectOne(long shippingOrderId) {
        ShippingOrder order = orders.lockById(shippingOrderId);
        if (order == null || order.getStatus() == ShippingStatus.DELIVERED
                || order.getStatus() == ShippingStatus.TERMINATED || order.getFulfillmentNo() == null) {
            return false;
        }
        shippingOrders.projectFulfillmentState(order.getFulfillmentNo());
        return true;
    }
}

