        mockMvc.perform(get("/api/benefits").param("startDate", "2026-08-02").param("endDate", "2026-08-01"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/api/benefits").param("endDate", "9999-12-30"))
                .andExpect(status().isOk());
