package com.dongqh.luckyhub.drawchance;

import com.dongqh.luckyhub.domain.dto.drawchance.DrawChanceReservationCommand;
import com.dongqh.luckyhub.service.drawchance.DrawChanceService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest(properties = {
        "spring.task.scheduling.enabled=false",
        "luckyhub.activity.status-refresh-initial-delay=86400000",
        "luckyhub.lottery.reconcile-initial-delay=24h",
        "luckyhub.messaging.enabled=false",
        "luckyhub.lottery.outbox-initial-delay=24h"
})
class DrawChanceConcurrencyTests {
    @Autowired DrawChanceService service;
    @Autowired JdbcTemplate jdbc;

    @Test
    void twentyConcurrentReservationsNeverOverdrawTenChances() throws Exception {
        String prefix = "p5-concurrent-" + UUID.randomUUID();
        jdbc.update("INSERT INTO sys_user(username,password,nickname,status) VALUES(?,?,?,1)", prefix, "x", "并发测试");
        long userId = jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?", Long.class, prefix);
        try {
            service.credit(userId, prefix + "-reward", 10);
            var executor = Executors.newFixedThreadPool(10);
            try {
                var futures = java.util.stream.IntStream.range(0, 20).mapToObj(index -> executor.submit(() ->
                        service.reserve(new DrawChanceReservationCommand(prefix + "-" + index,
                                88L, userId, 1, LocalDate.of(2026, 8, 9))).bonusReserved())).toList();
                long reserved = 0;
                for (var future : futures) reserved += future.get();
                assertThat(reserved).isEqualTo(10);
            } finally {
                executor.shutdownNow();
            }
            var account = service.get(userId);
            assertThat(account.availableBalance()).isZero();
            assertThat(account.reservedBalance()).isEqualTo(10);
        } finally {
            jdbc.update("DELETE FROM draw_chance_ledger WHERE user_id=?", userId);
            jdbc.update("DELETE FROM draw_chance_reservation WHERE user_id=?", userId);
            jdbc.update("DELETE FROM draw_chance_account WHERE user_id=?", userId);
            jdbc.update("DELETE FROM sys_user WHERE id=?", userId);
        }
    }

    @Test
    void mixedSingleAndTenReservationsNeverOverdrawTwentyFiveChances() throws Exception {
        String prefix = "mixed-concurrent-" + UUID.randomUUID();
        String username = "mix-" + UUID.randomUUID().toString().substring(0, 12);
        jdbc.update("INSERT INTO sys_user(username,password,nickname,status) VALUES(?,?,?,1)", username, "x", "混合并发测试");
        long userId = jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?", Long.class, username);
        List<Integer> drawCounts = new ArrayList<>(List.of(10, 10));
        for (int i = 0; i < 20; i++) drawCounts.add(1);
        CountDownLatch ready = new CountDownLatch(drawCounts.size());
        CountDownLatch start = new CountDownLatch(1);
        try {
            service.credit(userId, prefix + "-reward", 25);
            var executor = Executors.newFixedThreadPool(drawCounts.size());
            try {
                List<Future<Long>> futures = new ArrayList<>();
                for (int i = 0; i < drawCounts.size(); i++) {
                    int index = i;
                    int drawCount = drawCounts.get(i);
                    futures.add(executor.submit(() -> {
                        ready.countDown();
                        if (!start.await(5, TimeUnit.SECONDS)) throw new AssertionError("concurrency barrier timed out");
                        return service.reserve(new DrawChanceReservationCommand(prefix + "-" + index,
                                89L, userId, drawCount, LocalDate.of(2026, 8, 10))).bonusReserved();
                    }));
                }
                assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
                start.countDown();
                long reserved = 0;
                for (Future<Long> future : futures) reserved += future.get(30, TimeUnit.SECONDS);
                assertThat(reserved).isEqualTo(25);
            } finally {
                start.countDown();
                executor.shutdownNow();
                assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
            }
            var account = service.get(userId);
            assertThat(account.availableBalance()).isZero();
            assertThat(account.reservedBalance()).isEqualTo(25);
            assertThat(jdbc.queryForObject("""
                    SELECT COALESCE(SUM(bonus_reserved),0) FROM draw_chance_reservation
                    WHERE user_id=? AND activity_id=89
                    """, Long.class, userId)).isEqualTo(25L);
        } finally {
            jdbc.update("DELETE FROM draw_chance_ledger WHERE user_id=?", userId);
            jdbc.update("DELETE FROM draw_chance_reservation WHERE user_id=?", userId);
            jdbc.update("DELETE FROM draw_chance_account WHERE user_id=?", userId);
            jdbc.update("DELETE FROM sys_user WHERE id=?", userId);
        }
    }
}

package com.dongqh.luckyhub.drawchance;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.dto.drawchance.DrawChanceReservationCommand;
import com.dongqh.luckyhub.enums.drawchance.DrawChanceReservationStatus;
import com.dongqh.luckyhub.service.drawchance.DrawChanceService;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest(properties = "luckyhub.lottery.reconciliation-enabled=false")
class DrawChanceServiceTests {
    @Autowired DrawChanceService service;
    @Autowired JdbcTemplate jdbc;
    long userId;
    final String prefix = "p5-chance-" + UUID.randomUUID();

    @BeforeEach
    void createUser() {
        jdbc.update("INSERT INTO sys_user(username,password,nickname,status) VALUES(?,?,?,1)",
                prefix, "x", "次数测试");
        userId = jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?", Long.class, prefix);
    }

    @AfterEach
    void cleanup() {
        jdbc.update("DELETE FROM draw_chance_ledger WHERE user_id=?", userId);
        jdbc.update("DELETE FROM draw_chance_reservation WHERE user_id=?", userId);
        jdbc.update("DELETE FROM draw_chance_account WHERE user_id=?", userId);
        jdbc.update("DELETE FROM lottery_draw_order WHERE request_id LIKE ?", prefix + "%");
        jdbc.update("DELETE FROM sys_user WHERE id=?", userId);
    }

    @Test
    void creditIsIdempotentAndRejectsChangedIdentity() {
        assertThat(service.credit(userId, prefix + "-reward", 3).availableBalance()).isEqualTo(3);
        assertThat(service.credit(userId, prefix + "-reward", 3).availableBalance()).isEqualTo(3);
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM draw_chance_ledger WHERE user_id=?", Integer.class, userId)).isOne();

        assertThatThrownBy(() -> service.credit(userId, prefix + "-reward", 4))
                .isInstanceOf(BusinessException.class);
    }

    @Test
    void reserveMovesBonusAndReleaseOrConfirmSettlesExactlyOnce() {
        service.credit(userId, prefix + "-reward", 3);
        var first = service.reserve(command(prefix + "-r1", 10));
        assertThat(first.bonusReserved()).isEqualTo(3);
        assertThat(first.cumulativeBonusForDate()).isEqualTo(3);
        assertThat(service.get(userId).availableBalance()).isZero();
        assertThat(service.get(userId).reservedBalance()).isEqualTo(3);

        var duplicate = service.reserve(command(prefix + "-r1", 10));
        assertThat(duplicate.duplicate()).isTrue();
        service.release(first.requestId());
        service.release(first.requestId());
        assertThat(service.get(userId).availableBalance()).isEqualTo(3);
        assertThat(service.get(userId).reservedBalance()).isZero();

        var second = service.reserve(command(prefix + "-r2", 1));
        service.confirm(second.requestId());
        service.confirm(second.requestId());
        assertThat(service.get(userId).availableBalance()).isEqualTo(2);
        assertThat(service.get(userId).reservedBalance()).isZero();
        assertThat(jdbc.queryForObject("SELECT status FROM draw_chance_reservation WHERE request_id=?",
                String.class, second.requestId())).isEqualTo(DrawChanceReservationStatus.CONFIRMED.name());
        assertThatThrownBy(() -> service.release(second.requestId())).isInstanceOf(BusinessException.class);
    }

    @Test
    void zeroBalanceStillCreatesIdentityCheckedReservation() {
        var result = service.reserve(command(prefix + "-zero", 1));
        assertThat(result.bonusReserved()).isZero();
        assertThat(result.status()).isEqualTo(DrawChanceReservationStatus.RESERVED);
        assertThat(service.reserve(command(prefix + "-zero", 1)).duplicate()).isTrue();
        assertThatThrownBy(() -> service.reserve(new DrawChanceReservationCommand(
                prefix + "-zero", 99L, userId, 10, LocalDate.of(2026, 8, 9))))
                .isInstanceOf(BusinessException.class);
    }

    @Test
    void staleReconciliationFollowsActualOrderTerminalState() {
        service.credit(userId, prefix + "-reward", 2);
        var success = service.reserve(command(prefix + "-success", 1));
        var failed = service.reserve(command(prefix + "-failed", 1));
        insertOrder(success.requestId(), "SUCCESS");
        insertOrder(failed.requestId(), "FAILED");
        jdbc.update("UPDATE draw_chance_reservation SET created_at='1000-01-01 00:00:00' WHERE user_id=?", userId);

        assertThat(service.reconcileExpired(2, LocalDateTime.now().minusHours(1))).isEqualTo(2);
        assertThat(service.get(userId).availableBalance()).isEqualTo(1);
        assertThat(service.get(userId).reservedBalance()).isZero();
        assertThat(jdbc.queryForList("SELECT status FROM draw_chance_reservation WHERE user_id=? ORDER BY request_id",
                String.class, userId)).containsExactly("RELEASED", "CONFIRMED");
    }

    @Test
    void staleReservationWithoutDrawOrderIsReleasedExactlyOnce() {
        service.credit(userId, prefix + "-reward", 1);
        var abandoned = service.reserve(command(prefix + "-abandoned", 1));
        jdbc.update("UPDATE draw_chance_reservation SET created_at='1000-01-01 00:00:00' WHERE request_id=?",
                abandoned.requestId());

        assertThat(service.reconcileExpired(10, LocalDateTime.now().minusHours(1))).isOne();
        assertThat(service.reconcileExpired(10, LocalDateTime.now().minusHours(1))).isZero();
        assertThat(service.get(userId).availableBalance()).isOne();
        assertThat(service.get(userId).reservedBalance()).isZero();
        assertThat(jdbc.queryForObject("SELECT status FROM draw_chance_reservation WHERE request_id=?",
                String.class, abandoned.requestId())).isEqualTo(DrawChanceReservationStatus.RELEASED.name());
        assertThat(jdbc.queryForObject("""
                SELECT COUNT(*) FROM draw_chance_ledger
                WHERE user_id=? AND business_type='DRAW_RELEASE' AND business_id=?
                """, Integer.class, userId, abandoned.requestId())).isOne();
    }

    @Test
    void processingReservationsAtBatchHeadDoNotStarveLaterAbandonedReservation() {
        service.credit(userId, prefix + "-reward", 3);
        var firstProcessing = service.reserve(command(prefix + "-p1", 1));
        insertOrder(firstProcessing.requestId(), "PROCESSING");
        var secondProcessing = service.reserve(command(prefix + "-p2", 1));
        insertOrder(secondProcessing.requestId(), "PROCESSING");
        var abandoned = service.reserve(command(prefix + "-a3", 1));
        jdbc.update("UPDATE draw_chance_reservation SET created_at='1000-01-01 00:00:00' WHERE user_id=?", userId);

        assertThat(service.reconcileExpired(2, LocalDateTime.now().minusHours(1))).isOne();
        assertThat(jdbc.queryForObject("SELECT status FROM draw_chance_reservation WHERE request_id=?",
                String.class, abandoned.requestId())).isEqualTo(DrawChanceReservationStatus.RELEASED.name());
        assertThat(service.get(userId).availableBalance()).isOne();
        assertThat(service.get(userId).reservedBalance()).isEqualTo(2);
    }

    private void insertOrder(String requestId, String status) {
        jdbc.update("""
                INSERT INTO lottery_draw_order(request_id,user_id,activity_id,draw_count,draw_date,status)
                VALUES(?,?,88,1,'2026-08-09',?)
                """, requestId, userId, status);
    }

    private DrawChanceReservationCommand command(String requestId, int count) {
        return new DrawChanceReservationCommand(requestId, 88L, userId, count, LocalDate.of(2026, 8, 9));
    }
}

