package com.dongqh.luckyhub.fulfillment;
import com.dongqh.luckyhub.common.exception.BusinessException;import com.dongqh.luckyhub.domain.dto.fulfillment.CreateFulfillmentTaskCommand;import com.dongqh.luckyhub.enums.fulfillment.*;import com.dongqh.luckyhub.domain.model.fulfillment.PointsFulfillmentPayload;import com.dongqh.luckyhub.domain.model.fulfillment.FulfillmentClaim;import com.dongqh.luckyhub.service.fulfillment.*;import com.dongqh.luckyhub.domain.gateway.integration.GatewayResult;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;
import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.stream.IntStream;import static org.assertj.core.api.Assertions.*;
@SpringBootTest class FulfillmentLeaseConcurrencyTests {
 @Autowired FulfillmentTaskService tasks;@Autowired FulfillmentStateService state;@Autowired JdbcTemplate jdbc;
 @AfterEach void clean(){jdbc.update("DELETE FROM fulfillment_outbox");jdbc.update("DELETE FROM fulfillment_attempt");jdbc.update("DELETE FROM fulfillment_quarantine");jdbc.update("DELETE FROM fulfillment_task");}
 @Test void onlyOneOfTwentyClaimersWins() throws Exception {tasks.create(new CreateFulfillmentTaskCommand("LEASE-1","TEST","1",FulfillmentType.POINTS,1L,new PointsFulfillmentPayload(1,"x"),5));ExecutorService pool=Executors.newFixedThreadPool(20);try{CountDownLatch start=new CountDownLatch(1);List<Future<List<FulfillmentClaim>>> fs=IntStream.range(0,20).mapToObj(i->pool.submit(()->{start.await();return state.claimDue(1,Duration.ofSeconds(30));})).toList();start.countDown();int claims=0;for(Future<List<FulfillmentClaim>> f:fs)claims+=f.get(15,TimeUnit.SECONDS).size();assertThat(claims).isOne();}finally{pool.shutdownNow();}}
 @Test void staleLeaseTokenCannotComplete(){tasks.create(new CreateFulfillmentTaskCommand("LEASE-2","TEST","2",FulfillmentType.POINTS,1L,new PointsFulfillmentPayload(1,"x"),5));FulfillmentClaim claim=state.claimDue(1,Duration.ofSeconds(30)).get(0);FulfillmentClaim stale=new FulfillmentClaim(claim.taskId(),claim.fulfillmentNo(),claim.fulfillmentType(),claim.targetUserId(),claim.requestPayload(),claim.operation(),"wrong-token",claim.claimedAt(),claim.leaseUntil());assertThatThrownBy(()->state.recordResult(stale,GatewayResult.succeeded("EXT"),1)).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.getErrorCode()).isEqualTo(FulfillmentErrorCode.LEASE_CONFLICT));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM fulfillment_attempt WHERE fulfillment_no='LEASE-2'",Integer.class)).isZero();}
}

package com.dongqh.luckyhub.fulfillment;

import com.dongqh.luckyhub.messaging.fulfillment.event.FulfillmentTaskReadyEvent;
import com.dongqh.luckyhub.mapper.fulfillment.FulfillmentOutboxMapper;
import com.dongqh.luckyhub.messaging.fulfillment.outbox.*;
import com.dongqh.luckyhub.messaging.fulfillment.rabbit.FulfillmentEventPublisher;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;

import java.time.Duration;
import java.time.LocalDateTime;
import java.util.List;

import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class FulfillmentOutboxRelayTests {
    @Test void marksSentOnlyAfterConfirmedPublish() throws Exception {
        var json=JsonMapper.builder().findAndAddModules().build();var mapper=mock(FulfillmentOutboxMapper.class);var publisher=mock(FulfillmentEventPublisher.class);var event=new FulfillmentTaskReadyEvent("event-1","TASK-1",LocalDateTime.now());var row=FulfillmentOutbox.pending(event.eventId(),event.fulfillmentNo(),"FULFILLMENT_TASK_READY",json.writeValueAsString(event));row.setId(1L);when(mapper.selectRelayCandidates(any(),eq(10))).thenReturn(List.of(row));when(mapper.claimForRelay(eq(1L),anyString(),any(),any())).thenReturn(1);when(mapper.markSent(eq(1L),anyString(),any())).thenReturn(1);
        new FulfillmentOutboxRelay(mapper,publisher,json,10,Duration.ofSeconds(30)).relayBatch();
        verify(publisher).publish(event);verify(mapper).markSent(eq(1L),anyString(),any());verify(mapper,never()).markFailed(anyLong(),anyString(),anyString(),any());
    }
    @Test void recordsFailureWhenBrokerRejectsEvent() throws Exception {
        var json=JsonMapper.builder().findAndAddModules().build();var mapper=mock(FulfillmentOutboxMapper.class);var publisher=mock(FulfillmentEventPublisher.class);var event=new FulfillmentTaskReadyEvent("event-2","TASK-2",LocalDateTime.now());var row=FulfillmentOutbox.pending(event.eventId(),event.fulfillmentNo(),"FULFILLMENT_TASK_READY",json.writeValueAsString(event));row.setId(2L);when(mapper.selectRelayCandidates(any(),eq(10))).thenReturn(List.of(row));when(mapper.claimForRelay(eq(2L),anyString(),any(),any())).thenReturn(1);doThrow(new IllegalStateException("broker NACK")).when(publisher).publish(event);
        new FulfillmentOutboxRelay(mapper,publisher,json,10,Duration.ofSeconds(30)).relayBatch();
        verify(mapper).markFailed(eq(2L),anyString(),contains("broker NACK"),any());verify(mapper,never()).markSent(anyLong(),anyString(),any());
    }
    @Test void malformedEventIsFailedWithoutPublishing(){
        var json=JsonMapper.builder().findAndAddModules().build();var mapper=mock(FulfillmentOutboxMapper.class);var publisher=mock(FulfillmentEventPublisher.class);var row=FulfillmentOutbox.pending("event-3","TASK-3","FULFILLMENT_TASK_READY","{}");row.setId(3L);when(mapper.selectRelayCandidates(any(),eq(10))).thenReturn(List.of(row));when(mapper.claimForRelay(eq(3L),anyString(),any(),any())).thenReturn(1);
        new FulfillmentOutboxRelay(mapper,publisher,json,10,Duration.ofSeconds(30)).relayBatch();
        verify(publisher,never()).publish(any());verify(mapper).markFailed(eq(3L),anyString(),anyString(),any());verify(mapper,never()).markSent(anyLong(),anyString(),any());
    }
}

