import com.dongqh.luckyhub.domain.channel.inventory.dto.AllocateChannelStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.dto.InitializeSkuStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.dto.ReserveChannelStockCommand;
import com.dongqh.luckyhub.domain.channel.inventory.enums.ChannelInventoryErrorCode;
import com.dongqh.luckyhub.domain.channel.inventory.enums.InventoryReservationStatus;
import com.dongqh.luckyhub.domain.channel.inventory.service.ChannelInventoryService;
import com.dongqh.luckyhub.service.inventory.ActivityPrizeInventoryService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
