        assertCandidate(selectAt(9, active(11, 101, 10), active(12, 102, 30)), 11, 101);
        assertCandidate(selectAt(10, active(11, 101, 10), active(12, 102, 30)), 12, 102);
        assertCandidate(selectAt(39, active(11, 101, 10), active(12, 102, 30)), 12, 102);

        FixedRandomSource random = new FixedRandomSource(40);
        DrawCandidate result = new WeightedDrawEngineImpl(random)
                .select(List.of(active(11, 101, 10), active(12, 102, 30)), 60);

        assertThat(result.type()).isEqualTo(NO_WIN);
        assertThat(random.bound()).isEqualTo(100L);
    }

    @Test
    void zeroNoWinWeightLeavesTheLastPrizeBoundaryReachable() {
        FixedRandomSource random = new FixedRandomSource(39);

        DrawCandidate result = new WeightedDrawEngineImpl(random)
                .select(List.of(active(11, 101, 10), active(12, 102, 30)), 0);

        assertCandidate(result, 12, 102);
        assertThat(random.bound()).isEqualTo(40L);
    }

    @Test
    void disabledAndSoldOutIntervalsBecomeNoWinWithoutRedistribution() {
        List<PrizeWeightSnapshot> prizes = List.of(
                new PrizeWeightSnapshot(11, 101, 10, 5, false),
                new PrizeWeightSnapshot(12, 102, 30, 0, true),
                active(13, 103, 20)
        );

        assertThat(new WeightedDrawEngineImpl(new FixedRandomSource(0)).select(prizes, 40).type())
                .isEqualTo(NO_WIN);
        assertThat(new WeightedDrawEngineImpl(new FixedRandomSource(10)).select(prizes, 40).type())
                .isEqualTo(NO_WIN);
        assertCandidate(new WeightedDrawEngineImpl(new FixedRandomSource(40)).select(prizes, 40), 13, 103);
    }

    @Test
    void requiresValidPositiveTotalWeight() {
        WeightedDrawEngine engine = new WeightedDrawEngineImpl(new FixedRandomSource(0));

        assertThatThrownBy(() -> engine.select(List.of(), 0))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> engine.select(List.of(active(11, 101, 10)), -1))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> engine.select(
                List.of(new PrizeWeightSnapshot(11, 101, 0, 1, true)), 1))
                .isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void accumulatesBeyondIntegerRangeAndRejectsLongOverflow() {
        FixedRandomSource random = new FixedRandomSource(3_000_000_000L);
        DrawCandidate result = new WeightedDrawEngineImpl(random).select(List.of(
                active(11, 101, 2_000_000_000L),
                active(12, 102, 2_000_000_000L)
        ), 0);

        assertCandidate(result, 12, 102);
        assertThat(random.bound()).isEqualTo(4_000_000_000L);

        assertThatThrownBy(() -> new WeightedDrawEngineImpl(new FixedRandomSource(0)).select(List.of(
                active(11, 101, Long.MAX_VALUE),
                active(12, 102, 1)
        ), 0)).isInstanceOf(IllegalArgumentException.class);
    }

    private DrawCandidate selectAt(long value, PrizeWeightSnapshot... prizes) {
        return new WeightedDrawEngineImpl(new FixedRandomSource(value))
                .select(List.of(prizes), 60);
    }

    private PrizeWeightSnapshot active(long activityPrizeId, long prizeId, long weight) {
        return new PrizeWeightSnapshot(activityPrizeId, prizeId, weight, 1, true);
    }

    private void assertCandidate(DrawCandidate candidate, long activityPrizeId, long prizeId) {
        assertThat(candidate.type()).isEqualTo(PRIZE_CANDIDATE);
        assertThat(candidate.activityPrizeId()).isEqualTo(activityPrizeId);
        assertThat(candidate.prizeId()).isEqualTo(prizeId);
    }

    private static final class FixedRandomSource implements DrawRandomSource {
        private final long value;
        private long bound;

        private FixedRandomSource(long value) {
            this.value = value;
        }

        @Override
        public long nextLong(long bound) {
            this.bound = bound;
            return value;
        }

        private long bound() {
            return bound;
        }
    }
}

package com.dongqh.luckyhub.config.lottery;

import org.junit.jupiter.api.Test;
import org.redisson.api.RedissonClient;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.env.Environment;

import java.time.Duration;
import java.time.ZoneId;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest(properties = {
        "seata.enabled=false",
        "luckyhub.messaging.enabled=false"
})
class LotteryConfigurationTests {

    @Autowired
    private LotteryProperties properties;

    @Autowired
    private RedissonClient redissonClient;

    @Autowired
    private Environment environment;

    @Test
    void bindsSafeLotteryDefaults() {
        assertThat(properties.zoneId()).isEqualTo(ZoneId.of("Asia/Shanghai"));
        assertThat(properties.lockWait()).isEqualTo(Duration.ofSeconds(3));
        assertThat(properties.processingTimeout()).isEqualTo(Duration.ofMinutes(2));
        assertThat(properties.reconcileInterval()).isEqualTo(Duration.ofSeconds(30));
        assertThat(properties.reconcileInitialDelay()).isEqualTo(Duration.ofSeconds(60));
        assertThat(properties.reconcileBatchSize()).isEqualTo(100);
        assertThat(properties.outboxInterval()).isEqualTo(Duration.ofSeconds(5));
        assertThat(properties.outboxBatchSize()).isEqualTo(100);
        assertThat(redissonClient).isNotNull();
    }

    @Test
    void exposesRabbitMqReliabilitySettingsWithoutRedisStreamTransportSettings() {
        assertThat(environment.getProperty("spring.rabbitmq.virtual-host")).isEqualTo("/dongqh");
        assertThat(environment.getProperty("spring.rabbitmq.publisher-confirm-type"))
                .isEqualTo("correlated");
        assertThat(environment.getProperty("spring.rabbitmq.publisher-returns", Boolean.class))
                .isTrue();
        assertThat(environment.getProperty("spring.rabbitmq.template.mandatory", Boolean.class))
                .isTrue();
        assertThat(environment.getProperty("luckyhub.messaging.publisher-confirm-timeout", Duration.class))
                .isEqualTo(Duration.ofSeconds(5));
        assertThat(environment.getProperty("luckyhub.messaging.provider")).isNull();
        assertThat(environment.getProperty("luckyhub.messaging.lottery-stream")).isNull();
        assertThat(environment.getProperty("luckyhub.messaging.lottery-group")).isNull();
    }

    @Test
    void rejectsUnsafeMessagingAndOutboxSettings() {
        assertThatThrownBy(() -> new MessagingProperties(
                true, " ", Duration.ofSeconds(5), Duration.ofSeconds(30)))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new MessagingProperties(
                true, "consumer", Duration.ZERO, Duration.ofSeconds(30)))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new MessagingProperties(
                true, "consumer", Duration.ofSeconds(5), Duration.ZERO))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new LotteryProperties(ZoneId.of("Asia/Shanghai"), Duration.ofSeconds(1),
                Duration.ofMinutes(2), Duration.ofSeconds(30), Duration.ofSeconds(1), 100,
                Duration.ofSeconds(5), 0))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> propertiesWithReconciliation(Duration.ZERO, Duration.ZERO, 100))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> propertiesWithReconciliation(Duration.ofSeconds(1),
                Duration.ofSeconds(-1), 100)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> propertiesWithReconciliation(Duration.ofSeconds(1),
                Duration.ZERO, 0)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new LotteryProperties(ZoneId.of("Asia/Shanghai"), Duration.ofSeconds(1),
                Duration.ZERO, Duration.ofSeconds(30), Duration.ZERO, 100,
                Duration.ofSeconds(5), 100))
                .isInstanceOf(IllegalArgumentException.class);
    }

    private LotteryProperties propertiesWithReconciliation(
            Duration interval, Duration initialDelay, int batchSize) {
        return new LotteryProperties(ZoneId.of("Asia/Shanghai"), Duration.ofSeconds(1),
                Duration.ofMinutes(2), interval, initialDelay, batchSize,
                Duration.ofSeconds(5), 100);
    }
}

