package com.dongqh.luckyhub.lottery;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest
class LotteryRewardSchemaContractTests {

    @Autowired JdbcTemplate jdbc;

    @Test
    void migratesStageFiveTablesAndSnapshotColumnsThroughV16() {
        List<String> tables = jdbc.queryForList("""
                SELECT table_name FROM information_schema.tables
                WHERE table_schema=DATABASE() AND table_name IN (
                  'draw_chance_account','draw_chance_ledger',
                  'draw_chance_reservation','lottery_reward_quarantine')
                """, String.class);
        assertThat(tables).containsExactlyInAnyOrder(
                "draw_chance_account", "draw_chance_ledger",
                "draw_chance_reservation", "lottery_reward_quarantine");

        for (String table : List.of("lottery_draw_record", "user_benefit")) {
            Map<String, Map<String, Object>> columns = jdbc.queryForList("""
                    SELECT column_name,data_type,is_nullable,character_maximum_length
                    FROM information_schema.columns
                    WHERE table_schema=DATABASE() AND table_name=?
                      AND column_name IN ('reward_definition_id','reward_type','reward_target_id',
                        'reward_quantity','reward_payload','reward_fingerprint')
                    """, table).stream().collect(java.util.stream.Collectors.toMap(
                    row -> row.get("column_name").toString(), row -> row));
            assertThat(columns).hasSize(6);
            assertThat(columns.get("reward_payload").get("data_type")).isEqualTo("json");
            assertThat(columns.get("reward_fingerprint").get("data_type")).isEqualTo("char");
            assertThat(((Number) columns.get("reward_fingerprint")
                    .get("character_maximum_length")).longValue()).isEqualTo(64L);
            assertThat(columns.values()).allSatisfy(row ->
                    assertThat(row.get("is_nullable")).isEqualTo("YES"));
        }

        Integer migrated = jdbc.queryForObject("""
                SELECT COUNT(*) FROM flyway_schema_history
                WHERE version='16' AND success=1
                """, Integer.class);
        assertThat(migrated).isOne();
    }

    @Test
    void enforcesStableStageFiveBusinessIdentities() {
        List<String> indexes = jdbc.queryForList("""
                SELECT DISTINCT index_name FROM information_schema.statistics
                WHERE table_schema=DATABASE() AND index_name IN (
                  'uk_user_benefit_fulfillment','uk_draw_chance_account_user',
                  'uk_draw_chance_ledger_business','uk_draw_chance_reservation_request',
                  'uk_lottery_reward_quarantine_event')
                """, String.class);
        assertThat(indexes).hasSize(5);
    }

    @Test
    void rejectsNegativeBalancesAndDuplicateReservationIdentity() {
        assertThatThrownBy(() -> jdbc.update("""
                INSERT INTO draw_chance_account(user_id,available_balance,reserved_balance,version)
                VALUES(900000001,-1,0,0)
                """)).isInstanceOf(DataIntegrityViolationException.class);

        jdbc.update("""
                INSERT INTO draw_chance_reservation
                  (request_id,user_id,activity_id,draw_date,draw_count,bonus_reserved,status)
                VALUES('PHASE5-SCHEMA-R1',1,1,CURRENT_DATE,1,0,'RESERVED')
                """);
        try {
            assertThatThrownBy(() -> jdbc.update("""
                    INSERT INTO draw_chance_reservation
                      (request_id,user_id,activity_id,draw_date,draw_count,bonus_reserved,status)
                    VALUES('PHASE5-SCHEMA-R1',2,1,CURRENT_DATE,1,0,'RESERVED')
                    """)).isInstanceOf(DataIntegrityViolationException.class);
        } finally {
            jdbc.update("DELETE FROM draw_chance_reservation WHERE request_id='PHASE5-SCHEMA-R1'");
        }
    }
}

package com.dongqh.luckyhub.lottery;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class LotterySchemaContractTests {

    private static final Set<String> ORDINARY_PERMISSIONS = Set.of(
            "lottery:activity:read",
            "lottery:draw",
            "lottery:draw:read",
            "lottery:record:read",
            "benefit:read"
    );

    private static final Set<String> ALL_PERMISSIONS = Set.of(
            "lottery:order:read:all",
            "lottery:draw:read:all",
            "lottery:record:read:all",
            "benefit:read:all"
    );

    private final JdbcTemplate jdbcTemplate;

    @Autowired
    LotterySchemaContractTests(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Test
    void addsLotteryCoreColumnsAndTables() {
        assertThat(column("marketing_activity", "no_win_weight")).isPresent();
        assertThat(column("lottery_draw_order", "draw_date")).isPresent();
        assertThat(column("lottery_draw_record", "result_type")).isPresent();
        assertThat(column("lottery_draw_record", "prize_name")).isPresent();
        assertThat(column("user_benefit", "draw_record_id")).isPresent();
        assertThat(table("message_outbox")).isPresent();
        assertThat(table("message_consume_record")).isPresent();
    }

    @Test
    void requiresDrawSourceAndPrizeTypeForBenefits() {
        assertThat(column("user_benefit", "draw_record_id"))
                .get()
                .extracting(metadata -> metadata.get("IS_NULLABLE"))
                .isEqualTo("NO");
        assertThat(column("user_benefit", "prize_type"))
                .get()
                .extracting(metadata -> metadata.get("IS_NULLABLE"))
                .isEqualTo("NO");
    }

    @Test
    void seedsLotteryRolesAndPermissions() {
        List<String> roles = jdbcTemplate.queryForList("""
                SELECT role_code
                FROM sys_role
                WHERE role_code = 'USER'
                """, String.class);
        List<String> permissions = jdbcTemplate.queryForList("""
                SELECT permission_code
                FROM sys_permission
                WHERE permission_code IN (
                    'lottery:activity:read',
                    'lottery:draw',
                    'lottery:draw:read',
                    'lottery:record:read',
                    'benefit:read',
                    'lottery:order:read:all',
                    'lottery:draw:read:all',
                    'lottery:record:read:all',
                    'benefit:read:all'
                )
                """, String.class);

        assertThat(roles).containsExactly("USER");
        assertThat(permissions).containsExactlyInAnyOrderElementsOf(allLotteryPermissions());
    }

    @Test
    void grantsLotteryPermissionsToUserAndAdminRoles() {
        assertThat(rolePermissions("USER"))
                .containsExactlyInAnyOrderElementsOf(ORDINARY_PERMISSIONS);
        assertThat(rolePermissions("ADMIN"))
                .containsAll(allLotteryPermissions());
    }

    @Test
    void associatesEveryExistingUserWithUserRole() {
        Integer usersWithoutUserRole = jdbcTemplate.queryForObject("""
                SELECT COUNT(*)
                FROM sys_user user_record
                WHERE NOT EXISTS (
                    SELECT 1
                    FROM sys_user_role user_role
                    JOIN sys_role role_record ON role_record.id = user_role.role_id
                    WHERE user_role.user_id = user_record.id
                      AND role_record.role_code = 'USER'
                )
                """, Integer.class);

        assertThat(usersWithoutUserRole).isZero();
    }

    private Optional<Map<String, Object>> column(String tableName, String columnName) {
        return jdbcTemplate.queryForList("""
                SELECT column_name, data_type, is_nullable
                FROM information_schema.columns
                WHERE table_schema = DATABASE()
                  AND table_name = ?
                  AND column_name = ?
                """, tableName, columnName).stream().findFirst();
    }

    private Optional<String> table(String tableName) {
        return jdbcTemplate.queryForList("""
                SELECT table_name
                FROM information_schema.tables
                WHERE table_schema = DATABASE()
                  AND table_type = 'BASE TABLE'
                  AND table_name = ?
                """, String.class, tableName).stream().findFirst();
    }

    private Set<String> rolePermissions(String roleCode) {
        return Set.copyOf(jdbcTemplate.queryForList("""
                SELECT permission.permission_code
                FROM sys_role_permission role_permission
                JOIN sys_role role_record ON role_record.id = role_permission.role_id
                JOIN sys_permission permission ON permission.id = role_permission.permission_id
                WHERE role_record.role_code = ?
                  AND permission.permission_code IN (
                    'lottery:activity:read',
                    'lottery:draw',
                    'lottery:draw:read',
                    'lottery:record:read',
                    'benefit:read',
                    'lottery:order:read:all',
                    'lottery:draw:read:all',
                    'lottery:record:read:all',
                    'benefit:read:all'
                  )
                """, String.class, roleCode));
    }

    private Set<String> allLotteryPermissions() {
        Set<String> permissions = new java.util.HashSet<>(ORDINARY_PERMISSIONS);
        permissions.addAll(ALL_PERMISSIONS);
        return permissions;
    }
}

package com.dongqh.luckyhub.lottery.messaging;

import com.dongqh.luckyhub.messaging.lottery.event.DrawEventEnvelope;
import com.dongqh.luckyhub.messaging.lottery.event.DrawEventType;
import com.dongqh.luckyhub.messaging.lottery.event.PrizeFulfillmentRequestedEvent;
import com.dongqh.luckyhub.service.lottery.OutboxService;
import com.dongqh.luckyhub.enums.prize.PrizeType;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;

import java.time.LocalDateTime;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest
class OutboxPersistenceIntegrationTests {

    private final OutboxService outboxService;
    private final JdbcTemplate jdbcTemplate;
    private final ObjectMapper objectMapper;
    private final TransactionTemplate transactionTemplate;
    private final Set<String> eventIdsToClean = new LinkedHashSet<>();

    @Autowired
    OutboxPersistenceIntegrationTests(
            OutboxService outboxService,
            JdbcTemplate jdbcTemplate,
            ObjectMapper objectMapper,
            PlatformTransactionManager transactionManager) {
        this.outboxService = outboxService;
        this.jdbcTemplate = jdbcTemplate;
        this.objectMapper = objectMapper;
        this.transactionTemplate = new TransactionTemplate(transactionManager);
    }

    @AfterEach
    void cleanUpExactTestRows() {
        eventIdsToClean.forEach(eventId -> jdbcTemplate.update(
                "DELETE FROM message_outbox WHERE event_id = ?", eventId));
        eventIdsToClean.clear();
    }

    @Test
    void appendCommitsAndRollsBackWithTheCallersRealMysqlTransaction() {
        DrawEventEnvelope committed = newEnvelope(UUID.randomUUID(), "commit-request");
        DrawEventEnvelope rolledBack = newEnvelope(UUID.randomUUID(), "rollback-request");
        track(committed, rolledBack);

        transactionTemplate.executeWithoutResult(status -> outboxService.append(committed));
        transactionTemplate.executeWithoutResult(status -> {
            outboxService.append(rolledBack);
            status.setRollbackOnly();
        });

        assertThat(rowCount(committed.eventId())).isOne();
        assertThat(rowCount(rolledBack.eventId())).isZero();
    }

    @Test
    void mysqlUniqueConstraintRejectsADuplicateEventId() {
        DrawEventEnvelope event = newEnvelope(UUID.randomUUID(), "duplicate-request");
        track(event);
        transactionTemplate.executeWithoutResult(status -> outboxService.append(event));

        assertThatThrownBy(() -> transactionTemplate.executeWithoutResult(
                status -> outboxService.append(event)))
                .isInstanceOf(DataIntegrityViolationException.class);

        assertThat(rowCount(event.eventId())).isOne();
    }

    @Test
    void mysqlJsonPayloadRestoresAllEnvelopeMetadataAndBusinessPayload() throws Exception {
        DrawEventEnvelope event = newEnvelope(UUID.randomUUID(), "json-round-trip-request");
        track(event);
        transactionTemplate.executeWithoutResult(status -> outboxService.append(event));

        StoredOutbox stored = jdbcTemplate.queryForObject("""
                        SELECT event_id, event_type, event_version, aggregate_type,
                               aggregate_id, payload, status, retry_count
                        FROM message_outbox
                        WHERE event_id = ?
                        """,
                (resultSet, rowNumber) -> new StoredOutbox(
                        resultSet.getString("event_id"),
                        resultSet.getString("event_type"),
                        resultSet.getInt("event_version"),
                        resultSet.getString("aggregate_type"),
                        resultSet.getString("aggregate_id"),
                        resultSet.getString("payload"),
                        resultSet.getString("status"),
                        resultSet.getInt("retry_count")),
                event.eventId().toString());

        assertThat(stored).isNotNull();
        assertThat(stored.eventId()).isEqualTo(event.eventId().toString());
        assertThat(stored.eventType()).isEqualTo(DrawEventType.PRIZE_FULFILLMENT_REQUESTED.name());
        assertThat(stored.eventVersion()).isEqualTo(1);
        assertThat(stored.aggregateType()).isEqualTo("LOTTERY_DRAW_ORDER");
        assertThat(stored.aggregateId()).isEqualTo(event.orderId().toString());
        assertThat(stored.status()).isEqualTo("PENDING");
        assertThat(stored.retryCount()).isZero();

        DrawEventEnvelope restored = objectMapper.readValue(stored.payload(), DrawEventEnvelope.class);
        assertThat(restored.eventId()).isEqualTo(event.eventId());
        assertThat(restored.eventType()).isEqualTo(event.eventType());
        assertThat(restored.eventVersion()).isEqualTo(event.eventVersion());
        assertThat(restored.requestId()).isEqualTo(event.requestId());
        assertThat(restored.userId()).isEqualTo(event.userId());
        assertThat(restored.activityId()).isEqualTo(event.activityId());
        assertThat(restored.orderId()).isEqualTo(event.orderId());
        assertThat(restored.occurredAt()).isEqualTo(event.occurredAt());
        assertThat(restored.payloadAs(PrizeFulfillmentRequestedEvent.class, objectMapper))
                .isEqualTo(new PrizeFulfillmentRequestedEvent(501L, 502L, 503L, PrizeType.PHYSICAL));
    }

    private DrawEventEnvelope newEnvelope(UUID eventId, String requestId) {
        return new DrawEventEnvelope(
                eventId,
                DrawEventType.PRIZE_FULFILLMENT_REQUESTED,
                1,
                requestId + '-' + eventId,
                101L,
                201L,
                301L,
                LocalDateTime.of(2026, 7, 31, 20, 0, 30),
                objectMapper.valueToTree(
                        new PrizeFulfillmentRequestedEvent(501L, 502L, 503L, PrizeType.PHYSICAL)));
    }

    private void track(DrawEventEnvelope... events) {
        for (DrawEventEnvelope event : events) {
            eventIdsToClean.add(event.eventId().toString());
        }
    }

    private int rowCount(UUID eventId) {
        return jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM message_outbox WHERE event_id = ?",
                Integer.class,
                eventId.toString());
    }

    private record StoredOutbox(
            String eventId,
            String eventType,
            int eventVersion,
            String aggregateType,
            String aggregateId,
            String payload,
            String status,
            int retryCount) {
    }
}

