import com.dongqh.luckyhub.domain.model.reward.RewardSnapshot;
import com.dongqh.luckyhub.service.reward.RewardSnapshotService;
import org.junit.jupiter.api.Test;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

class DrawEligibilityServiceTests {
    private static final ZoneId SHANGHAI = ZoneId.of("Asia/Shanghai");
    private static final Clock CLOCK = Clock.fixed(Instant.parse("2026-07-31T04:00:00Z"), SHANGHAI);
    private final MarketingActivityMapper activityMapper = mock(MarketingActivityMapper.class);
    private final MarketingActivityPrizeMapper relationMapper = mock(MarketingActivityPrizeMapper.class);
    private final MarketingPrizeMapper prizeMapper = mock(MarketingPrizeMapper.class);
    private final RewardSnapshotService rewardSnapshots = mock(RewardSnapshotService.class);
    private final DrawEligibilityService service = new DrawEligibilityServiceImpl(
            activityMapper, relationMapper, prizeMapper, rewardSnapshots, CLOCK);

    @Test
    void loadsOneImmutableShanghaiTimeConfigurationSnapshot() {
        MarketingActivity activity = runningActivity();
        MarketingActivityPrize relation = new MarketingActivityPrize();
        relation.setId(2L); relation.setActivityId(1L); relation.setPrizeId(3L);
        relation.setWeight(40); relation.setRemainingStock(5); relation.setSortOrder(1);
        MarketingPrize prize = new MarketingPrize();
        prize.setId(3L); prize.setPrizeName("券"); prize.setPrizeType(PrizeType.COUPON);
        prize.setRewardDefinitionId(9L);
        prize.setImageUrl("https://img"); prize.setStatus(0);
        when(activityMapper.selectById(1L)).thenReturn(activity);
        when(relationMapper.selectList(any())).thenReturn(List.of(relation));
        when(prizeMapper.selectByIds(List.of(3L))).thenReturn(List.of(prize));
        RewardSnapshot reward = new RewardSnapshot(9L, "COUPON-9", RewardType.COUPON,
                6L, 1, "{\"templateId\":6}", "a".repeat(64));
        when(rewardSnapshots.resolveForPrizes(List.of(prize))).thenReturn(Map.of(3L, reward));

        DrawEligibilityService.EligibilitySnapshot snapshot = service.load(1L);

        assertThat(snapshot.dailyLimit()).isEqualTo(10);
        assertThat(snapshot.noWinWeight()).isEqualTo(60);
        assertThat(snapshot.snapshotTime().toString()).isEqualTo("2026-07-31T12:00");
        assertThat(snapshot.prizes()).singleElement().satisfies(item -> {
            assertThat(item.weight()).isEqualTo(40);
            assertThat(item.remainingStock()).isEqualTo(5);
            assertThat(item.enabled()).isFalse();
            assertThat(item.rewardSnapshot()).isEqualTo(reward);
        });
        verify(activityMapper, times(1)).selectById(1L);
        assertThatThrownBy(() -> snapshot.prizes().clear())
                .isInstanceOf(UnsupportedOperationException.class);
    }

    @Test
    void keepsNullRewardSnapshotForLegacyPrize() {
        MarketingActivityPrize relation = new MarketingActivityPrize();
        relation.setId(2L); relation.setActivityId(1L); relation.setPrizeId(3L);
        relation.setWeight(40); relation.setRemainingStock(5); relation.setSortOrder(1);
        MarketingPrize legacy = new MarketingPrize();
        legacy.setId(3L); legacy.setPrizeName("旧奖品"); legacy.setPrizeType(PrizeType.POINTS);
        legacy.setStatus(1);
        when(activityMapper.selectById(1L)).thenReturn(runningActivity());
        when(relationMapper.selectList(any())).thenReturn(List.of(relation));
        when(prizeMapper.selectByIds(List.of(3L))).thenReturn(List.of(legacy));
        when(rewardSnapshots.resolveForPrizes(List.of(legacy))).thenReturn(Map.of());

        assertThat(service.load(1L).prizes()).singleElement()
                .extracting(item -> item.rewardSnapshot()).isNull();
    }

    @Test
    void rejectsNonRunningOrOutsideTimeWindow() {
        MarketingActivity activity = runningActivity();
        activity.setStatus(ActivityStatus.DISABLED);
        when(activityMapper.selectById(1L)).thenReturn(activity);
        assertError(LotteryErrorCode.ACTIVITY_NOT_AVAILABLE);

        activity.setStatus(ActivityStatus.RUNNING);
        activity.setEndTime(java.time.LocalDateTime.of(2026, 7, 31, 12, 0));
        assertError(LotteryErrorCode.ACTIVITY_NOT_AVAILABLE);
        verifyNoInteractions(relationMapper, prizeMapper);
    }

    @Test
    void distinguishesMissingActivityAndInvalidEmptyWeightConfiguration() {
        when(activityMapper.selectById(1L)).thenReturn(null);
        assertError(LotteryErrorCode.ACTIVITY_NOT_FOUND);

        MarketingActivity activity = runningActivity();
        activity.setNoWinWeight(0);
        when(activityMapper.selectById(1L)).thenReturn(activity);
        when(relationMapper.selectList(any())).thenReturn(List.of());
        assertError(LotteryErrorCode.DRAW_WEIGHT_INVALID);
    }

    private MarketingActivity runningActivity() {
        MarketingActivity activity = new MarketingActivity();
        activity.setId(1L); activity.setStatus(ActivityStatus.RUNNING);
        activity.setStartTime(java.time.LocalDateTime.of(2026, 7, 31, 11, 0));
        activity.setEndTime(java.time.LocalDateTime.of(2026, 7, 31, 13, 0));
        activity.setDailyLimit(10); activity.setNoWinWeight(60);
        return activity;
    }

    private void assertError(LotteryErrorCode code) {
        assertThatThrownBy(() -> service.load(1L)).isInstanceOfSatisfying(
                BusinessException.class,
                error -> assertThat(error.getErrorCode()).isEqualTo(code));
    }
}

package com.dongqh.luckyhub.service.lottery;

import com.dongqh.luckyhub.domain.context.auth.LoginContext;
import com.dongqh.luckyhub.domain.model.auth.LoginPrincipal;
import com.dongqh.luckyhub.service.drawchance.DrawChanceService;
import com.dongqh.luckyhub.domain.dto.lottery.DrawCommand;
import com.dongqh.luckyhub.enums.lottery.DrawOrderStatus;
import com.dongqh.luckyhub.enums.lottery.DrawResultType;
import com.dongqh.luckyhub.domain.quota.lottery.DrawQuotaKeys;
import com.dongqh.luckyhub.domain.quota.lottery.DrawQuotaService;
import com.dongqh.luckyhub.domain.quota.lottery.QuotaReservationRequest;
import com.dongqh.luckyhub.domain.vo.lottery.DrawOrderView;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.UUID;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest
class LotteryOrchestrationIntegrationTests {
    private static final long USER_ID = 987654321L;
    @Autowired private LotteryService lotteryService;
    @Autowired private JdbcTemplate jdbcTemplate;
    @Autowired private StringRedisTemplate redisTemplate;
    @Autowired private DrawQuotaService quotaService;
    @Autowired private DrawChanceService drawChanceService;
    private String requestId;
    private Long activityId;
    private DrawOrderView result;
    private LocalDate retainedQuotaDate;
    private LocalDate originalQuotaDate;
    private boolean insertedUser;

    @AfterEach
    void cleanUpExactRows() {
        LoginContext.clear();
        if (requestId != null) {
            jdbcTemplate.update("DELETE FROM message_outbox WHERE aggregate_id IN "
                    + "(SELECT CAST(id AS CHAR) FROM lottery_draw_order WHERE request_id = ?)", requestId);
            jdbcTemplate.update("DELETE FROM lottery_draw_record WHERE request_id = ?", requestId);
            jdbcTemplate.update("DELETE FROM lottery_draw_order WHERE request_id = ?", requestId);
            redisTemplate.delete(DrawQuotaKeys.reservation(requestId));
            redisTemplate.opsForZSet().remove(DrawQuotaKeys.reservationTimeouts(), requestId);
            jdbcTemplate.update("DELETE FROM draw_chance_ledger WHERE user_id=?", USER_ID);
            jdbcTemplate.update("DELETE FROM draw_chance_reservation WHERE request_id=?", requestId);
            jdbcTemplate.update("DELETE FROM draw_chance_account WHERE user_id=?", USER_ID);
        }
        if (result != null) {
            redisTemplate.delete(DrawQuotaKeys.quota(activityId, USER_ID, result.drawDate()));
        }
        if (retainedQuotaDate != null && activityId != null) {
            redisTemplate.delete(DrawQuotaKeys.quota(activityId, USER_ID, retainedQuotaDate));
        }
        if (originalQuotaDate != null && activityId != null) {
            redisTemplate.delete(DrawQuotaKeys.quota(activityId, USER_ID, originalQuotaDate));
        }
        if (activityId != null) {
            jdbcTemplate.update("DELETE FROM marketing_activity WHERE id = ?", activityId);
        }
        if (insertedUser) jdbcTemplate.update("DELETE FROM sys_user WHERE id=?", USER_ID);
    }

    @Test
    void nineRewardedChancesExtendOneFreeDailyChanceToARealTenDraw() {
        jdbcTemplate.update("INSERT INTO sys_user(id,username,password,nickname,status) VALUES(?,?,?,?,1)",
                USER_ID, "rewarded-" + UUID.randomUUID(), "x", "奖励次数集成测试");
        insertedUser = true;
        activityId = insertNoWinActivity();
        jdbcTemplate.update("UPDATE marketing_activity SET daily_limit=1 WHERE id=?", activityId);
        requestId = UUID.randomUUID().toString();
        drawChanceService.credit(USER_ID, "integration-reward-" + requestId, 9);
        LoginContext.set(new LoginPrincipal(USER_ID, "integration", "session"));

        result = lotteryService.draw(new DrawCommand(requestId, activityId, 10));

        assertThat(result.status()).isEqualTo(DrawOrderStatus.SUCCESS);
        assertThat(result.results()).hasSize(10);
        assertThat(drawChanceService.get(USER_ID).availableBalance()).isZero();
        assertThat(drawChanceService.get(USER_ID).reservedBalance()).isEqualTo(9);
        assertThat(redisTemplate.opsForValue().get(
                DrawQuotaKeys.quota(activityId, USER_ID, result.drawDate()))).isEqualTo("10");
    }

    @Test
    void realRedisAndMysqlTenDrawIsAtomicIdempotentAndReturnsTenExactResults() {
        activityId = insertNoWinActivity();
        requestId = UUID.randomUUID().toString();
        LoginContext.set(new LoginPrincipal(USER_ID, "integration", "session"));
        DrawCommand command = new DrawCommand(requestId, activityId, 10);

        result = lotteryService.draw(command);
        DrawOrderView retry = lotteryService.draw(command);

        assertThat(result.status()).isEqualTo(DrawOrderStatus.SUCCESS);
        assertThat(result.results()).hasSize(10)
                .allMatch(item -> item.resultType() == DrawResultType.NO_WIN);
        assertThat(retry).isEqualTo(result);
        assertThat(jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM lottery_draw_order WHERE request_id = ?", Integer.class, requestId))
                .isOne();
        assertThat(jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM lottery_draw_record WHERE request_id = ?", Integer.class, requestId))
                .isEqualTo(10);
        assertThat(redisTemplate.opsForValue().get(
                DrawQuotaKeys.quota(activityId, USER_ID, result.drawDate()))).isEqualTo("10");
        assertThat(jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM message_outbox WHERE aggregate_id = ? AND event_type = 'DRAW_CONFIRMED'",
                Integer.class, Long.toString(result.orderId()))).isOne();
    }

    @Test
    void releasedRedisReservationCannotBypassFinalStateAfterMidnightAndPolicyChange() {
        activityId = insertNoWinActivity();
        requestId = UUID.randomUUID().toString();
        retainedQuotaDate = LocalDate.now().minusDays(1);
        LoginContext.set(new LoginPrincipal(USER_ID, "integration", "session"));
        originalQuotaDate = quotaService.reserve(
                new QuotaReservationRequest(requestId, activityId, USER_ID, 10, 10)).drawDate();
        quotaService.release(requestId);
        redisTemplate.opsForHash().put(DrawQuotaKeys.reservation(requestId), "drawDate",
                DateTimeFormatter.BASIC_ISO_DATE.format(retainedQuotaDate));
        jdbcTemplate.update("UPDATE marketing_activity SET daily_limit = 1 WHERE id = ?", activityId);

        assertThatThrownBy(() -> result = lotteryService.draw(new DrawCommand(requestId, activityId, 10)))
                .isInstanceOfSatisfying(com.dongqh.luckyhub.common.exception.BusinessException.class,
                        error -> assertThat(error.getErrorCode())
                                .isEqualTo(com.dongqh.luckyhub.enums.lottery.LotteryErrorCode.DRAW_ORDER_FAILED));

        assertThat(jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM lottery_draw_order WHERE request_id = ?", Integer.class, requestId))
                .isZero();
        assertThat(jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM lottery_draw_record WHERE request_id = ?", Integer.class, requestId))
                .isZero();
        assertThat(redisTemplate.opsForHash().get(
                DrawQuotaKeys.reservation(requestId), "status")).isEqualTo("RELEASED");
    }

    private long insertNoWinActivity() {
        GeneratedKeyHolder keyHolder = new GeneratedKeyHolder();
        jdbcTemplate.update(connection -> {
            PreparedStatement statement = connection.prepareStatement("""
                    INSERT INTO marketing_activity
                        (activity_name, status, start_time, end_time, daily_limit,
                         no_win_weight, created_by)
                    VALUES (?, 'RUNNING', NOW(3) - INTERVAL 1 HOUR,
                            NOW(3) + INTERVAL 1 HOUR, 10, 100, 1)
                    """, Statement.RETURN_GENERATED_KEYS);
            statement.setString(1, "task10-real-" + UUID.randomUUID());
            return statement;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }
}

package com.dongqh.luckyhub.service.lottery;

import com.dongqh.luckyhub.mapper.activity.MarketingActivityPrizeMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.transaction.annotation.Transactional;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.LocalDateTime;
import java.util.stream.IntStream;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
@Transactional
class LotteryPrizeMapperIntegrationTests {
    @Autowired MarketingActivityPrizeMapper mapper;
    @Autowired JdbcTemplate jdbc;

    @Test
    void disabledFirstHundredCannotHideLaterEnabledRowsAndResultIsOrderedAndBounded() {
        long activityId = insertActivity();
        for (int i = 1; i <= 101; i++) {
            insertRelation(activityId, insertPrize("禁用奖品" + i, 0), i, 1);
        }
        insertRelation(activityId, insertPrize("零库存奖品", 1), 0, 0);
        for (int i = 0; i < 105; i++) {
            insertRelation(activityId, insertPrize("启用奖品" + i, 1), 102 + i, 1);
        }

        var result = mapper.selectVisiblePrizeViews(activityId);

        assertThat(result).hasSize(100);
        assertThat(result).extracting(view -> view.prizeName())
                .containsExactlyElementsOf(IntStream.range(0, 100).mapToObj(i -> "启用奖品" + i).toList());
        assertThat(result).extracting(view -> view.sortOrder())
                .containsExactlyElementsOf(IntStream.range(102, 202).boxed().toList());
        assertThat(result).allSatisfy(view -> {
            assertThat(view.prizeId()).isPositive();
            assertThat(view.prizeType().name()).isEqualTo("PHYSICAL");
        });
    }

    private long insertActivity() {
        return insert("""
                INSERT INTO marketing_activity
                    (activity_name,status,start_time,end_time,daily_limit,no_win_weight,created_by)
                VALUES (?,?,?,?,?,?,?)
                """, "Task2 mapper contract", "RUNNING", LocalDateTime.now().minusHours(1),
                LocalDateTime.now().plusHours(1), 10, 1, 1L);
    }

    private long insertPrize(String name, int status) {
        return insert("""
                INSERT INTO marketing_prize(prize_name,prize_type,prize_level,status)
                VALUES (?, 'PHYSICAL', 'FIRST', ?)
                """, name, status);
    }

    private void insertRelation(long activityId, long prizeId, int sortOrder, int remainingStock) {
        jdbc.update("""
                INSERT INTO marketing_activity_prize
                    (activity_id,prize_id,weight,total_stock,remaining_stock,sort_order)
                VALUES (?,?,?,?,?,?)
                """, activityId, prizeId, 1, 1, remainingStock, sortOrder);
    }

    private long insert(String sql, Object... args) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(connection -> {
            PreparedStatement statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS);
            for (int i = 0; i < args.length; i++) statement.setObject(i + 1, args[i]);
            return statement;
        }, keys);
        return keys.getKey().longValue();
    }
}

