    private long createUser() {
        SysUser user = new SysUser();
        user.setUsername("po-" + UUID.randomUUID());
        user.setPassword("test-password");
        user.setNickname("实物下单用户");
        user.setStatus(1);
        users.insert(user);
        userIds.add(user.getId());
        return user.getId();
