import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ShippingAddressControllerTests {

    @Autowired MockMvc mvc;
    @MockitoBean ShippingAddressService service;
    @MockitoBean JwtService jwt;
    @MockitoBean SessionService sessions;
    @MockitoBean UserPermissionService permissions;

    @BeforeEach
    void caller() {
        when(jwt.parse("token")).thenReturn(new JwtPayload(77L, "shipping-user", "session"));
        when(sessions.isValid("session", 77L)).thenReturn(true);
    }

    @Test
    void exposesAllAddressOperationsWithOnlyMaskedResponseFields() throws Exception {
        when(permissions.findPermissionCodes(77L)).thenReturn(Set.of(PermissionCodes.SHIPPING_ADDRESS_MANAGE));
        when(service.create(eq(77L), any())).thenReturn(view());
        when(service.list(77L)).thenReturn(List.of(view()));
        when(service.update(eq(77L), eq(9L), any())).thenReturn(view());
        when(service.makeDefault(77L, 9L)).thenReturn(view());

        assertMasked(mvc.perform(post("/api/shipping/addresses").header("Authorization", "Bearer token")
                .contentType(MediaType.APPLICATION_JSON).content(body())).andExpect(status().isCreated()));
        assertMasked(mvc.perform(get("/api/shipping/addresses").header("Authorization", "Bearer token"))
                .andExpect(status().isOk()), "$.data[0]");
        assertMasked(mvc.perform(put("/api/shipping/addresses/9").header("Authorization", "Bearer token")
                .contentType(MediaType.APPLICATION_JSON).content(body())).andExpect(status().isOk()));
        assertMasked(mvc.perform(put("/api/shipping/addresses/9/default").header("Authorization", "Bearer token"))
                .andExpect(status().isOk()));
        mvc.perform(delete("/api/shipping/addresses/9").header("Authorization", "Bearer token"))
                .andExpect(status().isOk()).andExpect(jsonPath("$.data").doesNotExist());

        verify(service).delete(77L, 9L);
    }

    @Test
    void requiresAuthenticationAndExactPermissionOnEveryAddressRoute() throws Exception {
        when(permissions.findPermissionCodes(77L)).thenReturn(Set.of());
        for (MockHttpServletRequestBuilder request : List.of(
                post("/api/shipping/addresses").contentType(MediaType.APPLICATION_JSON).content(body()),
                get("/api/shipping/addresses"),
                put("/api/shipping/addresses/9").contentType(MediaType.APPLICATION_JSON).content(body()),
                delete("/api/shipping/addresses/9"),
                put("/api/shipping/addresses/9/default"))) {
            mvc.perform(request).andExpect(status().isUnauthorized());
            mvc.perform(request.header("Authorization", "Bearer token")).andExpect(status().isForbidden());
        }
        when(permissions.findPermissionCodes(77L)).thenReturn(Set.of(PermissionCodes.SHIPPING_READ));
        mvc.perform(get("/api/shipping/addresses").header("Authorization", "Bearer token"))
                .andExpect(status().isForbidden());
    }

    @Test
    void validatesCommandsAndPositiveIds() throws Exception {
        when(permissions.findPermissionCodes(77L)).thenReturn(Set.of(PermissionCodes.SHIPPING_ADDRESS_MANAGE));
        mvc.perform(post("/api/shipping/addresses").header("Authorization", "Bearer token")
                        .contentType(MediaType.APPLICATION_JSON).content(body().replace("13812345678", "123")))
                .andExpect(status().isBadRequest());
        mvc.perform(delete("/api/shipping/addresses/0").header("Authorization", "Bearer token"))
                .andExpect(status().isBadRequest());
    }

    private org.springframework.test.web.servlet.ResultActions assertMasked(
            org.springframework.test.web.servlet.ResultActions result) throws Exception {
        return assertMasked(result, "$.data");
    }

    private org.springframework.test.web.servlet.ResultActions assertMasked(
            org.springframework.test.web.servlet.ResultActions result, String path) throws Exception {
        return result.andExpect(jsonPath(path + ".receiverMasked").value("张*"))
                .andExpect(jsonPath(path + ".phoneMasked").value("138****5678"))
                .andExpect(jsonPath(path + ".regionMasked").value("浙江省杭州市余杭区***"))
                .andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("张三"))))
                .andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("13812345678"))))
                .andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("ciphertext"))));
    }

    private ShippingAddressView view() {
        return new ShippingAddressView(9L, "张*", "138****5678", "浙江省杭州市余杭区***",
                true, AddressStatus.ACTIVE, LocalDateTime.now(), LocalDateTime.now());
    }

    private String body() {
        return """
                {"receiverName":"张三","phone":"13812345678","province":"浙江省",
                 "city":"杭州市","district":"余杭区","detail":"文一西路1号","defaultAddress":true}
                """;
    }
}

package com.dongqh.luckyhub.shipping;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.po.rbac.SysUser;
import com.dongqh.luckyhub.mapper.rbac.SysUserMapper;
import com.dongqh.luckyhub.domain.dto.shipping.CreateShippingAddressCommand;
import com.dongqh.luckyhub.domain.dto.shipping.UpdateShippingAddressCommand;
import com.dongqh.luckyhub.domain.po.shipping.UserShippingAddress;
import com.dongqh.luckyhub.enums.shipping.AddressStatus;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.mapper.shipping.UserShippingAddressMapper;
import com.dongqh.luckyhub.service.shipping.ShippingAddressService;
import com.dongqh.luckyhub.domain.vo.shipping.ShippingAddressView;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@SpringBootTest
class ShippingAddressServiceTests {

    @Autowired ShippingAddressService service;
    @Autowired UserShippingAddressMapper addressMapper;
    @Autowired SysUserMapper userMapper;
    @Autowired JdbcTemplate jdbc;
    private final List<Long> userIds = new ArrayList<>();

    @AfterEach
    void clean() {
        userIds.forEach(userId -> jdbc.update("DELETE FROM user_shipping_address WHERE user_id=?", userId));
        userIds.forEach(userMapper::deleteById);
        userIds.clear();
    }

    @Test
    void firstAddressBecomesDefaultAndLaterExplicitDefaultAtomicallyReplacesIt() {
        long userId = createUser();
        ShippingAddressView first = service.create(userId, create("张三", "13812345678", false));
        ShippingAddressView second = service.create(userId, create("李四", "13912345678", true));

        assertThat(first.defaultAddress()).isTrue();
        assertThat(second.defaultAddress()).isTrue();
        assertThat(service.list(userId)).extracting(ShippingAddressView::defaultAddress)
                .containsExactly(true, false);
        assertThat(activeDefaultCount(userId)).isEqualTo(1);
    }

    @Test
    void trimsEncryptsAndOnlyReturnsMaskedFields() {
        long userId = createUser();
        ShippingAddressView view = service.create(userId, new CreateShippingAddressCommand(
                " 张三 ", " 13812345678 ", " 浙江省 ", " 杭州市 ", " 余杭区 ", " 文一西路 1 号 ", false));
        UserShippingAddress stored = addressMapper.selectById(view.id());

        assertThat(view.receiverMasked()).isEqualTo("张*");
        assertThat(view.phoneMasked()).isEqualTo("138****5678");
        assertThat(view.regionMasked()).isEqualTo("浙江省杭州市余杭区***");
        assertThat(stored.getReceiverCiphertext()).startsWith("v1.").doesNotContain("张三");
        assertThat(stored.getPhoneCiphertext()).doesNotContain("13812345678");
        assertThat(stored.getProvinceCiphertext()).doesNotContain("浙江省");
        assertThat(stored.getCityCiphertext()).doesNotContain("杭州市");
        assertThat(stored.getDistrictCiphertext()).doesNotContain("余杭区");
        assertThat(stored.getDetailCiphertext()).doesNotContain("文一西路");
    }

    @Test
    void updateReencryptsAllSixFieldsAndCanBecomeDefault() {
        long userId = createUser();
        ShippingAddressView first = service.create(userId, create("张三", "13812345678", false));
        service.create(userId, create("李四", "13912345678", false));
        UserShippingAddress before = addressMapper.selectById(first.id());
        List<String> oldCiphertexts = ciphertexts(before);

        ShippingAddressView updated = service.update(userId, first.id(), new UpdateShippingAddressCommand(
                "张三", "13812345678", "浙江省", "杭州市", "余杭区", "文一西路1号", true));
        UserShippingAddress after = addressMapper.selectById(first.id());

        assertThat(ciphertexts(after)).zipSatisfy(oldCiphertexts,
                (current, old) -> assertThat(current).isNotEqualTo(old));
        assertThat(updated.defaultAddress()).isTrue();
        assertThat(activeDefaultCount(userId)).isEqualTo(1);
    }

    @Test
    void deleteIsSoftClearsDefaultAndRemovesAddressFromReads() {
        long userId = createUser();
        ShippingAddressView created = service.create(userId, create("张三", "13812345678", false));

        service.delete(userId, created.id());

        UserShippingAddress deleted = addressMapper.selectById(created.id());
        assertThat(deleted.getStatus()).isEqualTo(AddressStatus.DELETED);
        assertThat(deleted.getIsDefault()).isZero();
        assertThat(deleted.getDeletedAt()).isNotNull();
        assertThat(service.list(userId)).isEmpty();
        assertError(() -> service.requireOwnedActive(userId, created.id()), ShippingErrorCode.ADDRESS_NOT_FOUND);
    }

    @Test
    void distinguishesAbsentIdsFromCrossUserAccessForAllMutations() {
        long owner = createUser();
        long other = createUser();
        long id = service.create(owner, create("张三", "13812345678", false)).id();
        UpdateShippingAddressCommand update = update("王五", "13712345678", false);

        assertError(() -> service.update(other, id, update), ShippingErrorCode.ADDRESS_ACCESS_DENIED);
        assertError(() -> service.delete(other, id), ShippingErrorCode.ADDRESS_ACCESS_DENIED);
        assertError(() -> service.makeDefault(other, id), ShippingErrorCode.ADDRESS_ACCESS_DENIED);
        assertError(() -> service.requireOwnedActive(other, id), ShippingErrorCode.ADDRESS_ACCESS_DENIED);
        assertError(() -> service.update(owner, Long.MAX_VALUE, update), ShippingErrorCode.ADDRESS_NOT_FOUND);
        assertError(() -> service.delete(owner, Long.MAX_VALUE), ShippingErrorCode.ADDRESS_NOT_FOUND);
        assertError(() -> service.makeDefault(owner, Long.MAX_VALUE), ShippingErrorCode.ADDRESS_NOT_FOUND);
        assertError(() -> service.requireOwnedActive(owner, Long.MAX_VALUE), ShippingErrorCode.ADDRESS_NOT_FOUND);
    }

    @Test
    void concurrentFirstAddressCreationLeavesExactlyOneDefault() throws Exception {
        long userId = createUser();
        runConcurrently(
                () -> service.create(userId, create("张三", "13812345678", false)),
                () -> service.create(userId, create("李四", "13912345678", false)));
        assertThat(service.list(userId)).hasSize(2);
        assertThat(activeDefaultCount(userId)).isEqualTo(1);
    }

    @Test
    void concurrentDefaultChangesLeaveExactlyOneDefault() throws Exception {
        long userId = createUser();
        long first = service.create(userId, create("张三", "13812345678", false)).id();
        long second = service.create(userId, create("李四", "13912345678", false)).id();
        runConcurrently(() -> service.makeDefault(userId, first), () -> service.makeDefault(userId, second));
        assertThat(activeDefaultCount(userId)).isEqualTo(1);
    }

    private void runConcurrently(Runnable first, Runnable second) throws Exception {
        var pool = Executors.newFixedThreadPool(2);
        var ready = new CountDownLatch(2);
        var go = new CountDownLatch(1);
        try {
            Future<?> one = pool.submit(() -> { ready.countDown(); await(go); first.run(); });
            Future<?> two = pool.submit(() -> { ready.countDown(); await(go); second.run(); });
            ready.await();
            go.countDown();
            one.get();
            two.get();
        } finally {
            pool.shutdownNow();
        }
    }

    private void await(CountDownLatch latch) {
        try { latch.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); throw new IllegalStateException(e); }
    }

    private long createUser() {
        SysUser user = new SysUser();
        user.setUsername("shipping-" + UUID.randomUUID());
        user.setPassword("test-password");
        user.setNickname("收货用户");
        user.setStatus(1);
        userMapper.insert(user);
        userIds.add(user.getId());
        return user.getId();
    }

    private CreateShippingAddressCommand create(String name, String phone, boolean isDefault) {
        return new CreateShippingAddressCommand(name, phone, "浙江省", "杭州市", "余杭区", "文一西路1号", isDefault);
    }

    private UpdateShippingAddressCommand update(String name, String phone, boolean isDefault) {
        return new UpdateShippingAddressCommand(name, phone, "浙江省", "杭州市", "余杭区", "文一西路2号", isDefault);
    }

    private List<String> ciphertexts(UserShippingAddress address) {
        return List.of(address.getReceiverCiphertext(), address.getPhoneCiphertext(), address.getProvinceCiphertext(),
                address.getCityCiphertext(), address.getDistrictCiphertext(), address.getDetailCiphertext());
    }

    private int activeDefaultCount(long userId) {
        return addressMapper.selectCount(new LambdaQueryWrapper<UserShippingAddress>()
                .eq(UserShippingAddress::getUserId, userId)
                .eq(UserShippingAddress::getStatus, AddressStatus.ACTIVE)
                .eq(UserShippingAddress::getIsDefault, 1)).intValue();
    }

    private void assertError(Runnable action, ShippingErrorCode code) {
        assertThatThrownBy(action::run).isInstanceOfSatisfying(BusinessException.class,
                exception -> assertThat(exception.getErrorCode()).isEqualTo(code));
    }
}

package com.dongqh.luckyhub.shipping;

import com.dongqh.luckyhub.common.exception.BusinessException;
import com.dongqh.luckyhub.domain.hmall.integration.HmallAddressClient;
import com.dongqh.luckyhub.domain.hmall.integration.HmallAddressView;
import com.dongqh.luckyhub.domain.po.rbac.SysUser;
import com.dongqh.luckyhub.mapper.rbac.SysUserMapper;
import com.dongqh.luckyhub.domain.dto.shipping.CreateShippingAddressCommand;
import com.dongqh.luckyhub.domain.po.shipping.ShippingAddressSnapshot;
import com.dongqh.luckyhub.enums.shipping.ShippingErrorCode;
import com.dongqh.luckyhub.enums.shipping.ShippingSourceType;
import com.dongqh.luckyhub.service.shipping.ShippingAddressService;
import com.dongqh.luckyhub.service.shipping.ShippingAddressSnapshotService;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.when;

@SpringBootTest
class ShippingAddressSnapshotTests {
    @Autowired ShippingAddressService addresses;
    @Autowired ShippingAddressSnapshotService snapshots;
    @Autowired SysUserMapper userMapper;
    @Autowired JdbcTemplate jdbc;
    @MockitoBean HmallAddressClient hmallAddresses;
    private final List<Long> userIds = new ArrayList<>();

    @AfterEach
    void clean() {
        userIds.forEach(id -> jdbc.update("DELETE FROM shipping_address_snapshot WHERE user_id=?", id));
        userIds.forEach(id -> jdbc.update("DELETE FROM user_shipping_address WHERE user_id=?", id));
        userIds.forEach(userMapper::deleteById);
        userIds.clear();
    }

    @Test
    void copiesCiphertextWithoutDecryptingAndRemainsImmutableAfterAddressChanges() {
        long userId = createUser();
        long addressId = addresses.create(userId, address("张三", "杭州市", "文一西路1号")).id();
        stubAddress(addressId, "张三", "13812345678", "杭州市", "文一西路1号");
        String sourceId = businessId("cash");

        ShippingAddressSnapshot created = snapshots.create(
                userId, addressId, ShippingSourceType.CASH_ORDER, sourceId);
        var originalCiphertexts = ciphertexts(created);
        var originalMasked = List.of(created.getReceiverMasked(), created.getPhoneMasked(), created.getRegionMasked());

        addresses.update(userId, addressId, new com.dongqh.luckyhub.domain.dto.shipping.UpdateShippingAddressCommand(
                "李四", "13912345678", "上海市", "上海市", "浦东新区", "世纪大道2号", true));
        addresses.delete(userId, addressId);
        ShippingAddressSnapshot unchanged = snapshots.require(created.getId());

        assertThat(ciphertexts(unchanged)).isEqualTo(originalCiphertexts);
        assertThat(List.of(unchanged.getReceiverMasked(), unchanged.getPhoneMasked(), unchanged.getRegionMasked()))
                .isEqualTo(originalMasked).containsExactly("张*", "138****5678", "浙江省杭州市余杭区***");
        assertThat(jdbc.queryForObject("""
                SELECT COUNT(*) FROM shipping_address_snapshot
                WHERE user_id=? AND source_type=? AND source_id=?
                """, Integer.class, userId, ShippingSourceType.CASH_ORDER.name(), sourceId)).isOne();
    }

    @Test
    void duplicateSourceReturnsEqualSnapshotButRejectsChangedOriginOrContents() {
        long userId = createUser();
        long first = addresses.create(userId, address("张三", "杭州市", "文一西路1号")).id();
        long second = addresses.create(userId, address("李四", "杭州市", "文一西路2号")).id();
        stubAddress(first, "张三", "13812345678", "杭州市", "文一西路1号");
        stubAddress(second, "李四", "13812345678", "杭州市", "文一西路2号");
        String sourceId = businessId("points");
        ShippingAddressSnapshot created = snapshots.create(
                userId, first, ShippingSourceType.POINTS_REDEMPTION, sourceId);

        assertThat(snapshots.create(userId, first, ShippingSourceType.POINTS_REDEMPTION, sourceId).getId())
                .isEqualTo(created.getId());
        assertError(() -> snapshots.create(userId, second, ShippingSourceType.POINTS_REDEMPTION, sourceId));
        addresses.update(userId, first, new com.dongqh.luckyhub.domain.dto.shipping.UpdateShippingAddressCommand(
                "王五", "13712345678", "浙江省", "杭州市", "余杭区", "未来科技城3号", false));
        stubAddress(first, "王五", "13712345678", "杭州市", "未来科技城3号");
        assertError(() -> snapshots.create(userId, first, ShippingSourceType.POINTS_REDEMPTION, sourceId));
    }

    private void stubAddress(long id, String contact, String mobile, String city, String street) {
        when(hmallAddresses.getAddress(id)).thenReturn(new HmallAddressView(
                id, "浙江省", city, "余杭区", mobile, street, contact, 0, null));
    }

    private long createUser() {
        SysUser user = new SysUser();
        user.setUsername("snapshot-" + UUID.randomUUID());
        user.setPassword("test-password");
        user.setNickname("快照用户");
        user.setStatus(1);
        userMapper.insert(user);
        userIds.add(user.getId());
        return user.getId();
    }

    private CreateShippingAddressCommand address(String receiver, String city, String detail) {
        return new CreateShippingAddressCommand(receiver, "13812345678", "浙江省", city,
                "余杭区", detail, false);
    }

    private String businessId(String prefix) {
        return prefix + "-" + UUID.randomUUID();
    }

    private List<String> ciphertexts(ShippingAddressSnapshot snapshot) {
        return List.of(snapshot.getReceiverCiphertext(), snapshot.getPhoneCiphertext(),
                snapshot.getProvinceCiphertext(), snapshot.getCityCiphertext(),
                snapshot.getDistrictCiphertext(), snapshot.getDetailCiphertext());
    }

    private void assertError(Runnable action) {
        assertThatThrownBy(action::run).isInstanceOfSatisfying(BusinessException.class,
                exception -> assertThat(exception.getErrorCode())
                        .isEqualTo(ShippingErrorCode.SHIPPING_IDEMPOTENCY_CONFLICT));
    }
}

