BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM information_schema.columns
         WHERE table_schema = 'hmall'
           AND table_name = 'user'
           AND column_name = 'role'
    ) THEN
        ALTER TABLE `user`
            ADD COLUMN `role` VARCHAR(20) NOT NULL DEFAULT 'USER';
    END IF;
END//
DELIMITER ;

CALL ensure_hmall_user_role();
DROP PROCEDURE ensure_hmall_user_role;

UPDATE `user`
   SET `role` = 'ADMIN'
 WHERE `id` = 1;

