import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Update;

import java.time.LocalDateTime;
import java.util.List;

public interface PayMessageOutboxMapper extends BaseMapper<PayMessageOutbox> {
    @Select("""
            SELECT * FROM pay_message_outbox
            WHERE status='PENDING'
               OR (status='FAILED' AND (next_retry_at IS NULL OR next_retry_at<=#{now}))
               OR (status='PROCESSING' AND next_retry_at<=#{now})
            ORDER BY id LIMIT #{limit}
            """)
    List<PayMessageOutbox> selectRelayCandidates(@Param("now") LocalDateTime now,
                                                 @Param("limit") int limit);

    @Update("""
            UPDATE pay_message_outbox
            SET status='PROCESSING',claim_token=#{token},next_retry_at=#{leaseUntil}
            WHERE id=#{id} AND (status='PENDING'
              OR (status='FAILED' AND (next_retry_at IS NULL OR next_retry_at<=#{now}))
              OR (status='PROCESSING' AND next_retry_at<=#{now}))
            """)
    int claim(@Param("id") long id, @Param("token") String token,
              @Param("now") LocalDateTime now, @Param("leaseUntil") LocalDateTime leaseUntil);

    @Update("""
            UPDATE pay_message_outbox SET status='SENT',sent_at=#{sentAt},last_error=NULL,
              claim_token=NULL,next_retry_at=NULL
            WHERE id=#{id} AND status='PROCESSING' AND claim_token=#{token}
            """)
    int markSent(@Param("id") long id, @Param("token") String token,
                 @Param("sentAt") LocalDateTime sentAt);

    @Update("""
            UPDATE pay_message_outbox SET status='FAILED',retry_count=retry_count+1,
              last_error=#{error},claim_token=NULL,next_retry_at=#{nextRetryAt}
            WHERE id=#{id} AND status='PROCESSING' AND claim_token=#{token}
            """)
    int markFailed(@Param("id") long id, @Param("token") String token,
                   @Param("error") String error, @Param("nextRetryAt") LocalDateTime nextRetryAt);
}

