function cashier(axios) {
  let options;
  const context = {
    Vue: function(config) { options = config; }, axios,
    util: { store: {get() {}, set() {}}, getUrlParam() { return '42'; } },
    location: {}, alert() {}, confirm() { return true; }, console,
    setInterval, clearInterval, setTimeout, clearTimeout
  };
  const html = fs.readFileSync(path.join(portal, 'pay.html'), 'utf8');
  const code = [...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/gi)].map(m => m[1]).join('\n');
  vm.runInNewContext(code, context);
  const app = options.data();
  Object.entries(options.methods).forEach(([name, fn]) => { app[name] = fn.bind(app); });
  app.order = {id:'42', status:1, totalFee:1300, couponId:null, paymentType:3};
  return {app, context};
}

test('cashier loads applicable coupons from owned order items, never session cart', async () => {
  const {app} = cashier({
    get: async url => { assert.equal(url, '/orders/42/checkout-items'); return [{itemId:'561178',num:1}]; },
    post: async (url, body) => {
      assert.equal(url, '/marketing/coupons/checkout/applicable');
      assert.equal(body.items[0].itemId, '561178');
      assert.equal(body.items[0].quantity, 1);
      return {data:[{userCouponId:'2096098706886033409',discountCent:150}]};
    }
  });
  await app.loadCheckoutCoupons();
  assert.equal(app.applicableCoupons[0].userCouponId, '2096098706886033409');
  assert.equal(app.couponLoading, false);
});

test('apply coupon preserves exact ID and trusts server price before reissuing payment', async () => {
  const {app} = cashier({put: async (url, body) => {
    assert.equal(url, '/orders/42/coupon');
    assert.equal(body.couponId, '2096098706886033409');
    assert.deepEqual(Object.keys(body), ['couponId']);
    return {id:'42',status:1,couponId:body.couponId,totalFee:1150,couponDiscountFee:150,paymentType:3};
  }});
  app.selectedCouponId = '2096098706886033409';
  app.payOrderNo = 'old-payment';
  let issued = false;
  app.createPayOrder = async () => {
    assert.equal(app.order.totalFee, 1150);
    assert.equal(app.payOrderNo, '');
    issued = true;
  };
  await app.applyCoupon();
  assert.equal(issued, true);
  assert.equal(app.order.couponId, '2096098706886033409');
});

test('failed coupon application never enables payment with an old payment number', async () => {
  const {app} = cashier({put: async () => { throw new Error('offline'); }});
  app.selectedCouponId = '2096098706886033409';
  app.payOrderNo = 'old-payment';
  await app.applyCoupon();
  assert.equal(app.payOrderNo, '');
  assert.ok(app.couponError);
});

test('payment is blocked while a selected coupon has not been applied', async () => {
  let paid = false;
  const {app} = cashier({post:async () => {paid = true;}});
  app.selectedCouponId = '2096098706886033409';
  app.payOrderNo = 'old-payment';
  await app.payByBalance();
  assert.equal(paid, false);
});

test('late response from the old payment quote cannot overwrite the refreshed payment', async () => {
  let resolveOld;
  let calls = 0;
  const {app} = cashier({post: () => {
    calls++;
    return calls === 1 ? new Promise(resolve => {resolveOld = resolve;}) : Promise.resolve('new-payment');
  }});
  const pending = app.createPayOrder('42');
  await app.createPayOrder('42');
  resolveOld('old-payment');
  await pending;
  assert.equal(app.payOrderNo, 'new-payment');
});

test('terminal orders cannot initiate another payment or coupon change', async () => {
  let writes = 0;
  const {app} = cashier({post:async () => {writes++;},put:async () => {writes++;}});
  app.order.status = 2;
  app.selectedCouponId = '2096098706886033409';
  await app.applyCoupon();
  await app.createPayOrder('42');
  await app.payByBalance();
  assert.equal(writes, 0);
});

test('coupon discovery outage still permits original-price balance payment', async () => {
  const posted = [];
  const order = {id:'42',status:1,totalFee:1300,couponId:null,paymentType:3,createTime:new Date().toISOString()};
  const {app} = cashier({
    get: async url => {
      if (url === '/orders/42') return order;
      if (url === '/orders/42/checkout-items') throw new Error('marketing unavailable');
      throw new Error('unexpected '+url);
    },
    post: async url => { posted.push(url); return url === '/pay-orders' ? 'original-payment' : null; }
  });
  await app.refreshCheckout();
  assert.ok(app.couponQueryError);
  assert.equal(app.couponError, '');
  assert.equal(app.payOrderNo, 'original-payment');
  app.password = 'not-a-real-secret';
  await app.payByBalance();
  assert.deepEqual(posted, ['/pay-orders', '/pay-orders/original-payment']);
  clearInterval(app.countdownTimer);
});

test('checkout refresh is single-flight so stale order cannot overwrite coupon state', async () => {
  let resolveOrder;
  let orderReads = 0;
  const {app} = cashier({
    get: url => {
      if (url === '/orders/42') {
        orderReads++;
        return new Promise(resolve => { resolveOrder = resolve; });
      }
      return Promise.resolve([]);
    },
    post: async url => url === '/pay-orders' ? 'payment' : {data:[]}
  });
  const first = app.refreshCheckout();
  const second = app.refreshCheckout();
  assert.equal(orderReads, 1);
  resolveOrder({id:'42',status:2,totalFee:1150,couponId:'9',paymentType:3,createTime:new Date().toISOString()});
  await Promise.all([first, second]);
  assert.equal(app.order.couponId, '9');
});

import re
import unittest
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
GATEWAY_CONFIG = ROOT / "hm-gateway/src/main/resources/application.yaml"


def route_block(application, route_id):
    match = re.search(
        rf"(?ms)^\s+- id: {re.escape(route_id)}\s+.*?(?=^\s+- id:|\Z)",
        application,
    )
    return match.group(0) if match else None


class ExtractedMarketingGatewayRoutesTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.application = GATEWAY_CONFIG.read_text(encoding="utf-8")

    def assert_routes_before_legacy_fallback(self, route_id, service_uri, path):
        block = route_block(self.application, route_id)
        self.assertIsNotNone(block, f"missing gateway route {route_id}")
        self.assertIn(f"uri: {service_uri}", block)
        self.assertIn(f"- Path={path}", block)
        self.assertLess(
            self.application.index(f"id: {route_id}"),
            self.application.index("id: marketing-legacy"),
        )

    def test_points_api_routes_to_points_service_before_legacy_fallback(self):
        self.assert_routes_before_legacy_fallback(
            "points-service",
            "lb://points-service",
            "/api/points/**,/api/admin/points/**",
        )

    def test_coupon_api_routes_to_coupon_service_before_legacy_fallback(self):
        self.assert_routes_before_legacy_fallback(
            "coupon-service",
            "lb://coupon-service",
            "/api/coupons/**,/api/admin/coupon-templates/**,/api/admin/coupons/**",
        )

    def test_membership_api_routes_to_membership_service_before_legacy_fallback(self):
        self.assert_routes_before_legacy_fallback(
            "membership-service",
            "lb://membership-service",
            "/api/memberships/**,/api/admin/membership-products/**",
        )

    def test_lottery_and_benefit_apis_route_to_lottery_service_before_legacy_fallback(self):
        self.assert_routes_before_legacy_fallback(
            "lottery-service",
            "lb://lottery-service",
            "/api/lottery/**,/api/benefits/**,/api/admin/activities/**,/api/admin/prizes/**,"
            "/api/admin/prize-images/**,/api/admin/reward-definitions/**",
        )


if __name__ == "__main__":
    unittest.main()

from pathlib import Path
import unittest
import xml.etree.ElementTree as ET


ROOT = Path(__file__).resolve().parents[1]
NS = {"m": "http://maven.apache.org/POM/4.0.0"}


def parse_pom(path: str) -> ET.Element:
    return ET.parse(ROOT / path).getroot()


def value(node: ET.Element, path: str) -> str | None:
    found = node.find(path, NS)
    return found.text.strip() if found is not None and found.text else None


class HmApiContractTest(unittest.TestCase):
    def test_reactor_contains_hm_api_before_cart(self):
        modules = [node.text.strip() for node in parse_pom("pom.xml").findall("m:modules/m:module", NS)]
        self.assertIn("hm-api", modules)
        self.assertLess(modules.index("hm-api"), modules.index("cart-service"))

    def test_hm_api_inherits_the_java_17_hmall_baseline(self):
        root = parse_pom("pom.xml")
        api = parse_pom("hm-api/pom.xml")
        parent = api.find("m:parent", NS)
        self.assertIsNotNone(parent)
        self.assertEqual("com.heima", value(parent, "m:groupId"))
        self.assertEqual("hmall", value(parent, "m:artifactId"))
        self.assertEqual("1.0.0", value(parent, "m:version"))
        self.assertEqual("../mall-backend/pom.xml", value(parent, "m:relativePath"))
        self.assertEqual("hm-api", value(api, "m:artifactId"))
        self.assertEqual("17", value(root, "m:properties/m:java.version"))

    def test_hm_api_is_a_non_runnable_openfeign_contract_jar(self):
        api = parse_pom("hm-api/pom.xml")
        dependencies = {
            (value(node, "m:groupId"), value(node, "m:artifactId"))
            for node in api.findall("m:dependencies/m:dependency", NS)
        }
        self.assertEqual(
            {
                ("org.springframework.cloud", "spring-cloud-starter-openfeign"),
                ("com.heima", "hm-common"),
            },
            dependencies,
        )
        self.assertIsNone(api.find("m:build/m:plugins/m:plugin", NS))
        self.assertFalse((ROOT / "hm-api/src/main/java/com/dongqh/hmapi/HmApiApplication.java").exists())
        self.assertFalse((ROOT / "hm-api/src/main/resources/application.yaml").exists())
        self.assertFalse((ROOT / "hm-api/src/test/java/com/dongqh/hmapi/HmApiApplicationTests.java").exists())

    def test_contract_is_self_contained_and_has_no_swagger_dependency(self):
        client = (ROOT / "hm-api/src/main/java/com/dongqh/hmapi/client/ItemClient.java").read_text("utf-8")
        dto = (ROOT / "hm-api/src/main/java/com/dongqh/hmapi/dto/ItemDTO.java").read_text("utf-8")
        self.assertIn("com.dongqh.hmapi.dto.ItemDTO", client)
        self.assertNotIn("cartservice", client)
        self.assertNotIn("io.swagger", dto)

    def test_no_contract_source_depends_on_swagger(self):
        java_root = ROOT / "hm-api/src/main/java"
        offenders = [
            str(path.relative_to(ROOT))
            for path in java_root.rglob("*.java")
            if "io.swagger" in path.read_text(encoding="utf-8")
        ]
        self.assertEqual([], offenders)

    def test_cart_and_user_clients_use_service_owned_paths(self):
        cart = (ROOT / "hm-api/src/main/java/com/dongqh/hmapi/client/CartClient.java").read_text("utf-8")
        user = (ROOT / "hm-api/src/main/java/com/dongqh/hmapi/client/UserClient.java").read_text("utf-8")
        self.assertIn('@DeleteMapping("/carts")', cart)
        self.assertIn('@GetMapping("/addresses/{addressId}")', user)

    def test_cart_consumes_hm_api_without_duplicate_contracts(self):
        cart = parse_pom("cart-service/pom.xml")
        dependencies = {
            (value(node, "m:groupId"), value(node, "m:artifactId"))
            for node in cart.findall("m:dependencies/m:dependency", NS)
        }
        self.assertIn(("com.heima", "hm-api"), dependencies)
        self.assertFalse((ROOT / "cart-service/src/main/java/com/dongqh/cartservice/client/ItemClient.java").exists())
        self.assertFalse((ROOT / "cart-service/src/main/java/com/dongqh/cartservice/domain/dto/ItemDTO.java").exists())

        application = (ROOT / "cart-service/src/main/java/com/dongqh/cartservice/CartServiceApplication.java").read_text("utf-8")
        service = (ROOT / "cart-service/src/main/java/com/dongqh/cartservice/service/impl/CartServiceImpl.java").read_text("utf-8")
        test = (ROOT / "cart-service/src/test/java/com/dongqh/cartservice/CartServiceApplicationTests.java").read_text("utf-8")
        self.assertIn('basePackages = "com.dongqh.hmapi.client"', application)
        self.assertIn("com.dongqh.hmapi.client.ItemClient", service)
        self.assertIn("com.dongqh.hmapi.dto.ItemDTO", service)
        self.assertIn("com.dongqh.hmapi.client.ItemClient", test)
        self.assertIn("com.dongqh.hmapi.dto.ItemDTO", test)


if __name__ == "__main__":
    unittest.main()

from pathlib import Path
import re
import unittest
import xml.etree.ElementTree as ET


ROOT = Path(__file__).resolve().parents[1]
NS = {"m": "http://maven.apache.org/POM/4.0.0"}
MODULES = (
    "mall-backend", "item-service", "hm-api", "hm-gateway", "cart-service",
    "user-service", "trade-service", "pay-service", "marketing-service",
)
SCRATCH_DIRS = {".codex-progress", ".superpowers"}
ROOT_PLATFORM_PROPERTIES = {
    "java.version": "17",
    "maven.compiler.release": "17",
    "spring-cloud.version": "2025.1.0",
    "spring-cloud-alibaba.version": "2025.1.0.0",
    "mybatis-plus.version": "3.5.17",
    "springdoc.version": "3.0.3",
}
CHILD_PLATFORM_PROPERTIES = (
    *ROOT_PLATFORM_PROPERTIES,
    "maven.compiler.source",
    "maven.compiler.target",
)
MANAGED_DEPENDENCY_GROUPS = {
    "org.springframework.boot",
    "org.springframework.cloud",
    "com.alibaba.cloud",
    "com.baomidou",
    "org.springdoc",
}
MANAGED_PLUGINS = {
    ("org.springframework.boot", "spring-boot-maven-plugin"),
    ("org.apache.maven.plugins", "maven-compiler-plugin"),
}
ROOT_MANAGED_DEPENDENCIES = {
    ("org.springframework.cloud", "spring-cloud-dependencies"):
        ("${spring-cloud.version}", "pom", "import"),
    ("com.alibaba.cloud", "spring-cloud-alibaba-dependencies"):
        ("${spring-cloud-alibaba.version}", "pom", "import"),
    ("com.baomidou", "mybatis-plus-spring-boot4-starter"):
        ("${mybatis-plus.version}", None, None),
    ("com.baomidou", "mybatis-plus-jsqlparser"):
        ("${mybatis-plus.version}", None, None),
    ("org.springdoc", "springdoc-openapi-starter-webmvc-ui"):
        ("${springdoc.version}", None, None),
}
ROOT_PARENT = ("com.dongqh", "hmall-lottery", "1.0.0-SNAPSHOT", "../pom.xml")
HMALL_PARENT = ("com.heima", "hmall", "1.0.0", "../mall-backend/pom.xml")
MODULE_PARENT_CHAINS = {
    "mall-backend/pom.xml": ROOT_PARENT,
    "marketing-service/pom.xml": ROOT_PARENT,
    "item-service/pom.xml": HMALL_PARENT,
    "hm-api/pom.xml": HMALL_PARENT,
    "hm-gateway/pom.xml": HMALL_PARENT,
    "cart-service/pom.xml": HMALL_PARENT,
    "user-service/pom.xml": HMALL_PARENT,
    "trade-service/pom.xml": HMALL_PARENT,
    "pay-service/pom.xml": HMALL_PARENT,
    "mall-backend/hm-common/pom.xml": ("com.heima", "hmall", "1.0.0", "../pom.xml"),
    "mall-backend/hm-service/pom.xml": ("com.heima", "hmall", "1.0.0", "../pom.xml"),
}
AUTO_CONFIGURATIONS = (
    "com.hmall.common.config.MyBatisConfig",
    "com.hmall.common.config.MvcConfig",
    "com.hmall.common.config.JsonConfig",
    "com.hmall.common.swagger.OpenApiAutoConfiguration",
)


def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def active_paths(pattern: str):
    return (
        path for path in ROOT.rglob(pattern)
        if path.relative_to(ROOT).parts[0] not in SCRATCH_DIRS
    )


def parent_coordinates(project):
    parent = project.find("m:parent", NS)
    if parent is None:
        return None
    relative_path = parent.find("m:relativePath", NS)
    resolved_relative_path = "../pom.xml" if relative_path is None else (relative_path.text or "").strip()
    return (
        parent.findtext("m:groupId", namespaces=NS),
        parent.findtext("m:artifactId", namespaces=NS),
        parent.findtext("m:version", namespaces=NS),
        resolved_relative_path,
    )


class Java17Boot4UpgradeContractTest(unittest.TestCase):
    def test_root_owns_the_platform_and_all_modules(self):
        root = ET.parse(ROOT / "pom.xml").getroot()
        parent = root.find("m:parent", NS)
        self.assertIsNotNone(parent, "root pom.xml must declare the Spring Boot parent")
        self.assertEqual("org.springframework.boot", parent.findtext("m:groupId", namespaces=NS))
        self.assertEqual("spring-boot-starter-parent", parent.findtext("m:artifactId", namespaces=NS))
        self.assertEqual("4.0.8", parent.findtext("m:version", namespaces=NS))
        self.assertEqual("17", root.findtext("m:properties/m:java.version", namespaces=NS))
        modules = [node.text.strip() for node in root.findall("m:modules/m:module", NS)]
        self.assertEqual(len(modules), len(set(modules)), "root pom.xml contains duplicate modules")
        self.assertEqual(list(MODULES), modules)

    def test_module_parent_chain_is_exact(self):
        violations = []
        for path, expected in MODULE_PARENT_CHAINS.items():
            actual = parent_coordinates(ET.parse(ROOT / path).getroot())
            if actual != expected:
                violations.append(f"{path}: expected parent {expected}, found {actual}")
        self.assertEqual([], violations)

    def test_platform_versions_are_single_sourced(self):
        violations = []
        root = ET.parse(ROOT / "pom.xml").getroot()
        for name, expected in ROOT_PLATFORM_PROPERTIES.items():
            actual = root.findtext(f"m:properties/m:{name}", namespaces=NS)
            if actual != expected:
                violations.append(f"pom.xml: expected {name}={expected}, found {actual}")

        managed_dependencies = root.findall("m:dependencyManagement/m:dependencies/m:dependency", NS)
        managed_coordinates = [
            (
                dependency.findtext("m:groupId", namespaces=NS),
                dependency.findtext("m:artifactId", namespaces=NS),
            )
            for dependency in managed_dependencies
        ]
        if len(managed_coordinates) != len(set(managed_coordinates)):
            violations.append("pom.xml: dependencyManagement contains duplicate coordinates")
        for coordinates, expected in ROOT_MANAGED_DEPENDENCIES.items():
            matches = [
                dependency for dependency, actual in zip(managed_dependencies, managed_coordinates)
                if actual == coordinates
            ]
            if len(matches) != 1:
                violations.append(
                    f"pom.xml: dependencyManagement must contain {coordinates} exactly once; found {len(matches)}"
                )
                continue
            dependency = matches[0]
            actual = (
                dependency.findtext("m:version", namespaces=NS),
                dependency.findtext("m:type", namespaces=NS),
                dependency.findtext("m:scope", namespaces=NS),
            )
            if actual != expected:
                violations.append(f"pom.xml: managed dependency {coordinates} expected {expected}, found {actual}")

        for pom in active_paths("pom.xml"):
            if pom == ROOT / "pom.xml":
                continue
            relative = pom.relative_to(ROOT)
            child = ET.parse(pom).getroot()
            parent = child.find("m:parent", NS)
            if parent is not None and parent.findtext("m:groupId", namespaces=NS) == "org.springframework.boot":
                violations.append(f"{relative}: inherits the Spring Boot parent directly")
            properties = child.find("m:properties", NS)
            if properties is not None:
                for name in CHILD_PLATFORM_PROPERTIES:
                    if properties.find(f"m:{name}", NS) is not None:
                        violations.append(f"{relative}: redeclares platform property {name}")
            for dependency in child.findall(".//m:dependency", NS):
                group_id = dependency.findtext("m:groupId", namespaces=NS)
                artifact_id = dependency.findtext("m:artifactId", namespaces=NS)
                version = dependency.findtext("m:version", namespaces=NS)
                if group_id in MANAGED_DEPENDENCY_GROUPS and version is not None:
                    violations.append(
                        f"{relative}: dependency {group_id}:{artifact_id} hardcodes version {version.strip()}"
                    )
            for plugin in child.findall(".//m:plugin", NS):
                group_id = plugin.findtext("m:groupId", default="org.apache.maven.plugins", namespaces=NS)
                artifact_id = plugin.findtext("m:artifactId", namespaces=NS)
                version = plugin.findtext("m:version", namespaces=NS)
                if (group_id, artifact_id) in MANAGED_PLUGINS and version is not None:
                    violations.append(
                        f"{relative}: plugin {group_id}:{artifact_id} hardcodes version {version.strip()}"
                    )
            source = pom.read_text(encoding="utf-8")
            for obsolete in (
                "mybatis-plus-boot-starter",
                "knife4j-openapi2-spring-boot-starter",
                "spring-cloud-starter-bootstrap",
            ):
                if obsolete in source:
                    violations.append(f"{relative}: contains obsolete dependency {obsolete}")
        self.assertEqual([], violations)

    def test_java_ee_imports_use_jakarta(self):
        offenders = []
        for java in active_paths("*.java"):
            source = java.read_text(encoding="utf-8")
            if re.search(r"import javax\.(servlet|validation)\.", source):
                offenders.append(str(java.relative_to(ROOT)))
        self.assertEqual([], offenders)

    def test_all_java_dockerfiles_use_temurin_17(self):
        dockerfiles = [
            "mall-backend/hm-service/Dockerfile", "item-service/Dockerfile",
            "cart-service/Dockerfile", "user-service/Dockerfile",
            "trade-service/Dockerfile", "pay-service/Dockerfile",
            "marketing-service/Dockerfile",
        ]
        for path in dockerfiles:
            with self.subTest(path=path):
                source = read(path)
                self.assertIn("eclipse-temurin-17", source)
                self.assertIn("eclipse-temurin:17-jre", source)
                self.assertNotIn("temurin-11", source)

    def test_boot4_auto_configuration_registration_exists(self):
        imports = "mall-backend/hm-common/src/main/resources/META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports"
        self.assertTrue((ROOT / imports).is_file())
        source = read(imports)
        registrations = []
        for line in source.splitlines():
            registration = line.split("#", 1)[0].strip()
            if registration:
                registrations.append(registration)
        self.assertEqual(list(AUTO_CONFIGURATIONS), registrations)


if __name__ == "__main__":
    unittest.main()

import re
import unittest
from pathlib import Path


SQL_PATH = (
    Path(__file__).resolve().parents[1]
    / "scripts"
    / "migration"
    / "marketing-catalog-inventory-preflight.sql"
)


class MarketingCatalogInventoryPreflightTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.sql = SQL_PATH.read_text(encoding="utf-8")
        cls.sql_without_comments = re.sub(
            r"/\*.*?\*/|--[^\r\n]*|\#[^\r\n]*",
            "",
            cls.sql,
            flags=re.DOTALL,
        )
        cls.statements = [
            statement.strip()
            for statement in cls.sql_without_comments.split(";")
            if statement.strip()
        ]

    def test_script_contains_only_select_statements(self):
        self.assertTrue(self.statements)
        for statement in self.statements:
            self.assertRegex(statement, r"(?is)^SELECT\b")
            self.assertNotRegex(
                statement,
                r"(?i)\b(ALTER|CREATE|DELETE|DROP|GRANT|INSERT|RENAME|REPLACE|REVOKE|TRUNCATE|UPDATE|USE)\b",
            )

    def test_script_never_selects_all_columns_or_row_level_mapping(self):
